    public function login()
    {
        $username = $_REQUEST['username'];
        $password = $_REQUEST['password'];
        $device_id = $_REQUEST['device_id'];
        
        if(!isset($username)){
            $response['status']= false;
            $response['message']= "username missing..!";
            return json_encode($response);
        }
        if($password==''){
            $response['status']= false;
            $response['message']= "Password missing..!";
            return json_encode($response);
        }
        $password = AuthComponent::password($password);
        $response = array();
        
        $users = $this->User->find('first', array('conditions'=>array('User.username'=>$username,'User.password'=>$password,'User.role'=>'cashier','User.status'=>1)));
        if(!empty($users))
        {
            if(isset($device_id)){
                $id=$users['User']['id'];
                $this->User->query("UPDATE users SET device_id = '$device_id',sync=0,local_sync=0 WHERE id = $id");
            }
            
            if(isset($users['User']['username'])){
                $username=$users['User']['username'];
            }else{
                $username='';
            }
            if(isset($users['User']['name'])){
                $name=$users['User']['name'];
            }else{
                $name='';
            }
            if(isset($users['User']['mobile'])){
                $mobile=$users['User']['mobile'];
            }else{
                $mobile='';
            }
            $modules=modules;
            
            $flags = [];
            foreach ($modules as $module) {
                $flags[$module] = false;
            }
            
            $usermodules = $this->User_module->find('all', array('conditions'=>array('User_module.user_id'=>$users['User']['id'],'User_module.status'=>1)));
            if($usermodules){
                foreach($usermodules as $usermodule){
                    $moduleName = $usermodule['User_module']['name'];
                    if (array_key_exists($moduleName, $flags)) {
                        $flags[$moduleName] = true;
                    }
                }
            }
            $loc_id=0;
            $userlocations = $this->User_location->find('first', array('conditions'=>array('user_id'=>$users['User']['id'],'status'=>1,'billing_location'=>1)));
            if($userlocations){
                $loc_id=$userlocations['User_location']['location_id'];
                $locations = $this->Location->find('first', array('conditions'=>array('Location.id'=>$loc_id,'Location.status'=>1)));
            
            }else{
                $locations = $this->Location->find('first', array('conditions'=>array('Location.id'=>$users['User']['location_id'],'Location.status'=>1)));
            }

            $datas['User_track']=array(
                'user_id'=>$users['User']['id'],
                'location_id'=>$users['User']['location_id'],
                'location_name'=>$users['User']['location_name'],
                'type'=>'login',
                'remarks'=>'login'
            );
            if(!$this->User_track->saveAll($datas['User_track']))
            {
                $response['track']= "Not Saved..!";
            }
            
            
            $response['status']= true;
            $response['message']= "Success..!";
            $response['id']= $users['User']['id'];
            $response['username']= $username;
            $response['name']= $name;
            $response['role']= $users['User']['role'];
            $response['can_settlement']= $users['User']['can_settlement'];
            $response['billprint_ip']= $users['User']['billprint_ip'];
            $response['mobile']= $mobile;
            $response['location_id']= $loc_id;
            $response['location_name']= $locations['Location']['name'] ?? '';
            $response['print_line1']= $locations['Location']['print_line1'] ?? '';
            $response['print_line2']= $locations['Location']['print_line2'] ?? '';
            $response['print_line3']= $locations['Location']['print_line3'] ?? '';
            $response['print_line4']= $locations['Location']['print_line4'] ?? '';
            $response['print_line5']= $locations['Location']['print_line5'] ?? '';
            $response['print_line6']= $locations['Location']['print_line6'] ?? '';
            $response['print_line7']= $locations['Location']['print_line7'] ?? '';
            $response['print_line8']= $locations['Location']['print_line8'] ?? '';
            $response['print_line9']= $locations['Location']['print_line9'] ?? '';
            $response['print_line10']= $locations['Location']['print_line10'] ?? '';
            $response['footer_msg']= $locations['Location']['footer_msg'] ?? '';
            $response['footer_msg2']= $locations['Location']['footer_msg2'] ?? '';
            $response['footer_msg3']= $locations['Location']['footer_msg3'] ?? '';
            $response['currency_symbol']= $locations['Location']['currency_symbol'] ?? '';
            $response['created']= $users['User']['created'];
            $response['track']= "Saved..!";
            
            foreach ($modules as $module) {
                $response[$module] = $flags[$module];
            }
            
            
        }
        else
        {
            $response['status']= false;
            $response['message']= "Failed..!";
        }
        return json_encode($response);
    }
     
    public function cardstatuscheck()
    {
        
        $cashierid = $_REQUEST['id'];
        $cardno=preg_replace('/\D/', '', $_REQUEST['cardno']);

        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id Missing",
            );
            return json_encode($response);
        }
        if($cardno==''){
            $response =array(
                'status'=> false,
                'message'=> "Card No Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found or User Deactivated",
            );
            return json_encode($response);
        }
        
        $card = $this->Card->find('first', array('conditions'=>array('Card.cardnumber'=>$cardno)));
        if(empty($card))
        {
            $response =array(
                'status'=> false,
                'message'=> "Card not found",
            );
            return json_encode($response);
        }else{
            if($card[Card]['name']){
                $name=$card['Card']['name'];
            }else{
                $name='';
            }
            $phone=$card['Card']['mobile'];
            $response['status']= true;
            $response['statusvalue']= $card[Card]['status'];
            $response['customername']= $name;
            $response['cardbalance']= $card[Card]['cardbalance'];
            $response['message']= "Card is diabled please contact to support.";
        }
        return json_encode($response);
    }
    
