    public function cardaddbalance()
    {
        $cashierid = $_REQUEST['id'];
        $cardno=preg_replace('/\D/', '', $_REQUEST['cardno']);
        $amount = $_REQUEST['amount'];
        $mode = $_REQUEST['mode'];
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id Missing",
            );
            return json_encode($response);
        }
        if($cardno==''){
            $response =array(
                'status'=> false,
                'message'=> "Card no Missing",
            );
            return json_encode($response);
        }
        if($amount==''){
            $response =array(
                'status'=> false,
                'message'=> "Amount Missing",
            );
            return json_encode($response);
        }
        if($amount<1){
            $response =array(
                'status'=> false,
                'message'=> "Amount need to be greater than 0",
            );
            return json_encode($response);
        }
        if($mode==''){
            $response =array(
                'status'=> false,
                'message'=> "payment mode Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found or User Deactivated",
            );
            return json_encode($response);
        }else{
            $cashiername=$users['User']['name'];
        }
        
        $card = $this->Card->find('first', array('conditions'=>array('Card.cardnumber'=>$cardno,'Card.status'=>2)));
        if(empty($card))
        {
            $response =array(
                'status'=> false,
                'message'=> "Card not found or Card Deactivated",
            );
            return json_encode($response);
        }else{
            $name=$card['Card']['name'];
            $mobile=$card['Card']['mobile'];
            $oldbal=$card['Card']['cardbalance'];
            $newbal=$oldbal+$amount;
            
            do {
                $txnid = '';
                for ($i = 0; $i < 10; $i++) {
                    $txnid .= rand(0, 9);
                }
                $existingOTP = $this->Cardtracking->find('first', array(
                    'conditions' => array(
                        'txnid' => $txnid
                    )
                ));
            } while ($existingOTP); // Continue generating OTP until it doesn't exist
            
            $data['Cardtracking']=array(
                'cardnumber'=>$cardno,
                'cashierID'=>$cashierid,
                'txnid'=>$txnid,
                'cashierName'=>$cashiername,
                'customername'=>$name,
                'customerphone'=>$mobile,
                'purpose'=>'add',
                'oldbalance'=>$oldbal,
                'amount'=>$amount,
                'newbalance'=>$newbal,
                'type'=>1,
                'payment_mode'=>$mode
            );
          
            if($this->Cardtracking->saveAll($data['Cardtracking']))
            {
                $this->Card->query("UPDATE cards SET cardbalance = $newbal,sync=0,local_sync=0 WHERE cardnumber = '$cardno'");
            
                $response= array('status'=> true,
                    'message'=> "Balance Added successfully",
                    'cardno'=>$cardno,
                    'balance'=>$newbal
                );
            }else{
                $response =array(
                    'status'=> false,
                    'message'=> "failed",
                );
            }
        }
        return json_encode($response);
    }
    
    public function cardwithdrawalbalance()
    {
        $cashierid = $_REQUEST['id'];
        $cardno=preg_replace('/\D/', '', $_REQUEST['cardno']);
        $amount = $_REQUEST['amount'];
        $otp = $_REQUEST['otp'];
        $mode = $_REQUEST['mode'];
        $reference_id = $_REQUEST['reference_id'];
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id Missing",
            );
            return json_encode($response);
        }
        if($cardno==''){
            $response =array(
                'status'=> false,
                'message'=> "Card no Missing",
            );
            return json_encode($response);
        }
        if($amount==''){
            $response =array(
                'status'=> false,
                'message'=> "Amount Missing",
            );
            return json_encode($response);
        }
        
        if($mode==''){
            $response =array(
                'status'=> false,
                'message'=> "payment mode Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found or User Deactivated",
            );
            return json_encode($response);
        }else{
            $cashiername=$users['User']['name'];
        }
        
        $card = $this->Card->find('first', array('conditions'=>array('Card.cardnumber'=>$cardno,'Card.status'=>2)));
        if(empty($card))
        {
            $response =array(
                'status'=> false,
                'message'=> "Card not found or Card Deactivated",
            );
            return json_encode($response);
        }else{
            $pinreq=$card['Card']['pin_required'];
            if($pinreq){
                if($otp==''){
                    $response =array(
                        'status'=> false,
                        'message'=> "PIN Missing",
                    );
                    return json_encode($response);
                }
                $card = $this->Card->find('first', array('conditions'=>array('Card.cardnumber'=>$cardno,'Card.pin'=>$otp,'Card.status'=>2)));
                if(empty($card))
                {
                    $response =array(
                        'status'=> false,
                        'message'=> "Wrong PIN ",
                    );
                    return json_encode($response);
                }
            }
            $card = $this->Card->find('first', array('conditions'=>array('Card.cardnumber'=>$cardno,'Card.cardbalance >= '=>$amount)));
            if(empty($card))
            {
                $response =array(
                    'status'=> false,
                    'message'=> "Withdrawal Amount not exist in card ",
                );
                return json_encode($response);
            }
            
            $today = date("Y-m-d H:i:s");
            $currentDate = new DateTime($today);
            $newdate = $currentDate->modify('-2 minute')->format('Y-m-d H:i:s');

            $cardtrackingchk = $this->Cardtracking->query("SELECT * FROM cardtracking where cardnumber='$cardno' and amount='$amount' and created between '$newdate' and '$today' and type=2");
            if(!empty($cardtrackingchk))
            {
                $response =array(
                    'status'=> false,
                    'message'=> "Withdraw blocked for 2 minutes",
                );
                return json_encode($response);
            }
            
            $name=$card['Card']['name'];
            $mobile=$card['Card']['mobile'];
            $oldbal=$card['Card']['cardbalance'];
            $newbal=$oldbal-$amount;
            
            do {
                $txnid = '';
                for ($i = 0; $i < 10; $i++) {
                    $txnid .= rand(0, 9);
                }
                $existingOTP = $this->Cardtracking->find('first', array(
                    'conditions' => array(
                        'txnid' => $txnid
                    )
                ));
            } while ($existingOTP); // Continue generating OTP until it doesn't exist
            
            $data['Cardtracking']=array(
                'cardnumber'=>$cardno,
                'cashierID'=>$cashierid,
                'txnid'=>$txnid,
                'reference_id'=>$reference_id,
                'cashierName'=>$cashiername,
                'customername'=>$name,
                'customerphone'=>$mobile,
                'purpose'=>'withdrawal',
                'oldbalance'=>$oldbal,
                'amount'=>$amount,
                'newbalance'=>$newbal,
                'type'=>2,
                'payment_mode'=>$mode
            );
          
            if($this->Cardtracking->saveAll($data['Cardtracking']))
            {
                $this->Card->query("UPDATE cards SET cardbalance = $newbal,sync=0,local_sync=0 WHERE cardnumber = '$cardno'");
            
                $response= array('status'=> true,
                    'message'=> "money paid sucessfully",
                    'cardno'=>$cardno,
                    'balance'=>$newbal
                );
            }else{
                $response =array(
                    'status'=> false,
                    'message'=> "failed",
                );
            }
        }
        return json_encode($response);
    }
    
    public function carddeactivate()
    {
        $cashierid = $_REQUEST['id'];
        $cardno = $_REQUEST['cardno'];
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id Missing",
            );
            return json_encode($response);
        }
        if($cardno==''){
            $response =array(
                'status'=> false,
                'message'=> "Card no Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found or User Deactivated",
            );
            return json_encode($response);
        }
        $card = $this->Card->find('first', array('conditions'=>array('Card.cardnumber'=>$cardno,'Card.status'=>2)));
        if(empty($card))
        {
            $response =array(
                'status'=> false,
                'message'=> "Card not found or Card already Deactivated",
            );
            return json_encode($response);
        }else{
            $this->Card->query("UPDATE cards SET status = 0,sync=0,local_sync=0 WHERE cardnumber = '$cardno'");
        
            $response= array('status'=> true,
                'message'=> "Card Deactivated successfully",
            );
        
        }
        return json_encode($response);
    }
    
    public function cardtransfer()
    {
        $cashierid = $_REQUEST['id'];
        $cardno=preg_replace('/\D/', '', $_REQUEST['cardno']);
        $newcardno = $_REQUEST['newcardno'];
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id Missing",
            );
            return json_encode($response);
        }
        if($cardno==''){
            $response =array(
                'status'=> false,
                'message'=> "Card no Missing",
            );
            return json_encode($response);
        }
        if($newcardno==''){
            $response =array(
                'status'=> false,
                'message'=> "New Card No Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found or User Deactivated",
            );
            return json_encode($response);
        }else{
            $cashiername=$users['User']['name'];
        }
        
        $card = $this->Card->find('first', array('conditions'=>array('Card.cardnumber'=>$cardno,'Card.status'=>2)));
        if(empty($card))
        {
            $response =array(
                'status'=> false,
                'message'=> "Card not found or Card Deactivated",
            );
            return json_encode($response);
        }else{
            $newcard = $this->Card->find('first', array('conditions'=>array('Card.cardnumber'=>$newcardno)));
            if(!empty($newcard))
            {
                $status=$newcard['Card']['status'];
                if($status==1){
                    $response =array(
                        'status'=> false,
                        'message'=> "New Card No Already Exist",
                    );
                    return json_encode($response);
                }else{
                    $response= array('status'=> true,
                        'message'=> "New Card no Already Exist But Card Deactivated"
                    );
                    return json_encode($response);
                }
            }else{
            
                $name=$card['Card']['name'];
                $mobile=$card['Card']['mobile'];
                $oldbal=$card['Card']['cardbalance'];
                
                $data['Card']=array(
                    'cardnumber'=>$newcardno,
                    'cardbalance'=>$oldbal,
                    'name'=>$name,
                    'mobile'=>$mobile,
                    'status'=>2
                );
              
                if($this->Card->saveAll($data['Card']))
                {
                    $this->Card->query("UPDATE cards SET cardbalance = 0,status=0,sync=0,local_sync=0 WHERE cardnumber = '$cardno'");
                    
                    do {
                        $txnid = '';
                        for ($i = 0; $i < 10; $i++) {
                            $txnid .= rand(0, 9);
                        }
                        $existingOTP = $this->Cardtracking->find('first', array(
                            'conditions' => array(
                                'txnid' => $txnid
                            )
                        ));
                    } while ($existingOTP); // Continue generating OTP until it doesn't exist
                    
                    $data['Cardtracking']=array(
                        'cardnumber'=>$newcardno,
                        'cashierID'=>$cashierid,
                        'txnid'=>$txnid,
                        'cashierName'=>$cashiername,
                        'customername'=>$name,
                        'customerphone'=>$mobile,
                        'purpose'=>'transferto',
                        'oldbalance'=>0,
                        'amount'=>$oldbal,
                        'newbalance'=>$oldbal,
                        'type'=>1,
                        'payment_mode'=>'transfer'
                    );
                  
                    if($this->Cardtracking->saveAll($data['Cardtracking']))
                    {
                        do {
                            $txnid = '';
                            for ($i = 0; $i < 10; $i++) {
                                $txnid .= rand(0, 9);
                            }
                            $existingOTP = $this->Cardtracking->find('first', array(
                                'conditions' => array(
                                    'txnid' => $txnid
                                )
                            ));
                        } while ($existingOTP); 
                        
                        $data1['Cardtracking']=array(
                            'cardnumber'=>$cardno,
                            'cashierID'=>$cashierid,
                            'txnid'=>$txnid,
                            'cashierName'=>$cashiername,
                            'customername'=>$name,
                            'customerphone'=>$mobile,
                            'purpose'=>'transferfrom',
                            'oldbalance'=>$oldbal,
                            'amount'=>$oldbal,
                            'newbalance'=>0,
                            'type'=>2,
                            'payment_mode'=>'transfer'
                        );
                        if($this->Cardtracking->saveAll($data1['Cardtracking']))
                        {
                            $response= array('status'=> true,
                                'message'=> "Card Transfer successfully",
                                'cardno'=>$newcardno,
                                'balance'=>$oldbal
                            );
                        }else{
                            $response =array(
                                'status'=> false,
                                'message'=> "failed to save card tracking 101",
                            ); 
                        }
                    }else{
                        $response =array(
                            'status'=> false,
                            'message'=> "failed to save card tracking",
                        );
                    }
                    
                }else{
                    $response =array(
                        'status'=> false,
                        'message'=> "failed to save card",
                    );
                }
            }
        }
        return json_encode($response);
    }
    
    public function cardcreate()
    {
        $sendmessage= new UtilityController;
        
        $cashierid = $_REQUEST['id'];
        $cardno=preg_replace('/\D/', '', $_REQUEST['cardno']);
        $name = $_REQUEST['name'];
        $mobile = $_REQUEST['mobile'];
        $email = $_REQUEST['email'];
        $valid_to = $_REQUEST['validto'];
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id Missing",
            );
            return json_encode($response);
        }
        if($cardno==''){
            $response =array(
                'status'=> false,
                'message'=> "Card no Missing",
            );
            return json_encode($response);
        }
        if($name==''){
            $response =array(
                'status'=> false,
                'message'=> "Name Missing",
            );
            return json_encode($response);
        }
        if($mobile==''){
            $response =array(
                'status'=> false,
                'message'=> "Mobile no Missing",
            );
        }
        
        if($email==''){
            $response =array(
                'status'=> false,
                'message'=> "Email Missing",
            );
        }
        if (!preg_match('/^\d{10}$/', $mobile)) {
            $response =array(
                'status'=> false,
                'message'=> "Mobile no is not valid",
            );
            return json_encode($response);
        }
        if($valid_to==''){
            $response =array(
                'status'=> false,
                'message'=> "Validity Missing",
            );
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found or User Deactivated",
            );
            return json_encode($response);
        }else{
            $cashiername=$users['User']['name'];
        }
        
        $card = $this->Card->find('first', array('conditions'=>array('Card.cardnumber'=>$cardno,'Card.status'=>2)));
        if(!empty($card))
        {
            $response =array(
                'status'=> false,
                'message'=> "Card Already Exist",
            );
            return json_encode($response);
        }else{
