    public function dasboarddata()
    {
        $cashierid = $_REQUEST['id'];
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found or User Deactivated",
            );
            return json_encode($response);
        }
        
        $todayDate = date("Y-m-d");
        $card = $this->Cardtracking->query("SELECT SUM(IF(type=1,1,0))+SUM(IF(type=2,1,0)) AS total_txnid, SUM(IF(type=3,1,0)) AS cardissue, SUM(IF(type=1 and purpose='add',amount,0)) AS deposit, SUM(IF(type=2 and purpose='withdrawal',amount,0)) AS deduct FROM cardtracking WHERE cashierID=$cashierid and date(created)='$todayDate'");
        
        if(!empty($card))
        {
            if($card[0][0]['deposit']){
                $deposit=$card[0][0]['deposit'];
            }else{
                $deposit="0";
            }
            if($card[0][0]['deduct']){
                $deduct=$card[0][0]['deduct'];
            }else{
                $deduct="0";
            }
            if($card[0][0]['total_txnid']){
                $total_txnid=$card[0][0]['total_txnid'];
            }else{
                $total_txnid="0";
            }
            if($card[0][0]['cardissue']){
                $cardissue=$card[0][0]['cardissue'];
            }else{
                $cardissue="0";
            }
            
            $response= array('status'=> true,
                'message'=> "success",
                'total_txn' => $total_txnid,
                'card_issued' => $cardissue,   
                'amount_collected' => $deposit,   
                'amount_deducted' => $deduct
            );
        }else{
            $response =array(
                'status'=> false,
                'message'=> "No data found",
            );
        }
        return json_encode($response);
    }
    
    public function card_history()
    {
        $cashierid = $_REQUEST['id'];
        $cardno=preg_replace('/\D/', '', $_REQUEST['cardno']);
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id Missing",
            );
            return json_encode($response);
        }
        if($cardno==''){
            $response =array(
                'status'=> false,
                'message'=> "Card no Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found or User Deactivated",
            );
            return json_encode($response);
        }
        
        $card = $this->Card->find('first', array('conditions'=>array('Card.cardnumber'=>$cardno)));
        if(empty($card))
        {
            $response =array(
                'status'=> false,
                'message'=> "Card Not found ",
            );
            return json_encode($response);
        }else{
            $cardtracks = $this->Cardtracking->find('all', array('conditions'=>array('Cardtracking.cardnumber'=>$cardno),'order' => array('Cardtracking.id' => 'desc')));
            foreach($cardtracks as $cardtrack){
                if($cardtrack['Cardtracking']['type']==1){
                    $type_value='add';
                }elseif($cardtrack['Cardtracking']['type']==2){
                    $type_value='deduct';
                }elseif($cardtrack['Cardtracking']['type']==3){
                    $type_value='security';
                }else{
                    $type_value='refund';
                }
                if($cardtrack['Cardtracking']['cashierName']){
                    $cashierName=$cardtrack['Cardtracking']['cashierName'];
                }else{
                    $cashierName='';
                }
                if($cardtrack['Cardtracking']['customername']){
                    $customername=$cardtrack['Cardtracking']['customername'];
                }else{
                    $customername='';
                }
                if($cardtrack['Cardtracking']['customerphone']){
                    $customerphone=$cardtrack['Cardtracking']['customerphone'];
                }else{
                    $customerphone='';
                }
                if($cardtrack['Cardtracking']['payment_mode']){
                    $payment_mode=$cardtrack['Cardtracking']['payment_mode'];
                }else{
                    $payment_mode='';
                }
                $item[]=array(
                    'id' => $cardtrack['Cardtracking']['id'],
                    'cardnumber' =>  $cardtrack['Cardtracking']['cardnumber'],
                    'cashierID' =>  $cardtrack['Cardtracking']['cashierID'],
                    'txnid' =>  $cardtrack['Cardtracking']['txnid'],
                    'cashierName' =>  $cashierName,
                    'customername' =>  $customername,
                    'customerphone' =>  $customerphone,
                    'purpose' =>  $cardtrack['Cardtracking']['purpose'],
                    'oldbalance' =>  $cardtrack['Cardtracking']['oldbalance'], 
                    'amount' =>  $cardtrack['Cardtracking']['amount'], 
                    'newbalance' =>  $cardtrack['Cardtracking']['newbalance'], 
                    'type' =>  $cardtrack['Cardtracking']['type'], 
                    'type_value' =>  $type_value, 
                    'payment_mode' =>  $payment_mode,  
                    'created' =>  $cardtrack['Cardtracking']['created']
                );
            }
            $response= array('status'=> true,
                'message'=> "success",
                'users'=>$item
            );
        }
        return json_encode($response);
    }
    
    public function user_modules()
    {
        $id = $_REQUEST['id'];
        
        if(!isset($id)){
            $response['status']= false;
            $response['message']= "user id missing..!";
            return json_encode($response);
        }
        $response = array();
        
        $users = $this->User_module->find('all', array('conditions'=>array('user_id'=>$id,'status'=>1)));
        if(!empty($users))
        {
            $card=false;
            $catalogue=false;
            $reporting=false;
            $ordering=false;
            foreach($users as $user){
                $name=$user['User_module']['name'];
                if($name=='card'){
                    $card=true;
                }
                if($name=='catalogue'){
                    $catalogue=true;
                }
                if($name=='reporting'){
                    $reporting=true;
                }
                if($name=='ordering'){
                    $ordering=true;
                }
            }
            
            $response['status']= true;
            $response['message']= "Success..!";
            $response['id']= $id;
            $response['card']= $card;
            $response['catalogue']= $catalogue;
            $response['reporting']= $reporting;
            $response['ordering']= $ordering;
        }
        else
        {
            $response['status']= false;
            $response['message']= "Failed..!";
        }
        return json_encode($response);
    }
    
