    public function product_list()
    {
        $cashierid = $_REQUEST['id'];
        $catid = $_REQUEST['catid'];
        $subcatid = $_REQUEST['subcatid'];
        if(isset($subcatid)){
            $catid=$subcatid;
        }
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id Missing",
            );
            return json_encode($response);
        }
        if($catid==''){
            $response =array(
                'status'=> false,
                'message'=> "Category Id Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        if($catid==0){
            $products = $this->Catalog_product->find('all', array('conditions'=>array('Catalog_product.status'=>1)));
        }else{
            $products = $this->Catalog_product->find('all', array(
                'conditions' => array(
                    'Catalog_product.status' => 1,
                    'OR' => array(
                        'Catalog_product.cat_id' => $catid,
                        'Catalog_product.subcat_id' => $catid
                    )
                )
            ));
        }
        
        if(empty($products))
        {
            $response =array(
                'status'=> false,
                'message'=> "Products Not found ",
            );
            return json_encode($response);
        }else{
            foreach($products as $product){
                
                $taxesitems=[];
                $taxess = $this->Catalog_product_tax->find('all', array('conditions'=>array('Catalog_product_tax.product_id'=>$product['Catalog_product']['id'],'Catalog_product_tax.status'=>1)));
                foreach($taxess as $tax){
                    $taxesitems[]=array(
                        'tax_id' => $tax['Catalog_product_tax']['tax_id'],
                        'tax_name' =>  $tax['Catalog_product_tax']['tax_name'],
                        'tax_percentage' =>  $tax['Catalog_product_tax']['tax_percentage']
                    );
                }
            
            
                $addonitems=[];
                if($product['Catalog_product']['addon']){
                    $addons = $this->Catalog_product_addon->find('all', array('conditions'=>array('Catalog_product_addon.product_id'=>$product['Catalog_product']['id'],'Catalog_product_addon.status'=>1)));
                    foreach($addons as $addon){
                        $addonitems[]=array(
                            'id' => $addon['Catalog_product_addon']['id'],
                            'name' =>  $addon['Catalog_product_addon']['name'],
                            'created' =>  $addon['Catalog_product_addon']['created']
                        );
                    }
                }
                
                if(!$product['Catalog_product']['image']){
                    $product['Catalog_product']['image']='';
                }
                
                if($product['Catalog_product']['image']){
                    $imgpth=Router::url('/', true) . DS . 'uploads' . DS . 'product_images' . DS . $product['Catalog_product']['image'];
                }else{
                    $imgpth=''; 
                }        
                $item[]=array(
                    'id' => $product['Catalog_product']['id'],
                    'name' =>  $product['Catalog_product']['name'],
                    'cat_id' =>  $product['Catalog_product']['cat_id'],
                    'cat_name' =>  $product['Catalog_product']['cat_name'],
                    'description' => $product['Catalog_product']['description'],
                    'food_type' =>  $product['Catalog_product']['food_type'],
                    'sort_order' =>  $product['Catalog_product']['sort_order'],
                    'recommended' =>  $product['Catalog_product']['recommended'],
                    'variation' =>  $product['Catalog_product']['variation'],
                    'price' => $product['Catalog_product']['price'],
                    'kds' => $product['Catalog_product']['kds'],
                    'markup_price' =>  $product['Catalog_product']['markup_price'],
                    'allergy_tags' =>  $product['Catalog_product']['allergy_tags'],
                    'weight' =>  $product['Catalog_product']['weight'],
                    'serves_people' =>  $product['Catalog_product']['serves_people'],
                    'image' => $imgpth,
                    'taxes'=>$taxesitems,
                    'addons'=>$addonitems,
                    'status' =>  $product['Catalog_product']['status'],
                    'created' =>  $product['Catalog_product']['created']
                );
            }
            $response= array('status'=> true,
                'message'=> "success",
                'products'=>$item
            );
        }
        return json_encode($response);
    }
    
