    public function table_list()
    {
        $cashierid = $_REQUEST['id'];
        $todayDate = date('Y-m-d'); 
                
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        $location_id=$users['User']['location_id'];
        if(isset($_REQUEST['status'])){
            $tbles = $this->Order_table->find('all', array('conditions'=>array('location_id'=>$location_id,'status'=>$_REQUEST['status'],'is_takeaway'=>0),    'order' => array('Order_table.id' => 'ASC')
        ));
        }else{
            $tbles = $this->Order_table->find('all', array('conditions'=>array('location_id'=>$location_id,'status !='=>0,'is_takeaway'=>0),
                'order' => array('Order_table.id' => 'ASC')
        ));
        }
        if(empty($tbles))
        {
            $response =array(
                'status'=> false,
                'message'=> "Tables Not found ",
            );
            return json_encode($response);
        }else{
            $open_table_amount = 0;
            $item = array();
            
            foreach($tbles as $tble){
                $sc=0;
                $disc=0;
                $tablereference_id=$tble['Order_table']['reference_id'];
                
                
                $tableid=$tble['Order_table']['id'];
                $mergetablecheck = $this->Order_table_tracking->query("SELECT GROUP_CONCAT(main_table_number) as main_table_id FROM `order_table_tracking` WHERE merged_table_id='$tableid' and status=1");
                $main_table_id = $mergetablecheck[0][0]['main_table_id'] ?? '';
                
                $tablereference_id = [$tablereference_id]; 
                
                $mergetablecheckamount = $this->Order_table_tracking->find('all', [
                    'conditions' => [
                        'Order_table_tracking.main_table_ref_id' => $tablereference_id[0],
                        'Order_table_tracking.status' => 1,
                        "DATE(Order_table_tracking.created) =" => $todayDate
                    ]
                ]);
                
                if (!empty($mergetablecheckamount)) {
                    foreach ($mergetablecheckamount as $merge) {
                        $tablereference_id[] = $merge['Order_table_tracking']['merged_table_ref_id']; 
                    }
                }
                
                $orderdata=$this->ordercomputewithdiscounttemp($tablereference_id,$cashierid,$sc,$disc);
                
                $totalservicechg=$orderdata['totalservicechg'] ?? 0;
                $totalprice=$orderdata['totalprice'] ?? 0;
                $totaltax=$orderdata['totaltax'] ?? 0;
                $totaldiscount=$orderdata['totaldiscount'] ?? 0;
                $amount=round((($totalprice+$totaltax+$totalservicechg)-$totaldiscount),0);
                
                 if ($tble['Order_table']['status'] == 2) {
                    $open_table_amount += $amount;
                }
                

                $getStartDateTime = $this->Order_table_tracking->query("SELECT created FROM order_orderhistories WHERE reference_id = '".$tble['Order_table']['reference_id']."' and status !=0 ORDER BY id ASC LIMIT 1");
                $startDateTime = $getStartDateTime[0]['order_orderhistories']['created'] ?? '';
                
                $item[]=array(
                    'id' => $tble['Order_table']['number'],
                    'number' =>  $tble['Order_table']['number'],
                    'reference_id' =>  $tble['Order_table']['reference_id'],
                    'amount' =>  isset($amount) ? (string)$amount : "0",
                    'is_alert' =>  $tble['Order_table']['is_alert'],    
                    'is_waiter_required' =>  $tble['Order_table']['is_waiter_required'],
                    'is_customer_detail_required' =>  $tble['Order_table']['is_customer_detail_required']?$tble['Order_table']['is_customer_detail_required']:"0",
                    'status' =>  $tble['Order_table']['status'],
                    'is_takeaway' =>  $tble['Order_table']['is_takeaway'],
                    'merge_with' =>  $main_table_id,
                    'waiter_id' =>  $tble['Order_table']['waiter_id'] ?? '',
                    'waiter_name' =>  $tble['Order_table']['waiter_name'] ?? '',
                    'start_datetime' =>  $startDateTime
                );
                
            }
            usort($item, function ($a, $b) {
                return strnatcmp($a['number'], $b['number']);
            });
            $response= array('status'=> true,
                'message'=> "success",
                'tables'=>$item,
                'open_table_amount'=>number_format($open_table_amount,2)
            );
        }
        return json_encode($response);
    }

    public function table_list_new()
    {
        $cashierid = $_REQUEST['id'] ?? '';
        $todayDate = date('Y-m-d'); 
                
        $response = array();
        if($cashierid==''){
            $response = array(
                'status'=> false,
                'message'=> "Cashier Id Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response = array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        $location_id = $users['User']['location_id'];
        if(isset($_REQUEST['status'])){
            $tbles = $this->Order_table->find('all', array(
                'conditions'=>array('location_id'=>$location_id,'status'=>$_REQUEST['status'],'is_takeaway'=>0),
                'order' => array('Order_table.id' => 'ASC')
            ));
        }else{
            $tbles = $this->Order_table->find('all', array(
                'conditions'=>array('location_id'=>$location_id,'status !='=>0,'is_takeaway'=>0),
                'order' => array('Order_table.id' => 'ASC')
            ));
        }
        if(empty($tbles))
        {
            $response = array(
                'status'=> false,
                'message'=> "Tables Not found ",
            );
            return json_encode($response);
        }else{
            $open_table_amount = 0;

            // Fetch active table categories
            $allCategories = $this->Table_category->find('all', array(
                'conditions' => array('Table_category.status' => 1),
                'order' => array('Table_category.id' => 'ASC')
            ));

            $categoryMap = array();
            foreach ($allCategories as $cat) {
                $catId = (int)$cat['Table_category']['id'];
                $categoryMap[$catId] = array(
                    'category_id' => $catId,
                    'category_name' => $cat['Table_category']['name'],
                    'total_tables' => 0,
                    'tables' => array()
                );
            }

            $uncategorized = array(
                'category_id' => 0,
                'category_name' => 'General',
                'total_tables' => 0,
                'tables' => array()
            );

            foreach($tbles as $tble){
                $sc = 0;
                $disc = 0;
                $tablereference_id = $tble['Order_table']['reference_id'];
                
                $tableid = $tble['Order_table']['id'];
                $mergetablecheck = $this->Order_table_tracking->query("SELECT GROUP_CONCAT(main_table_number) as main_table_id FROM `order_table_tracking` WHERE merged_table_id='$tableid' and status=1");
                $main_table_id = $mergetablecheck[0][0]['main_table_id'] ?? '';
                
                $tablereference_id = [$tablereference_id]; 
                
                $mergetablecheckamount = $this->Order_table_tracking->find('all', [
                    'conditions' => [
                        'Order_table_tracking.main_table_ref_id' => $tablereference_id[0],
                        'Order_table_tracking.status' => 1,
                        "DATE(Order_table_tracking.created) =" => $todayDate
                    ]
                ]);
                
                if (!empty($mergetablecheckamount)) {
                    foreach ($mergetablecheckamount as $merge) {
                        $tablereference_id[] = $merge['Order_table_tracking']['merged_table_ref_id']; 
                    }
                }
                
                $orderdata = $this->ordercomputewithdiscounttemp($tablereference_id,$cashierid,$sc,$disc);
                
                $totalservicechg = $orderdata['totalservicechg'] ?? 0;
                $totalprice = $orderdata['totalprice'] ?? 0;
                $totaltax = $orderdata['totaltax'] ?? 0;
                $totaldiscount = $orderdata['totaldiscount'] ?? 0;
                $amount = round((($totalprice+$totaltax+$totalservicechg)-$totaldiscount),0);
                
                if ($tble['Order_table']['status'] == 2) {
                    $open_table_amount += $amount;
                }

                $getStartDateTime = $this->Order_table_tracking->query("SELECT created FROM order_orderhistories WHERE reference_id = '".$tble['Order_table']['reference_id']."' and status !=0 ORDER BY id ASC LIMIT 1");
                $startDateTime = $getStartDateTime[0]['order_orderhistories']['created'] ?? '';
                
                $catId = !empty($tble['Order_table']['table_category_id']) ? (int)$tble['Order_table']['table_category_id'] : 0;
                $catName = isset($categoryMap[$catId]) ? $categoryMap[$catId]['category_name'] : 'General';

                $tableItem = array(
                    'id' => $tble['Order_table']['number'],
                    'number' =>  $tble['Order_table']['number'],
                    'reference_id' =>  $tble['Order_table']['reference_id'],
                    'amount' =>  isset($amount) ? (string)$amount : "0",
                    'category_id' => (string)$catId,
                    'category_name' => $catName,
                    'is_alert' =>  $tble['Order_table']['is_alert'],    
                    'is_waiter_required' =>  $tble['Order_table']['is_waiter_required'],
                    'is_customer_detail_required' =>  $tble['Order_table']['is_customer_detail_required']?$tble['Order_table']['is_customer_detail_required']:"0",
                    'status' =>  $tble['Order_table']['status'],
                    'is_takeaway' =>  $tble['Order_table']['is_takeaway'],
                    'merge_with' =>  $main_table_id,
                    'waiter_id' =>  $tble['Order_table']['waiter_id'] ?? '',
                    'waiter_name' =>  $tble['Order_table']['waiter_name'] ?? '',
                    'start_datetime' =>  $startDateTime
                );

                if (isset($categoryMap[$catId])) {
                    $categoryMap[$catId]['tables'][] = $tableItem;
                } else {
                    $uncategorized['tables'][] = $tableItem;
                }
            }

            $finalCategories = array();
            foreach ($categoryMap as $cat) {
                usort($cat['tables'], function ($a, $b) {
                    return strnatcmp($a['number'], $b['number']);
                });
                $cat['total_tables'] = count($cat['tables']);
                $finalCategories[] = $cat;
            }

            if (!empty($uncategorized['tables'])) {
                usort($uncategorized['tables'], function ($a, $b) {
                    return strnatcmp($a['number'], $b['number']);
                });
                $uncategorized['total_tables'] = count($uncategorized['tables']);
                $finalCategories[] = $uncategorized;
            }

            $response = array(
                'status' => true,
                'message' => "success",
                'table_categories' => $finalCategories,
                'open_table_amount' => number_format($open_table_amount, 2)
            );
        }
        return json_encode($response);
    }

    public function orderhistorysave_table()
    {
        $response['status']= false;
        $response['message']= "fail";
        
        $cashierid = $_REQUEST['id'];
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id is Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }else{
            $location_id = $users['User']['location_id'] ?? '';

            if (isset($_REQUEST['data'])) {
                $data = $_REQUEST['data'];
            } else {
                $response =array(
                    'status'=> false,
                    'message'=> "data not found",
                );
                return json_encode($response);
            }
            
            $datajson=$data;
            $data = json_decode($data, true);
            if(isset($data['table_number'])){
                $tableno=$data['table_number'];
            }else{
                $response =array(
                    'status'=> false,
                    'message'=> "Table Number missing",
                );
                return json_encode($response);
            }
            
            if(isset($data['tablereference_id'])){
                $tablereference_id=$data['tablereference_id'];
            }else{
                $response =array(
                    'status'=> false,
                    'message'=> "Table Refrence Id missing",
                );
                return json_encode($response);
            }
            
            
            $existingRecord = $this->Order_orderhistory_json->find('first', array(
                'conditions' => array(
                    'Order_orderhistory_json.reference_id' => $tablereference_id,
                    'Order_orderhistory_json.table_number' => $tableno
                ),
                'fields' => array('id', 'json', 'created'),
                'order'  => array('Order_orderhistory_json.id DESC')
            ));

            if ($existingRecord) {
                $existingCreated = $existingRecord['Order_orderhistory_json']['created'];
                $existingJson    = $existingRecord['Order_orderhistory_json']['json'];

                $createdTime   = strtotime($existingCreated);
                $currentTime   = time();
                $diffInSeconds = $currentTime - $createdTime;

                if ($diffInSeconds <= 60) {
                    $existingDecoded = json_decode($existingJson, true);
                    $newDecoded      = json_decode($datajson, true);

                    if ($existingDecoded == $newDecoded) {
                        $response['status']  = false;
                        $response['message'] = 'Record with identical JSON already exists for this reference ID and table number.';
                        return json_encode($response);
                    }
                }
            }
            
            $datas['Order_orderhistory_json']=array(
                'reference_id'=>$tablereference_id,
                'table_number'=>$tableno,
                'json'=>$datajson
            );
            
            if($this->Order_orderhistory_json->saveAll($datas['Order_orderhistory_json']))
            {
            }
            

            $device_id=$data['device_id'];
            
            $tables = $this->Order_table->find('first', array(
                'conditions' => array(
                    'Order_table.number' => $tableno,
                    'Order_table.reference_id' => $tablereference_id,
                    'Order_table.status IN' => array(1, 2, 4)
                )
            ));
            if(!empty($tables))
            {
                
                $groupid .= rand(0, 9).$cashierid.time();
                
                $todayDate = date('Y-m-d');
                $tdaykot = $this->Order_orderhistory->query("
                    SELECT kot_number 
                    FROM order_orderhistories 
                    WHERE store_id = '$location_id' 
                    ORDER BY id DESC 
                    LIMIT 1
                ");
    
                $kot_no=1;
                if (!empty($tdaykot) && isset($tdaykot[0]['order_orderhistories']['kot_number'])) {
                    $kot_no = $tdaykot[0]['order_orderhistories']['kot_number'] + 1;
                }
                
                $prepTimes = [];
            
                foreach ($data['orderhistory'] as $orderhistory) {
                    $packagechck = $this->Catalog_product->find('first', [
                        'conditions' => [
                            'Catalog_product.id' => $orderhistory['product_id'],
                            'Catalog_product.status' => 1,
                        ],
                        'fields' => ['Catalog_product.id','Catalog_product.preparation_time'],
                        'recursive' => -1
                    ]);
                
                    $prep = !empty($packagechck) ? intval($packagechck['Catalog_product']['preparation_time']) : 0;
                    $prepTimes[] = $prep;
                }
                
                $maxPrep = !empty($prepTimes) ? max($prepTimes) : 0;
                
                foreach($data['orderhistory'] as $orderhistory){
                    $cat_id=$orderhistory['cat_id'];
                    $cat_name=$orderhistory['cat_name'];
                    
                    if(isset($orderhistory['kds'])){
                        $kds=$orderhistory['kds'];
                    }else{
                        $kds=1;
                    }
                    
                    $packagechck = $this->Catalog_product->find('first', [
                        'conditions' => [
                            'Catalog_product.id' => $orderhistory['product_id'],
                            'Catalog_product.status' => 1,
                        ],
                        'fields' => ['Catalog_product.id','Catalog_product.dish_type','Catalog_product.preparation_time'],
                        'recursive' => -1
                    ]);
                    
                    $prep = !empty($packagechck) ? intval($packagechck['Catalog_product']['preparation_time']) : 0;
                    $dish_type=$packagechck['Catalog_product']['dish_type'];
                    
                    if ($maxPrep == 0) {
                        $delaySeconds = 10; 
                    } elseif ($prep == $maxPrep) {
                        $delaySeconds = 10; 
                    } else {
                        $diff = max(0, $maxPrep - $prep);
                        $delaySeconds = $diff * 60; 
                    }
                
                    $fireTime = time();
                    $fireTime = date('Y-m-d H:i:s', $fireTime);
                    
                    $datas['Order_orderhistory']=array(
