                    if (!empty($linkpackagechk[0][0]['link_qty'])) {
                        $link_package_item_quantity = $linkpackagechk[0][0]['link_qty'];
                    }
            
                    if ($orderproduct_quantity <= $link_package_item_quantity) {
                        $discount_percentage = 100;
                    } elseif ($link_package_item_quantity > 0) {
                        $discount_percentage = round(($link_package_item_quantity * 100) / $orderproduct_quantity, 2);
                    } else {
                        $discount_percentage = 0;
                    }
                    
                    $orderdata = $this->ordercomputewithpackagediscount($reference_id, $cashierid,$orderproduct_id, $discount_percentage);
                    if($orderdata['status'])
                    {
                        $packagechngchk=true;
                    }
                }
            }
    
            if($order){
                $todayDate = date("Y-m-d");
                $currenttime=date("H:i:s");
                
                $locations = $this->Order_orderhistory->query("SELECT store_id FROM `order_orderhistories` WHERE reference_id='$reference_id' and status!=0 group BY store_id");
                
                foreach($locations as $location){
                    $location_id = $location['order_orderhistories']['store_id'];
                    
                    $tdaytrx=$this->Order_transaction->query("SELECT COUNT(id) as tkn FROM `order_transactions` WHERE date(created)='$todayDate' and status=2");
                    $token=$tdaytrx['0']['0']['tkn']+1;
                    
                    $orderdata=$this->Order_orderhistory->query("SELECT SUM(price) as price,sum(discount) as discount,sum(total_tax) as total_tax,SUM(total_price) as total_price FROM `order_orderhistories` WHERE reference_id='$reference_id' and store_id='$location_id' and status!=0");
                    $updated_discount=0;
                    $updated_tax=0;
                    $updated_final_amount=0;
                    
                    if($packagechngchk){
                        $orderstaxdatas = $this->Order_tax->query("SELECT ot.product_id, SUM((ot.price * ot.quantity) * (ot.discount_percentage / 100)) AS discounted_total, SUM(((ot.price * ot.quantity) * (ot.discount_percentage / 100)) * (IFNULL(ooh.tax_percent, 0) / 100)) AS total_tax, SUM(((ot.price * ot.quantity) * (ot.discount_percentage / 100)) * (1 + (IFNULL(ooh.tax_percent, 0) / 100))) AS final_amount FROM order_tax ot LEFT JOIN ( SELECT product_id, SUM(total_tax_percentage) AS tax_percent FROM order_orderhistories WHERE reference_id = '$reference_id' AND status = 1 and store_id='$location_id' GROUP BY product_id ) ooh ON ooh.product_id = ot.product_id WHERE ot.reference_id = '$reference_id' AND ot.package = 0  and ot.store_id='$location_id' AND ot.status = 1");
                        if(!empty($orderstaxdatas))
