                            $updated_tax=$orderstaxdatas[0][0]['total_tax'];
                            $updated_final_amount=$orderstaxdatas[0][0]['final_amount'];
                        }
                    }
                    $rawAmount = ($orderdata[0][0]['total_price']+$orderdata[0][0]['total_tax'])-$orderdata[0][0]['discount']-$updated_final_amount;
