                    $roundfinalamount = round($rawAmount, 2);

                    $round_amount = $finalamount - $roundfinalamount;
                    
                    $datas['Order_transaction']=array(
                        'reference_id'=>$reference_id,
                        'device_id'=>$device_id,
                        'cashier_id'=>$cashierid,
                        'price'=>$orderdata[0][0]['total_price']-$updated_discount,
                        'total_tax'=>round($orderdata[0][0]['total_tax']-$updated_tax,3),
                        'discount'=>$orderdata[0][0]['discount'] ?? 0,
                        'amount'=>round($finalamount,0),
                        'round'=>round($round_amount,2),
                        'name'=>$name,
                        'phone'=>$phone,
                        'address'=>$address,
                        'waiter_id'=>$waiter_id,
                        'waiter_name'=>$waiter_name,
                        'tokenno'=>$token,
                        'createtime'=>$currenttime,
                        'store_id'=>$location_id,
                        'group_id'=>$groupid
                    );
                    
                    if($this->Order_transaction->saveAll($datas['Order_transaction']))
                    {
                        $dbsave=true;
                        $error = '';
                    }else{
                        $dbsave=false;
                        $error = $store_id;
                    }
                }    
                
                
                if($dbsave)
                {
                    $response['status']= true;
                    $response['message']= "Transaction Data Saved Successfully..!";
                }else{
                    $response['status']= false;
                    $response['message']= "Transaction Data not saved Error for store - ".$error;
                }
                
            }
        }
        
        return json_encode($response);
    }
        
    public function orderpaymentsave()
    {
        $response['status']= false;
        $response['message']= "fail";
        
        $cashierid = $_REQUEST['id'];
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id is Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }else{
            if (isset($_REQUEST['data'])) {
                $data = $_REQUEST['data'];
            } else {
                $response =array(
                    'status'=> false,
                    'message'=> "data not found",
                );
                return json_encode($response);
            }
            
            $data = json_decode($data, true);
            
            $reference_id=$data['reference_id'];
            $device_id=$data['device_id'];
            
            $transactions = $this->Order_transaction->find('first', array(
                'fields' => array('SUM(Order_transaction.amount) AS total_amount'),
                'conditions' => array(
                    'Order_transaction.reference_id' => $reference_id,
                    'Order_transaction.status' => 1
                )
            ));
            
            $total_txn_Amount = !empty($transactions[0]['total_amount']) ? $transactions[0]['total_amount'] : 0;
            
            if (empty($transactions[0]['total_amount'])) {
                $response = array(
                    'status' => false,
                    'message' => "Transaction not found",
                );
                return json_encode($response);
            } else{
                $check_refernce_with_store = $this->Order_transaction->find('all', array(
                    'fields' => array('store_id','id','amount'),
                    'conditions' => array(
                        'Order_transaction.reference_id' => $reference_id,
                        'Order_transaction.status' => 1
                    )
                ));
                
                foreach($check_refernce_with_store as $ref_store){
                
                    $store_id=$ref_store['Order_transaction']['store_id'];
                    $txn_table_id=$ref_store['Order_transaction']['id'];
                    $txn_amount=$ref_store['Order_transaction']['amount'];
                
                    foreach($data['payment'] as $payment){
                        
                        
                        $amount_percent = $payment['amount'] / $total_txn_Amount;
                        $final_payment = round($txn_amount * $amount_percent);
                        $actual_payment = round($txn_amount * $amount_percent,2);
                        
                        $round = $final_payment - $actual_payment;
                    
                        $datas['Order_payment']=array(
                            'reference_id'=>$reference_id,
                            'device_id'=>$device_id,
                            'cashier_id'=>$cashierid,
                            'type'=>$payment['type'],
                            'type_value'=>$payment['type_value'],
                            'amount'=>$final_payment,
                            'remarks'=>$payment['remarks'],
                            'store_id'=>$store_id,
                            'txn_table_id'=>$txn_table_id,
                            'round'=>round($round,2)
                        );
                        
                        if($this->Order_payment->saveAll($datas['Order_payment']))
                        {
                            $finalpayment=0;
                            $finalamount=0;
                            $allpayments=$this->Order_payment->query("SELECT sum(amount) as pay_amount FROM `order_payments` WHERE reference_id='$reference_id' and status!=0");
                            if($allpayments){
                                $finalpayment=$allpayments[0][0]['pay_amount']; //150
                            }
                            
                            $finalamount=$total_txn_Amount ?? 0; //txn_amount_total
                        
                            $amount_diff=$finalamount-$finalpayment;
                            if($amount_diff<1){
                                   
                                $this->Order_orderhistory->query("UPDATE order_orderhistories SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status = 1");
                                $this->Order_transaction->query("UPDATE order_transactions SET status = 2,payment_mode='$type_value',sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status!=0");
                                $this->Order_payment->query("UPDATE order_payments SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status!=0");
                                $this->Order_tax->query("UPDATE order_tax SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status != 0");
                                
                                $stockupdate=$this->stock_update($reference_id);
                                if($stockupdate){
                                    $response['status']= true;
                                    $response['message']= "Payment Data Saved Successfully..!";
                                    $response['full_payment']= true;
                                }else{
                                    $response['status']= true;
                                    $response['message']= "Payment Data Saved Successfully..! But stock not updated";
                                    $response['full_payment']= true;
                                }
                            }else{
                                $response['status']= true;
                                $response['message']= "Payment Data Saved Successfully..!";
                                $response['full_payment']= false;
                            }            
                        }else{
                            $response['status']= false;
                            $response['message']= "Payment Data not saved Error:102";
                            $response['full_payment']= false;
                        }
                    }
                }
            }
        }
        return json_encode($response);
    }
    
    public function reprint_kot()
    {
        $cashierid = $_REQUEST['id'];
        $reference_id = $_REQUEST['reference_id'];
        $group_id = $_REQUEST['group_id'];
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "User Id Missing",
            );
            return json_encode($response);
        }
        if($reference_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Reference Id Missing",
            );
            return json_encode($response);
        }
        if($group_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Group Id Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        $orderitems=[];
        
        $orderss = $this->Order_orderhistory->query("SELECT * FROM `order_orderhistories` WHERE reference_id='$reference_id' and group_id='$group_id' and status!=0 ");
        if(!empty($orderss))
        {
            foreach($orderss as $orders){
                $product_id=$orders['order_orderhistories']['product_id'];
                $order_id=$orders['order_orderhistories']['id'];
                $selected_modifiers=[];
                $orders_modifiers = $this->Order_modifier->query("SELECT * FROM `order_modifier` WHERE reference_id='$reference_id' and product_id='$product_id' and orderhistory_id='$order_id' and status!=0");
                
                foreach($orders_modifiers as $orders_modifier){
                    
                    $modifiers=$orders_modifier['order_modifier'];
