                        'modifier_group_id' => $modifier_group_id,
                        'modifier_group_name' => $modifier_group_name,
                        'modifier_id' => $modifier_id,
                        'modifier_name' => $modifier_name,
                        'modifier_price' => $modifier_price,
                        );
                    
                }
                
                if(!isset($orders['order_orderhistories']['remarks'])){
                    $orders['order_orderhistories']['remarks']='';
                }
                $orderitems[]=array(
                    'id' => $orders['order_orderhistories']['id'],
                    'reference_id' =>  $orders['order_orderhistories']['reference_id'],
                    'cashier_id' =>  $orders['order_orderhistories']['cashier_id'],
                    'group_id' =>  $orders['order_orderhistories']['group_id'],
                    'category' =>  $orders['order_orderhistories']['category'],
                    'category_name' =>  $orders['order_orderhistories']['category_name'],
                    'kds' =>  $orders['order_orderhistories']['kds'],
                    'product_id' =>  $orders['order_orderhistories']['product_id'],
                    'product_name' =>  $orders['order_orderhistories']['product_name'],
                    'quantity' =>  $orders['order_orderhistories']['quantity'],
                    'price' =>  $orders['order_orderhistories']['price'],
                    'total_tax' =>  $orders['order_orderhistories']['total_tax'],
                    'total_price' =>  $orders['order_orderhistories']['total_price'],
                    'discount' =>  $orders['order_orderhistories']['discount'],
                    'table_number' =>  $orders['order_orderhistories']['table_number'],
                    'kot_number' =>  $orders['order_orderhistories']['kot_number'],
                    'remarks' =>  $orders['order_orderhistories']['remarks'],
                    'selected_modifiers' => $selected_modifiers,
                    'status' =>  $orders['order_orderhistories']['status'],
                    'created' =>  $orders['order_orderhistories']['created']
                );
            }
        }
        $finalamount=0;
        $transactionitems=[];
        $transactions = $this->Order_transaction->find('all', array('conditions'=>array('reference_id'=>$reference_id,'status !='=>0)));
        if(!empty($transactions))
        {
            foreach($transactions as $orders){
                if(!$orders['Order_transaction']['remarks']){
                    $orders['Order_transaction']['remarks']='';
                }
                $finalamount=$orders['Order_transaction']['amount'];
                $cashierid=$orders['Order_transaction']['cashier_id'];
                $reference_id=$orders['Order_transaction']['reference_id'];
                
                $discper = $this->Order_tax->query("SELECT discount_percentage FROM `order_tax` WHERE reference_id='$reference_id' and status!=0 and discount_percentage!=0 limit 1");
                if(!empty($discper))
                {
                    $discount_percentage=$discper[0]['order_tax']['discount_percentage'];
                }
                if(!isset($discount_percentage)){
                    $discount_percentage="0";
                }
                
                $transactionitems[]=array(
                    'id' => $orders['Order_transaction']['id'],
                    'reference_id' =>  $orders['Order_transaction']['reference_id'],
                    'orderno' =>  $orders['Order_transaction']['orderno'],
                    'device_id' =>  $orders['Order_transaction']['device_id'],
                    'cashier_id' =>  $orders['Order_transaction']['cashier_id'],
                    'table_number' =>  $orders['Order_transaction']['table_number'],
                    'price' =>  $orders['Order_transaction']['price'],
                    'total_tax' =>  $orders['Order_transaction']['total_tax'],
                    'servicecharge' =>  $orders['Order_transaction']['servicecharge'],
                    'discount' =>  $orders['Order_transaction']['discount'],
                    'discount_percentage' =>  $discount_percentage,
                    'discount_type' =>  $orders['Order_transaction']['discount_type'],
                    'discount_type_value' =>  $orders['Order_transaction']['discount_type_value'],
                    'delivery_charge' =>  $orders['Order_transaction']['delivery_charge'],
                    'packing_charge' =>  $orders['Order_transaction']['packing_charge'],
                    'amount' =>  $orders['Order_transaction']['amount'],
                    'round' =>  $orders['Order_transaction']['round'],
                    'name' =>  $orders['Order_transaction']['name'],
                    'phone' =>  $orders['Order_transaction']['phone'],
                    'address' =>  $orders['Order_transaction']['address'],
                    'remarks' =>  $orders['Order_transaction']['remarks'],
                    'status' =>  $orders['Order_transaction']['status'],
                    'tokenno' =>  $orders['Order_transaction']['tokenno'],
                    'createtime' =>  $orders['Order_transaction']['createtime'],
                    'pax' =>  $orders['Order_transaction']['pax'],
                    'created' =>  $orders['Order_transaction']['created']
                );
            }
        }
        $paymentitems=[];
        $payments = $this->Order_payment->find('all', array('conditions'=>array('reference_id'=>$reference_id,'status !='=>0)));
        if(!empty($payments))
        {
            foreach($payments as $orders){
                if(!isset($orders['Order_payment']['remarks'])){
                    $orders['Order_payment']['remarks']='';
                }
                $paymentitems[]=array(
                    'id' => $orders['Order_payment']['id'],
                    'reference_id' =>  $orders['Order_payment']['reference_id'],
                    'cashier_id' =>  $orders['Order_payment']['cashier_id'],
                    'type' =>  $orders['Order_payment']['type'],
                    'type_value' =>  $orders['Order_payment']['type_value'],
                    'amount' =>  $orders['Order_payment']['amount'],
                    'status' =>  $orders['Order_payment']['status'],
                    'remarks' =>  $orders['Order_payment']['remarks'],
                    'created' =>  $orders['Order_payment']['created']
                );
            }
        }
        $taxitems=[];
        $taxes = $this->Order_tax->query("SELECT tax_id,tax_name,tax_percentage,sum(tax_value) as tax_value FROM `order_tax` WHERE reference_id='$reference_id' and tax_percentage!=0 and status!=0 GROUP by tax_id");
        if(!empty($taxes))
        {
            foreach($taxes as $tax){
                
                $taxitems[]=array(
                    'tax_id' => $tax['order_tax']['tax_id'],
                    'tax_name' =>  $tax['order_tax']['tax_name'],
                    'tax_percentage' =>  $tax['order_tax']['tax_percentage'],
                    'tax_value' =>  "" .round($tax[0]['tax_value'],2)
                );
            }
        }
        $finalpayment=0;
        $allpayments=$this->Order_payment->query("SELECT sum(amount) as pay_amount FROM `order_payments` WHERE reference_id='$reference_id' and status!=0");
        if($allpayments){
            $finalpayment=$allpayments[0][0]['pay_amount'];
        }
        $amount_diff=round(($finalamount-$finalpayment),2);
        if ($amount_diff < 1 && $amount_diff >= 0) {
            $amount_diff = 0;
        }
        
        $cashier_name='';
        $cashname=$this->User->query("SELECT name FROM `users` WHERE id='$cashierid'");
        if($cashname){
           $cashier_name =$cashname[0]['users']['name'];
        }
        
        $printeritems=[];
        $targetStoreId = !empty($users['User']['location_id']) ? $users['User']['location_id'] : (!empty($orderss[0]['order_orderhistories']['store_id']) ? $orderss[0]['order_orderhistories']['store_id'] : '');
        $printerCond = !empty($targetStoreId) ? "status=1 AND store_id='$targetStoreId'" : "status=1";
        $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE $printerCond");
        if(empty($printerss) && !empty($targetStoreId)){
            $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE status=1");
        }
        if(!empty($printerss))
        {
            foreach($printerss as $printers){
                
                $printeritems[]=array(
                    'id' => $printers['pos_printers']['id'],
                    'store_id' =>  $printers['pos_printers']['store_id'],
                    'name' =>  $printers['pos_printers']['name'],
                    'kds' =>  $printers['pos_printers']['kds'],
                    'ip' =>  $printers['pos_printers']['ip'],
                    'status' =>  $printers['pos_printers']['status']
                );
            }
        }
        
        $response= array('status'=> true,
                'message'=> "success",
                'cashier_name'=>$cashier_name,
                'orders'=>$orderitems,
                'transactions'=>$transactionitems,
                'payments'=>$paymentitems,
                'taxes'=>$taxitems,
                'printers'=>$printeritems,
                'remaining_amount'=>number_format($amount_diff, 2, '.', '')
            );
        return json_encode($response);
    }
    public function bill_table()
    {
        $response['status']= false;
        $response['message']= "fail";
        
        $cashierid = $_REQUEST['id'];
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id is Missing",
            );
            return json_encode($response);
        }
        $table_number = $_REQUEST['table_number'];
        if($table_number==''){
            $response =array(
                'status'=> false,
                'message'=> "Table Number is Missing",
            );
            return json_encode($response);
        }
        $table_referenceid = $_REQUEST['reference_id'];
        if($table_referenceid==''){
            $response =array(
                'status'=> false,
                'message'=> "Table refernce Id is Missing",
            );
            return json_encode($response);
        }
        $device_id='';
        if(isset($_REQUEST['device_id'])){
            $device_id=$_REQUEST['device_id'];
        }
        $name='';
        if(isset($_REQUEST['name'])){
            $name=$_REQUEST['name'];
        }
        $phone='';
        if(isset($_REQUEST['phone'])){
            $phone=$_REQUEST['phone'];
        }
        $address='';
        if(isset($_REQUEST['address'])){
            $address=$_REQUEST['address'];
        }
        $pax=1;
        if(isset($_REQUEST['pax'])){
            $pax=$_REQUEST['pax'];
        }
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
            
        $tablechk = $this->Order_table->find('first', array('conditions'=>array('Order_table.reference_id'=>$table_referenceid,'Order_table.number'=>$table_number,'Order_table.status'=>2)));
        if(empty($tablechk))
        {
            $response =array(
                'status'=> false,
                'message'=> "Something went wrong for this table kindly check!!!",
            );
            return json_encode($response);
        }
        $waiter_id=$tablechk['Order_table']['waiter_id'];
        $waiter_name = $tablechk['Order_table']['waiter_name'];
        $pax = $tablechk['Order_table']['customer_pax'] ?? 1;
        $is_takeaway = $tablechk['Order_table']['is_takeaway'];
        
        $trxchck = $this->Order_transaction->find('first', array('conditions'=>array('Order_transaction.reference_id'=>$table_referenceid,'Order_transaction.status !='=>0)));
        if(!empty($trxchck))
        {
            $response =array(
                'status'=> false,
                'message'=> "Reference Id already Exist",
            );
            return json_encode($response);
        }        
        
        $orderss = $this->Order_orderhistory->query("SELECT sum(price) as price,sum(total_tax) as total_tax,sum(total_price) as total_price,sum(discount) as discount FROM `order_orderhistories` WHERE reference_id='$table_referenceid' and status!=0");
        if(!empty($orderss))
        {
            if($orderss[0][0]['total_price']<1){
                $response =array(
                    'status'=> false,
                    'message'=> "There is no item to bill. Please Check..!",
                );
                return json_encode($response);
            }
            
            $todayDate = date("Y-m-d");
            $tdaytrx=$this->Order_transaction->query("SELECT COUNT(id) as tkn FROM `order_transactions` WHERE date(created)='$todayDate' and status=2");
            $token=$tdaytrx['0']['0']['tkn']+1;
            $currenttime=date("H:i:s");
            
            $datas['Order_transaction']=array(
                'reference_id'=>$table_referenceid,
                'device_id'=>$device_id,
                'cashier_id'=>$cashierid,
                'price'=>round($orderss[0][0]['total_price'],2),
                'total_tax'=>round($orderss[0][0]['total_tax'],2),
                'discount'=>round($orderss[0][0]['discount'],2),
                'amount'=>round(($orderss[0][0]['total_price']+$orderss[0][0]['total_tax'])-$orderss[0][0]['discount']),
                'round'=>round(round(($orderss[0][0]['total_price']+$orderss[0][0]['total_tax'])-$orderss[0][0]['discount'])-($orderss[0][0]['total_price']+$orderss[0][0]['total_tax'])-$orderss[0][0]['discount'],2),
                'name'=>$name,
                'phone'=>$phone,
                'address'=>$address,
                'tokenno'=>$token,
                'table_number'=>$table_number,
                'pax'=>$pax,
                'waiter_id'=>$waiter_id,
                'waiter_name'=>$waiter_name,
                'is_takeaway' => $is_takeaway,
                'createtime'=>$currenttime
            );
            if($this->Order_transaction->saveAll($datas['Order_transaction']))
            {
                $this->Order_table->query("UPDATE order_tables SET status = 3,sync=0,local_sync=0 WHERE reference_id = '$table_referenceid'");
        
                $response['status']= true;
                $response['message']= "Bill Generated Successfully..!";
            }else{
                $response['status']= false;
                $response['message']= "Transaction Data not saved Error:103";
            }
        }
        
        return json_encode($response);
    }
    
    public function ordercomputewithpackagediscount($txnid=null,$user_id=null,$product_id=0,$discount=0)
    {
        $response['status']=false;
        $totalservicechg=0;
        $totalprice=0;
        $totaltax1=0;
        $totaltax2=0;
        $totaldiscount=0;
        $sc=0;
        $is_sc=0;
        if($is_sc==1){
            $locIdForSc = $this->resolveLocationIdForTxn($txnid, $user_id);
            $sc = $this->getLocationServiceChargeRate($locIdForSc);
        }
        $discq="(((Order_orderhistory.total_price)-(Order_orderhistory.discount))*$discount/100)";
        $priceq="((Order_orderhistory.total_price)-(Order_orderhistory.discount))";
        
        $this->Order_orderhistory->virtualFields = array('tdisc'=>"SUM($discq)",'tservicechg'=>"SUM(($priceq-$discq)*($sc/100))",'tprice'=>"SUM($priceq)",'total_tax'=>"SUM(($priceq+(($priceq-$discq)*($sc/100))-$discq)*((Order_orderhistory.total_tax_percentage)/100))");  
        $orderhistories=$this->Order_orderhistory->find('first',array('conditions'=>array('Order_orderhistory.reference_id'=>$txnid,'Order_orderhistory.product_id'=>$product_id,'Order_orderhistory.status !=' =>0),'fields'=>array('product_id','tdisc','Order_orderhistory.reference_id','tprice','total_tax','tservicechg')));
        if(!empty($orderhistories['Order_orderhistory']['reference_id'])){
            $response['status']=true;
            $totalservicechg=round($orderhistories['Order_orderhistory']['tservicechg'],2);
            $totalprice=round($orderhistories['Order_orderhistory']['tprice'],2);
            $totaltax=round($orderhistories['Order_orderhistory']['total_tax'],2);
            $totaldiscount=round($orderhistories['Order_orderhistory']['tdisc'],2);
            
            $discq="(((Order_orderhistory.price)-(Order_orderhistory.discount))*$discount/100)";
            $priceq="((Order_orderhistory.price)-(Order_orderhistory.discount))";
            
            $taxes=[];
            
            $this->Order_orderhistory->virtualFields = array('tamount'=>"($priceq+(($priceq-$discq)*($sc/100))-$discq)");  
            $neworderhistories=$this->Order_orderhistory->find('all',array('conditions'=>array('Order_orderhistory.reference_id'=>$txnid,'Order_orderhistory.product_id'=>$product_id,'Order_orderhistory.cashier_id'=>$user_id,'Order_orderhistory.status !=' =>0),'fields'=>array('Order_orderhistory.reference_id','tamount','product_id','price','id')));
            foreach($neworderhistories as $data){
                $orderhistoryid=$data['Order_orderhistory']['id'];
                $reference_id=$data['Order_orderhistory']['reference_id'];
                $product_id=$data['Order_orderhistory']['product_id'];
                $tamount=$data['Order_orderhistory']['tamount'];
                $price=$data['Order_orderhistory']['price'];
                
                $taxitem=$this->Order_tax->find('all',array('conditions'=>array('Order_tax.reference_id'=>$txnid,'Order_tax.product_id'=>$product_id,'Order_tax.status !='=>0,'Order_tax.orderhistory_id'=>$orderhistoryid)));
                foreach($taxitem as $item){
                    $id=$item['Order_tax']['id'];
                    $tax_id=$item['Order_tax']['tax_id'];
                    $tax_percentage=$item['Order_tax']['tax_percentage'];
                    $quantity=$item['Order_tax']['quantity'];
                    $taxamount=round($tamount*$quantity,2);
                    $taxvalue=round((($tamount*$quantity*$tax_percentage)/100),2);
                    
                    $db = $this->Order_tax->getDataSource();
                    
                    try {
                        $this->Order_tax->updateAll(
                            [
                                'Order_tax.taxable_price'       => $taxamount,
                                'Order_tax.tax_value'           => $taxvalue,
                                'Order_tax.discount_percentage' => $discount,
                                'Order_tax.sync'                => 0,
                                'Order_tax.local_sync'          => 0
                            ],
                            [
                                'Order_tax.id' => $id
                            ]
                        );
                    
                        if ($db->lastError()) {
                            $this->trackUser($txnid,$users, 'ordercomputewithpackagediscount (silent)', [
                                'ref_id'    => $txnid,
                                'taxamount' => $taxamount,
                                'taxvalue'  => $taxvalue,
                                'discount'  => $discount,
                                'id'        => $id,
                                'db_error'  => $db->lastError()
                            ]);
                        }
                    } catch (Exception $e) {
                        $this->trackUser($txnid,$users, 'ordercomputewithpackagediscount (exception)', [
                            'ref_id'    => $txnid,
                            'taxamount' => $taxamount,
                            'taxvalue'  => $taxvalue,
                            'discount'  => $discount,
                            'id'        => $id,
                            'error'     => $e->getMessage()
                        ]);
                    }

                }
            }
            
            $response['totalservicechg']=$totalservicechg;
            $response['totalprice']=$totalprice;
            $response['totaltax']=$totaltax;
            $response['totaldiscount']=$totaldiscount;
        }
        return $response;
    }
    
    
    public function orderpaymentsave_table()
    {
        $response['status']= false;
        $response['message']= "fail";
        
        $cashierid = $_REQUEST['id'];
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id is Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }else{
            if (isset($_REQUEST['data'])) {
                $data = $_REQUEST['data'];
            } else {
                $response =array(
                    'status'=> false,
                    'message'=> "data not found",
                );
                return json_encode($response);
            }
            
            $data = json_decode($data, true);
            
            $reference_id=$data['reference_id'];
            $device_id=$data['device_id'];
            
            $transactions = $this->Order_transaction->find('first', array('conditions'=>array('Order_transaction.reference_id'=>$reference_id,'Order_transaction.status !='=>0)));
            if(empty($transactions))
            {
                $response =array(
                    'status'=> false,
                    'message'=> "Transaction not found",
                );
                return json_encode($response);
            }else{
                $store_id=$transactions['Order_transaction']['store_id'];
                
                foreach($data['payment'] as $payment){
                    $payType = $payment['type'] ?? 'Cash';
                    $payTypeValue = $payment['type_value'] ?? $payType;
            
                    $datas['Order_payment']=array(
                        'reference_id'=>$reference_id,
                        'store_id'=>$store_id,
                        'device_id'=>$device_id,
                        'cashier_id'=>$cashierid,
                        'type'=>$payType,
                        'type_value'=>$payTypeValue,
                        'amount'=>$payment['amount'],
                        'remarks'=>$payment['remarks'] ?? ''
                    );
                    if($this->Order_payment->saveAll($datas['Order_payment']))
                    {
                        $finalpayment=0;
                        $finalamount=0;
                        $allpayments=$this->Order_payment->query("SELECT sum(amount) as pay_amount FROM `order_payments` WHERE reference_id='$reference_id' and status!=0");
                        if($allpayments){
                            $finalpayment=$allpayments[0][0]['pay_amount'];
                        }
                        if($transactions){
                            $finalamount=$transactions['Order_transaction']['amount'];
                        }
                        $amount_diff=$finalamount-$finalpayment;
                        if($amount_diff<1){
                            
                            $this->Order_orderhistory->query("UPDATE order_orderhistories SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status = 1");
                            $this->Order_transaction->query("UPDATE order_transactions SET status = 2,payment_mode='$payTypeValue',sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status!=0");
                            $this->Order_payment->query("UPDATE order_payments SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status!=0");
                            $this->Order_tax->query("UPDATE order_tax SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status != 0");
                            
                            do {
                                $pin = 'TX' . $cashierid . date('Y') . uniqid();
                            } while ($this->Order_table->find('first', array('fields' => 'Order_table.id', 'conditions' => array('Order_table.reference_id' => $pin))));
                            
                            $tablestatus = $this->Order_table->find('first', array('conditions'=>array('reference_id'=>$reference_id,'is_takeaway'=>1)));
                            if(!empty($tablestatus))
                            {   
                                $this->Order_table->query("UPDATE order_tables SET status=0,sync=0,local_sync=0  WHERE reference_id = '$reference_id'");
                            }else{
                                $this->Order_table->query("UPDATE order_tables SET customer_name='',customer_phone='',customer_address='',customer_pax=1,status = 1,reference_id='$pin',is_alert=0,sync=0,local_sync=0 WHERE reference_id = '$reference_id'");
                            }

                            $stockupdate=$this->stock_update($reference_id);
                            if(!$stockupdate){
                                $response['status']= true;
                                $response['message']= "Payment Data Saved Successfully..! But stock not updated";
                                $response['full_payment']= true; 
                            }
                            $response['status']= true;
                            $response['message']= "Payment Data Saved Successfully..!";
                            $response['full_payment']= true;
                        }else{
                            $response['status']= true;
                            $response['message']= "Payment Data Saved Successfully..!";
                            $response['full_payment']= false;
                        }
                    }else{
                        $response['status']= false;
                        $response['message']= "Payment Data not saved Error:102";
                        $response['full_payment']= false;
                    }
                }
            }
        }
        return json_encode($response);
    }
    
    public function swap_table()
    {
        $response['status']= false;
        $response['message']= "fail";
        
        $cashierid = $_REQUEST['id'];
        if($cashierid==''){
            $response =array(
