                'message'=> "To Reference id is Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        $chktransaction=$this->Order_table->find('first',array('conditions'=>array('Order_table.status'=>2,'Order_table.reference_id'=>$from_table)));
        
        if(empty($chktransaction)){
            $response['message']= "Option not available for source table!";
            return json_encode($response);
        }
        $from_table_no=$chktransaction['Order_table']['number'];
        
        $chktable=$this->Order_table->find('first',array('conditions'=>array('Order_table.status'=>1,'Order_table.reference_id'=>$to_table)));
        if(empty($chktable)){
            $response['message']= "Option not available for Destination table!";
            return json_encode($response);
        }
        $to_table_no=$chktable['Order_table']['number'];
        
        $todayDate = date("Y-m-d");
        $mergetablecheck = $this->Order_table_tracking->find('all', [
            'conditions' => [
                'Order_table_tracking.main_table_ref_id' => $from_table,
                'Order_table_tracking.status' => 1,
                "DATE(Order_table_tracking.created) =" => $todayDate
            ]
        ]);
        if (!empty($mergetablecheck)) {
            foreach ($mergetablecheck as $merge) {
                
                $mrgid=$merge['Order_table_tracking']['id'];
                
                $this->Order_table_tracking->query("UPDATE order_table_tracking SET status = 0,sync=0,local_sync=0 WHERE id = '$mrgid'");
        
                $mrgrefid = $merge['Order_table_tracking']['merged_table_ref_id']; 
                $mrgrefid = $merge['Order_table_tracking']['merged_table_ref_id']; 
                $mrgrefid = $merge['Order_table_tracking']['merged_table_ref_id']; 
                
                $trackingData = [
                    'main_table_id'      => $chktable['Order_table']['id'],
                    'main_table_number'  => $to_table_no,
                    'main_table_ref_id'  => $from_table,
                    'merged_table_id'    => $merge['Order_table_tracking']['merged_table_id'],
                    'merged_table_number'=> $merge['Order_table_tracking']['merged_table_number'],
                    'merged_table_ref_id'=> $merge['Order_table_tracking']['merged_table_ref_id']
                ];
            
                $this->Order_table_tracking->save($trackingData);
            }
        }
        
        do {
            $pin = 'TX' . $cashierid . date('Y') . uniqid();
        } while ($this->Order_table->find('first', array('fields' => 'Order_table.id', 'conditions' => array('Order_table.reference_id' => $pin))));
        $this->Order_table->query("UPDATE order_tables SET status = 1,reference_id='$pin',customer_phone='',customer_name='',customer_pax='',sync=0,local_sync=0 WHERE reference_id = '$from_table'");
        
        $customer_phone =  $chktransaction['Order_table']['customer_phone'];
        $customer_name =  $chktransaction['Order_table']['customer_name'];
        $customer_pax =  $chktransaction['Order_table']['customer_pax'];
        
        $this->Order_table->query("UPDATE order_tables SET status = 2,reference_id='$from_table',sync=0,local_sync=0,customer_phone='$customer_phone',customer_name='$customer_name',customer_pax='$customer_pax' WHERE reference_id = '$to_table'");
        
        $this->Order_orderhistory->query("UPDATE order_orderhistories SET table_number='$to_table_no', sync=0, local_sync=0 WHERE reference_id='$from_table' AND status!=0");
        $this->Order_transaction->query("UPDATE order_transactions SET table_number='$to_table_no', sync=0, local_sync=0 WHERE reference_id='$from_table' AND status!=0");
         
        $this->Kds_track->query("UPDATE kds_tracks SET table_no='$to_table_no', sync=0, local_sync=0 WHERE order_reference_id='$from_table' AND status!=0");

        $uFullName = !empty($users['User']['name']) ? $users['User']['name'] : ($users['User']['username'] ?? 'Staff');
        $this->User_track->create();
        $this->User_track->save([
            'reference_id'  => $from_table,
            'user_id'       => $cashierid,
            'location_id'   => $users['User']['location_id'] ?? 0,
            'location_name' => $users['User']['location_name'] ?? '',
            'type'          => 'swap',
            'remarks'       => "Table switched/shifted from Table {$from_table_no} to Table {$to_table_no}",
            'status'        => 1
        ]);

        $response['status']= true;
        $response['message']= "Swap Successfully..!";

        return json_encode($response);
    }
    
