    public function quantity_increase()
    {
        $response['status']= false;
        $response['message']= "fail";
        
        $cashierid = $_REQUEST['id'];
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id is Missing",
            );
            return json_encode($response);
        }
        
        $order_id = $_REQUEST['order_id'];
        if($order_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Order id is Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        $orderss = $this->Order_orderhistory->find('first', array('conditions'=>array('id'=>$order_id,'status !='=>0)));
        if(!empty($orderss))
        {
            $newquantity=$orderss['Order_orderhistory']['quantity']+1;
            $price_value=$newquantity*$orderss['Order_orderhistory']['price'];
            $total_tax_percentage=$orderss['Order_orderhistory']['total_tax_percentage'];
            $total_tax=round(((($price_value-$orderss['Order_orderhistory']['discount'])*$total_tax_percentage)/100),2);
            
            $total_price=round($price_value,2);
            
            $this->Order_orderhistory->query("UPDATE order_orderhistories SET quantity=$newquantity,total_price=$total_price,total_tax=$total_tax,sync=0,local_sync=0 WHERE id = '$order_id'");
            $this->Order_modifier->query("UPDATE order_modifier SET quantity=$newquantity,sync=0,local_sync=0 WHERE orderhistory_id = '$order_id'");
            
            $reference_id=$orderss['Order_orderhistory']['reference_id'];
            $product_id=$orderss['Order_orderhistory']['product_id'];
            $tamount=$total_price;
            $price=$orderss['Order_orderhistory']['price'];
            $taxitem=$this->Order_tax->find('all',array('conditions'=>array('Order_tax.orderhistory_id'=>$order_id,'Order_tax.reference_id'=>$reference_id,'Order_tax.product_id'=>$product_id,'Order_tax.status !='=>0)));
            foreach($taxitem as $item){
                $id=$item['Order_tax']['id'];
                $tax_percentage=$item['Order_tax']['tax_percentage'];
                $quantity=$item['Order_tax']['quantity']+1;
                $taxamount=round($price*$quantity,2);
                $taxvalue=round((($price*$quantity*$tax_percentage)/100),2);
                
                $this->Order_tax->query("UPDATE order_tax SET quantity=$quantity,taxable_price = '$taxamount',tax_value='$taxvalue',sync=0,local_sync=0 WHERE id = '$id'");
            }
            
            $this->User_track->create();
            $this->User_track->save([
                'reference_id'  => $reference_id,
                'user_id'       => $cashierid,
                'location_id'   => $users['User']['location_id'] ?? 0,
                'location_name' => $users['User']['location_name'] ?? '',
                'type'          => 'quantity_increase',
                'remarks'       => "Quantity of '{$orderss['Order_orderhistory']['product_name']}' increased to {$newquantity}",
                'status'        => 1
            ]);
            
            $response['status']= true;
            $response['message']= "Quantity Increased Successfully..!";

        
        }else{
            $response['status']= false;
            $response['message']= "Order item not found..!";

        }
        
        
        return json_encode($response);
    }
    
    public function quantity_decrease()
    {
