            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        $orderss = $this->Order_orderhistory->find('first', array('conditions'=>array('id'=>$order_id,'quantity >'=>1,'status !='=>0)));
        if(!empty($orderss))
        {
            $newquantity=$orderss['Order_orderhistory']['quantity']-1;
            $price_value=$newquantity*$orderss['Order_orderhistory']['price'];
            $total_tax_percentage=$orderss['Order_orderhistory']['total_tax_percentage'];
            $total_tax=round(((($price_value-$orderss['Order_orderhistory']['discount'])*$total_tax_percentage)/100),2);
            
            $total_price=round($price_value,2);
            
            $this->Order_orderhistory->query("UPDATE order_orderhistories SET quantity=$newquantity,total_price=$total_price,total_tax=$total_tax,sync=0,local_sync=0 WHERE id = '$order_id'");
            $this->Order_modifier->query("UPDATE order_modifier SET quantity=$newquantity,sync=0,local_sync=0 WHERE orderhistory_id = '$order_id'");
            
            $reference_id=$orderss['Order_orderhistory']['reference_id'];
            $product_id=$orderss['Order_orderhistory']['product_id'];
            $tamount=$total_price;
            $price=$orderss['Order_orderhistory']['price'];
            $taxitem=$this->Order_tax->find('all',array('conditions'=>array('Order_tax.orderhistory_id'=>$order_id,'Order_tax.reference_id'=>$reference_id,'Order_tax.product_id'=>$product_id,'Order_tax.status !='=>0)));
            foreach($taxitem as $item){
                $id=$item['Order_tax']['id'];
                $tax_percentage=$item['Order_tax']['tax_percentage'];
                $quantity=$item['Order_tax']['quantity']-1;
                $taxamount=round($price*$quantity,2);
                $taxvalue=round((($price*$quantity*$tax_percentage)/100),2);
                
                $this->Order_tax->query("UPDATE order_tax SET quantity=$quantity,taxable_price = '$taxamount',tax_value='$taxvalue',sync=0,local_sync=0 WHERE id = '$id'");
            }
            
            $this->User_track->create();
            $this->User_track->save([
                'reference_id'  => $reference_id,
                'user_id'       => $cashierid,
                'location_id'   => $users['User']['location_id'] ?? 0,
                'location_name' => $users['User']['location_name'] ?? '',
                'type'          => 'quantity_decrease',
                'remarks'       => "Quantity of '{$orderss['Order_orderhistory']['product_name']}' decreased to {$newquantity}",
                'status'        => 1
            ]);
            
            $response['status']= true;
            $response['message']= "Quantity Decreased Successfully..!";

        
        }else{
            $response['status']= false;
            $response['message']= "Quantity must be greater then 1 or Order item not found..!";

        }
        
        
        return json_encode($response);
    }
    
    public function table_clear()
    {
        $cashierid = $_REQUEST['id'];
        $ref_id = $_REQUEST['reference_id'];
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "User Id Missing",
            );
            return json_encode($response);
        }
        
        if($ref_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Reference id Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        $tables=$this->Order_table->find('first',array('conditions'=>array('Order_table.reference_id'=>$ref_id,'Order_table.status'=>2)));
        if(empty($tables))
        {   
            $response= array('status'=> false,
                'message'=> "Table not found"
            );
            return json_encode($response);
        }
        
        $checkref=$this->Order_orderhistory->find('first',array('conditions'=>array('Order_orderhistory.reference_id'=>$ref_id,'Order_orderhistory.status !='=>0)));
        if(!empty($checkref))
        {   
            $response= array('status'=> false,
                'message'=> "Please clear the item first"
            );
            return json_encode($response);
        }
        
        do {
            $pin = 'TX' . $cashierid . date('Y') . uniqid();
        } while ($this->Order_table->find('first', array('fields' => 'Order_table.id', 'conditions' => array('Order_table.reference_id' => $pin))));

        $tablestatus = $this->Order_table->find('first', array('conditions'=>array('reference_id'=>$ref_id,'is_takeaway'=>1)));
        if(!empty($tablestatus))
        {   
            $this->Order_table->query("UPDATE order_tables SET status=0,sync=0,local_sync=0 WHERE reference_id = '$ref_id'");
        }else{
            $this->Order_table->query("UPDATE order_tables SET customer_name='',customer_phone='',customer_address='',customer_pax=1,status=1,reference_id='$pin',is_alert=0,sync=0,local_sync=0 WHERE reference_id='$ref_id'");
        }

        $this->Order_table_tracking->query("UPDATE order_table_tracking SET status=0,sync=0,local_sync=0 WHERE main_table_ref_id='$ref_id' OR merged_table_ref_id='$ref_id'");
        
        $response= array('status'=> true,
            'message'=> "Table Cleared"
        );
        return json_encode($response);
    }
    
    public function table_unbill()
    {
        $cashierid = $_REQUEST['id'];
        $ref_id = $_REQUEST['reference_id'];
        
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "User Id Missing",
            );
            return json_encode($response);
        }
        
        if($ref_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Reference id Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        $txnchk = $this->Order_transaction->find('first', array('conditions'=>array('Order_transaction.reference_id'=>$ref_id)));
        if(empty($txnchk))
        {   
            $response= array('status'=> false,
                'message'=> "No Transaction found"
            );
            return json_encode($response);
        }else{
            $tableid=$txnchk['Order_transaction']['table_number'];
            
            $tables=$this->Order_table->find('first',array('conditions'=>array('Order_table.number'=>$tableid,'Order_table.reference_id'=>$ref_id,'Order_table.status !='=>0)));
            
            $orderdata=$this->ordercompute($ref_id,$cashierid,0,0);
            
            
            $updateData = [
                'Order_transaction.status' => 0
            ];
            
            $updated = $this->Order_transaction->updateAll(
                $updateData,
                ['Order_transaction.reference_id' => $ref_id]
            );
            
            $this->Order_transaction->updateAll(
                array(
                    'Order_transaction.sync' => 0,
                    'Order_transaction.local_sync' => 0
                ),
                array(
                    'Order_transaction.reference_id' => $ref_id
                )
            );

            if ($updated) {
                
                $this->Order_payment->updateAll(
                    array(
                        'Order_payment.status' => 0,
                        'Order_payment.sync' => 0,
                        'Order_payment.local_sync' => 0
                    ),
                    array(
                        'Order_payment.reference_id' => $ref_id
                    )
                );
            
                if ($tables) {
                    $this->Order_table->updateAll(
                        array(
                            'Order_table.status'     => 2,
                            'Order_table.sync'       => 0,
                            'Order_table.local_sync' => 0
                        ),
                        array(
                            'Order_table.id' => (int)$tables['Order_table']['id']
                        )
                    );
                }

                $this->loadModel('ReeloDiscount');
                $reeloDiscountExist = $this->ReeloDiscount->find('first', array(
                    'conditions' => array(
                            'ReeloDiscount.reference_id' => $ref_id
                    )
                ));
                if (!empty($reeloDiscountExist)) {
                    $this->ReeloDiscount->updateAll(
                        array(
                            'ReeloDiscount.status' => 0,
                            'ReeloDiscount.sync' => 0,
                            'ReeloDiscount.local_sync' => 0
                        ),
                        array(
                            'ReeloDiscount.reference_id' => $ref_id
                        )
                    );
                }
            
                $response = [
                    'status' => true,
                    'message' => "Bill updated"
                ];
                return json_encode($response);
            
            } else {
            
                $response = [
                    'status' => false,
                    'message' => "Bill not updated"
                ];
                return json_encode($response);
            }

            
        }
        
        
    }
    
    public function table_billupdate_discount()
    {
        $cashierid = $_REQUEST['id'];
        $ref_id = $_REQUEST['reference_id'];
        $disc=$_REQUEST['discount'];
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "User Id Missing",
            );
            return json_encode($response);
        }
        
        if($ref_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Reference id Missing",
            );
            return json_encode($response);
        }
        
        if($disc==''){
            $response =array(
                'status'=> false,
                'message'=> "Discount Missing",
            );
            return json_encode($response);
        }
        if($disc>99){
            $response =array(
                'status'=> false,
                'message'=> "Discount is not more than 99%",
            );
            return json_encode($response);
        }
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        if($disc>=0){
            $checkdiscount=$this->Order_orderhistory->find('first',array('conditions'=>array('Order_orderhistory.discount > '=>0,'Order_orderhistory.status'=>2,'Order_orderhistory.reference_id'=>$ref_id)));
            if(!empty($checkdiscount)){
                $response['status']= false;
                $response['message']= "Discount can not merge with item level discount";
                return json_encode($response);     
            }
        }else{
            $response['status']= false;
            $response['message']= "please check discount value";
            return json_encode($response);  
        }
        
        $tables=$this->Order_table->find('first',array('conditions'=>array('Order_table.reference_id'=>$ref_id,'Order_table.status'=>3)));
        if(empty($tables)){
            $response['status']= false;
            $response['message']= "Table is not in billing state";
            return json_encode($response);
        }
        
        $txnchk = $this->Order_transaction->find('first', array('conditions'=>array('Order_transaction.reference_id'=>$ref_id, 'Order_transaction.cashier_id'=>$cashierid)));
        if(empty($txnchk))
        {
            $response= array('status'=> false,
                'message'=> "No Transaction found"
            );
            return json_encode($response);
        }
        if($txnchk['Order_transaction']['servicecharge']>0){
            $sc=1;
        }else{
            $sc=0;
        }
        
        $orderdata=$this->ordercompute($ref_id,$cashierid,$sc,$disc);
        
        if($orderdata['status'])
        {
            $totalservicechg=$orderdata['totalservicechg'];
            $totalprice=$orderdata['totalprice'];
            $totaltax=$orderdata['totaltax'];
            $totaldiscount=$orderdata['totaldiscount'];
            $totalamount=round((($totalprice+$totaltax+$totalservicechg)-$totaldiscount),0);
            
            $createtime = date('H:i:s');
            $this->Order_transaction->query("UPDATE `order_transactions` SET `price` = '$totalprice',`total_tax`='$totaltax',`servicecharge`='$totalservicechg',`discount`='$totaldiscount',`discount_type`='1',`discount_type_value`='$disc',`amount`='$totalamount',`createtime`='$createtime',sync=0,local_sync=0 WHERE `order_transactions`.`reference_id` = '$ref_id'");
            
            $response =array(
                'status'=> true,
                'message'=> "Saved",
            );
            return json_encode($response);
        }else{
            $response =array(
                'status'=> false,
                'message'=> "Not Saved",
            );
            return json_encode($response);
        }
    }
    
