    public function ordercompute($txnid = null, $user_id = null, $is_sc = 1, $discount = 0)
    {
        $response = ['status' => false];
    
        if (empty($txnid)) {
            return $response;
        }
    
        $sc = 0;
        if ($is_sc == 1) {
            $locIdForSc = $this->resolveLocationIdForTxn($txnid, $user_id);
            $sc = $this->getLocationServiceChargeRate($locIdForSc);
        }
    
        $priceq = "(Order_orderhistory.total_price - Order_orderhistory.discount)";
        $discq  = "($priceq * $discount / 100)";
        $scq    = "(($priceq - $discq) * $sc / 100)";
        $taxq   = "(($priceq - $discq + $scq) * (Order_orderhistory.total_tax_percentage / 100))";
    
        $this->Order_orderhistory->virtualFields = [
            'tprice'      => "SUM($priceq)",
            'tdisc'       => "SUM($discq)",
            'tservicechg' => "SUM($scq)",
            'total_tax'   => "SUM($taxq)"
        ];
    
        $summary = $this->Order_orderhistory->find('first', [
            'conditions' => [
                'Order_orderhistory.reference_id' => $txnid,
                'Order_orderhistory.status !='    => 0
            ],
            'fields' => ['reference_id', 'tprice', 'tdisc', 'tservicechg', 'total_tax'],
            'recursive' => -1
        ]);
    
        if (empty($summary['Order_orderhistory']['reference_id'])) {
            return $response;
        }
    
        $response['status']         = true;
        $response['totalprice']     = round($summary['Order_orderhistory']['tprice'], 2);
        $response['totaldiscount']  = round($summary['Order_orderhistory']['tdisc'], 2);
        $response['totalservicechg']= round($summary['Order_orderhistory']['tservicechg'], 2);
        $response['totaltax']       = round($summary['Order_orderhistory']['total_tax'], 2);
    
        $priceq = "(Order_orderhistory.price - Order_orderhistory.discount)";
        $discq  = "($priceq * $discount / 100)";
        $scq    = "(($priceq - $discq) * $sc / 100)";
        $tamountq = "($priceq - $discq + $scq)";
    
        $this->Order_orderhistory->virtualFields = [
            'tamount' => $tamountq
        ];
    
        $items = $this->Order_orderhistory->find('all', [
            'conditions' => [
                'Order_orderhistory.reference_id' => $txnid,
                'Order_orderhistory.status !='    => 0
            ],
            'fields' => ['id', 'product_id', 'price', 'tamount'],
            'recursive' => -1
        ]);
    
        foreach ($items as $row) {
    
            $orderhistory_id = $row['Order_orderhistory']['id'];
            $product_id      = $row['Order_orderhistory']['product_id'];
            $tamount         = round($row['Order_orderhistory']['tamount'], 2);
    
            $taxItems = $this->Order_tax->find('all', [
                'conditions' => [
                    'Order_tax.reference_id'     => $txnid,
                    'Order_tax.orderhistory_id' => $orderhistory_id,
                    'Order_tax.product_id'      => $product_id,
                    'Order_tax.status !='       => 0
                ],
                'recursive' => -1
            ]);
    
            foreach ($taxItems as $taxRow) {
    
                $tax = $taxRow['Order_tax'];
    
                $taxable_price = round($tamount * $tax['quantity'], 2);
                $tax_value     = round(($taxable_price * $tax['tax_percentage']) / 100, 2);
    
                try {
                    $this->Order_tax->updateAll(
                        [
                            'Order_tax.taxable_price'       => $taxable_price,
                            'Order_tax.tax_value'           => $tax_value,
                            'Order_tax.discount_percentage' => $discount,
                            'Order_tax.sync'                => 0,
                            'Order_tax.local_sync'          => 0
                        ],
                        [
                            'Order_tax.id' => $tax['id']
                        ]
                    );
                    
                    $db = $this->Order_tax->getDataSource();
                    if ($db->lastError()) {
                        $this->trackUser($txnid, $user_id, 'order_tax_update_sql_error', [
                            'tax_id' => $tax['id'],
                            'error'  => $db->lastError()
                        ]);
                    }
                } catch (Exception $e) {
                    $this->trackUser($txnid, $user_id, 'order_tax_update_exception', [
                        'tax_id' => $tax['id'],
                        'error'  => $e->getMessage()
                    ]);
                }
            }
        }
    
        return $response;
    }

    public function wallet_report_print()
    {
        $cashierid = $_REQUEST['id'];
        $sdate = $_REQUEST['sdate'];
        $edate = $_REQUEST['edate'];
        
        $response = array();
        
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id Missing",
            );
            return json_encode($response);
        }
        
        if($sdate==''){
            $response =array(
                'status'=> false,
                'message'=> "Start date Missing",
            );
            return json_encode($response);
        }
        
        if($edate==''){
            $response =array(
                'status'=> false,
                'message'=> "End date Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        $cashiernames=$this->User->find('first',array('conditions'=>array('User.id'=>$cashierid)));
        $cashiername=$cashiernames['User']['name'];
        
        $location_id = !empty($cashiernames['User']['location_id']) ? $cashiernames['User']['location_id'] : null;
        $shiftRange = $this->getShiftDateRange($sdate, $edate, $location_id);
        $startDatetime = $shiftRange['startDatetime'];
        $endDatetime   = $shiftRange['endDatetime'];

        $card = $this->Card->query("SELECT SUM(IF(status IN (2,1),1,0)) AS activecard, SUM(IF(status=0,1,0)) AS inactivecard FROM cards WHERE created between '$startDatetime' AND '$endDatetime'");
        $activecards=$card[0][0]['activecard'];
        $inactivecards=$card[0][0]['inactivecard'];
        
        $cardtracking = $this->Cardtracking->query("SELECT SUM(IF(type=1 and purpose='add',amount,0)) AS totadd, SUM(IF(type=2 and purpose='withdrawal',amount,0)) AS totused, SUM(IF(type=3,amount,0)) AS totsec, SUM(IF(type=4,amount,0)) AS totref,COUNT(DISTINCT(customerphone)) as customers FROM cardtracking WHERE created between '$startDatetime' AND '$endDatetime'");
        $totaladded=$cardtracking[0][0]['totadd'];
        $totalused=$cardtracking[0][0]['totused'];
        $totalsecurity=$cardtracking[0][0]['totsec'];
        $totalrefund=$cardtracking[0][0]['totref'];
        
        $key = array();
        $value = array();
        
        $key[] = "Card Data";
        $value[] = "------";
        $key[] = "Active Cards";
        $value[] = round($activecards,2);
        $key[] = "Inactive Cards";
        $value[] = round($inactivecards,2);
        
        $key[] = "Wallet Data";
        $value[] = "------";
        $key[] = "Total Balance Added";
        $value[] = round($totaladded,2);
        $key[] = "Total Used Amount";
        $value[] = round($totalused,2);
        $key[] = "Total Refunded Amount";
        $value[] = round($totalrefund,2);
        $key[] = "Total Security Amount";
        $value[] = round($totalsecurity,2);
        $key[] = "Net Balance";
        $value[] = round(($totaladded-$totalused),2);
        
        $newData = array();

        $newData[] = array(
            "key" => "Card Data",
            "value" => "------",
            "heading" => true
        );
        
        for ($i = 1; $i < count($key); $i++) {
            $newData[] = array(
                "key" => $key[$i],
                "value" => (string)$value[$i],
                "heading" => $key[$i] === "Wallet Data"
            );
        }
        
        $response = array(
            'status' => true,
            'message' => "success",
            'data' => $newData
        );
        
        return json_encode($response, JSON_PRETTY_PRINT);
    }
    
