            return json_encode($response);
        }
        if($txnchk['Order_transaction']['servicecharge']>0){
            $sc=1;
        }else{
            $sc=0;
        }
        
        $orderdata=$this->ordercompute($ref_id,$cashierid,$sc,$disc);
        
        if($orderdata['status'])
        {
            $totalservicechg=$orderdata['totalservicechg'];
            $totalprice=$orderdata['totalprice'];
            $totaltax=$orderdata['totaltax'];
            $totaldiscount=$orderdata['totaldiscount'];
            $totalamount=round((($totalprice+$totaltax+$totalservicechg)-$totaldiscount),0);
            
            $createtime = date('H:i:s');
            $this->Order_transaction->query("UPDATE `order_transactions` SET `price` = '$totalprice',`total_tax`='$totaltax',`servicecharge`='$totalservicechg',`discount`='$totaldiscount',`discount_type`='1',`discount_type_value`='$disc',`amount`='$totalamount',`createtime`='$createtime',sync=0,local_sync=0 WHERE `order_transactions`.`reference_id` = '$ref_id'");
            
            $response =array(
                'status'=> true,
                'message'=> "Saved",
            );
            return json_encode($response);
        }else{
            $response =array(
                'status'=> false,
                'message'=> "Not Saved",
            );
            return json_encode($response);
        }
    }
    
