    public function cron_disable_cards()
    {
        // Current date and time
        $today= date('Y-m-d H:i:s');
        
        $cards = $this->Card->query("SELECT * FROM `cards` WHERE status=2");
        foreach($cards as $card) {
            $cardnumber = $card['cards']['cardnumber'];
            $cardtracks = $this->Cardtracking->query("SELECT newbalance FROM `cardtracking` WHERE cardnumber='$cardnumber' order by id desc limit 1");
            if($cardtracks[0]['cardtracking']['newbalance']){
                
                do {
                    $txnid = '';
                    for ($i = 0; $i < 10; $i++) {
                        $txnid .= rand(0, 9);
                    }
                    $existingOTP = $this->Cardtracking->find('first', array(
                        'conditions' => array(
                            'txnid' => $txnid
                        )
                    ));
                } while ($existingOTP); // Continue generating OTP until it doesn't exist
                
                $data['Cardtracking']=array(
                    'cardnumber'=>$cardnumber,
                    'txnid'=>$txnid,
                    'purpose'=>'transfertoTheParkWallet',
                    'oldbalance'=>$cardtracks[0]['cardtracking']['newbalance'],
                    'amount'=>$cardtracks[0]['cardtracking']['newbalance'],
                    'newbalance'=>0,
                    'type'=>5,
                    'payment_mode'=>'transfertoTheParkWallet'
                );
              
                if($this->Cardtracking->saveAll($data['Cardtracking']))
                {
                    $this->Card->query("UPDATE cards SET cardbalance = 0,status=1,name='',mobile=0,email='',sync=0,local_sync=0,valid_to=NULL WHERE cardnumber = '$cardnumber'");
                }else{
                    echo "Not Saved";
                }
            }else{
                $this->Card->query("UPDATE cards SET cardbalance = 0,status=1,name='',mobile=0,email='',sync=0,local_sync=0,valid_to=NULL WHERE cardnumber = '$cardnumber'");
            }
        }
    }
    
    public function payment_storecard()
    {
        $cashierid = $_REQUEST['id'];
        $cardno=preg_replace('/\D/', '', $_REQUEST['cardno']);
        $amount = $_REQUEST['amount'];
        $otp = $_REQUEST['otp'];
        $mode = $_REQUEST['mode'];
        $reference_id = $_REQUEST['reference_id'];
        $device_id = $_REQUEST['device_id'];
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id Missing",
            );
            return json_encode($response);
        }
        if($cardno==''){
            $response =array(
                'status'=> false,
                'message'=> "Card no Missing",
            );
            return json_encode($response);
        }
        if($amount==''){
            $response =array(
                'status'=> false,
                'message'=> "Amount Missing",
            );
            return json_encode($response);
        }
        if($mode==''){
            $response =array(
                'status'=> false,
                'message'=> "payment mode Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found or User Deactivated",
            );
            return json_encode($response);
        }else{
            $cashiername=$users['User']['name'];
        }
        
        $transactions = $this->Order_transaction->find('first', array('conditions'=>array('Order_transaction.reference_id'=>$reference_id,'Order_transaction.status'=>1)));
        if(empty($transactions))
        {
            $response =array(
                'status'=> false,
                'message'=> "Transaction not found",
            );
            return json_encode($response);
        }
        
        $card = $this->Card->find('first', array('conditions'=>array('Card.cardnumber'=>$cardno,'Card.status'=>2)));
        if(empty($card))
        {
            $response =array(
                'status'=> false,
                'message'=> "Card not found or Card Deactivated",
            );
            return json_encode($response);
        }else{
            $pinreq=$card['Card']['pin_required'];
            if($pinreq){
                if($otp==''){
                    $response =array(
                        'status'=> false,
                        'message'=> "PIN Missing",
                    );
                    return json_encode($response);
                }
                $card = $this->Card->find('first', array('conditions'=>array('Card.cardnumber'=>$cardno,'Card.pin'=>$otp,'Card.status'=>2)));
                if(empty($card))
                {
                    $response =array(
                        'status'=> false,
                        'message'=> "Wrong PIN ",
                    );
                    return json_encode($response);
                }
            }
            $card = $this->Card->find('first', array('conditions'=>array('Card.cardnumber'=>$cardno,'Card.cardbalance >= '=>$amount)));
            if(empty($card))
            {
                $response =array(
                    'status'=> false,
                    'message'=> "Withdrawal Amount not exist in card ",
                );
                return json_encode($response);
            }
            
            $today = date("Y-m-d H:i:s");
            $currentDate = new DateTime($today);
            $newdate = $currentDate->modify('-2 minute')->format('Y-m-d H:i:s');

            $cardtrackingchk = $this->Cardtracking->query("SELECT * FROM cardtracking where cardnumber='$cardno' and amount='$amount' and created between '$newdate' and '$today' and type=2");
            if(!empty($cardtrackingchk))
            {
                $response =array(
                    'status'=> false,
                    'message'=> "Withdraw blocked for 2 minutes",
                );
                return json_encode($response);
            }
            
            $name=$card['Card']['name'];
            $mobile=$card['Card']['mobile'];
            $oldbal=$card['Card']['cardbalance'];
            $newbal=$oldbal-$amount;
            
            do {
                $txnid = '';
                for ($i = 0; $i < 10; $i++) {
                    $txnid .= rand(0, 9);
                }
                $existingOTP = $this->Cardtracking->find('first', array(
                    'conditions' => array(
                        'txnid' => $txnid
                    )
                ));
            } while ($existingOTP); // Continue generating OTP until it doesn't exist
            
            $data['Cardtracking']=array(
                'cardnumber'=>$cardno,
                'cashierID'=>$cashierid,
                'txnid'=>$txnid,
                'reference_id'=>$reference_id,
                'cashierName'=>$cashiername,
                'customername'=>$name,
                'customerphone'=>$mobile,
                'purpose'=>'withdrawal',
                'oldbalance'=>$oldbal,
                'amount'=>$amount,
                'newbalance'=>$newbal,
                'type'=>2,
                'payment_mode'=>$mode
            );
          
            if($this->Cardtracking->saveAll($data['Cardtracking']))
            {
                $this->Card->query("UPDATE cards SET cardbalance = $newbal,sync=0,local_sync=0 WHERE cardnumber = '$cardno'");
            
                $datas['Order_payment']=array(
                    'reference_id'=>$reference_id,
                    'device_id'=>$device_id,
                    'cashier_id'=>$cashierid,
                    'type'=>8,
                    'type_value'=>'StoreCard',
                    'amount'=>$amount,
                    'remarks'=>$cardno
                );
                if($this->Order_payment->saveAll($datas['Order_payment']))
                {
                    $finalpayment=0;
                    $finalamount=0;
                    $allpayments=$this->Order_payment->query("SELECT sum(amount) as pay_amount FROM `order_payments` WHERE reference_id='$reference_id'");
                    if($allpayments){
                        $finalpayment=$allpayments[0][0]['pay_amount'];
                    }
                    if($transactions){
                        $finalamount=$transactions['Order_transaction']['amount'];
                    }
                    $amount_diff=$finalamount-$finalpayment;
                    if($amount_diff<1){
                        
                        $this->Order_orderhistory->query("UPDATE order_orderhistories SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status = 1");
                        $this->Order_transaction->query("UPDATE order_transactions SET status = 2,payment_mode='StoreCard',sync=0,local_sync=0 WHERE reference_id = '$reference_id'");
                        $this->Order_payment->query("UPDATE order_payments SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id'");
                        $this->Order_tax->query("UPDATE order_tax SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status != 0");
                        
                        $stockupdate=$this->stock_update($reference_id);
                        if(!$stockupdate){
                            $response['status']= true;
                            $response['message']= "Payment Data Saved Successfully..! But stock not updated";
                            $response['full_payment']= true; 
                        }
                        $response['status']= true;
                        $response['message']= "Payment Data Saved Successfully..!";
                        $response['full_payment']= true;
                        
                    }else{
                        $response['status']= true;
                        $response['message']= "Payment Data Saved Successfully..!";
                        $response['full_payment']= false;
                    }            
                }else{
                    $response['status']= false;
                    $response['message']= "Payment Data not saved Error:102";
                    $response['full_payment']= false;
                }
            }else{
                $response =array(
                    'status'=> false,
                    'message'=> "failed",
                );
            }
        }
        return json_encode($response);
    }
    
