    public function cron_booking_alarm()
    {
        $today= date('Y-m-d H:i:s');
        $addDatetime = new DateTime($today);
        $addDatetime->modify("+30 minutes");
        $checkTime = $addDatetime->format('Y-m-d H:i:s');
        
        
        $upcomingBookings =  $this->Online_booking->query("SELECT * FROM `online_bookings` WHERE booking_time between '$today' and '$checkTime' AND status=1 LIMIT 10");
        foreach($upcomingBookings as $upcomingBooking) {
            $tableNumber = $upcomingBooking['online_bookings']['table_number'];
            $tableCheck = $this->Order_table->query("SELECT * FROM `order_tables` WHERE number='$tableNumber' AND status!=1");
            if($tableCheck) {
                $this->Order_table->query("UPDATE order_tables SET is_alert = '1',sync=0,local_sync=0 WHERE number = '$tableNumber'");
            }else{
                $this->Order_table->query("UPDATE order_tables SET is_alert = '0',sync=0,local_sync=0 WHERE number = '$tableNumber'");
            }
        }
        
        $addtime = new DateTime($today);
        $addtime->modify("-5 minutes");
        $check_time = $addtime->format('Y-m-d H:i:s');
        $Bookingupdates = $this->Online_booking->query("SELECT * FROM `online_bookings` WHERE booking_time between '$check_time' and '$today' AND status=1");
        foreach($Bookingupdates as $Bookingupdate) {
            $tableNumber = $Bookingupdate['online_bookings']['table_number'];
            $id = $Bookingupdate['online_bookings']['id'];
            $payment_type = $Bookingupdate['online_bookings']['payment_type'];
            if($payment_type==2){
                $pay_option = $Bookingupdate['online_bookings']['pay_option'];
                $pay_option_value = $Bookingupdate['online_bookings']['pay_option_value'];
            }else{
                $pay_option=1;
                $pay_option_value='postpaid';
            }
            
            $tableCheck = $this->Order_table->query("SELECT * FROM `order_tables` WHERE number='$tableNumber' AND status=1");
            if($tableCheck) {
                $datas['Order_payment']=array(
                    'reference_id'=>$tableCheck[0]['order_tables']['reference_id'],
                    'cashier_id'=>$Bookingupdate['online_bookings']['user_id'],
                    'type'=>$pay_option,
                    'type_value'=>$pay_option_value,
                    'amount'=>$Bookingupdate['online_bookings']['cover_charge'],
                    'remarks'=>$Bookingupdate['online_bookings']['remarks'],
                    'status'=>2
                );
                if($this->Order_payment->saveAll($datas['Order_payment']))
                {
                    $this->Order_table->query("UPDATE order_tables SET status = '2',modified='$today',sync=0,local_sync=0 WHERE number = '$tableNumber'");
                    $this->Online_booking->query("UPDATE online_bookings SET status = '3',modified='$today',sync=0,local_sync=0 WHERE id = '$id'");
                }
            }
        }
        
    }
    
