    public function waiter_list()
    {
        $cashierid = $_REQUEST['id'];
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        $waiters = $this->Order_waiter->find('all', array('conditions'=>array('status'=>1)));
    
        if(empty($waiters))
        {
            $response =array(
                'status'=> false,
                'message'=> "Waiters Not found",
            );
            return json_encode($response);
        }else{
            foreach($waiters as $waiter){
                
                $item[]=array(
                    'id' => $waiter['Order_waiter']['id'],
                    'name' =>  $waiter['Order_waiter']['name'],
                    'phone' =>  $waiter['Order_waiter']['phone'],
                    'pin_number' =>  $waiter['Order_waiter']['pin_number'],
                    'is_pin_required' =>  $waiter['Order_waiter']['is_pin_required'],
                    'status' =>  $waiter['Order_waiter']['status'],
                );
            }
            $response= array('status'=> true,
                'message'=> "success",
                'waiters'=>$item
            );
        }
        return json_encode($response);
    }
    
    public function assign_waiter()
    {
        $response = array();
        $cashierid = $_REQUEST['id'];
        $reference_id = $_REQUEST['table_reference_id'];
        $waiter_id = $_REQUEST['waiter_id'];
        
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id Missing",
            );
            return json_encode($response);
        }
        if($reference_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Reference Id Missing",
            );
            return json_encode($response);
        }
        if($waiter_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Waiter Id Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        $waiters = $this->Order_waiter->find('first', array('conditions'=>array('id'=>$waiter_id,'status'=>1)));
        if(empty($waiters))
        {
            $response =array(
                'status'=> false,
                'message'=> "Waiter Not found",
            );
            return json_encode($response);
        }
        $waiter_name = $waiters['Order_waiter']['name'];
        
        $tables = $this->Order_table->find('first', array('conditions'=>array('Order_table.reference_id'=>$reference_id,'Order_table.status'=> [1, 2])));
        if(empty($tables))
        {
            $response =array(
                'status'=> false,
                'message'=> "Table Not found or not vacant",
            );
            return json_encode($response);
        }    
        
        $this->Order_table->query("UPDATE order_tables SET waiter_id = '$waiter_id',waiter_name='$waiter_name',sync=0,local_sync=0 WHERE reference_id = '$reference_id'");
            
        $response= array('status'=> true,
            'message'=> "success",
        );
    
        return json_encode($response); 
    }
    
    public function ordercomputewithdiscount($txnid=null,$user_id=null,$is_sc=1,$discount=0)
    {
        $response['status']=false;
        $totalservicechg=0;
        $totalprice=0;
        $totaltax1=0;
        $totaltax2=0;
        $totaldiscount=0;
        $sc=0;
        if($is_sc==1){
            $locIdForSc = $this->resolveLocationIdForTxn($txnid, $user_id);
            $sc = $this->getLocationServiceChargeRate($locIdForSc);
        }
        $discq="(((Order_orderhistory.total_price)-(Order_orderhistory.discount))*$discount/100)";
        $priceq="((Order_orderhistory.total_price)-(Order_orderhistory.discount))";
    
        $this->Order_orderhistory->virtualFields = array('tdisc'=>"SUM($discq)",'tservicechg'=>"SUM(($priceq-$discq)*($sc/100))",'tprice'=>"SUM($priceq)",'total_tax'=>"SUM(($priceq+(($priceq-$discq)*($sc/100))-$discq)*((Order_orderhistory.total_tax_percentage)/100))");  
        
        $orderhistories=$this->Order_orderhistory->find('first',array('conditions'=>array('Order_orderhistory.reference_id'=>$txnid,'Order_orderhistory.status !=' =>0),'fields'=>array('tdisc','Order_orderhistory.reference_id','tprice','total_tax','tservicechg')));
        
        if(!empty($orderhistories['Order_orderhistory']['reference_id'])){
            $response['status']=true;
            $totalservicechg=round($orderhistories['Order_orderhistory']['tservicechg'],2);
            $totalprice=round($orderhistories['Order_orderhistory']['tprice'],2);
            $totaltax=round($orderhistories['Order_orderhistory']['total_tax'],2);
            $totaldiscount=round($orderhistories['Order_orderhistory']['tdisc'],2);
            
            //tax update
            $discq="(((Order_orderhistory.price)-(Order_orderhistory.discount))*$discount/100)";
            $priceq="((Order_orderhistory.price)-(Order_orderhistory.discount))";
            
            $taxes=[];
            
            $this->Order_orderhistory->virtualFields = array('tamount'=>"($priceq+(($priceq-$discq)*($sc/100))-$discq)");  
            $neworderhistories=$this->Order_orderhistory->find('all',array('conditions'=>array('Order_orderhistory.reference_id'=>$txnid,'Order_orderhistory.cashier_id'=>$user_id,'Order_orderhistory.status !=' =>0),'fields'=>array('Order_orderhistory.reference_id','tamount','product_id','price')));
            foreach($neworderhistories as $data){
                $reference_id=$data['Order_orderhistory']['reference_id'];
                $product_id=$data['Order_orderhistory']['product_id'];
                $tamount=$data['Order_orderhistory']['tamount'];
                $price=$data['Order_orderhistory']['price'];
                
                
                $taxitem=$this->Order_tax->find('all',array('conditions'=>array('Order_tax.reference_id'=>$txnid,'Order_tax.product_id'=>$product_id,'Order_tax.status !=' =>0)));
                foreach($taxitem as $item){
                    $id=$item['Order_tax']['id'];
                    $tax_id=$item['Order_tax']['tax_id'];
                    $tax_percentage=$item['Order_tax']['tax_percentage'];
                    $quantity=$item['Order_tax']['quantity'];
                    $taxamount=round($tamount*$quantity,2);
                    $taxvalue=round((($tamount*$quantity*$tax_percentage)/100),2);
                    
                    if (isset($taxes[$tax_id])) {
                        $taxes[$tax_id]['tax_value'] += round($taxvalue, 2);
                    } else {
                        // Add new entry if tax_id doesn't exist
                        $taxes[$tax_id] = array(
                            'id' => $id,
                            'tax_id' =>  $item['Order_tax']['tax_id'],
                            'tax_name' => $item['Order_tax']['tax_name'],
                            'tax_percentage' => $tax_percentage,
                            'tax_value' => round($taxvalue, 2)
                        );
                    }
                }
            }
            
            $response['totalservicechg']=$totalservicechg;
            $response['totalprice']=$totalprice;
            $response['totaltax']=$totaltax;
            $response['totaldiscount']=$totaldiscount;
            $response['taxes']=$taxes;
        }
        return $response;
    }
    
    public function billupdate_discount()
    {
        $cashierid = $_REQUEST['id'];
        $ref_id=$_REQUEST['reference_id'];
        $disc=$_REQUEST['discount'];
        $sc = $_REQUEST['service_charge'];
        $device_id = $_REQUEST['device_id'];
        $type = $_REQUEST['type'];
        $table = $_REQUEST['table'];
        $discount_type_value=$disc;
        
        $name='';
        if(isset($_REQUEST['name'])){
            $name=$_REQUEST['name'];
        }
        $phone='';
        if(isset($_REQUEST['phone'])){
            $phone=$_REQUEST['phone'];
        }
        $address='';
        if(isset($_REQUEST['address'])){
            $address=$_REQUEST['address'];
        }
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "User Id Missing",
            );
            return json_encode($response);
        }
        
        if($ref_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Reference id Missing",
            );
            return json_encode($response);
        }
        
        if($disc==''){
            $response =array(
                'status'=> false,
                'message'=> "Discount Missing",
            );
            return json_encode($response);
        }
        
        
        if($sc==''){
            $response =array(
                'status'=> false,
                'message'=> "Service Charge Missing",
            );
            return json_encode($response);
        }
        
        if($device_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Device Id Missing",
            );
            return json_encode($response);
        }
        
        $todayDate = date("Y-m-d");
        
        if($type==0){
            if(!empty($disc)){
                $coup = $this->Coupon->find('first', array('conditions'=>array('Coupon.code'=>$disc,'Coupon.expiry_date >='=>$todayDate,'Coupon.status'=>1)));
                if(empty($coup))
                {
                    $response =array(
                        'status'=> false,
                        'message'=> "Coupon not found Or Coupon Expired",
                    );
                    return json_encode($response);
                }
                $disc=$coup['Coupon']['value'];
            }else{
                $disc=0;
            }
        }
        
        if($type==1){
            $disc=$disc;
        }
        
        if($type==2){
            $subtotals = $this->Order_orderhistory->query("SELECT SUM(total_price) as subtotal FROM `order_orderhistories` WHERE status!=0 and reference_id='$ref_id'");
            if($subtotals){
                $subtotal=$subtotals[0][0]['subtotal'];
                if($subtotal){
                    $disc=(($disc*100)/$subtotal);
                }else{
                    $response =array(
                        'status'=> false,
                        'message'=> "Bill Not Found",
                    );
                    return json_encode($response);
                }
            }else{
                $response =array(
                    'status'=> false,
                    'message'=> "Bill Not Found",
                );
                return json_encode($response);
            }
        }
        
        if($disc>99){
            $response =array(
                'status'=> false,
                'message'=> "Discount is not more than 99%",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        $packagechk = $this->Order_orderhistory->find('first', array('conditions'=>array('Order_orderhistory.reference_id'=>$ref_id,'Order_orderhistory.package'=>1,'Order_orderhistory.status !='=>0)));
        if(empty($packagechk))
        {
            $response =array(
                'status'=> false,
                'message'=> "You can not Merge Discount with package.",
            );
            return json_encode($response);
        }
        
        if($disc>=0){
            $checkdiscount=$this->Order_orderhistory->find('first',array('conditions'=>array('Order_orderhistory.discount > '=>0,'Order_orderhistory.cashier_id'=>$cashierid,'Order_orderhistory.status'=>2,'Order_orderhistory.reference_id'=>$ref_id)));
            if(!empty($checkdiscount)){
                $response['status']= false;
                $response['message']= "Discount can not merge with item level discount";
                return json_encode($response);     
            }
        }else{
            $response['status']= false;
            $response['message']= "please check discount value";
            return json_encode($response);  
        }
        
        if($table){
            $tables=$this->Order_table->find('first',array('conditions'=>array('Order_table.reference_id'=>$ref_id,'Order_table.status'=>3)));
            if(empty($tables)){
                $response['status']= false;
                $response['message']= "Table is not in billing state";
                return json_encode($response);
            }
        }
        
        $txnchk = $this->Order_transaction->find('first', array('conditions'=>array('Order_transaction.reference_id'=>$ref_id, 'Order_transaction.cashier_id'=>$cashierid , 'Order_transaction.status !='=>0)));
        if(empty($txnchk))
        {
            $response= array('status'=> false,
                'message'=> "No Transaction found"
            );
            return json_encode($response);
        }
        
        $orderdata=$this->ordercompute($ref_id,$cashierid,$sc,$disc);
        
        if($orderdata['status'])
        {
            $totalservicechg=$orderdata['totalservicechg'];
            $totalprice=$orderdata['totalprice'];
            $totaltax=$orderdata['totaltax'];
            $totaldiscount=$orderdata['totaldiscount'];
            $totalamount=round((($totalprice+$totaltax+$totalservicechg)-$totaldiscount),0);
            
            $createtime = date('H:i:s');
            $this->Order_transaction->query("UPDATE `order_transactions` SET `price` = '$totalprice',`total_tax`='$totaltax',`servicecharge`='$totalservicechg',`discount`='$totaldiscount',`discount_type`='$type',`discount_type_value`='$discount_type_value',`amount`='$totalamount',`createtime`='$createtime',`name`='$name',`phone`='$phone',`address`='$address',sync=0,local_sync=0 WHERE `order_transactions`.`reference_id` = '$ref_id'");
            
            $response =array(
                'status'=> true,
                'message'=> "Saved",
            );
            return json_encode($response);
        }else{
            $response =array(
                'status'=> false,
                'message'=> "Not Saved",
            );
            return json_encode($response);
        }
    }
    
    
