                                                    'Catalog_modifier.price',
                                                    'Catalog_modifier.weight'
                                                ],
                                                'recursive' => -1
                                            ]);
                                            
                                            $groupMap = [];
                                            
                                            foreach ($modifierss as $mod_item) {
                                                $groupId = $mod_item['Inventory_linking']['component_id'];
                                                
                                                // Initialize group if not already present
                                                if (!isset($groupMap[$groupId])) {
                                                    $groupMap[$groupId] = [
                                                        'id' => $mod_item['Inventory_linking']['id'],
                                                        'modifier_group_id' => $groupId,
                                                        'modifier_group_name' => $mod_item['Inventory_linking']['component_name'],
