                                                        'created' => $mod_item['Inventory_linking']['created'],
                                                        'modifiers' => []
                                                    ];
                                                }
                                            
                                                // Only push modifier if exists
                                                if (!empty($mod_item['Catalog_modifier']['id'])) {
                                                    $foodType = $mod_item['Catalog_modifier']['food_type'] == 1 ? 'Non-Veg' : 'Veg';
                                            
                                                    $modifierData = [
                                                        'id' => $mod_item['Catalog_modifier']['id'],
                                                        'name' => $mod_item['Catalog_modifier']['name'],
                                                        'modifier_name' => $mod_item['IL2']['component_name'],
