                                                        'weight' => $mod_item['Catalog_modifier']['weight'],
                                                        'description' => $mod_item['Catalog_modifier']['description'],
                                                    ];
                                            
                                                    $groupMap[$groupId]['modifiers'][] = $modifierData;
                                                }
                                            }
                                            
                                            // Final group array
                                            $groupmodifier_items = array_values($groupMap);
                
                                            
                                            if($product['Catalog_product']['image']){
                                                $imgpth=Router::url('/', true) . DS . 'uploads' . DS . 'product_images' . DS . $product['Catalog_product']['image'];
                                            }else{
