                                            $start_time='';
                                            $end_date='';
                                            $end_time='';
                                            $days=[];
                                            
                                            $todayDay = date('l', strtotime($todayDate));
                                            $offers = $this->Offer->query("SELECT *
                                                FROM pos_offers
                                                WHERE status = 1
                                                  AND sku_id = $product_id
                                                  AND start_date <= '$todayDate'
                                                  AND end_date >= '$todayDate'
                                                  AND (days IS NULL OR days = '' OR days = 'full_week' OR FIND_IN_SET('$todayDay', days) > 0) order by id desc LIMIT 1 ");
                                                  
                                            if($offers[0]['pos_offers']['offer_id']){
                                                $is_offer='1';
