                                                $end_date=$offers[0]['pos_offers']['end_date'];
                                                $end_time=$offers[0]['pos_offers']['end_time'];
                                                $rawDays = $offers[0]['pos_offers']['days'] ?? '';
                                                $days = !empty($rawDays) ? (($rawDays === 'full_week') ? ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'] : array_values(array_filter(array_map('trim', explode(',', $rawDays))))) : [];
                                            }
                                            
                                            
                                            $item[]=array(
                                                'id' => $product['Catalog_product']['id'],
                                                'name' =>  $product['Catalog_product']['name'],
                                                'cat_id' =>  $product['Catalog_product']['cat_id'],
                                                'cat_name' =>  $product['Catalog_product']['cat_name'],
                                                'description' => $product['Catalog_product']['description'],
                                                'food_type' =>  $product['Catalog_product']['food_type'],
                                                'sort_order' =>  $product['Catalog_product']['sort_order'],
