                                                'serves_people' =>  $product['Catalog_product']['serves_people'],
                                                'type' =>  $product['Catalog_product']['type'],
                                                'image' => $imgpth,
                                                'taxes'=>$taxesitems,
                                                'modifier_group'=>$groupmodifier_items,
                                                'status' =>  $product['Catalog_product']['status'],
