                                                'end_date' =>  $end_date ?? '',
                                                'end_time' =>  $end_time ?? '',
                                                'days' =>  $days
                                            );
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            
            $all_locations[]=array(
                'id' => $location['user_locations']['id'],
                'location_id' =>  $location['user_locations']['location_id'],
                'location_name' =>  $location['user_locations']['location_name']
            );
        }
        
        $printeritems=[];
        $targetStoreId = !empty($users['User']['location_id']) ? $users['User']['location_id'] : '';
        $printerCond = !empty($targetStoreId) ? "status=1 AND store_id='$targetStoreId'" : "status=1";
        $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE $printerCond");
        if(empty($printerss) && !empty($targetStoreId)){
            $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE status=1");
        }
        if(!empty($printerss))
