                    'ip' =>  $dish['catalog_product']['dish_type'],
                    'status' =>  1
                );
            }
        }
        
        $todayDate = date("Y-m-d");
        $carditems[] = [
            'name'=>'today',
            'value'=>$todayDate
        ];
        $carditems[] = [
            'name'=>'unlimited',
            'value'=>'2030-12-31'
        ];
        $carditems[] = [
            'name'=>'custom',
            'value'=>'custom'
        ];
        
        $paymentitems[] = [
            'name'=>'cash'
        ];
        $paymentitems[] = [
            'name'=>'card'
        ];
        $paymentitems[] = [
            'name'=>'online'
        ];
                
        $payment_partner = [];
        if (!isset($this->PaymentPartner)) {
            $this->PaymentPartner = ClassRegistry::init('PaymentPartner');
