        return json_encode($response);
    }
    
    public function transaction_history()
    {
        $cashierid = $_REQUEST['id'];
        
        $startdate = date("Y-m-d");
        $enddate = date("Y-m-d");
            
        if(isset($_REQUEST['from'])){
            $startdate = $_REQUEST['from'];
        }
        if(isset($_REQUEST['to'])){
            $enddate = $_REQUEST['to'];
        }

        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "User Id Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "Cashier not found",
            );
            return json_encode($response);
        }
        
        $location_id = !empty($users['User']['location_id']) ? $users['User']['location_id'] : null;
        $_shiftRange = $this->getShiftDateRange($startdate, $enddate, $location_id);
        $startDatetime = $_shiftRange['startDatetime'];
        $endDatetime   = $_shiftRange['endDatetime'];
        
        $transactionitems=[];
        $transactions = $this->Order_transaction->find('all', array('conditions'=>array('cashier_id'=>$cashierid,'status'=>2,'created BETWEEN ? AND ?' => array($startDatetime, $endDatetime)),'order' => array('Order_transaction.id' => 'DESC')));
        if(!empty($transactions))
        {
            foreach($transactions as $orders){
                if(!$orders['Order_transaction']['remarks']){
                    $orders['Order_transaction']['remarks']='';
                }
                $finalamount=$orders['Order_transaction']['amount'];
                $cashierid=$orders['Order_transaction']['cashier_id'];
                $reference_id=$orders['Order_transaction']['reference_id'];
                $store_id=$orders['Order_transaction']['store_id'];
                
                $discper = $this->Order_tax->query("SELECT discount_percentage FROM `order_tax` WHERE reference_id='$reference_id' and status!=0 and discount_percentage!=0 limit 1");
                if(!empty($discper))
                {
                    $discount_percentage=number_format($discper[0]['order_tax']['discount_percentage'],2);
                }
                if(!isset($discount_percentage)){
                    $discount_percentage="0";
                }
                $payment_mode='';
                $pay_mode = $this->Order_payment->query("SELECT GROUP_CONCAT(type_value) as payment FROM `order_payments` WHERE reference_id='$reference_id' and store_id='$store_id' and status=2");
                if(!empty($pay_mode))
                {
                    $payment_mode=$pay_mode[0][0]['payment'];
                }
                
        $orderitems=[];
        $orderss = $this->Order_orderhistory->query("SELECT id,reference_id,group_id,cashier_id,category,category_name,kds,product_id,product_name,SUM(quantity) as quantity,price,sum(total_tax) as total_tax,sum(total_tax_percentage) as total_tax_percentage,sum(total_price) as total_price,SUM(discount) as discount,table_number,remarks,device_id,status,created FROM `order_orderhistories` WHERE reference_id='$reference_id' and store_id='$store_id' and status!=0 group BY product_id");
        if(!empty($orderss))
        {
            foreach($orderss as $items){
                if(!isset($items['order_orderhistories']['remarks'])){
                    $items['order_orderhistories']['remarks']='';
                }
                $orderitems[]=array(
                    'id' => $items['order_orderhistories']['id'],
                    'reference_id' =>  $items['order_orderhistories']['reference_id'],
                    'cashier_id' =>  $items['order_orderhistories']['cashier_id'],
                    'group_id' =>  $items['order_orderhistories']['group_id'],
                    'category' =>  $items['order_orderhistories']['category'],
                    'category_name' =>  $items['order_orderhistories']['category_name'],
                    'kds' =>  $items['order_orderhistories']['kds'],
                    'product_id' =>  $items['order_orderhistories']['product_id'],
                    'product_name' =>  $items['order_orderhistories']['product_name'],
                    'quantity' =>  $items[0]['quantity'],
                    'price' =>  $items['order_orderhistories']['price'],
                    'total_tax' =>  $items[0]['total_tax'],
                    'total_price' =>  $items[0]['total_price'],
                    'discount' =>  $items[0]['discount'],
                    'table_number' =>  $items['order_orderhistories']['table_number'],
                    'remarks' =>  $items['order_orderhistories']['remarks'],
                    'status' =>  $items['order_orderhistories']['status'],
                    'created' =>  $items['order_orderhistories']['created']
                );
            }
        }
                
                $transactionitems[]=array(
                    'id' => $orders['Order_transaction']['id'],
                    'reference_id' =>  $orders['Order_transaction']['reference_id'],
                    'orderno' =>  $orders['Order_transaction']['orderno'],
                    'device_id' =>  $orders['Order_transaction']['device_id'],
                    'cashier_id' =>  $orders['Order_transaction']['cashier_id'],
                    'table_number' =>  $orders['Order_transaction']['table_number'],
                    'price' =>  $orders['Order_transaction']['price'],
                    'total_tax' =>  $orders['Order_transaction']['total_tax'],
                    'servicecharge' =>  $orders['Order_transaction']['servicecharge'],
                    'discount' =>  $orders['Order_transaction']['discount'],
                    'discount_percentage' =>  $discount_percentage,
                    'discount_type' =>  $orders['Order_transaction']['discount_type'],
                    'discount_type_value' =>  $orders['Order_transaction']['discount_type_value'],
                    'delivery_charge' =>  $orders['Order_transaction']['delivery_charge'],
                    'packing_charge' =>  $orders['Order_transaction']['packing_charge'],
                    'amount' =>  $orders['Order_transaction']['amount'],
                    'round' =>  $orders['Order_transaction']['round'],
                    'name' =>  $orders['Order_transaction']['name'],
                    'phone' =>  $orders['Order_transaction']['phone'],
                    'address' =>  $orders['Order_transaction']['address'],
                    'remarks' =>  $orders['Order_transaction']['remarks'],
                    'status' =>  $orders['Order_transaction']['status'],
                    'tokenno' =>  $orders['Order_transaction']['tokenno'],
                    'createtime' =>  $orders['Order_transaction']['createtime'],
                    'created' =>  $orders['Order_transaction']['created'],
                    'payment_mode' =>$payment_mode??'',
                    'items' =>$orderitems
                );
            }
        }
        
        $cashier_name='';
        $cashname=$this->User->query("SELECT name FROM `users` WHERE id='$cashierid'");
        if($cashname){
           $cashier_name =$cashname[0]['users']['name'];
        }
        
        $response= array('status'=> true,
                'message'=> "success",
                'cashier_name'=>$cashier_name,
                'transactions'=>$transactionitems
            );
        return json_encode($response);
    }
    
    public function transaction_detail()
