    public function insert_manager_track()
    {
        $response['status']= false;
        $response['message']= "fail";
        
        $id = $_REQUEST['id'];
        if($id==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id is Missing",
            );
            return json_encode($response);
        }
        
        $reference_id = $_REQUEST['reference_id'];
        if($reference_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Reference Id is Missing",
            );
            return json_encode($response);
        }
        
        $pin = $_REQUEST['pin'];
        if($pin==''){
            $response =array(
                'status'=> false,
                'message'=> "Manager PIN is Missing",
            );
            return json_encode($response);
        }
        
        $type = $_REQUEST['type'];
        $remarks = $_REQUEST['remarks'];
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$id,'User.status'=>1,'User.role'=>'cashier')));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "Cashier not found",
            );
            return json_encode($response);
        }
        $location_id=$users['User']['location_id'];
        $location_name=$users['User']['location_name'];
        
        $userpinchk = $this->User->find('first', array('conditions'=>array('User.location_id'=>$location_id,'User.status'=>1,'User.role'=>'manager','User.pin'=>$pin)));
        if(empty($userpinchk))
        {
            $response =array(
                'status'=> false,
                'message'=> "Manager Pin not found for this location",
            );
            return json_encode($response);
        }
        $datas['User_track']=array(
            'user_id'=>$userpinchk['User']['id'],
            'reference_id'=>$reference_id,
            'location_id'=>$location_id,
            'location_name'=>$location_name,
            'type'=>$type,
            'remarks'=>$remarks
        );
        if($this->User_track->saveAll($datas['User_track']))
        {
            $response['status']= true;
            $response['message']= "Manager Track Saved Successfully..!";
        }else{
            $response['status']= false;
            $response['message']= "Manager Track not Saved..!";
        }
        return json_encode($response);
    }
    
    
