    public function merge_table()
    {
        $cashierid       = $_REQUEST['id']                ?? '';
        $main_table_id   = $_REQUEST['main_table_ref_id'] ?? '';
        $merged_table_id = $_REQUEST['merge_table_ref_id'] ?? '';
    
        if (empty($cashierid)) {
            return json_encode(['status' => false, 'message' => "Cashier Id Missing"]);
        }
        if (empty($main_table_id)) {
            return json_encode(['status' => false, 'message' => "Main Table Id Missing"]);
        }
        if (empty($merged_table_id)) {
            return json_encode(['status' => false, 'message' => "Merge Table Id Missing"]);
        }
        if($main_table_id==$merged_table_id){
            return json_encode(['status' => false, 'message' => "Main table and Merge Table Not Same"]);
        }
        $user = $this->User->find('first', [
            'conditions' => ['User.id' => $cashierid, 'User.status' => 1],
            'fields' => ['User.id'],
            'recursive' => -1
        ]);
        if (empty($user)) {
            return json_encode(['status' => false, 'message' => "User not found"]);
        }
    
        $mainTable = $this->Order_table->find('first', [
            'conditions' => ['Order_table.reference_id' => $main_table_id, 'Order_table.status' => 2],
            'fields' => ['Order_table.id', 'Order_table.reference_id', 'Order_table.number'],
            'recursive' => -1
        ]);
        if (empty($mainTable)) {
            return json_encode(['status' => false, 'message' => "Main Table Not found Or Not Booked...!"]);
        }
        
        $mergeTable = $this->Order_table->find('first', [
            'conditions' => ['Order_table.reference_id' => $merged_table_id, 'Order_table.status IN' => [1,2]],
            'fields' => ['Order_table.id', 'Order_table.reference_id', 'Order_table.number'],
            'recursive' => -1
        ]);
        if (empty($mergeTable)) {
            return json_encode(['status' => false, 'message' => "Merge Table Not found...!"]);
        }
        
        $trackingData = [
            'main_table_id'      => $mainTable['Order_table']['id'],
            'main_table_number'  => $mainTable['Order_table']['number'],
            'main_table_ref_id'  => $mainTable['Order_table']['reference_id'],
            'merged_table_id'    => $mergeTable['Order_table']['id'],
            'merged_table_number'=> $mergeTable['Order_table']['number'],
            'merged_table_ref_id'=> $mergeTable['Order_table']['reference_id']
        ];
    
        if ($this->Order_table_tracking->save($trackingData)) {
            
            $this->Order_table->updateAll(
                array(
                    'Order_table.status' => 4,
                    'Order_table.sync' => 0,
                    'Order_table.local_sync' => 0
                ),
                array(
                    'Order_table.reference_id' => $merged_table_id
                )
            );
            
            return json_encode(['status' => true, 'message' => "Table Merged Successfully..!"]);
        }
    
        return json_encode(['status' => false, 'message' => "Table Merging not successful..!"]);
    }

    public function release_merge_table()
    {
        $cashierid = $_REQUEST['id'] ?? '';
        $merged_table_id = $_REQUEST['merge_table_ref_id'] ?? '';
    
        if (empty($cashierid)) {
            return json_encode(['status' => false, 'message' => "Cashier Id Missing"]);
        }
        if (empty($merged_table_id)) {
            return json_encode(['status' => false, 'message' => "Merge Table Id Missing"]);
        }
    
        $user = $this->User->find('first', [
            'conditions' => ['User.id' => $cashierid, 'User.status' => 1],
            'fields' => ['User.id'], // optimize field selection
            'recursive' => -1
        ]);
        if (empty($user)) {
            return json_encode(['status' => false, 'message' => "User not found"]);
        }
    
        $mergedTable = $this->Order_table->find('first', [
            'conditions' => ['Order_table.reference_id' => $merged_table_id, 'Order_table.status' => 4],
            'fields' => ['Order_table.id'],
            'recursive' => -1
        ]);
        if (empty($mergedTable)) {
            return json_encode(['status' => false, 'message' => "Merge Tables Not found"]);
        }
    
        $this->Order_table_tracking->updateAll(
            array(
                'Order_table_tracking.status' => 0,
                'Order_table_tracking.sync' => 0,
                'Order_table_tracking.local_sync' => 0
            ),
            array(
                'Order_table_tracking.merged_table_ref_id' => $merged_table_id
            )
        );

    
        // Generate unique reference_id
        do {
            $pin = 'TX' . $cashierid . date('Y') . uniqid();
        } while ($this->Order_table->hasAny(['Order_table.reference_id' => $pin]));
    
        $this->Order_table->updateAll(
            array(
                'Order_table.status' => 1,
                'Order_table.reference_id' => "'" . $pin . "'",
                'Order_table.sync' => 0,
                'Order_table.local_sync' => 0
            ),
            array(
                'Order_table.reference_id' => $merged_table_id
            )
        );

    
        return json_encode(['status' => true, 'message' => "Table Released Successfully..!"]);
    }
    
    public function kds_discount()
    {
        $cashierid = $_REQUEST['id'];
        $ref_id=$_REQUEST['reference_id'];
        $disc=$_REQUEST['discount'];
        $sc = $_REQUEST['service_charge'];
        $device_id = $_REQUEST['device_id'];
        $type = $_REQUEST['type'];
        $table = $_REQUEST['table'];
        $discount_type_value=$disc;
        $dish_type = $_REQUEST['kds'];
        // [DISCOUNT-DEBUG CONTROLLER] kds_discount entry
        error_log('[DISCOUNT-DEBUG CONTROLLER kds_discount] discount='.$disc.' type='.$type.' service_charge='.$sc.' reference_id='.$_REQUEST['reference_id'].' cashier_id='.$_REQUEST['id'].' kds='.$dish_type);
        
        $name='';
        if(isset($_REQUEST['name'])){
            $name=$_REQUEST['name'];
        }
        $phone='';
        if(isset($_REQUEST['phone'])){
            $phone=$_REQUEST['phone'];
        }
        $address='';
        if(isset($_REQUEST['address'])){
            $address=$_REQUEST['address'];
        }
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "User Id Missing",
            );
            return json_encode($response);
        }
        
        if($ref_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Reference id Missing",
            );
            return json_encode($response);
        }
        
        if($disc==''){
            $response =array(
                'status'=> false,
                'message'=> "Discount Missing",
            );
            return json_encode($response);
        }
        
        
        if($sc==''){
            $response =array(
                'status'=> false,
                'message'=> "Service Charge Missing",
            );
            return json_encode($response);
        }
        
        if($device_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Device Id Missing",
            );
            return json_encode($response);
        }
        if($dish_type==''){
            $response =array(
                'status'=> false,
                'message'=> "Dish Type Missing",
            );
            return json_encode($response);
        }
        
        $todayDate = date("Y-m-d");
        
        if($dish_type=='all'){
            $kdss = $this->Catalog_product->query("SELECT GROUP_CONCAT(kds) as kds FROM `catalog_product` WHERE id IN (SELECT product_id FROM `order_orderhistories` WHERE status!=0 and reference_id='$ref_id' group BY kds) and status=1");
            if(!empty($kdss))
            {
                foreach($kdss as $kdslist){
                    $kds=$kdslist[0]['kds'];
                }
            }
        }else{
            $kdss = $this->Catalog_product->query("SELECT GROUP_CONCAT(kds) as kds FROM `catalog_product` WHERE id IN (SELECT product_id FROM `order_orderhistories` WHERE status!=0 and reference_id='$ref_id' group BY kds) and status=1  and dish_type=$dish_type");
            if (!empty($kdss) && !empty($kdss[0][0]['kds']))
            {
                foreach($kdss as $kdslist){
                    $kds=$kdslist[0]['kds'];
                }
            }else{
                $response =array(
                    'status'=> false,
                    'message'=> "No kds found for this dish type",
                );
                return json_encode($response);
            }
        }
        
        if($type==0){
            if(!empty($disc)){
                $coup = $this->Coupon->find('first', array('conditions'=>array('Coupon.code'=>$disc,'Coupon.expiry_date >='=>$todayDate,'Coupon.status'=>1)));
                if(empty($coup))
                {
                    $response =array(
                        'status'=> false,
                        'message'=> "Coupon not found Or Coupon Expired",
                    );
                    return json_encode($response);
                }
                $disc=$coup['Coupon']['value'];
            }else{
                $disc=0;
            }
        }
        
        if($type==1){
            error_log('[DISCOUNT-DEBUG kds_discount] entering PERCENTAGE branch discount='.$disc);
            $disc=$disc;
        }
        
        if($type==2){
            error_log('[DISCOUNT-DEBUG kds_discount] entering FLAT branch flat_amount='.$disc);
            if($dish_type=='all'){
                $subtotals = $this->Order_orderhistory->query("SELECT SUM(total_price) as subtotal FROM `order_orderhistories` WHERE status!=0 and reference_id='$ref_id'");
            }else{
                $subtotals = $this->Order_orderhistory->query("SELECT SUM(total_price) as subtotal FROM `order_orderhistories` WHERE status!=0 and reference_id='$ref_id' and kds IN ($kds)");
            }
            if($subtotals){
                $subtotal=$subtotals[0][0]['subtotal'];
                if($subtotal){
                    $disc=(($disc*100)/$subtotal);
                    error_log('[DISCOUNT-DEBUG kds_discount] FLAT->PCT conversion: flat_amount='.$discount_type_value.' subtotal(total_price)='.$subtotal.' converted_pct='.$disc);
                }else{
                    $response =array(
                        'status'=> false,
                        'message'=> "Bill Not Found",
                    );
                    return json_encode($response);
                }
            }else{
                $response =array(
                    'status'=> false,
                    'message'=> "Bill Not Found",
                );
                return json_encode($response);
            }
        }
        if($disc>99){
            $response =array(
                'status'=> false,
                'message'=> "Discount is not more than 99%",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        $kdsarray = explode(",", $kds);

        
        if($dish_type!='all'){
            $kdsStoreId = !empty($users['User']['location_id']) ? $users['User']['location_id'] : '';
            $kdsConditions = array('Pos_printer.kds'=>$kdsarray, 'Pos_printer.status'=>1);
            if (!empty($kdsStoreId)) {
                $kdsConditions['Pos_printer.store_id'] = $kdsStoreId;
            }
            $kdschk = $this->Pos_printer->find('first', array('conditions'=>$kdsConditions));
            if(empty($kdschk) && !empty($kdsStoreId)) {
                $kdschk = $this->Pos_printer->find('first', array('conditions'=>array('Pos_printer.kds'=>$kdsarray, 'Pos_printer.status'=>1)));
            }
            if(empty($kdschk))
            {
                $response =array(
                    'status'=> false,
                    'message'=> "KDS not found",
                );
                return json_encode($response);
            }
        }
        if($dish_type!='all'){
            $kdschk = $this->Order_orderhistory->find('first', array('conditions'=>array('Order_orderhistory.reference_id'=>$ref_id,'Order_orderhistory.kds'=>$kdsarray,'Order_orderhistory.status !='=>0)));
        }else{
            $kdschk = $this->Order_orderhistory->find('first', array('conditions'=>array('Order_orderhistory.reference_id'=>$ref_id,'Order_orderhistory.status !='=>0)));
        }
        if(empty($kdschk))
        {
            $response =array(
                'status'=> false,
                'message'=> "No Item found for this KDS.",
            );
            return json_encode($response);
        }
        
        $packagechk = $this->Order_orderhistory->find('first', array('conditions'=>array('Order_orderhistory.reference_id'=>$ref_id,'Order_orderhistory.package'=>1,'Order_orderhistory.status !='=>0)));
        if(!empty($packagechk))
        {
            $response =array(
                'status'=> false,
                'message'=> "You can not Merge Discount with package.",
            );
            return json_encode($response);
        }
        
        if($disc>=0){
            $checkdiscount=$this->Order_orderhistory->find('first',array('conditions'=>array('Order_orderhistory.discount > '=>0,'Order_orderhistory.cashier_id'=>$cashierid,'Order_orderhistory.status'=>2,'Order_orderhistory.reference_id'=>$ref_id)));
            if(!empty($checkdiscount)){
                $response['status']= false;
                $response['message']= "Discount can not merge with item level discount";
                return json_encode($response);     
            }
        }else{
            $response['status']= false;
            $response['message']= "please check discount value";
            return json_encode($response);  
        }
        
        if($table){
            $tables=$this->Order_table->find('first',array('conditions'=>array('Order_table.reference_id'=>$ref_id,'Order_table.status'=>3)));
            if(empty($tables)){
                $response['status']= false;
                $response['message']= "Table is not in billing state";
                return json_encode($response);
            }
        }
        
        $txnchk = $this->Order_transaction->find('first', array('conditions'=>array('Order_transaction.reference_id'=>$ref_id, 'Order_transaction.cashier_id'=>$cashierid)));
        if(empty($txnchk))
        {
            $response= array('status'=> false,
                'message'=> "No Transaction found"
            );
            return json_encode($response);
        }
        
        if($dish_type=='all'){
            error_log('[DISCOUNT-DEBUG BEFORE COMPUTE kds_discount] disc_pct='.$disc.' type='.$type.' sc='.$sc.' dish=all ref='.$ref_id);
            $orderdata=$this->ordercompute($ref_id,$cashierid,$sc,$disc);
        }else{
            $this->Order_tax->query("UPDATE order_tax SET discount_percentage='0',sync=0,local_sync=0 WHERE reference_id = '$ref_id'");
            error_log('[DISCOUNT-DEBUG BEFORE COMPUTE kds_discount] disc_pct='.$disc.' type='.$type.' sc='.$sc.' dish='.$dish_type.' ref='.$ref_id);
            $orderdata=$this->ordercomputewithkds($ref_id,$cashierid,$sc,$disc,$dish_type);
        }
        if($orderdata['status'])
        {
            $totalservicechg=$orderdata['totalservicechg'];
            $totalprice=$orderdata['totalprice'];
            $totaltax=$orderdata['totaltax'];
            $totaldiscount=$orderdata['totaldiscount'];
            $totalamount=round((($totalprice+$totaltax+$totalservicechg)-$totaldiscount),0);
            error_log('[DISCOUNT-DEBUG AFTER COMPUTE kds_discount] subtotal='.$totalprice.' tax='.$totaltax.' servicecharge='.$totalservicechg.' discount='.$totaldiscount.' discount_type='.$type.' final_amount='.$totalamount);
            error_log('[DISCOUNT-DEBUG DB WRITE kds_discount] discount='.$totaldiscount.' discount_type='.$type.' discount_type_value='.$discount_type_value.' amount='.$totalamount.' price='.$totalprice.' tax='.$totaltax.' servicecharge='.$totalservicechg);
            
            $createtime = date('H:i:s');
            $this->Order_transaction->query("UPDATE `order_transactions` SET `price` = '$totalprice',`total_tax`='$totaltax',`servicecharge`='$totalservicechg',`discount`='$totaldiscount',`discount_type`='$type',`discount_type_value`='$discount_type_value',`amount`='$totalamount',`createtime`='$createtime',`name`='$name',`phone`='$phone',`address`='$address',sync=0,local_sync=0 WHERE `order_transactions`.`reference_id` = '$ref_id'");
            
            $response =array(
                'status'=> true,
                'message'=> "Saved",
            );
            error_log('[DISCOUNT-DEBUG RESPONSE kds_discount] discount='.$totaldiscount.' amount='.$totalamount.' price='.$totalprice.' tax='.$totaltax.' servicecharge='.$totalservicechg);
            return json_encode($response);
        }
        
        else{
            $response =array(
                'status'=> false,
                'message'=> "Not Saved",
            );
            return json_encode($response);
        }
    }
    public function ordercomputewithkds($txnid = null, $user_id = null, $is_sc = 1, $discount = 0, $dish = 0)
    {
        $response = ['status' => false];
    
        if (empty($txnid)) {
            return $response;
        }
    
        $sc = 0;
        if ($is_sc == 1) {
            $locIdForSc = $this->resolveLocationIdForTxn($txnid, $user_id);
            $sc = $this->getLocationServiceChargeRate($locIdForSc);
        }
        $kds = (int)$dish; // dish type to filter discount
    
        // STEP 1: FETCH ALL ORDER ITEMS
        $items = $this->Order_orderhistory->find('all', [
            'conditions' => [
                'Order_orderhistory.reference_id' => $txnid,
                'Order_orderhistory.status !=' => 0
            ],
            'fields' => [
                'Order_orderhistory.id',
                'Order_orderhistory.product_id',
                'Order_orderhistory.dish_type',
                'Order_orderhistory.price',
                'Order_orderhistory.quantity',
                'Order_orderhistory.discount',
                'Order_orderhistory.total_tax_percentage'
            ],
            'recursive' => -1
        ]);
    
        if (empty($items)) return $response;
    
        // STEP 2: CALCULATE TOTALS
        $totalprice = $totaldiscount = $totalservicechg = $totaltax = 0;
        error_log('[DISCOUNT-DEBUG BEFORE COMPUTE ordercomputewithkds] disc_pct='.$discount.' sc='.$sc.' kds='.$kds.' txnid='.$txnid);
    
        foreach ($items as $row) {
            $item = $row['Order_orderhistory'];
    
            $basePrice = ($item['price'] * $item['quantity']) - $item['discount'];
            $applyDiscount = ($item['dish_type'] == $kds);
            $itemDiscount = $applyDiscount ? ($basePrice * $discount) / 100 : 0;
    
            $priceAfterDiscount = $basePrice - $itemDiscount;
            $serviceCharge = ($priceAfterDiscount * $sc) / 100;
            $taxableAmount = $priceAfterDiscount + $serviceCharge;
            $taxValue = ($taxableAmount * $item['total_tax_percentage']) / 100;
    
            error_log('[DISCOUNT-DEBUG ordercomputewithkds item] id='.$item['id'].' dish_type='.$item['dish_type'].' price='.$item['price'].' qty='.$item['quantity'].' basePrice='.$basePrice.' applyDiscount='.($applyDiscount?'yes':'no').' itemDiscount='.$itemDiscount.' priceAfterDisc='.$priceAfterDiscount.' sc='.$serviceCharge.' tax='.$taxValue);
    
            $totalprice += $basePrice;
            $totaldiscount += $itemDiscount;
            $totalservicechg += $serviceCharge;
            $totaltax += $taxValue;
        }
        // STEP 3: UPDATE ORDER TAX (RESET + APPLY)
        $taxRows = $this->Order_tax->find('all', [
            'conditions' => [
                'Order_tax.reference_id' => $txnid,
                'Order_tax.status !=' => 0
            ],
            'fields' => [
                'Order_tax.id',
                'Order_tax.orderhistory_id',
                'Order_tax.tax_percentage',
                'Order_tax.quantity'
            ],
            'recursive' => -1
        ]);
    
        // Build a lookup map
        $itemMap = [];
        foreach ($items as $itemRow) {
            $itemMap[$itemRow['Order_orderhistory']['id']] = $itemRow['Order_orderhistory'];
        }
    
        foreach ($taxRows as $row) {
            $tax = $row['Order_tax'];
    
            if (!isset($itemMap[$tax['orderhistory_id']])) continue;
    
            $item = $itemMap[$tax['orderhistory_id']];
    
            $basePrice = ($item['price'] * $tax['quantity']) - $item['discount'];
    
            // Use the item’s dish_type to determine discount
            $applyDiscount = ($item['dish_type'] == $kds);
            $itemDiscount = $applyDiscount ? ($basePrice * $discount) / 100 : 0;
    
            $priceAfterDiscount = $basePrice - $itemDiscount;
            $serviceCharge = ($priceAfterDiscount * $sc) / 100;
            $taxablePrice = round($priceAfterDiscount + $serviceCharge, 2);
            $taxValue = round(($taxablePrice * $tax['tax_percentage']) / 100, 2);
            $discountPercent = $applyDiscount ? (float)$discount : 0.0;
    
            // Update tax row
            try {
                $this->Order_tax->updateAll(
                    [
                        'taxable_price' => (float)$taxablePrice,
                        'tax_value' => (float)$taxValue,
                        'discount_percentage' => $discountPercent,
                        'dish_type' => (int)$item['dish_type'], // crucial: copy dish_type from item
                        'sync' => 0,
                        'local_sync' => 0
                    ],
                    ['id' => (int)$tax['id']]
                );
                
                $db = $this->Order_tax->getDataSource();
                if ($db->lastError()) {
                    $this->trackUser($txnid,$user_id,'order_tax_sql_error1',[
                        'tax_id'=>$tax['id'],
                        'error'=>$db->lastError()
                    ]);
                }
            } catch (Exception $e) {
                $this->trackUser($txnid, $user_id, 'order_tax_update_error', [
                    'tax_id' => $tax['id'],
                    'error' => $e->getMessage()
                ]);
            }
        }
    
        // STEP 4: RETURN TOTALS
        return [
            'status' => true,
            'totalprice' => round($totalprice, 2),
            'totaldiscount' => round($totaldiscount, 2),
            'totalservicechg' => round($totalservicechg, 2),
            'totaltax' => round($totaltax, 2)
        ];
    }

    public function save_customer_details()
    {
        $cashierid = $_REQUEST['id'] ?? '';
        $ref_id = $_REQUEST['ref_id'] ?? '';
        $name = $_REQUEST['name'] ?? '';
        $phone = trim($_REQUEST['phone'] ?? '');
        $address = $_REQUEST['address'] ?? '';
        $pax = $_REQUEST['pax'] ?? 1;
    
        if (empty($cashierid)) {
            return json_encode(['status' => false, 'message' => "Cashier Id Missing"]);
        }
        if (empty($ref_id)) {
            return json_encode(['status' => false, 'message' => "Table Ref Id Missing"]);
        }
        if (empty($phone)) {
            return json_encode(['status' => false, 'message' => "Customer Mobile Missing"]);
        }
        if (!preg_match('/^[6-9][0-9]{9}$/', $phone)) {
            return json_encode(['status' => false, 'message' => "Invalid phone number. Must be 10 digits starting with 9, 8, 7, or 6"]);
        }
        if (empty($pax)) {
            return json_encode(['status' => false, 'message' => "PAX Missing"]);
        }
    
        $user = $this->User->find('first', [
            'conditions' => ['User.id' => $cashierid, 'User.status' => 1],
            'fields' => ['User.id'], // optimize field selection
            'recursive' => -1
        ]);
        if (empty($user)) {
            return json_encode(['status' => false, 'message' => "User not found"]);
        }
    
        $tablechk = $this->Order_table->find('first', [
            'conditions' => ['Order_table.reference_id' => $ref_id],
            'fields' => ['Order_table.id','Order_table.pax'],
            'recursive' => -1
        ]);
        if (empty($tablechk)) {
            return json_encode(['status' => false, 'message' => "Table Not found"]);
        }
        $table_pax = $tablechk['Order_table']['pax'];
        
        if($pax>$table_pax){
            return json_encode(['status' => false, 'message' => "PAX is not more then table limit."]);
        }
        
        $this->Order_table->updateAll(
            [
                'Order_table.customer_name' => "'" . addslashes($name) . "'",
                'Order_table.customer_phone' => "'" . addslashes($phone) . "'",
                'Order_table.customer_address' => "'" . addslashes($address) . "'",
                'Order_table.customer_pax' => "'" . addslashes($pax) . "'",
                'Order_table.sync'             => 0,
                'Order_table.local_sync'       => 0
            ],
            ['Order_table.reference_id' => $ref_id]
        );

    
        return json_encode(['status' => true, 'message' => "Customer Details updated Successfully..!"]);
    }
    
    public function get_customer_details()
    {
        $cashierid = $_REQUEST['id'] ?? '';
        $ref_id = $_REQUEST['ref_id'] ?? '';
    
        if (empty($cashierid)) {
            return json_encode(['status' => false, 'message' => "Cashier ID missing"]);
        }
    
        if (empty($ref_id)) {
            return json_encode(['status' => false, 'message' => "Table reference ID missing"]);
        }
    
        // Check if user exists
        $user = $this->User->find('first', [
            'conditions' => ['User.id' => $cashierid, 'User.status' => 1],
            'fields' => ['User.id'],
            'recursive' => -1
        ]);
    
        if (empty($user)) {
            return json_encode(['status' => false, 'message' => "User not found"]);
        }
    
        // Get table details
        $tablechk = $this->Order_table->find('first', [
            'conditions' => ['Order_table.reference_id' => $ref_id],
            'fields' => ['Order_table.id', 'Order_table.customer_name', 'Order_table.customer_phone', 'Order_table.customer_address', 'Order_table.customer_pax', 'Order_table.status'],
            'recursive' => -1
        ]);
    
        if (empty($tablechk)) {
            return json_encode(['status' => false, 'message' => "Table not found"]);
        }
        
        $name    = trim($tablechk['Order_table']['customer_name']);
        $phone   = trim($tablechk['Order_table']['customer_phone']);
        $address = trim($tablechk['Order_table']['customer_address']);
        if($tablechk['Order_table']['status']==1){
            $customer_pax = '';
        }else{
            $customer_pax = trim($tablechk['Order_table']['customer_pax']);
        }
    
        return json_encode([
            'status' => true,
            'message' => "Customer Found.",
            'name' => $name,
            'phone' => $phone,
            'address' => $address,
            'pax' => $customer_pax
        ]);
    }

