    //takeaway APIS
    public function create_takeaway_table()
    {
        $cashierid = $_REQUEST['id'] ?? '';
        $name = $_REQUEST['name'] ?? '';
        $phone = $_REQUEST['phone'] ?? '';
        $address = $_REQUEST['address'] ?? '';
        
        if (empty($cashierid)) {
            return json_encode(['status' => false, 'message' => "Cashier Id Missing"]);
        }
        if (empty($name)) {
            return json_encode(['status' => false, 'message' => "Customer Name Missing"]);
        }
        if (empty($phone)) {
            return json_encode(['status' => false, 'message' => "Customer Phone Missing"]);
        }
        $user = $this->User->find('first', [
            'conditions' => ['User.id' => $cashierid, 'User.status' => 1],
            'recursive' => -1
        ]);
        if (empty($user)) {
            return json_encode(['status' => false, 'message' => "User not found"]);
        }
        
        $tablechk = $this->Order_table->find('first', [
            'conditions' => ['Order_table.number' => $phone],
            'fields' => ['Order_table.id'],
            'recursive' => -1
        ]);
        if (!empty($tablechk)) {
            return json_encode(['status' => false, 'message' => "Table Already Exist"]);
        }
        
        do {
            $txnid = '';
            for ($i = 0; $i < 10; $i++) {
                $txnid .= rand(1, 9);
            }
            $existingOTP = $this->Order_transaction->find('first', array(
                'conditions' => array(
                    'reference_id' => $txnid
                )
            ));
        } while ($existingOTP); // Continue generating OTP until it doesn't exist
        
        $data['Order_table']=array(
            'number'=>$phone,
            'reference_id'=>$txnid,
            'cover_charge'=>0,
            'weekend_charge'=>0,
            'pax'=>0,
            'customer_name'=>$name,
            'customer_phone'=>$phone,
            'customer_address'=>$address,
            'location_id'=>$user['User']['location_id'],
            'location_name'=>$user['User']['location_name'],
            'is_takeaway'=>1
        );
      
        if($this->Order_table->saveAll($data['Order_table']))
        {
            $last_id = $this->Order_table->id; // ✅ last inserted ID
            
            return json_encode(['id' => $phone,'number' => $phone,'reference_id' => $txnid,'is_takeaway' => '1','status' => true, 'message' => "Customer Details updated Successfully..!"]);
        }else{
            return json_encode(['status' => false, 'message' => "Customer Details Not updated Successfully..!"]);
        }
        
    }
    
    public function takeaway_table_list()
    {
        $cashierid = $_REQUEST['id'];
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        if(isset($_REQUEST['status'])){
            $tbles = $this->Order_table->find('all', array('conditions'=>array('status'=>$_REQUEST['status'],'is_takeaway'=>1)));
        }else{
            $tbles = $this->Order_table->find('all', array('conditions'=>array('status !='=>0,'is_takeaway'=>1)));
        }
        if(empty($tbles))
        {
            $response =array(
                'status'=> false,
                'message'=> "Tables Not found ",
            );
            return json_encode($response);
        }else{
            foreach($tbles as $tble){
                $sc=0;
                $disc=0;
                $tablereference_id=$tble['Order_table']['reference_id'];
                $orderdata=$this->ordercomputewithdiscount($tablereference_id,$cashierid,$sc,$disc);
                $amount=$orderdata['totalprice'];
                
                $item[]=array(
                    'id' => $tble['Order_table']['number'],
                    'number' =>  $tble['Order_table']['number'],
                    'reference_id' =>  $tble['Order_table']['reference_id'],
                    'amount' =>  isset($amount) ? (string)$amount : "0",
                    'is_alert' =>  $tble['Order_table']['is_alert'],
                    'is_waiter_required' =>  $tble['Order_table']['is_waiter_required'],
