    public function kds_listing()
    {
        $this->autoRender = false;
        $kds = $_REQUEST['station_id'] ?? '';
    
        if (empty($kds)) {
            return json_encode(['status' => false, 'message' => "KDS Id Missing"]);
        }
        
        $date = date("Y-m-d");
        if (empty($date)) {
            return json_encode(['status' => false, 'message' => "Date Missing"]);
        }
    
        $result = $this->Order_orderhistory->query("
            SELECT *,
                (SELECT waiter_name FROM order_tables WHERE reference_id = order_orderhistories.reference_id) AS waiter_name
            FROM order_orderhistories
            WHERE DATE(created) = '$date'
                AND status != 0
                
            GROUP BY reference_id, group_id
        ");
        if (empty($result)) {
            return json_encode(['status' => false, 'message' => "No Order found"]);
        }
    
        $orders = [];
    
        foreach ($result as $order) {
            $reference_id = $order['order_orderhistories']['reference_id'];
            $group_id = $order['order_orderhistories']['group_id'];
    
            $orderitems = $this->Order_orderhistory->query("
                SELECT * FROM order_orderhistories
                WHERE DATE(created) = '$date'
                    AND status != 0
                    AND reference_id = '$reference_id'
                    AND group_id = '$group_id'
            ");
        
            $items = [];
            foreach ($orderitems as $orderitem) {
                $reference_id=$orderitem['order_orderhistories']['reference_id'];
                $product_id=$orderitem['order_orderhistories']['product_id'];
                $order_id=$orderitem['order_orderhistories']['id'];
                
                $selected_modifiers=[];
                $orders_modifiers = $this->Order_modifier->query("SELECT * FROM `order_modifier` WHERE reference_id='$reference_id' and product_id='$product_id' and orderhistory_id='$order_id' and status!=0");
                foreach($orders_modifiers as $orders_modifier){
                    
                    $modifiers=$orders_modifier['order_modifier'];
                    $modifier_group_id=$modifiers['modifier_group_id'];
                    $modifier_group_name=$modifiers['modifier_group_name'];
                    $modifier_id=$modifiers['modifier_id'];
                    $modifier_name=$modifiers['modifier_name'];
                    $modifier_price=$modifiers['modifier_price'];
                    
                    $selected_modifiers[]=array(
                        'modifier_group_id' => $modifier_group_id,
                        'modifier_group_name' => $modifier_group_name,
                        'modifier_id' => $modifier_id,
                        'modifier_name' => $modifier_name,
                        'modifier_price' => $modifier_price,
                        );
                    
                }
                
                $items[] = array(
                    'order_history_id' => $orderitem['order_orderhistories']['id'],
                    'item_id'       => $orderitem['order_orderhistories']['product_id'],
                    'quantity'         => $orderitem['order_orderhistories']['quantity'],
                    'item_name'     => $orderitem['order_orderhistories']['product_name'],
                    'modifiers' => $selected_modifiers
                );
            }
    
            $orders[] = array(
                'kds_ref_id'   => $reference_id,
                'kds_group_id' => $group_id,
                'table_no'     => $order['order_orderhistories']['table_number'],
                'created'      => $order['order_orderhistories']['created'],
                'waiter_name'  => $order['order_orderhistories']['waiter_name'] ?? '',
                'kds_status'   => $order['order_orderhistories']['kds_status'],
                'items'        => $items
            );
        }
    
        return json_encode(['status' => true, 'orders' => $orders]);
    }
    
    public function kds_status_update()
    {
        $this->autoRender = false;
    
        $kds_user_id = $_REQUEST['kds_user_id'] ?? '';
        $reference_id = $_REQUEST['reference_id'] ?? '';
        $order_id = $_REQUEST['order_history_id'] ?? '';
        $status = $_REQUEST['status'] ?? '';
    
        if (empty($kds_user_id)) {
            return json_encode(['status' => false, 'message' => "KDS User Id Missing"]);
        }
        if (empty($reference_id)) {
            return json_encode(['status' => false, 'message' => "Reference Id Missing"]);
        }
        if (empty($order_id)) {
            return json_encode(['status' => false, 'message' => "Order ID Missing"]);
        }
        if (empty($status)) {
            return json_encode(['status' => false, 'message' => "Status Missing"]);
        }
    
        $user = $this->Kds_user->find('first', [
            'conditions' => [
                'Kds_user.id' => $kds_user_id,
                'Kds_user.status' => 1
            ],
            'recursive' => 1
        ]);
        if (empty($user)) {
            return json_encode(['status' => false, 'message' => "KDS user not found"]);
        }
    
        $orders = $this->Order_orderhistory->find('first', [
            'conditions' => [
                'id' => $order_id,
                'reference_id' => $reference_id,
                'status !=' => 0
            ]
        ]);
        if (empty($orders)) {
            return json_encode(['status' => false, 'message' => "Order not found"]);
        }
    
        $data['Kds_track'][] = [
            'order_history_id'   => $order_id,
            'order_reference_id' => $reference_id,
            'kds_group_id'       => $orders['Order_orderhistory']['group_id'],
            'kds_user_id'        => $kds_user_id,
            'product_id'         => $orders['Order_orderhistory']['product_id'],
            'product_name'       => $orders['Order_orderhistory']['product_name'],
            'status'             => $status
        ];
    
        $track_id = null;
        if (empty($data['Kds_track'])) {
            return json_encode(['status' => false, 'message' => "data not found"]);
        }
        
        $this->Kds_track->create();
        $this->Kds_track->saveAll($data['Kds_track']);
        $track_id = $this->Kds_track->id; // ✅ last inserted id
        
        // Update Order_orderhistory
        $this->Order_orderhistory->updateAll(
            [
                'Order_orderhistory.kds_track_id' => "'$track_id'",
                'Order_orderhistory.kds_status'   => "'$status'",
                'Order_orderhistory.sync'         => 0,
                'Order_orderhistory.local_sync'   => 0
            ],
            ['Order_orderhistory.id' => $order_id]
        );
    
        return json_encode(['status' => true, 'message' => "KDS Status Updated", 'track_id' => $track_id]);
    }

    
    public function online_order_accept()
    {
        $cashierid    = isset($_REQUEST['id'])           ? $_REQUEST['id']           : '';
        $reference_id = isset($_REQUEST['reference_id']) ? $_REQUEST['reference_id'] : '';

        if ($cashierid == '') {
            return json_encode(array('status' => false, 'message' => "User Id Missing"));
        }

        $users = $this->User->find('first', array('conditions' => array('User.id' => $cashierid, 'User.status' => 1)));
        if (empty($users)) {
            return json_encode(array('status' => false, 'message' => "Cashier not found"));
        }

        if ($reference_id == '') {
            return json_encode(array('status' => false, 'message' => "Reference Id Missing"));
        }

        // Idempotency: if POS records already created, return success
        $already = $this->Order_transaction->find('first', array(
            'conditions' => array('Order_transaction.reference_id' => $reference_id)
        ));
        if (!empty($already)) {
            return json_encode(array('status' => false, 'message' => "Order already accepted"));
        }

        // Load the pending online_order row
        $webhook = $this->Online_order->find('first', array(
            'conditions' => array(
                'Online_order.reference_id' => $reference_id,
                'Online_order.status'       => 0
            )
        ));

        if (empty($webhook)) {
            return json_encode(array('status' => false, 'message' => "Order not found or already processed"));
        }

        $txnid    = $webhook['Online_order']['reference_id'];
        $upOrderId = $webhook['Online_order']['order_id'];
        $storeId   = $webhook['Online_order']['store_id'];

        // Parse canonical payload saved by LocalUpController::order_create()
        $payload    = json_decode($webhook['Online_order']['response'], true);
        $header     = isset($payload['header'])     ? $payload['header']     : array();
        $financials = isset($payload['financials']) ? $payload['financials'] : array();
        $items      = isset($payload['items'])      ? $payload['items']      : array();

        if (empty($items)) {
            return json_encode(array('status' => false, 'message' => "Order has no items"));
        }

        $storeId       = isset($header['store_id'])          ? $header['store_id']         : $storeId;
        $displayId     = isset($header['up_display_id'])     ? $header['up_display_id']     : $upOrderId;
        $paymentMode   = isset($header['payment_mode'])      ? $header['payment_mode']      : 'prepaid';
        $channel       = isset($header['channel'])           ? $header['channel']           : 'online';
        $instructions  = isset($header['instructions'])      ? $header['instructions']      : '';
        $isTakeaway    = !empty($header['is_takeaway'])       ? 1                            : 0;
        $customer      = isset($header['customer'])          ? $header['customer']          : array();
        $custName      = isset($customer['name'])  ? $customer['name']  : 'Online Customer';
        $custPhone     = isset($customer['phone']) ? $customer['phone'] : '';
        $custAddress   = isset($customer['email']) ? $customer['email'] : '';

        $subtotal        = (float)(isset($financials['subtotal'])          ? $financials['subtotal']          : 0);
        $totalTax        = (float)(isset($financials['total_taxes'])       ? $financials['total_taxes']       : 0);
        $deliveryCharge  = (float)(isset($financials['delivery_charges'])  ? $financials['delivery_charges']  : 0);
        $packagingCharge = (float)(isset($financials['packaging_charges']) ? $financials['packaging_charges'] : 0);
        $serviceCharge   = (float)(isset($financials['service_charges'])   ? $financials['service_charges']   : 0);
        $discount        = (float)(isset($financials['discount'])          ? $financials['discount']          : 0);
        $payableAmount   = (float)(isset($financials['payable_amount'])    ? $financials['payable_amount']    : 0);
        
        
        $otherTaxes = 0;
        $otherTaxes = (float)(isset($payload['other_charges']) ? $payload['other_charges'] : 0);

        // Totals accumulated from items
        $totalItemsPrice  = 0;
        $totalTaxCalc     = 0;

        // Pre-pass: sum item totals and item-level discounts.
        // UP sends item.discount for item-specific promos and details.discount for the
        // overall order total. Only the RESIDUAL (details.discount - sum(item.discount))
        // is a true order-level amount that needs proportional distribution.
        $itemSubtotalForDiscount = 0;
        $sumItemLevelDiscount    = 0;
        foreach ($items as $_preItem) {
            $itemSubtotalForDiscount += (float)(isset($_preItem['total_price'])
                ? $_preItem['total_price']
                : ((float)(isset($_preItem['unit_price']) ? $_preItem['unit_price'] : 0)
                   * (int)(isset($_preItem['qty']) ? $_preItem['qty'] : 1)));
            $sumItemLevelDiscount += (float)(isset($_preItem['discount']) ? $_preItem['discount'] : 0);
        }
        // Order-level-only discount = total order discount minus what UP already gave at item level
        $orderLevelOnlyDiscount = max(0.0, $discount - $sumItemLevelDiscount);
        $remainingDiscount = $orderLevelOnlyDiscount;
        $itemCount         = count($items);
        $itemIdx           = 0;

        $groupId          = rand(0,9) . $cashierid . time();
        $deviceId         = 'UP_CONNECTOR';
        
        $kotDate = date('Y-m-d'); // ensure correct format
        $tdaykot = $this->Order_orderhistory->query("
            SELECT kot_number 
            FROM order_orderhistories 
            WHERE store_id = '$storeId' 
            ORDER BY id DESC 
            LIMIT 1
        ");

        $kot_no=1;
        if (!empty($tdaykot) && isset($tdaykot[0]['order_orderhistories']['kot_number'])) {
            $kot_no = $tdaykot[0]['order_orderhistories']['kot_number'] + 1;
        }
        
        $chargesDetail = isset($payload['charges_details']) ? $payload['charges_details'] : array();
       
        if (!empty($chargesDetail)) {
            foreach ($chargesDetail as $charge) {
                $chargeTitle = isset($charge['title']) ? $charge['title'] : '';
                $chargeTaxes = isset($charge['taxes']) && is_array($charge['taxes']) ? $charge['taxes'] : array();
                if (!empty($chargeTaxes)) {
                    foreach ($chargeTaxes as $ct) {
                        $otName  = isset($ct['title']) ? $ct['title'] : (isset($ct['name']) ? $ct['name'] : 'Tax');
                        $otRate  = isset($ct['rate'])  ? (float)$ct['rate']  : 0;
                        $otValue = isset($ct['value']) ? (float)$ct['value'] : 0;

                        $mappedTaxes = $this->_resolveUpTax($otName, $otRate, $storeId);

                        $tcData = array(
                            'store_id'              => $storeId,
                            'online_aggregator_id'  => $upOrderId,
                            'reference_id'          => $txnid,
                            'tax_id'                => $mappedTaxes['tax_id'],
                            'tax_name'              => $mappedTaxes['tax_name'],
                            'tax_percentage'        => $mappedTaxes['tax_percentage'],
                            'tax_value'             => round($otValue, 2),
                            'charge_title'          => $chargeTitle,
                            'sync'                  => 0,
                            'local_sync'            => 0,
                            'status'                => 1,
                        );
                        $this->loadModel('Tax_charge');
                        $this->Tax_charge->create();
                        $this->Tax_charge->save(array('Tax_charge' => $tcData));
                    }
                }
            }
        }

        foreach ($items as $item) {
            $itemIdx++;
            $qty       = (int)(isset($item['qty'])        ? $item['qty']        : 1);
            $unitPrice = (float)(isset($item['unit_price'])  ? $item['unit_price']  : 0);
            $itemDisc  = (float)(isset($item['discount'])    ? $item['discount']    : 0);
            $itemTotal = (float)(isset($item['total_price']) ? $item['total_price'] : $unitPrice * $qty);
            $catId     = isset($item['category_id'])   ? $item['category_id']   : 0;
            $catName   = isset($item['category_name']) ? $item['category_name'] : '';

            // Distribute the order-level-only discount proportionally by item value.
            // Last item absorbs any rounding remainder so the total stays exact.
            if ($itemSubtotalForDiscount > 0 && $orderLevelOnlyDiscount > 0) {
                if ($itemIdx === $itemCount) {
                    $itemOrderShare = $remainingDiscount;
                } else {
                    $itemOrderShare = round($itemTotal / $itemSubtotalForDiscount * $orderLevelOnlyDiscount, 2);
                    $remainingDiscount -= $itemOrderShare;
                }
            } else {
                $itemOrderShare = 0;
            }
            // Combined discount: item-level UP discount + proportional order-level share
            $effectiveDisc  = $itemDisc + $itemOrderShare;
            // Taxable base = pre-discount item total minus ALL discounts (item + order share)
            $effectiveTotal = $itemTotal - $effectiveDisc;

            // Sum item-level taxes from canonical payload
            $itemTax    = 0;
            $itemTaxPct = 0;
            if (!empty($item['taxes']) && is_array($item['taxes'])) {
                foreach ($item['taxes'] as $t) {
                    $itemTax    += (float)(isset($t['value']) ? $t['value'] : 0);
                    $itemTaxPct += (float)(isset($t['rate'])  ? $t['rate']  : 0);
                }
            }
            $totalTaxCalc    += $itemTax;
            $totalItemsPrice += $itemTotal;

            $kdsDetails = $this->Catalog_product->find('first', array(
                'fields' => array('Catalog_product.kds'),
                'conditions' => array(
                    'Catalog_product.id' => $item['merchant_id'],
                    'Catalog_product.status' => 1
                )
            ));

            $kdsid = $kdsDetails['Catalog_product']['kds'];

            // Save order_orderhistory row
            $ohData = array(
                'reference_id'         => $txnid,
                'group_id'             => $groupId,
                'cashier_id'           => $cashierid,
                'store_id'             => $storeId,
                'category'             => $catId,
                'category_name'        => $catName,
                'kds'                  => $kdsid,
                'product_id'           => isset($item['merchant_id']) ? $item['merchant_id'] : 0,
                'product_name'         => isset($item['name']) ? $item['name'] : '',
                'quantity'             => $qty,
                'price'                => $unitPrice,
                'total_price'          => $itemTotal,
                'total_tax'            => round($itemTax, 2),
                'total_tax_percentage' => round($itemTaxPct, 2),
                'discount'             => $itemDisc,
                'device_id'            => $deviceId,
                'kds_status'           => 3,
                'kot_number'           =>$kot_no,
                'kot_date'             =>$kotDate,
                'remarks'              => $instructions,
                'status'               => 2,
                'sync'                 => 0,
                'local_sync'           => 0,
            );
            $this->Order_orderhistory->create();
            $this->Order_orderhistory->save(array('Order_orderhistory' => $ohData));
            $lastOhId = $this->Order_orderhistory->getLastInsertID();

            // Save order_modifier rows for item options (addons)
            if (!empty($item['options']) && is_array($item['options'])) {
                foreach ($item['options'] as $opt) {
                    $modData = array(
                        'orderhistory_id'     => $lastOhId,
                        'product_id'          => isset($item['merchant_id']) ? $item['merchant_id'] : 0,
                        'product_name'        => isset($item['name']) ? $item['name'] : '',
                        'modifier_group_id'   => isset($opt['group_id'])    ? (int)$opt['group_id']    : 0,
                        'modifier_group_name' => isset($opt['group_title']) ? $opt['group_title']      : '',
                        'modifier_group_type' => 0,
                        'modifier_id'         => isset($opt['option_id'])   ? (int)$opt['option_id']   : 0,
                        'modifier_name'       => isset($opt['option_name']) ? $opt['option_name']      : '',
                        'modifier_price'      => (float)(isset($opt['price']) ? $opt['price'] : 0),
                        'quantity'            => (int)(isset($opt['qty']) ? $opt['qty'] : 1),
                        'reference_id'        => $txnid,
                        'store_id'            => $storeId,
                        'status'              => 1,
                        'sync'                => 0,
                        'local_sync'          => 0,
                    );
                    $this->Order_modifier->create();
                    $this->Order_modifier->save(array('Order_modifier' => $modData));
                }
            }

            // Save order_tax rows with UP→local tax mapping
            if (!empty($item['taxes']) && is_array($item['taxes'])) {
                $discPct = ($unitPrice > 0) ? round(($effectiveDisc * 100) / ($unitPrice * $qty), 2) : 0;
                foreach ($item['taxes'] as $t) {
                    $tName  = isset($t['title']) ? $t['title'] : (isset($t['name']) ? $t['name'] : 'Tax');
                    $tRate  = (float)(isset($t['rate'])  ? $t['rate']  : 0);
                    $tValue = (float)(isset($t['value']) ? $t['value'] : 0);

                    $mappedTax = $this->_resolveUpTax($tName, $tRate, $storeId);

                    $taxData = array(
                        'orderhistory_id'      => $lastOhId,
                        'store_id'             => $storeId,
                        'product_id'           => isset($item['merchant_id']) ? $item['merchant_id'] : 0,
                        'product_name'         => isset($item['name']) ? $item['name'] : '',
                        'kds'                  => $kdsid,
                        'price'                => $unitPrice,
                        'taxable_price'        => round($effectiveTotal, 2),
                        'cat_id'               => $catId,
                        'cat_name'             => $catName,
                        'discount_percentage'  => $discPct,
                        'quantity'             => $qty,
                        'tax_id'               => $mappedTax['tax_id'],
                        'tax_name'             => $mappedTax['tax_name'],
                        'tax_percentage'       => $mappedTax['tax_percentage'],
                        'tax_value'            => round($tValue, 2),
                        'reference_id'         => $txnid,
                        'status'               => 2,
                        'sync'                 => 0,
                        'local_sync'           => 0,
                    );
                    $this->Order_tax->create();
                    $this->Order_tax->save(array('Order_tax' => $taxData));
                }
            }
        }

        // Save order_customers (upsert by phone)
        if (!empty($custPhone)) {
            $ds = $this->Order_transaction->getDataSource();
            $ds->query(
                'INSERT INTO order_customers (phone, name, status, sync, local_sync) VALUES (' .
                $ds->value($custPhone) . ',' .
                $ds->value($custName)  . ', 1, 0, 0) ' .
                'ON DUPLICATE KEY UPDATE name = VALUES(name)'
            );
        }

        // Calculate token and round
        $todayDate   = date('Y-m-d');
        $currentTime = date('H:i:s');
        $tdaytrx = $this->Order_transaction->query(
            "SELECT COUNT(id) as tkn FROM order_transactions WHERE date(created)='$todayDate' AND status=2"
        );
        $token = (isset($tdaytrx[0][0]['tkn']) ? (int)$tdaytrx[0][0]['tkn'] : 0) + 1;

        $gross      = $payableAmount ?: ($totalItemsPrice + ($totalTax ?: $totalTaxCalc) + $deliveryCharge + $packagingCharge + $serviceCharge - $discount);
        $grossRound = round($gross);
        $roundDiff  = round($grossRound - $gross, 2);

        $payType = 11;
        $txnData = array(
            'reference_id'       => $txnid,
            'group_id'           => $groupId,
            'device_id'          => $deviceId,
            'cashier_id'         => $cashierid,
            'store_id'           => $storeId,
            'orderno'            => $displayId,
            'name'               => $custName,
            'phone'              => $custPhone,
            'address'            => $custAddress,
            'price'              => $subtotal ?: $totalItemsPrice,
            'total_tax'          => $totalTax ?: round($totalTaxCalc, 3),
            'other_taxes'        => round($otherTaxes, 2),
            'servicecharge'      => $serviceCharge,
            'delivery_charge'    => $deliveryCharge,
            'packing_charge'     => $packagingCharge,
            'discount'           => $discount,
            'discount_type'      => 2,
            'discount_type_value'=> $discount,
            'amount'             => $grossRound,
            'round'              => round($roundDiff,0),
            'is_takeaway'        => $isTakeaway,
            'payment_mode'       => ($paymentMode === 'prepaid') ? 'Online' : 'Cash',
            'tokenno'            => $token,
            'createtime'         => $currentTime,
            'remarks'            => $instructions,
            'status'             => 2,
            'sync'               => 0,
            'local_sync'         => 0,
        );
        $this->Order_transaction->create();
        $this->Order_transaction->save(array('Order_transaction' => $txnData));

        // Save order_payment
        $payData = array(
            'reference_id' => $txnid,
            'store_id'     => $storeId,
            'device_id'    => $deviceId,
            'cashier_id'   => $cashierid,
            'type'         => $payType,
            'type_value'   => $channel,
            'amount'       => $grossRound,
            'round'        => $roundDiff,
            'status'       => 2,
            'sync'         => 0,
            'local_sync'   => 0,
        );
        $this->Order_payment->create();
        $this->Order_payment->save(array('Order_payment' => $payData));

        // Update online_order status to accepted (1)
        $this->Online_order->updateAll(
            array(
                'Online_order.status'     => 1,
                'Online_order.cron_run'   => 1,
                'Online_order.sync'       => 0,
                'Online_order.local_sync' => 0,
            ),
            array('Online_order.reference_id' => $txnid)
        );

        // Acknowledge to UrbanPiper
        if (!empty($upOrderId)) {
            App::uses('UrbanpiperClient', 'Lib/Urbanpiper');
            App::uses('UrbanpiperLogger', 'Lib/Urbanpiper');
            try {
                $upClient = new UrbanpiperClient();
                $ackResult = $upClient->acknowledgeOrder($upOrderId);
                if (!$ackResult['success']) {
                    UrbanpiperLogger::warn('online_order_accept ack FAILED up_order_id=' . $upOrderId . ' http=' . $ackResult['http_code']);
                }
            } catch (Exception $e) {
                // Non-fatal — order is accepted locally
            }
        }

        return json_encode(array('status' => true, 'message' => "Order accepted"));
    }
    
    private function _resolveUpTax($taxName, $taxRate, $storeId) {
        $ds = $this->Order_transaction->getDataSource();

        // 1. Try store-specific mapping
        $rows = $ds->query(
            'SELECT local_tax_id, local_tax_name, local_tax_percentage FROM up_tax_map' .
            ' WHERE up_tax_name = ' . $ds->value($taxName) .
            ' AND up_tax_rate = '   . $ds->value($taxRate) .
            ' AND store_id = '      . $ds->value($storeId) .
            ' AND status = 1 LIMIT 1'
        );

        if (empty($rows)) {
            // 2. Try global mapping (store_id IS NULL)
            $rows = $ds->query(
                'SELECT local_tax_id, local_tax_name, local_tax_percentage FROM up_tax_map' .
                ' WHERE up_tax_name = ' . $ds->value($taxName) .
                ' AND up_tax_rate = '   . $ds->value($taxRate) .
                ' AND store_id IS NULL' .
                ' AND status = 1 LIMIT 1'
            );
        }

        if (!empty($rows)) {
            $r = isset($rows[0]['up_tax_map']) ? $rows[0]['up_tax_map'] : $rows[0][0];
            return array(
                'tax_id'         => (int)$r['local_tax_id'],
                'tax_name'       => $r['local_tax_name'] ?: $taxName,
                'tax_percentage' => (float)$r['local_tax_percentage'],
            );
        }

        // 3. Not mapped: look up catalog_tax by name/percentage
        $catRows = $ds->query(
            'SELECT id, name, percentage FROM catalog_tax' .
            ' WHERE name LIKE ' . $ds->value('%' . $taxName . '%') .
            ' AND status = 1 LIMIT 1'
        );

        $localTaxId  = 0;
        $localTaxPct = $taxRate;
        $localTaxName = $taxName;

        if (!empty($catRows)) {
            $cr = isset($catRows[0]['catalog_tax']) ? $catRows[0]['catalog_tax'] : $catRows[0][0];
            $localTaxId   = (int)$cr['id'];
            $localTaxPct  = (float)$cr['percentage'];
            $localTaxName = $cr['name'];
        } else {
            // Create a new catalog_tax entry so it shows in reports
            $ds->query(
                'INSERT IGNORE INTO catalog_tax (name, percentage, status) VALUES (' .
                $ds->value($taxName) . ',' .
                $ds->value($taxRate) . ', 1)'
            );
            $catNew = $ds->query(
                'SELECT id FROM catalog_tax WHERE name = ' . $ds->value($taxName) . ' LIMIT 1'
            );
            if (!empty($catNew)) {
                $cr = isset($catNew[0]['catalog_tax']) ? $catNew[0]['catalog_tax'] : $catNew[0][0];
                $localTaxId = (int)$cr['id'];
            }
        }

        // Auto-register global mapping for future orders
        if ($localTaxId > 0) {
            $ds->query(
                'INSERT IGNORE INTO up_tax_map' .
                ' (up_tax_name, up_tax_rate, local_tax_id, local_tax_name, local_tax_percentage)' .
                ' VALUES (' .
                $ds->value($taxName) . ',' .
                $ds->value($taxRate) . ',' .
                $ds->value($localTaxId) . ',' .
                $ds->value($localTaxName) . ',' .
                $ds->value($localTaxPct) . ')'
            );
        }

        return array(
            'tax_id'         => $localTaxId,
            'tax_name'       => $localTaxName,
            'tax_percentage' => $localTaxPct,
        );
    }
    
     public function online_order_transaction_history()
    {
        // fetch according to store id 
        $cashierid = isset($_REQUEST['id']) ? $_REQUEST['id'] : '';
    
        $startdate = isset($_REQUEST['from']) ? $_REQUEST['from'] : date("Y-m-d");
        $enddate   = isset($_REQUEST['to'])   ? $_REQUEST['to']   : date("Y-m-d");

        if ($cashierid == '') {
            return json_encode([
                'status'  => false,
                'message' => "User Id Missing",
            ], JSON_UNESCAPED_UNICODE);
        }
    
        $users = $this->User->find('first', [
            'conditions' => [
                'User.id'     => $cashierid,
                'User.status' => 1
            ]
        ]);
    
        if (empty($users)) {
            return json_encode([
                'status'  => false,
                'message' => "Cashier not found",
            ], JSON_UNESCAPED_UNICODE);
        }
    
        $store_id = $users['User']['location_id'];

        // Build shift datetime range
        $_shiftRange = $this->getShiftDateRange($startdate, $enddate, $store_id);
        $startDatetime = $_shiftRange['startDatetime'];
        $endDatetime   = $_shiftRange['endDatetime'];

        $transactionitems = [];
    
        $transactions = $this->Online_order->find('all', [
            'conditions' => [
                'store_id' => $store_id,
                'created BETWEEN ? AND ?' => [
                    $startDatetime,
                    $endDatetime
                ],
                'status NOT IN' => [2, 5]
            ],
            'order' => ['Online_order.id' => 'DESC']
        ]);
    
        if (!empty($transactions)) {
            foreach ($transactions as $orders) {
                $total_pack_charge = 0;
    
                $finalamount   = $orders['Online_order']['total_amount'];
                $cashier_id    = $orders['Online_order']['cashier_id'];
                $reference_id  = $orders['Online_order']['reference_id'];
                $response      = $orders['Online_order']['response'];
                $response_res  = json_decode($response, true);
    
                if (json_last_error() !== JSON_ERROR_NONE) {
                    // skip invalid json responses
                    continue;
                }
    
                // packaging charges — canonical stores this as a flat number in financials
                if (isset($response_res['financials']['packaging_charges'])) {
                    $total_pack_charge = (float)$response_res['financials']['packaging_charges'];
                }
    
                // timestamps — canonical stores delivery_datetime in header
                $delivery_ts = isset($response_res['header']['delivery_datetime'])
                    ? intval($response_res['header']['delivery_datetime']) / 1000
                    : time();
    
                $currenttime     = date("H:i:s", $delivery_ts);
                $currenttimedate = date("Y-m-d H:i:s", $delivery_ts);
    
                // auto token number
                $todayDate = date("Y-m-d");
                $tdaytrx = $this->Order_transaction->query("SELECT COUNT(id) as tkn FROM `order_transactions` WHERE date(created)='$todayDate'  and status=2");
                $token = isset($tdaytrx[0][0]['tkn']) ? $tdaytrx[0][0]['tkn'] + 1 : 1;
    
                // round values
                $finalamount = round($orders['Online_order']['total_amount']);
                $round_amount = $finalamount - $orders['Online_order']['total_amount'];
    
                $webhooks = $this->Online_order->find('all', ['conditions' => ['Online_order.reference_id' => $reference_id]]);
                
                $orderitems = [];
                $remarks = [];
                $total_tax_value = 0;
            
                foreach ($webhooks as $webhook) {
                    // Canonical JSON stored as array (not raw UP object format)
                    $response_obj = json_decode($webhook['Online_order']['response'], true);
                    $ordertxnid   = $webhook['Online_order']['reference_id'];
            
                    if (empty($response_obj['items'])) {
                        return json_encode(['status' => false, 'message' => "Missing order items for txn $ordertxnid"]);
                    }
                    
                    $delivery_ts = isset($response_obj['header']['delivery_datetime'])
                        ? intval($response_obj['header']['delivery_datetime']) / 1000
                        : time();
            
                    $currenttime     = date("H:i:s", $delivery_ts);
                    $currenttimedate = date("Y-m-d H:i:s", $delivery_ts);
                    
                    foreach ($response_obj['items'] as $item) {
                        $item_tax_value = 0;
                        $item_tax_rate  = 0;
            
                        if (!empty($item['taxes'])) {
                            foreach ($item['taxes'] as $tax) {
                                $item_tax_value += $tax['value'];
                                $item_tax_rate  += $tax['rate'];
                            }
                        }
                        $total_tax_value += $item_tax_value;
            
                        $ttlprice = ($item['unit_price'] * $item['qty']) - ($item['discount'] ?? 0);
                        
                        $orderitems[] = [
                            'id'                   => '',
                            'reference_id'         => $ordertxnid,
                            'cashier_id'           => '',
                            'group_id'             => '',
                            'category'             => $item['category_id']   ?? '0',
                            'category_name'        => $item['category_name'] ?? '',
                            'kds'                  => '',
                            'product_id'           => $item['merchant_id']   ?? '0',
                            'product_name'         => $item['name']          ?? '',
                            'quantity'             => strval($item['qty']        ?? '0'),
                            'price'                => strval($item['unit_price'] ?? '0'),
                            'total_tax'            => number_format(round($item_tax_value, 2), 2),
                            'total_tax_percentage' => strval($item_tax_rate),
                            'total_price'          => strval($ttlprice),
                            'discount'             => strval($item['discount'] ?? '0'),
                            'table_number'         => '0',
                            'remarks'              => '',
                            'status'               => '2',
                            'created'              => $currenttimedate
                        ];
                    }
                }
                
                $transactionitems[] = [
                    'id'                => $orders['Online_order']['id'],
                    'reference_id'      => $reference_id,
                    'orderno'           => $orders['Online_order']['order_id'],
                    'device_id'         => '0',
                    'cashier_id'        => $cashier_id??'0',
                    'table_number'      => '0',
                    'price'             => $orders['Online_order']['total_price'] ?? '0',
                    'total_tax'         => $orders['Online_order']['total_taxes'] ?? '0',
                    'servicecharge'     => '0',
                    'discount'          => isset($response_res['financials']['discount']) ? strval($response_res['financials']['discount']) : "0",
                    'discount_percentage' => '0',
                    'discount_type'     => '2',
                    'discount_type_value' => 'Flat',
                    'delivery_charge'   => '0',
                    'packing_charge'    => strval($total_pack_charge) ?? '0',
                    'amount'            => strval($finalamount) ?? '0',
                    'round'             => number_format($round_amount, 2, '.', ''), 
                    'name'              => $response_res['header']['customer']['name']         ?? '',
                    'phone'             => $response_res['header']['customer']['phone']        ?? '',
                    'address'           => $response_res['header']['customer']['address_city'] ?? '',
                    'remarks'           => $orders['Online_order']['remarks'] ?? '',
                    'status'            => strval($orders['Online_order']['status']),
                    'tokenno'           => "$token",
                    'createtime'        => $currenttime,
                    'created'           => $currenttimedate,
                    'payment_mode'      => $response_res['header']['channel'] ?? '',
                    'items'             => $orderitems
                ];
            }
        }
    
        // cashier name
        $cashier_name = '';
        $cashname = $this->User->query("SELECT name FROM `users` WHERE id='$cashierid'");
        if ($cashname && isset($cashname[0]['users']['name'])) {
            $cashier_name = $cashname[0]['users']['name'];
        }
    
        $response = [
            'status'       => true,
            'message'      => "success",
            'cashier_name' => $cashier_name,
            'transactions' => $transactionitems
        ];
    
        return json_encode($response, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT);
    }
    
    public function online_order_food_ready()
    {
        $cashierid    = isset($_REQUEST['id'])           ? $_REQUEST['id']           : '';
        $reference_id = isset($_REQUEST['reference_id']) ? $_REQUEST['reference_id'] : '';

        if ($cashierid == '') {
            return json_encode(array('status' => false, 'message' => "User Id Missing"));
        }

        $users = $this->User->find('first', array('conditions' => array('User.id' => $cashierid, 'User.status' => 1)));
        if (empty($users)) {
            return json_encode(array('status' => false, 'message' => "Cashier not found"));
        }

        if ($reference_id == '') {
            return json_encode(array('status' => false, 'message' => "Reference Id Missing"));
        }

        $webhook = $this->Online_order->find('first', array(
            'conditions' => array(
                'Online_order.reference_id' => $reference_id,
                'Online_order.status'       => 1
            )
        ));

        if (empty($webhook)) {
            return json_encode(array('status' => false, 'message' => "Order not found or not yet accepted"));
        }

        $upOrderId = $webhook['Online_order']['order_id'];

        // Push Food Ready to UrbanPiper
        $upresponse  = $this->order_status_change($upOrderId, "Food Ready", "Food packed at restaurant");
        $chkresponse = json_decode($upresponse, true);

        // Update local status to Food Ready (2) regardless of UP response
        $this->Online_order->updateAll(
            array('Online_order.status' => 2),
            array('Online_order.reference_id' => $reference_id)
        );

        if (!empty($chkresponse['status']) && $chkresponse['status'] == true) {
            return json_encode(array('status' => true, 'message' => "Food ready status updated"));
        } else {
            return json_encode(array('status' => true, 'message' => "Food ready marked locally; UP push: " . ($chkresponse['message'] ?? 'unknown')));
        }
    }
    
    function order_status_change($orderno=null,$status=null,$message=null)
    {
        $response=array();
        $response['status']=false;
        $response['message']="fail";
        $retry_attempt=0;
    
        // G6 fix: credentials moved to env vars — never hardcode in source.
        // Credentials moved to env vars. Rotate any old keys in UrbanPiper Hub.
        $upApiKey  = 'biz_adm_egGcwzZpmqZk';
        $upApiPass = '1dda18a8837267a9ae5d630ed67fe220f517b911';
        $upBaseUrl = 'https://api.urbanpiper.com';

        $data=array('new_status'=>$status,'message'=>$message);
        $data_post = json_encode($data);
        $url = $upBaseUrl . "/external/api/v1/orders/$orderno/status/";
        $ch = curl_init($url);
        curl_setopt($ch, CURLOPT_POSTFIELDS, $data_post);
        curl_setopt($ch, CURLOPT_HTTPHEADER, array(
            'Authorization: apikey ' . $upApiKey . ':' . $upApiPass,
            'Content-Type: application/json'
        ));
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, 0);
        curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, 0);
        curl_setopt($ch, CURLOPT_CUSTOMREQUEST, "PUT");
        $output = curl_exec($ch);
        $httpcode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        if (curl_errno($ch)) {
            $error = curl_error($ch);
            $response['message']=$error;
            die(json_encode($response));
        }
        curl_close($ch);
        if($httpcode>=500)
        {
            $error['status']="error";
            $error['message']=$httpcode." error";
            $output=json_encode($error);
        }

        if($httpcode==401)
        {
            $error['status']="error";
            $error['message']=$httpcode." error";
            $output=json_encode($error);
        }
            
        $result=json_decode($output,true);
        if(!empty($result) && $result['status']=='success')
        {
            $response['status']=true;
            $response['message']=$result['message'];
        }else{
            $response['message']=$result['message'];
        }
        return json_encode($response);
    }
    
    public function online_order_cancelled()
    {
        $cashierid    = isset($_REQUEST['id'])           ? $_REQUEST['id']           : '';
        $reference_id = isset($_REQUEST['reference_id']) ? $_REQUEST['reference_id'] : '';
        $current_state = isset($_REQUEST['status_code']) ? $_REQUEST['status_code']  : 'store_busy';

        if ($cashierid == '') {
            return json_encode(array('status' => false, 'message' => "User Id Missing"));
        }

        $users = $this->User->find('first', array('conditions' => array('User.id' => $cashierid, 'User.status' => 1)));
        if (empty($users)) {
            return json_encode(array('status' => false, 'message' => "Cashier not found"));
        }

        if ($reference_id == '') {
            return json_encode(array('status' => false, 'message' => "Reference Id Missing"));
        }

        $webhook = $this->Online_order->find('first', array(
            'conditions' => array('Online_order.reference_id' => $reference_id)
        ));

        if (empty($webhook)) {
            return json_encode(array('status' => false, 'message' => "Order not found"));
        }

        $upOrderId = $webhook['Online_order']['order_id'];

        // Void POS records if they exist
        $this->Order_orderhistory->updateAll(
            array('Order_orderhistory.status' => 0, 'Order_orderhistory.sync' => 0),
            array('Order_orderhistory.reference_id' => $reference_id)
        );
        $this->Order_tax->updateAll(
            array('Order_tax.status' => 0, 'Order_tax.sync' => 0),
            array('Order_tax.reference_id' => $reference_id)
        );
        $this->Order_transaction->updateAll(
            array('Order_transaction.status' => 0, 'Order_transaction.sync' => 0),
            array('Order_transaction.reference_id' => $reference_id)
        );
        $this->Order_payment->updateAll(
            array('Order_payment.status' => 0, 'Order_payment.sync' => 0),
            array('Order_payment.reference_id' => $reference_id)
        );

        // Mark online_order as cancelled (5)
        $this->Online_order->updateAll(
            array('Online_order.status' => 5, 'Online_order.sync' => 0, 'Online_order.local_sync' => 0),
            array('Online_order.reference_id' => $reference_id)
        );

        // Push Cancelled to UrbanPiper
        if (!empty($upOrderId)) {
            $cancelReasonMap = array(
                'item_out_of_stock'      => 'item_out_of_stock',
                'store_closed'           => 'store_closed',
                'store_busy'             => 'store_busy',
                'rider_not_available'    => 'rider_not_available',
                'out_of_delivery_radius' => 'out_of_delivery_radius',
                'connectivity_issue'     => 'connectivity_issue',
                'total_missmatch'        => 'total_missmatch',
                'invalid_item'           => 'invalid_item',
                'option_out_of_stock'    => 'option_out_of_stock',
                'invalid_option'         => 'invalid_option',
            );
            $reason = isset($cancelReasonMap[$current_state]) ? $cancelReasonMap[$current_state] : $current_state;
            $this->order_status_change($upOrderId, "Cancelled", $reason);
        }

        return json_encode(array('status' => true, 'message' => "Order cancelled"));
    }
    
    public function pos_status_update($reference_id)
    {
        $success = true;
    
        if (!$this->Order_orderhistory->updateAll(
            array(
                'Order_orderhistory.status'     => 0,
                'Order_orderhistory.sync'       => 0,
                'Order_orderhistory.local_sync' => 0
            ),
            array(
                'Order_orderhistory.reference_id' => $reference_id
            )
        )) {
            $success = false;
        }

    
        // Update Order_tax
        if (!$this->Order_tax->updateAll(
            array(
                'Order_tax.status'     => 0,
                'Order_tax.sync'       => 0,
                'Order_tax.local_sync' => 0
            ),
            array(
                'Order_tax.reference_id' => $reference_id
            )
        )) {
            $success = false;
        }
        
        // Update Order_transaction
        if (!$this->Order_transaction->updateAll(
            array(
                'Order_transaction.status'     => 0,
                'Order_transaction.sync'       => 0,
                'Order_transaction.local_sync' => 0
            ),
            array(
                'Order_transaction.reference_id' => $reference_id
            )
        )) {
            $success = false;
        }
        
        // Update Order_payment
        if (!$this->Order_payment->updateAll(
            array(
                'Order_payment.status'     => 0,
                'Order_payment.sync'       => 0,
                'Order_payment.local_sync' => 0
            ),
            array(
                'Order_payment.reference_id' => $reference_id
            )
        )) {
            $success = false;
        }

        return $success;
    }
    
    public function online_order_notify()
    {
        $cashierid = $_REQUEST['id'];
        
        if ($cashierid == '') {
            return json_encode([
                'status' => false,
                'message' => "User Id Missing",
            ]);
        }
    
        $users = $this->User->find('first', [
            'conditions' => ['User.id' => $cashierid, 'User.status' => 1]
        ]);
        if (empty($users)) {
            return json_encode([
                'status' => false,
                'message' => "Cashier not found",
            ]);
        }
    
        if ($reference_id == '') {
            return json_encode([
                'status' => false,
                'message' => "Reference Id Missing",
            ]);
        }
    
        $store_id = $users['User']['location_id'];
    
        // Get order
        $webhook = $this->Online_order->find('first', [
            'conditions' => [
                'Online_order.store_id' => $store_id,
                'Online_order.notify' => 0,
                'Online_order.status' => 0
            ]
        ]);
    
        $success = $this->Online_order->updateAll(
            array(
                'Online_order.notify'     => 1,
                'Online_order.sync'       => 0,
                'Online_order.local_sync' => 0
            ),
            array(
                'Online_order.reference_id' => $webhook['Online_order']['reference_id']
            )
        );

        
        $response['status']=true;
        $response['title']="New Order Arrived!";
        $response['message']="Please Check!";
        
        return json_encode($response, JSON_UNESCAPED_UNICODE);
    }

    public function online_order_transaction_detail()
    {
        $cashierid = $_REQUEST['id'];
        $reference_id = $_REQUEST['reference_id'];
        
        if (empty($cashierid)) {
            return json_encode(['status' => false, 'message' => "User Id Missing"]);
        }
        if (empty($reference_id)) {
            return json_encode(['status' => false, 'message' => "Reference Id Missing"]);
        }
    
        $users = $this->User->find('first', ['conditions' => ['User.id' => $cashierid, 'User.status' => 1]]);
        if (empty($users)) {
            return json_encode(['status' => false, 'message' => "User not found"]);
        }
    
        $webhooks = $this->Online_order->find('all', ['conditions' => ['Online_order.reference_id' => $reference_id]]);
        
        $orderitems = [];
        $remarks = [];
        $total_tax_value = 0;
    
        foreach ($webhooks as $webhook) {
            $response = json_decode($webhook['Online_order']['response']);
            $txnid = $webhook['Online_order']['reference_id'];
    
            if (empty($response->order->items)) {
                return json_encode(['status' => false, 'message' => "Missing order items for txn $txnid"]);
            }
            
            $delivery_ts = isset($response->order->details->delivery_datetime)
                ? intval($response->order->details->delivery_datetime) / 1000
                : time();

            $currenttime     = date("H:i:s", $delivery_ts);
            $currenttimedate = date("Y-m-d H:i:s", $delivery_ts);
            
            
            foreach ($response->order->items as $item) {
                $item_tax_value = 0;
                $item_tax_rate = 0;
    
                if (!empty($item->taxes)) {
                    foreach ($item->taxes as $tax) {
                        $item_tax_value += $tax->value;
                        $item_tax_rate += $tax->rate;
                    }
                }
                $total_tax_value += $item_tax_value;
    
                $ttlprice = ($item->price * $item->quantity) - ($item->discount ?? 0);
                // timestamps
                
                $orderitems[] = [
                    'id'                   => '',
                    'reference_id'         => $txnid,
                    'cashier_id'           => '',
                    'group_id'             => '',
                    'category'             => isset($item->category->merchant_id) ? $item->category->merchant_id : '0',
                    'category_name'        => isset($item->category->name) ? $item->category->name : '',
                    'kds'                  => '',
                    'product_id'           => $item->merchant_id ?? '0',
                    'product_name'         => $item->title ?? '',
                    'quantity'             => strval($item->quantity) ?? '0',
                    'price'                => strval($item->price) ?? '0',
                    'total_tax'            => number_format(round($item_tax_value,2),2),
                    'total_tax_percentage' => strval($item_tax_rate),
                    'total_price'          => strval($ttlprice),
                    'discount'             => strval($item->discount) ?? '0',
                    'table_number'         => '0',
                    'remarks'              => '',
                    'status'               => '2',
                    'created'              =>  $currenttimedate
                ];
            }
        }
    
        return json_encode([
            'status'      => true,
            'message'     => "success",
            'cashier_name'=> '',
            'orders'      => $orderitems
        ]);
    }

