        }
        if($reference_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Reference Id Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        $orderitems=[];
        $order_punch_by='';
        
        $orderss = $this->Order_orderhistory->query("SELECT *,  ( SELECT name FROM users WHERE id = ( SELECT cashier_id FROM order_orderhistories WHERE reference_id = '$reference_id'  AND status != 0 ORDER BY id ASC LIMIT 1 ) LIMIT 1 ) AS first_cashier_name FROM `order_orderhistories` WHERE reference_id='$reference_id' and status!=0");
        if(!empty($orderss))
        {
            
            foreach($orderss as $orders){
                $product_id=$orders['order_orderhistories']['product_id'];
                $order_id=$orders['order_orderhistories']['id'];
                $order_punch_by = $orders[0]['first_cashier_name'];

                $selected_modifiers=[];
                $orders_modifiers = $this->Order_modifier->query("SELECT * FROM `order_modifier` WHERE reference_id='$reference_id' and product_id='$product_id' and orderhistory_id='$order_id' and status!=0");
                foreach($orders_modifiers as $orders_modifier){
                    
                    $modifiers=$orders_modifier['order_modifier'];
                    $modifier_group_id=$modifiers['modifier_group_id'];
                    $modifier_group_name=$modifiers['modifier_group_name'];
                    $modifier_id=$modifiers['modifier_id'];
                    $modifier_name=$modifiers['modifier_name'];
                    $modifier_price=$modifiers['modifier_price'];
                    
                    $selected_modifiers[]=array(
                        'modifier_group_id' => $modifier_group_id,
                        'modifier_group_name' => $modifier_group_name,
                        'modifier_id' => $modifier_id,
                        'modifier_name' => $modifier_name,
                        'modifier_price' => $modifier_price,
                        );
                    
                }
                
                if(!isset($orders['order_orderhistories']['remarks'])){
                    $orders['order_orderhistories']['remarks']='';
                }
                $orderitems[]=array(
                    'id' => $orders['order_orderhistories']['id'],
                    'reference_id' =>  $orders['order_orderhistories']['reference_id'],
                    'cashier_id' =>  $orders['order_orderhistories']['cashier_id'],
                    'group_id' =>  $orders['order_orderhistories']['group_id'],
                    'category' =>  $orders['order_orderhistories']['category'],
                    'category_name' =>  $orders['order_orderhistories']['category_name'],
                    'kds' =>  $orders['order_orderhistories']['kds'],
                    'kot_number' =>  $orders['order_orderhistories']['kot_number'],
                    'product_id' =>  $orders['order_orderhistories']['product_id'],
                    'product_name' =>  $orders['order_orderhistories']['product_name'],
                    'quantity' =>  $orders['order_orderhistories']['quantity'],
                    'price' =>  $orders['order_orderhistories']['price'],
                    'total_tax' =>  $orders['order_orderhistories']['total_tax'],
                    'total_price' =>  $orders['order_orderhistories']['total_price'],
                    'discount' =>  $orders['order_orderhistories']['discount'],
                    'table_number' =>  $orders['order_orderhistories']['table_number'],
                    'remarks' =>  $orders['order_orderhistories']['remarks'],
                    'selected_modifiers' => $selected_modifiers,
                    'status' =>  $orders['order_orderhistories']['status'],
                    'created' =>  $orders['order_orderhistories']['created']
                );
            }
        }

        $reeloDiscountMsg = '';
        $this->loadModel('ReeloDiscount');
        $reeloDiscsForMsg = $this->ReeloDiscount->find('all', array(
            'conditions' => array(
                'ReeloDiscount.reference_id' => $reference_id,
                'ReeloDiscount.status' => 1,
                'ReeloDiscount.discount_on' => 'item'
            ),
            'recursive' => -1
        ));

        if (!empty($reeloDiscsForMsg)) {
            $this->loadModel('Order_orderhistory');
            $activeOhItems = $this->Order_orderhistory->find('all', array(
                'conditions' => array(
                    'Order_orderhistory.reference_id' => $reference_id,
                    'Order_orderhistory.status !=' => 0
                ),
                'fields' => array('Order_orderhistory.product_id', 'Order_orderhistory.id'),
                'recursive' => -1
            ));
            $activeItemIds = array();
            foreach ($activeOhItems as $aoh) {
                if (isset($aoh['Order_orderhistory']['product_id'])) {
                    $activeItemIds[] = (string)$aoh['Order_orderhistory']['product_id'];
                }
                if (isset($aoh['Order_orderhistory']['id'])) {
                    $activeItemIds[] = (string)$aoh['Order_orderhistory']['id'];
                }
            }

            $prodMap = array();
            foreach ($orderitems as $oitem) {
                if (isset($oitem['product_id'])) {
                    $prodMap[(string)$oitem['product_id']] = $oitem['product_name'] ?? '';
                }
                if (isset($oitem['id'])) {
                    $prodMap[(string)$oitem['id']] = $oitem['product_name'] ?? '';
                }
            }

            $msgParts = array();
            foreach ($reeloDiscsForMsg as $rdisc) {
                $itemJsonStr = $rdisc['ReeloDiscount']['item_json'] ?? '';
                $discType = $rdisc['ReeloDiscount']['discount_type'] ?? '';
                $discVal = $rdisc['ReeloDiscount']['discount_value'] ?? $rdisc['ReeloDiscount']['discount_type_value'] ?? '';

                $formattedDisc = '';
                if (strcasecmp($discType, 'percentage') === 0) {
                    $formattedDisc = floatval($discVal) . '%';
                } else {
                    $formattedDisc = 'Rs.' . floatval($discVal);
                }

                $itemsArr = json_decode($itemJsonStr, true);
                if (is_array($itemsArr) && !empty($itemsArr)) {
                    $itemNames = array();
                    foreach ($itemsArr as $iObj) {
                        if (is_array($iObj)) {
                            $pId = $iObj['product_id'] ?? $iObj['_id'] ?? $iObj['id'] ?? null;
                            $q = $iObj['quantity'] ?? null;
                        } else if (is_scalar($iObj)) {
                            $pId = (string)$iObj;
                            $q = null;
                        } else {
                            $pId = null;
                            $q = null;
                        }

                        if ($pId !== null && in_array((string)$pId, $activeItemIds, true)) {
                            $pName = $prodMap[(string)$pId] ?? '';
                            if (empty($pName)) {
                                $pName = 'Item ' . $pId;
                            }
                            if ($q !== null && intval($q) > 0) {
                                $itemNames[] = intval($q) . 'x ' . $pName;
                            } else {
                                $itemNames[] = $pName;
                            }
                        }
                    }
                    if (!empty($itemNames)) {
                        $msgParts[] = $formattedDisc . ' Off on ' . implode(', ', $itemNames);
                    } else {
                        $msgParts[] = $formattedDisc . ' Off on selected items';
                    }
                } else {
                    $msgParts[] = $formattedDisc . ' Off on item level';
                }
            }
            if (!empty($msgParts)) {
                $reeloDiscountMsg = implode('; ', $msgParts);
            }
        }

        $finalamount=0;
        $transactionitems=[];
        $transactions = $this->Order_transaction->query(
            "SELECT GROUP_CONCAT(id) as id,reference_id,GROUP_CONCAT(orderno) as orderno,device_id,cashier_id,table_number,
            SUM(price) as price,SUM(total_tax) as total_tax,SUM(servicecharge) as servicecharge,SUM(discount) as discount,
            SUM(discount_type_value) as discount_type_value,SUM(delivery_charge) as delivery_charge,SUM(packing_charge) as packing_charge,
            SUM(amount) as amount,SUM(round) as round,discount_type ,name,phone,address,GROUP_CONCAT(remarks) as remarks,status,GROUP_CONCAT(tokenno) as tokenno,
            createtime,created,pax,(select name from users where id=order_transactions.cashier_id) as cash_name FROM `order_transactions` WHERE reference_id='$reference_id' and status!=0");
        
        if(!empty($transactions))
        {
            foreach($transactions as $orders){
                
                if(!$orders[0]['remarks']){
                    $orders[0]['remarks']='';
                }
                $finalamount=$orders[0]['amount'];
                $cashierid=$orders[0]['cashier_id'];
                $reference_id=$orders['order_transactions']['reference_id'];
                
                $discper = $this->Order_tax->query("SELECT discount_percentage FROM `order_tax` WHERE reference_id='$reference_id' and status!=0 and discount_percentage!=0 limit 1");
                if(!empty($discper))
                {
                    $discount_percentage=number_format($discper[0]['order_tax']['discount_percentage'],2);
                }
                if(!isset($discount_percentage)){
                    $discount_percentage="0";
                }
                $kotQuery = $this->Order_orderhistory->query("
                    SELECT GROUP_CONCAT(DISTINCT(kot_number)) AS kot_numbers 
                    FROM order_orderhistories 
                    WHERE reference_id = '$reference_id' and status!=0
                ");
        
                $kot_numbers = '';
                if (!empty($kotQuery) && isset($kotQuery[0][0]['kot_numbers'])) {
                    $kot_numbers = $kotQuery[0][0]['kot_numbers'];
                }
                
                $transactionitems[]=array(
                    'id' => $orders[0]['id'],
                    'reference_id' =>  $orders['order_transactions']['reference_id'],
                    'orderno' =>  $orders[0]['orderno'],
                    'device_id' =>  $orders['order_transactions']['device_id'],
                    'cashier_id' =>  $orders['order_transactions']['cashier_id'],
                    'cashier_name' => isset($orders[0]['cash_name']) ? $orders[0]['cash_name'] : '',
                    'table_number' =>  $orders['order_transactions']['table_number'],
                    'price' =>  number_format($orders[0]['price'],2),
                    'total_tax' =>  number_format($orders[0]['total_tax'],2),
                    'servicecharge' =>  $orders[0]['servicecharge'],
                    'discount' =>  $orders[0]['discount'],
                    'discount_percentage' =>  $discount_percentage,
                    'discount_type' =>  $orders['order_transactions']['discount_type'],
                    'discount_type_value' =>  $orders[0]['discount_type_value'],
                    'taxable_amount' => number_format(($orders[0]['price'] + $orders[0]['servicecharge']) - $orders[0]['discount'], 2),
                    'delivery_charge' =>  $orders[0]['delivery_charge'],
                    'packing_charge' =>  $orders[0]['packing_charge'],
                    'amount' =>  $orders[0]['amount'],
                    'round' =>  $orders[0]['round'],
                    'name' =>  $orders['order_transactions']['name'],
                    'phone' =>  $orders['order_transactions']['phone'],
                    'address' =>  $orders['order_transactions']['address'],
                    'remarks' =>  $orders['order_transactions']['remarks'],
                    'status' =>  $orders['order_transactions']['status'],
                    'tokenno' =>  $orders[0]['tokenno'],
                    'createtime' =>  $orders['order_transactions']['createtime'],
                    'pax' =>  $orders['order_transactions']['pax'],
                    'created' =>  $orders['order_transactions']['created'],
                    'kot_number' => $kot_numbers
                );
            }
        }
        $paymentitems=[];
        $payments = $this->Order_payment->find('all', array('conditions'=>array('reference_id'=>$reference_id,'status !='=>0)));
        if(!empty($payments))
        {
            foreach($payments as $orders){
                if(!isset($orders['Order_payment']['remarks'])){
                    $orders['Order_payment']['remarks']='';
                }
                $paymentitems[]=array(
                    'id' => $orders['Order_payment']['id'],
                    'reference_id' =>  $orders['Order_payment']['reference_id'],
                    'cashier_id' =>  $orders['Order_payment']['cashier_id'],
                    'type' =>  $orders['Order_payment']['type'],
                    'type_value' =>  $orders['Order_payment']['type_value'],
                    'amount' =>  $orders['Order_payment']['amount'],
                    'status' =>  $orders['Order_payment']['status'],
                    'remarks' =>  $orders['Order_payment']['remarks'],
                    'created' =>  $orders['Order_payment']['created']
                );
            }
        }
        $taxitems=[];
        $taxes = $this->Order_tax->query("SELECT tax_id,tax_name,tax_percentage,sum(tax_value) as tax_value FROM `order_tax` WHERE reference_id='$reference_id' and tax_percentage!=0 and status!=0 GROUP by tax_id");
        if(!empty($taxes))
        {
            foreach($taxes as $tax){
                
                $taxitems[]=array(
                    'tax_id' => $tax['order_tax']['tax_id'],
                    'tax_name' =>  $tax['order_tax']['tax_name'],
                    'tax_percentage' =>  $tax['order_tax']['tax_percentage'],
                    'tax_value' =>  "" .round($tax[0]['tax_value'],2)
                );
            }
        }
        
        $finalpayment=0;
        $allpayments=$this->Order_payment->query("SELECT sum(amount) as pay_amount FROM `order_payments` WHERE reference_id='$reference_id' and status=2");
        if($allpayments){
            $finalpayment=$allpayments[0][0]['pay_amount'];
        }
        
        $amount_diff=round(($finalamount-$finalpayment),2);
        if ($amount_diff < 1 && $amount_diff >= 0) {
            $amount_diff = 0;
        }
        
        $cashier_name='';
        $cashname=$this->User->query("SELECT name FROM `users` WHERE id='$cashierid'");
        if($cashname){
           $cashier_name =$cashname[0]['users']['name'];
        }
        
        $printeritems=[];
        $targetStoreId = !empty($users['User']['location_id']) ? $users['User']['location_id'] : (!empty($transactions[0]['order_transactions']['store_id']) ? $transactions[0]['order_transactions']['store_id'] : (!empty($orderss[0]['order_orderhistories']['store_id']) ? $orderss[0]['order_orderhistories']['store_id'] : ''));
        $printerCond = !empty($targetStoreId) ? "status=1 AND store_id='$targetStoreId'" : "status=1";
        $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE $printerCond");
        if(empty($printerss) && !empty($targetStoreId)){
            $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE status=1");
        }
        if(!empty($printerss))
        {
            foreach($printerss as $printers){
                
                $printeritems[]=array(
                    'id' => $printers['pos_printers']['id'],
                    'store_id' =>  $printers['pos_printers']['store_id'],
                    'name' =>  $printers['pos_printers']['name'],
                    'kds' =>  $printers['pos_printers']['kds'],
                    'ip' =>  $printers['pos_printers']['ip'],
                    'status' =>  $printers['pos_printers']['status']
                );
            }
        }
        
        $brandsale=[];
        $brandsaless = $this->Order_transaction->query("SELECT store_id,(SELECT name from locations WHERE id=order_transactions.store_id) as brandname,(SELECT print_line4 from locations WHERE id=order_transactions.store_id) as brandgst,orderno,(SELECT GROUP_CONCAT(CONCAT(type_value, ' - ', amount)) from order_payments WHERE status=2 and reference_id=order_transactions.reference_id and store_id=order_transactions.store_id) as payment_mode FROM `order_transactions` WHERE reference_id='$reference_id' and status!=0 GROUP by store_id");
        if(!empty($brandsaless))
        {
            foreach($brandsaless as $brandsales){
                
                $brandsale[]=array(
                   'store_id'     => $brandsales['order_transactions']['store_id'] ?? '',
                'brandname'    => $brandsales[0]['brandname'] ?? '',
                'brandgst'     => $brandsales[0]['brandgst'] ?? '',
                'orderno'      => $brandsales['order_transactions']['orderno'] ?? '',
                'payment_mode' => $brandsales[0]['payment_mode'] ?? ''
                );
            }
        }
        
        
        $response= array('status'=> true,
                'message'=> "success",
                'cashier_name'=>$cashier_name,
                'order_punch_by'=>$order_punch_by,
                'orders'=>$orderitems,
                'transactions'=>$transactionitems,
                'payments'=>$paymentitems,
                'taxes'=>$taxitems,
                'printers'=>$printeritems,
                'brandsale'=>$brandsale,
                'remaining_amount'=>number_format($amount_diff, 2, '.', ''),
                'reelo_discount_message' => $reeloDiscountMsg
            );
            
        return json_encode($response);
    }
    
    
    public function table_view_edit()
    {
        $this->autoRender = false;
        $user_id = isset($_REQUEST['id']) ? $_REQUEST['id'] : '';
        $reference_id = isset($_REQUEST['reference_id']) ? $_REQUEST['reference_id'] : '';
        $today = date("Y-m-d");
        //reference id 

        $startdate = date("Y-m-d");
        $enddate   = date("Y-m-d");
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$user_id,'User.status'=>1)));
        $location_id = !empty($users['User']['location_id']) ? $users['User']['location_id'] : null;

        $storeConfig = $this->Location->find('first', array('conditions' => array('Location.id' => $location_id)));
        $shiftstart = !empty($storeConfig['Location']['shift_start_time']) ? $storeConfig['Location']['shift_start_time'] : shiftstart;
        $shiftend = !empty($storeConfig['Location']['shift_end_time']) ? $storeConfig['Location']['shift_end_time'] : shiftend;
        
        $currentTime = date('H:i:s');
        if (strtotime($currentTime) <= strtotime($shiftend)) {
            $shiftDate = date('Y-m-d', strtotime('-1 day'));
        } else {
            $shiftDate = date('Y-m-d');
        }

        $shiftRange = $this->getShiftDateRange($shiftDate, $shiftDate, $location_id);
        $startDatetime = $shiftRange['startDatetime'];
        $endDatetime   = $shiftRange['endDatetime'];

        if (empty($reference_id)) {
            return json_encode(['status' => false, 'message' => "Reference Id Missing"]);
        }
    
        // Fetch KDS stations once
        $kdsStationCond = [
            'Kds_users_station_mapping.status' => 1
        ];
        if (!empty($location_id)) {
            $kdsStationCond['Kds_users_station_mapping.station_store_id'] = $location_id;
        }
        $kds_stations = $this->Kds_users_station_mapping->find('all', [
            'conditions' => $kdsStationCond,
            'group' => ['Kds_users_station_mapping.station_id'],
            'recursive' => -1
        ]);
        if (empty($kds_stations) && !empty($location_id)) {
            $kds_stations = $this->Kds_users_station_mapping->find('all', [
                'conditions' => ['Kds_users_station_mapping.status' => 1],
                'group' => ['Kds_users_station_mapping.station_id'],
                'recursive' => -1
            ]);
        }

        if (empty($kds_stations)) {
            return json_encode(['status' => false, 'message' => "No KDS stations assigned"]);
        }
    
        $stations_id = array();
        $stations_map = array();
        foreach ($kds_stations as $s) {
            $station = $s['Kds_users_station_mapping'];
            $stations_id[] = $station['station_id'];
            $stations_map[$station['station_id']] = array(
                'station_id' => $station['station_id'],
                'station_name' => $station['station_name'],
                'station_store_id' => $station['station_store_id'],
                'station_store_name' => $station['station_store_name'],
                'items' => array()
            );
        }
    
        if (empty($stations_id)) {
            $stations_id = array(0);
        }
    
        // Fetch all orders for today for these stations
        $orderConditions = array(
            'Order_orderhistory.created >=' => $startDatetime,
            'Order_orderhistory.created <=' => $endDatetime,
            'Order_orderhistory.status !=' => 0,
            'Order_orderhistory.kds' => $stations_id,
            'Order_orderhistory.reference_id' => $reference_id
        );
        if (!empty($location_id)) {
            $orderConditions['Order_orderhistory.store_id'] = $location_id;
        }
        $orders_raw = $this->Order_orderhistory->find('all', [
            'conditions' => $orderConditions,
            'fields' => array(
                'Order_orderhistory.*',
                'Order_table.waiter_name',
                'GROUP_CONCAT(DISTINCT Order_orderhistory.kot_number ORDER BY Order_orderhistory.kot_number SEPARATOR ", ") AS kot_numbers'
            ),
            'joins' => array(
                array(
                    'table' => 'order_tables',
                    'alias' => 'Order_table',
                    'type' => 'LEFT',
                    'conditions' => array('Order_table.reference_id = Order_orderhistory.reference_id')
                )
            ),
            'group' => array('Order_orderhistory.reference_id', 'Order_orderhistory.group_id'),
            'order' => ['Order_orderhistory.id DESC'],  // ðŸ‘ˆ Added order by
            //'limit' => 10,   //  Added limit here
            'recursive' => -1
        ]);
    
        if (empty($orders_raw)) {
            return json_encode(array('status' => false, 'message' => "No Order found"));
        }
    
        // Collect all reference_ids
        $reference_ids = array();
        foreach ($orders_raw as $o) {
            $reference_ids[] = $o['Order_orderhistory']['reference_id'];
            $group_ids[] = $o['Order_orderhistory']['group_id'];
        }
    
        $orderItemConditions = array(
            'Order_orderhistory.status !=' => 0,
            'Order_orderhistory.created >=' => $startDatetime,
            'Order_orderhistory.created <=' => $endDatetime,
            'Order_orderhistory.reference_id' => $reference_ids,
            'Order_orderhistory.group_id' => $group_ids,
            'Order_orderhistory.kds' => $stations_id
        );
        if (!empty($location_id)) {
            $orderItemConditions['Order_orderhistory.store_id'] = $location_id;
        }
        $order_items_raw = $this->Order_orderhistory->find('all', array(
            'conditions' => $orderItemConditions,
            'fields' => array(
                'Order_orderhistory.*',
                'Catalog_product.preparation_time'
            ),
            'joins' => array(
                array(
                    'table' => 'catalog_product',
                    'alias' => 'Catalog_product',
                    'type' => 'LEFT',
                    'conditions' => array('Catalog_product.id = Order_orderhistory.product_id')
                )
            ),
            'recursive' => -1
        ));
    
        // Fetch all modifiers in bulk
        $order_items_ids = array();
        foreach ($order_items_raw as $oi) {
            $order_items_ids[] = $oi['Order_orderhistory']['id'];
        }
    
        $modifiers_raw = array();
        if (!empty($order_items_ids)) {
            $modifiers_raw = $this->Order_modifier->find('all', array(
                'conditions' => array(
                    'Order_modifier.orderhistory_id' => $order_items_ids,
                    'Order_modifier.status !=' => 0
                ),
                'recursive' => -1
            ));
        }
    
        // Map modifiers by orderhistory_id
        $modifiers_map = array();
        foreach ($modifiers_raw as $mod) {
            $m = $mod['Order_modifier'];
            $modifiers_map[$m['orderhistory_id']][] = array(
                'modifier_group_id' => $m['modifier_group_id'],
                'modifier_group_name' => $m['modifier_group_name'],
                'modifier_id' => $m['modifier_id'],
                'modifier_name' => $m['modifier_name'],
                'modifier_price' => $m['modifier_price']
            );
        }
    
        // Organize items under stations and references
        $orders = array();
        foreach ($orders_raw as $order) {
            $order_data = $order['Order_orderhistory'];
            $reference_id = $order_data['reference_id'];
            $group_id = $order_data['group_id'];
            $kotNumbers = $order[0]['kot_numbers'];  // from the custom SQL field
            
            $stations = array();
            foreach ($stations_map as $station_id => $station_data) {
                $items = array();
                foreach ($order_items_raw as $oi) {
                    $oi_data = $oi['Order_orderhistory'];
                    if ($oi_data['reference_id'] == $reference_id && $oi_data['kds'] == $station_id && $oi_data['group_id'] == $group_id ) {
                        
                        
                        $kds_last_details = $this->Kds_track->find('first', [
                            'conditions' => [
                                'Kds_track.order_reference_id' => $reference_id,
                                'Kds_track.kds_group_id'       => $group_id,
                                'Kds_track.product_id'         => $oi_data['product_id'],
                                'Kds_track.status'             => 1
                            ],
                            'order'     => ['Kds_track.id' => 'DESC'], // latest record
                            'recursive' => -1
                        ]);
                        
                        if (empty($kds_last_details)) {
                            $kds_time = $oi_data['created'];
                        } else {
                            $kds_time = $kds_last_details['Kds_track']['created'];
                        }

                        $items[] = array(
                            'order_history_id' => $oi_data['id'],
                            'group_id' => $oi_data['group_id'],
                            'item_id' => $oi_data['product_id'],
                            'quantity' => $oi_data['quantity'],
                            'item_name' => $oi_data['product_name'],
                            'kds_status' => $oi_data['kds_status'],
                            'kds_status_update_at' => $kds_time,
                            'remarks' => $oi_data['remarks'],
                            'prep_time' => strval(isset($oi['Catalog_product']['preparation_time']) ? $oi['Catalog_product']['preparation_time'] : '0'),
                            'modifiers' => isset($modifiers_map[$oi_data['id']]) ? $modifiers_map[$oi_data['id']] : array(),
                            // --- B2G1 cross-KOT offer fields ---
                            'price'      => $oi_data['price'] ?? '',
                            'offer_id'   => $oi_data['offer_id'] ?? '',
                            'offer_type' => $oi_data['offer_type'] ?? '',
                            'offer_name' => $oi_data['offer_name'] ?? '',
                            'is_offer'   => $oi_data['is_offer'] ?? '0',
                            'is_voided'  => ($oi_data['status'] == '0') ? '1' : '0',
                            'is_free'    => (($oi_data['price'] ?? '') == '0' && ($oi_data['offer_id'] ?? '') != '') ? '1' : '0',
                            'createdAt'  => $oi_data['created'] ?? ($order_data['created'] ?? '')
                        );
                    }
                }
                $station_data['items'] = $items;
                if($station_data['items']){
                    $stations[] = $station_data;
                }
            }
            
            if($order_data['table_number']){
                $table_number=$order_data['table_number'];
            }else{
                $table_number='Quick Order';
            }
    
            $orders[] = array(
                'kds_ref_id' => $reference_id,
                'kds_group_id' => $group_id,
                'table_no' => $table_number,
                'kot_number' => $kotNumbers,
                'created' => $order_data['created'],
                'waiter_name' => isset($order['Order_table']['waiter_name']) ? $order['Order_table']['waiter_name'] : '',
                'kds_status' => $order_data['kds_status'],
                'stations' => $stations
            );
        }
    
        return json_encode(array('status' => true, 'orders' => $orders), JSON_UNESCAPED_UNICODE);
    }
    
    public function payment_mode_update()
    {
        $response['status']= false;
        $response['message']= "fail";
        
        $cashierid = $_REQUEST['id'];
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id is Missing",
            );
            return json_encode($response);
        }
        
        $reference_id = $_REQUEST['reference_id'];
        if($reference_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Reference Id is Missing",
            );
            return json_encode($response);
        }
        
        $payment_type = $_REQUEST['type'];
        if($payment_type==''){
            $response =array(
                'status'=> false,
                'message'=> "Payment type is Missing",
            );
            return json_encode($response);
        }
        
        $payment_type_value = $_REQUEST['type_value'];
        if($payment_type_value==''){
            $response =array(
                'status'=> false,
                'message'=> "Payment type Value is Missing",
            );
            return json_encode($response);
        }
        
        $amount = $_REQUEST['amount'];
        if($amount==''){
            $response =array(
                'status'=> false,
                'message'=> "Payment Amount is Missing",
            );
            return json_encode($response);
        }
        
        $device_id=$_REQUEST['device_id'];
        $remarks='';
        $remarks=$_REQUEST['remarks'];
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        // Check if there is an active wallet discount in reelo_discount
        $this->loadModel('ReeloDiscount');
        
        $reeloDiscount = $this->ReeloDiscount->find('first', array(
            'conditions' => array(
                'ReeloDiscount.reference_id' => $reference_id,
                'ReeloDiscount.status' => 1,
                'ReeloDiscount.reelo_discount_type' => 2
            )
        ));
        
        if (!empty($reeloDiscount)) {
            $this->ReeloDiscount->query("UPDATE reelo_discounts SET sync = 0, local_sync = 0, status = 0 WHERE reference_id = '$reference_id'");
        }

        //payment save
        
        $transactions = $this->Order_transaction->find('first', array('conditions'=>array('Order_transaction.reference_id'=>$reference_id,'Order_transaction.status'=>2)));
        if(empty($transactions))
        {
            $response =array(
                'status'=> false,
                'message'=> "Transaction not billed",
            );
            return json_encode($response);
        }
        $reference_id=$transactions['Order_transaction']['reference_id'];
        $total_amount=$transactions['Order_transaction']['amount'];
        $store_id=$transactions['Order_transaction']['store_id'];
        if($amount>=$total_amount){
            $this->Order_payment->query("UPDATE order_payments SET status = 0,sync=0,local_sync=0 WHERE reference_id = '$reference_id'");
                                
            $datas['Order_payment']=array(
                'reference_id'=>$reference_id,
                'device_id'=>$device_id,
                'store_id'=>$store_id,
                'cashier_id'=>$cashierid,
                'type'=>$payment_type,
                'type_value'=>$payment_type_value,
                'amount'=>$amount,
                'remarks'=>$remarks,
                'status'=>2
            );
            
            if($this->Order_payment->saveAll($datas['Order_payment']))
            {
                $response['status']= true;
                $response['message']= "Payment Mode Updated Successfully..!";
            
                // Call sale_return if transaction was synced with Reelo
                if (!empty($transactions) && $transactions['Order_transaction']['reelo_sync'] == 1) {
                    
                    $this->Order_transaction->query("UPDATE order_transactions SET reelo_sync = 0 WHERE id = " . intval($transactions['Order_transaction']['id']));
                    $transactions['Order_transaction']['reelo_sync'] = 0;
                    
                    App::uses('ReeloApisController', 'Controller');
                    $reeloApis = new ReeloApisController($this->request, $this->response);
                    $reeloApis->constructClasses();

                    $origReqReferenceId = $_REQUEST['reference_id'] ?? null;
                    $_REQUEST['reference_id'] = $reference_id;

                    $reeloApis->sale_return();

                    if ($origReqReferenceId !== null) {
                        $_REQUEST['reference_id'] = $origReqReferenceId;
                    } else {
                        unset($_REQUEST['reference_id']);
                    }
                }
            }else{
                $response['status']= false;
                $response['message']= "Payment Mode not Saved..!";
            }
        }else{
            $response['status']= false;
            $response['message']= "Update Failed !! Payment Mode Update Can't accept Partial payments..!!";
        }
        return json_encode($response);
    }
    
    public function bill_preview()
    {
        $cashierid = $_REQUEST['id'];
        $ref_id=$_REQUEST['reference_id'];
        $disc=0;
        
        $locIdForSc = $this->resolveLocationIdForTxn($ref_id, $cashierid);
        $sc = $this->getLocationServiceChargeRate($locIdForSc ?? null);
        
        $type = 1;
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "User Id Missing",
            );
            return json_encode($response);
        }
        
        
        $todayDate = date("Y-m-d");
        
        $ref_id = [$ref_id]; // convert initial ref id to array

        $refid = []; // T9-fix: ensure $refid is always an array even with no merged tables

        $mergetablecheck = $this->Order_table_tracking->find('all', [
            'conditions' => [
                'Order_table_tracking.main_table_ref_id' => $ref_id[0],
                'Order_table_tracking.status' => 1,
                "DATE(Order_table_tracking.created) =" => $todayDate
            ]
        ]);
        if (!empty($mergetablecheck)) {
            foreach ($mergetablecheck as $merge) {
                $ref_id[] = $merge['Order_table_tracking']['merged_table_ref_id']; 
            }
        }
        $ref_in = "'" . implode("','", $ref_id) . "'";
        
        if($type==0){
            if(!empty($disc)){
                $coup = $this->Coupon->find('first', array('conditions'=>array('Coupon.code'=>$disc,'Coupon.expiry_date >='=>$todayDate,'Coupon.status'=>1)));
                if(empty($coup))
                {
                    $response =array(
                        'status'=> false,
                        'message'=> "Coupon not found Or Coupon Expired",
                    );
                    return json_encode($response);
                }
                $disc=$coup['Coupon']['value'];
            }else{
                $disc=0;
            }
        }
        
        if($type==1){
            $disc=$disc;
        }
        
        if($type==2){
            $subtotals = $this->Order_orderhistory->query("SELECT SUM(total_price) as subtotal FROM `order_orderhistories` WHERE status!=0 and reference_id IN ($ref_in)");
            
            if($subtotals){
                $subtotal=$subtotals[0][0]['subtotal'];
                if($subtotal){
                    $disc=(($disc*100)/$subtotal);
                }else{
                    $response =array(
                        'status'=> false,
                        'message'=> "Bill Not Found",
                    );
                    return json_encode($response);
                }
            }else{
                $response =array(
                    'status'=> false,
                    'message'=> "Bill Not Found",
                );
                return json_encode($response);
            }
        }
        
        if($disc>99){
            $response =array(
                'status'=> false,
                'message'=> "Discount is not more than 99%",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        if($disc>=0){
            $checkdiscount=$this->Order_orderhistory->find('first',array('conditions'=>array('Order_orderhistory.discount > '=>0,'Order_orderhistory.cashier_id'=>$cashierid,'Order_orderhistory.status'=>2,'Order_orderhistory.reference_id IN'=>$ref_id)));
            if(!empty($checkdiscount)){
                $response['status']= false;
                $response['message']= "Discount can not merge with item level discount";
                return json_encode($response);     
            }
        }else{
            $response['status']= false;
            $response['message']= "please check discount value";
            return json_encode($response);  
        }
        $orderdata=$this->ordercomputewithdiscounttemp($ref_id,$cashierid,$sc,$disc);
            
        if($orderdata['status'])
        {
            $totalservicechg=$orderdata['totalservicechg'];
            $totalprice=$orderdata['totalprice'];
            $totaltax=$orderdata['totaltax'];
            $totaldiscount=$orderdata['totaldiscount'];
            $totalamount=round((($totalprice+$totaltax+$totalservicechg)-$totaldiscount),2);
            
            
            $orderitems=[];
            $orderss = $this->Order_orderhistory->query("SELECT id,reference_id,group_id,cashier_id,category,category_name,kds,product_id,product_name,SUM(quantity) as quantity,price,sum(total_tax) as total_tax,sum(total_tax_percentage) as total_tax_percentage,sum(total_price) as total_price,SUM(discount) as discount,table_number,remarks,device_id,status,created FROM `order_orderhistories` WHERE reference_id IN ($ref_in) and status!=0 group BY product_id");
            if(!empty($orderss))
            {
                foreach($orderss as $orders){
                    if(!isset($orders['order_orderhistories']['remarks'])){
                        $orders['order_orderhistories']['remarks']='';
                    }
                    
                    $taxesitems=[];
                    $taxess = $this->Catalog_product_tax->find('all', array('conditions'=>array('Catalog_product_tax.product_id'=>$orders['order_orderhistories']['product_id'],'Catalog_product_tax.status'=>1)));
                    foreach($taxess as $tax){
                        $taxesitems[]=array(
