                    }
                    
                    $orderitems[]=array(
                        'id' => $orders['order_orderhistories']['id'],
                        'reference_id' =>  $orders['order_orderhistories']['reference_id'],
                        'cashier_id' =>  $orders['order_orderhistories']['cashier_id'],
                        'group_id' =>  $orders['order_orderhistories']['group_id'],
                        'category' =>  $orders['order_orderhistories']['category'],
                        'category_name' =>  $orders['order_orderhistories']['category_name'],
                        'kds' =>  $orders['order_orderhistories']['kds'],
                        'product_id' =>  $orders['order_orderhistories']['product_id'],
                        'product_name' =>  $orders['order_orderhistories']['product_name'],
                        'quantity' =>  $orders[0]['quantity'],
                        'price' =>  $orders['order_orderhistories']['price'],
                        'total_tax' =>  $orders[0]['total_tax'],
                        'total_price' =>  $orders[0]['total_price'],
                        'discount' =>  $orders[0]['discount'],
                        'table_number' =>  $orders['order_orderhistories']['table_number'],
                        'remarks' =>  $orders['order_orderhistories']['remarks'],
                        'status' =>  $orders['order_orderhistories']['status'],
                        'created' =>  $orders['order_orderhistories']['created'],
                        'taxes'=>$taxesitems
                    );
                }
            }
            $tablenomb=0;
            $tableno=$this->Order_table->query("SELECT GROUP_CONCAT(number) as tbale FROM `order_tables` WHERE status!=0 and reference_id IN ($ref_in)");
            if($tableno){
               $tablenomb =$tableno[0][0]['tbale'];
            }
            
            $finalamount=0;
            $transactionitems=[];
            $createtime = date('H:i:s');
            $transactionitems[]=array(
                'id' => '',
                'reference_id' =>  $ref_in,
                'orderno' =>  '',
                'device_id' =>  '',
                'cashier_id' =>  $cashierid,
                'table_number'        => (string) $tablenomb,
                'price'               => (string) number_format($totalprice, 2), // optional 2 decimals
                'total_tax'           => (string) round($totaltax, 2),
                'servicecharge'       => (string) $totalservicechg,
                'discount'            => (string) $totaldiscount,
                'discount_percentage' => (string) $disc,
                'delivery_charge'     => '0',
                'packing_charge'      => '0',
                'amount'              => (string) round($totalamount, 0),
                'round'               => '0',
                'name' =>  '',
                'phone' =>  '',
                'address' => '',
                'remarks' =>  '',
                'status' =>  '',
                'tokenno' =>  '',
                'createtime' =>  $createtime,
                'created' =>  ''
            );
            
            $paymentitems=[];
            
            $taxitems=[];
            $taxess=$orderdata['taxes'];
            foreach($taxess as $tax){
                $taxitems[]=array(
                    'tax_id' => $tax['tax_id'],
                    'tax_name' =>  $tax['tax_name'],
                    'tax_percentage' =>  $tax['tax_percentage'],
                    'tax_value' =>  number_format($tax['tax_value'],1)
                );
            }
                
            $amount_diff=0;
            
            $cashier_name='';
            $cashname=$this->User->query("SELECT name FROM `users` WHERE id='$cashierid'");
            if($cashname){
               $cashier_name =$cashname[0]['users']['name'];
            }
            
            $printeritems=[];
            $targetStoreId = !empty($locIdForSc) ? $locIdForSc : '';
            $printerCond = !empty($targetStoreId) ? "status=1 AND store_id='$targetStoreId'" : "status=1";
            $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE $printerCond");
            if(empty($printerss) && !empty($targetStoreId)){
                $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE status=1");
            }
            if(!empty($printerss))
            {
                foreach($printerss as $printers){
                    
                    $printeritems[]=array(
                        'id' => $printers['pos_printers']['id'],
                        'store_id' =>  $printers['pos_printers']['store_id'],
