        }else{
            $response =array(
                'status'=> false,
                'message'=> "No data found",
            );
            return json_encode($response);
        }
    }
    
    public function ordercomputewithdiscounttemp($txnids=null,$user_id=null,$is_sc=1,$discount=0)
    {
        $response['status']=false;
        $totalservicechg=0;
        $totalprice=0;
        $totaltax1=0;
        $totaltax2=0;
        $totaldiscount=0;
        $sc=0;
        
        if (!is_array($txnids)) {
            $txnids = [$txnids];
        }
        if($is_sc==1){
            $locIdForSc = $this->resolveLocationIdForTxn($txnids, $user_id);
            $sc = $this->getLocationServiceChargeRate($locIdForSc);
        }
        $discq="(((Order_orderhistory.total_price)-(Order_orderhistory.discount))*$discount/100)";
        $priceq="((Order_orderhistory.total_price)-(Order_orderhistory.discount))";
    
        $this->Order_orderhistory->virtualFields = array('tdisc'=>"SUM($discq)",'tservicechg'=>"SUM(($priceq-$discq)*($sc/100))",'tprice'=>"SUM($priceq)",'total_tax'=>"SUM(($priceq+(($priceq-$discq)*($sc/100))-$discq)*((Order_orderhistory.total_tax_percentage)/100))");  
        
        $orderhistories=$this->Order_orderhistory->find('first',array('conditions'=>array('Order_orderhistory.reference_id IN'=>$txnids,'Order_orderhistory.status !=' =>0),'fields'=>array('tdisc','Order_orderhistory.reference_id','tprice','total_tax','tservicechg')));
                
        if(!empty($orderhistories)){
            $response['status']=true;
            $totalservicechg=round($orderhistories['Order_orderhistory']['tservicechg'],2);
            $totalprice=round($orderhistories['Order_orderhistory']['tprice'],2);
            $totaltax=round($orderhistories['Order_orderhistory']['total_tax'],2);
            $totaldiscount=round($orderhistories['Order_orderhistory']['tdisc'],2);
            
            //tax update
            $discq="(((Order_orderhistory.price)-(Order_orderhistory.discount))*$discount/100)";
            $priceq="((Order_orderhistory.price)-(Order_orderhistory.discount))";
            
            $taxes=[];
            
            $this->Order_orderhistory->virtualFields = array('tamount'=>"($priceq+(($priceq-$discq)*($sc/100))-$discq)");  
            $neworderhistories=$this->Order_orderhistory->find('all',array('conditions'=>array('Order_orderhistory.reference_id IN'=>$txnids,'Order_orderhistory.cashier_id'=>$user_id,'Order_orderhistory.status !='=>0),'fields'=>array('Order_orderhistory.reference_id','tamount','product_id','price')));
            foreach($neworderhistories as $data){
                $reference_id=$data['Order_orderhistory']['reference_id'];
                $product_id=$data['Order_orderhistory']['product_id'];
                $tamount=$data['Order_orderhistory']['tamount'];
                $price=$data['Order_orderhistory']['price'];
                
                $taxitem=$this->Order_tax->find('all',array('conditions'=>array('Order_tax.reference_id IN'=>$txnids,'Order_tax.product_id'=>$product_id,'Order_tax.status !='=>0)));
                foreach($taxitem as $item){
                    $id=$item['Order_tax']['id'];
                    $tax_id=$item['Order_tax']['tax_id'];
                    $tax_percentage=$item['Order_tax']['tax_percentage'];
                    $quantity=$item['Order_tax']['quantity'];
                    $taxamount=round($tamount*$quantity,2);
                    $taxvalue=round((($tamount*$quantity*$tax_percentage)/100),2);
                    
                    if (isset($taxes[$tax_id])) {
                        $taxes[$tax_id]['tax_value'] += round($taxvalue, 2);
                    } else {
                        // Add new entry if tax_id doesn't exist
                        $taxes[$tax_id] = array(
                            'id' => $id,
                            'tax_id' =>  $item['Order_tax']['tax_id'],
                            'tax_name' => $item['Order_tax']['tax_name'],
                            'tax_percentage' => $tax_percentage,
                            'tax_value' => number_format($taxvalue, 2)
                        );
                    }
                }
            }
            
            $response['totalservicechg']=$totalservicechg;
            $response['totalprice']=$totalprice;
            $response['totaltax']=$totaltax;
            $response['totaldiscount']=$totaldiscount;
            $response['taxes']=$taxes;
        }
        return $response;
    }
    
    public function bill_table_package()
    {
        $response['status']= false;
        $response['message']= "fail";
        
        $cashierid = $_REQUEST['id'];
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id is Missing",
            );
            return json_encode($response);
        }
        $table_number = $_REQUEST['table_number'];
        if($table_number==''){
            $response =array(
                'status'=> false,
                'message'=> "Table Number is Missing",
            );
            return json_encode($response);
        }
        $table_referenceid = $_REQUEST['reference_id'];
        if($table_referenceid==''){
            $response =array(
                'status'=> false,
                'message'=> "Table refernce Id is Missing",
            );
            return json_encode($response);
        }
        $device_id='';
        if(isset($_REQUEST['device_id'])){
            $device_id=$_REQUEST['device_id'];
        }
        $name='';
        if(isset($_REQUEST['name'])){
            $name=$_REQUEST['name'];
        }
        $phone='';
        if(isset($_REQUEST['phone'])){
            $phone=$_REQUEST['phone'];
        }
        $address='';
        if(isset($_REQUEST['address'])){
            $address=$_REQUEST['address'];
        }
        $pax=1;
        if(isset($_REQUEST['pax'])){
            $pax=$_REQUEST['pax'];
        }
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        else{
            $location_id = $users['User']['location_id'];
        }
            
        $tablechk = $this->Order_table->find('first', array('conditions'=>array('Order_table.reference_id'=>$table_referenceid,'Order_table.number'=>$table_number,'Order_table.status'=>2)));
        if(empty($tablechk))
        {
            $response =array(
                'status'=> false,
                'message'=> "Something went wrong for this table kindly check!!!",
            );
            return json_encode($response);
        }
        $waiter_id=$tablechk['Order_table']['waiter_id'];
        $waiter_name = $tablechk['Order_table']['waiter_name'];
        $pax = $tablechk['Order_table']['customer_pax'] ?? 1;
        $name    = trim($tablechk['Order_table']['customer_name']);
        $phone   = trim($tablechk['Order_table']['customer_phone']);
        $address = trim($tablechk['Order_table']['customer_address']);
        $is_takeaway = $tablechk['Order_table']['is_takeaway'];

        $customerchk = $this->Order_customers->find('first', [
            'conditions' => ['Order_customers.phone' => $phone,'Order_customers.status !=' => 0],
            'fields' => ['Order_customers.id'],
            'recursive' => -1
        ]);
    
        if (empty($customerchk)) {
            // Insert new customer
            $data = [
                'Order_customers' => [
                    'phone'   => $phone,
                    'name'    => $name,
                    'address' => $address
                ]
            ];
    
            if ($this->Order_customers->saveAll($data)) {
                
            } else {
                return json_encode([
                    'status' => false,
                    'message' => "Failed to save customer details."
                ]);
            }
        } else {
            // Customer already exists — optional: update their name/address if needed
            $this->Order_customers->id = $customerchk['Order_customers']['id'];
            $this->Order_customers->save([
                'name' => $name,
                'address' => $address
            ]);
    
        }
        
        $this->Order_table->updateAll(
            [
                // 'Order_table.waiter_id' => "'0'",
                // 'Order_table.waiter_name' => "''",
                // 'Order_table.customer_address' => "''",
                // 'Order_table.customer_phone' => "''",
                'Order_table.sync'          => 0,
                'Order_table.local_sync'    => 0        
            ],
            ['Order_table.reference_id' => $table_referenceid]
        );
        
        $trxchck = $this->Order_transaction->find('first', array(
            'conditions' => array(
                'Order_transaction.reference_id' => $table_referenceid,
                'NOT' => array('Order_transaction.status' => array(3, 4, 0))
            )
        ));
        if(!empty($trxchck))
        {
            $response =array(
                'status'=> false,
                'message'=> "Reference Id already Exist",
            );
            return json_encode($response);
        }        
        
        $todayDate = date("Y-m-d");
            
        $refid = []; // T9-fix: ensure $refid is always an array even with no merged tables

        $mergetablecheck = $this->Order_table_tracking->find('all', [
            'conditions' => [
                'Order_table_tracking.main_table_ref_id' => $table_referenceid,
                'Order_table_tracking.status' => 1,
                "DATE(Order_table_tracking.created) =" => $todayDate
            ]
        ]);
        if (!empty($mergetablecheck)) {
            foreach ($mergetablecheck as $merge) {
                $refid[] = $merge['Order_table_tracking']['merged_table_ref_id']; 
            }
        }
        
        $refid = "'" . implode("','", $refid) . "'";
        
        $this->Order_orderhistory->query("
            UPDATE order_orderhistories o
            SET o.reference_id = '$table_referenceid',o.sync=0,o.local_sync=0
            WHERE o.reference_id IN ($refid)
        ");
        
        $this->Order_tax->query("
            UPDATE order_tax t
            SET t.reference_id = '$table_referenceid',t.sync=0,t.local_sync=0
            WHERE t.reference_id IN ($refid)
        ");
        
        //chk package value in table - item in ordergistory link quanti*package
        // Fetch all product_ids for the given reference_id
        // 1. Set package=1 for packaged items using JOIN (efficient)
        $this->Order_orderhistory->query("
            UPDATE order_orderhistories o
            JOIN catalog_package p ON o.product_id = p.main_product_id AND p.status = 1
            SET o.package = 1,o.sync=0,o.local_sync=0
            WHERE o.reference_id = '$table_referenceid' AND o.status != 0
        ");
        
        $this->Order_tax->query("
            UPDATE order_tax t
            JOIN catalog_package p ON t.product_id = p.main_product_id AND p.status = 1
            SET t.package = 1,t.sync=0,t.local_sync=0
            WHERE t.reference_id = '$table_referenceid' AND t.status = 1
        ");
        // 2. Get total packaged quantity
        $total_package = 0;
        $totalpackagechkorder = $this->Order_orderhistory->query("
            SELECT SUM(package) AS total_package
            FROM order_orderhistories 
            WHERE reference_id = '$table_referenceid' AND status != 0 AND package = 1
        ");
        $packagechngchk=false;
        if (!empty($totalpackagechkorder[0][0]['total_package'])) {
            
            $total_package = isset($totalpackagechkorder[0][0]['total_package']) 
                ? $totalpackagechkorder[0][0]['total_package'] 
                : 0;
                // 3. Non-package items and discount percentage logic
                $discount_percentage = 0;
                $nonpackagechkorder = $this->Order_orderhistory->query("
                    SELECT product_id, SUM(quantity) as order_quantity
                    FROM order_orderhistories 
                    WHERE reference_id = '$table_referenceid' AND status != 0 AND package = 0
                    GROUP BY product_id
                ");
                $discount_pro_array = []; // initialize
                foreach ($nonpackagechkorder as $row) {
                    $orderproduct_id = $row['order_orderhistories']['product_id'];
                    $orderproduct_quantity = $row[0]['order_quantity'];
                    
                    // 4. Find linked package quantity for this non-package item
                    $linkpackagechk = $this->Catalog_package->query("
                        SELECT SUM(link_quantity) AS link_qty,link_product_id
                        FROM catalog_package
                        WHERE link_product_id = '$orderproduct_id' AND status = 1
                        AND main_product_id IN (
                            SELECT product_id 
                            FROM order_orderhistories 
                            WHERE reference_id = '$table_referenceid' AND package = 1 AND status != 0
                        )
                    ");
                    
                    $link_package_item_quantity = 0;
                    if (!empty($linkpackagechk[0][0]['link_qty'])) {
                        $link_package_item_quantity = $linkpackagechk[0][0]['link_qty'];
                    }
                    
                    // 5. Calculate discount
                    if ($orderproduct_quantity <= $link_package_item_quantity) {
                        $discount_percentage = 100;
                    } elseif ($link_package_item_quantity > 0) {
                        $discount_percentage = round(($link_package_item_quantity * 100) / $orderproduct_quantity, 2);
                    } else {
                        $discount_percentage = 0;
                    }
                
                    $orderdata = $this->ordercomputewithpackagediscount($table_referenceid, $cashierid,$orderproduct_id, $discount_percentage);
                    if($orderdata['status'])
                    {
                        $packagechngchk=true;
                    }
                }
            }

            //discount update in ordertax
            $orderss = $this->Order_orderhistory->query("SELECT sum(price) as price,sum(total_tax) as total_tax,sum(total_price) as total_price,sum(discount) as discount FROM `order_orderhistories` WHERE reference_id='$table_referenceid' and status!=0");
            if(!empty($orderss))
            {
                if($orderss[0][0]['total_price']<1){
                    $response =array(
                        'status'=> false,
                        'message'=> "There is no item to bill. Please Check..!",
                    );
                    return json_encode($response);
                }
                
                $todayDate = date("Y-m-d");
                $tdaytrx=$this->Order_transaction->query("SELECT COUNT(id) as tkn FROM `order_transactions` WHERE date(created)='$todayDate' and status=2");
                $token=$tdaytrx['0']['0']['tkn']+1;
                $currenttime=date("H:i:s");
                $updated_discount=0;
                $updated_tax=0;
                $updated_final_amount=0;
                if($packagechngchk){
                    $orderstaxdatas = $this->Order_tax->query("SELECT ot.product_id, SUM((ot.price * ot.quantity) * (ot.discount_percentage / 100)) AS discounted_total, SUM(((ot.price * ot.quantity) * (ot.discount_percentage / 100)) * (IFNULL(ooh.tax_percent, 0) / 100)) AS total_tax, SUM(((ot.price * ot.quantity) * (ot.discount_percentage / 100)) * (1 + (IFNULL(ooh.tax_percent, 0) / 100))) AS final_amount FROM order_tax ot LEFT JOIN ( SELECT product_id, SUM(total_tax_percentage) AS tax_percent FROM order_orderhistories WHERE reference_id = '$table_referenceid' AND status = 1 GROUP BY product_id ) ooh ON ooh.product_id = ot.product_id WHERE ot.reference_id = '$table_referenceid' AND ot.package = 0 AND ot.status = 1");
                    if(!empty($orderstaxdatas))
                    {
                        $updated_discount=$orderstaxdatas[0][0]['discounted_total'];
                        $updated_tax=$orderstaxdatas[0][0]['total_tax'];
                        $updated_final_amount=$orderstaxdatas[0][0]['final_amount'];
                    }
                }
                $grand_total = $orderss[0][0]['total_price'] + $orderss[0][0]['total_tax'];
                $net_total = $grand_total - $orderss[0][0]['discount'] - $updated_final_amount;
                
                $finalamount = round(($orderss[0][0]['total_price']+$orderss[0][0]['total_tax'])-$orderss[0][0]['discount']-$updated_final_amount);        // Rounded to nearest integer
                $roundfinalamount = round(($orderss[0][0]['total_price']+$orderss[0][0]['total_tax'])-$orderss[0][0]['discount']-$updated_final_amount,2); // Rounded to 2 decimal places
                
                $round_amount = $finalamount - $roundfinalamount;
                
                $datas['Order_transaction']=array(
                    'reference_id'=>$table_referenceid,
                    'device_id'=>$device_id,
                    'cashier_id'=>$cashierid,
                    'store_id'=>$location_id,
                    'price'=>round($orderss[0][0]['total_price']-$updated_discount,2),
                    'total_tax'=>round($orderss[0][0]['total_tax']-$updated_tax,2),
                    'discount'=>round($orderss[0][0]['discount'],2),
                    'amount'=>$finalamount,
                    'round'=>round($round_amount,2),
                    'name'=>$name,
                    'phone'=>$phone,
                    'address'=>$address,
                    'tokenno'=>$token,
                    'table_number'=>$table_number,
                    'pax'=>$pax,
                    'waiter_id'=>$waiter_id,
                    'waiter_name'=>$waiter_name,
                    'is_takeaway' => $is_takeaway,
                    'createtime'=>$currenttime
                );
                if($this->Order_transaction->saveAll($datas['Order_transaction']))
                {
                    $this->Order_table->query("UPDATE order_tables SET status = 3,sync=0,local_sync=0 WHERE reference_id = '$table_referenceid' and status!=0");
                    $this->Order_table->query("UPDATE order_tables SET status = 1,sync=0,local_sync=0 WHERE reference_id IN ($refid)  and status!=0");
                    $this->Order_table_tracking->query("UPDATE order_table_tracking SET status = 0,sync=0,local_sync=0 WHERE merged_table_ref_id IN ($refid)");
            
                    $response['status']= true;
                    $response['message']= "Bill Generated Successfully..!";
                }else{
                    $response['status']= false;
                    $response['message']= "Transaction Data not saved Error:103";
                }
            }
        
        return json_encode($response);
    }
    
    public function custom_quantity_update()
    {
        $this->autoRender = false;
    
        $response = ['status' => false, 'message' => 'Failed'];
    
        // ✅ Safely read inputs
        $cashierid    = isset($_REQUEST['id']) ? trim($_REQUEST['id']) : '';
        $reference_id = isset($_REQUEST['reference_id']) ? trim($_REQUEST['reference_id']) : '';
        $quantity     = isset($_REQUEST['quantity']) ? trim($_REQUEST['quantity']) : '';
        $order_id     = isset($_REQUEST['order_id']) ? trim($_REQUEST['order_id']) : '';
    
        // ✅ Input validation
        if ($cashierid === '') {
            return json_encode(['status' => false, 'message' => 'Cashier ID is missing']);
        }
        if ($reference_id === '') {
            return json_encode(['status' => false, 'message' => 'Reference ID is missing']);
        }
        if ($quantity === '' || !is_numeric($quantity) || $quantity <= 0) {
            return json_encode(['status' => false, 'message' => 'Quantity is missing or invalid']);
        }
        if ($order_id === '') {
            return json_encode(['status' => false, 'message' => 'Order ID is missing']);
        }
    
        // ✅ Check if user exists
        $user = $this->User->find('first', [
            'conditions' => ['User.id' => $cashierid, 'User.status' => 1],
            'recursive' => -1
        ]);
    
        if (empty($user)) {
            return json_encode(['status' => false, 'message' => 'User not found']);
        }
    
        // ✅ Check if table exists
        $table = $this->Order_table->find('first', [
            'conditions' => [
                'Order_table.reference_id' => $reference_id,
                'Order_table.status IN' => [2,4]
            ],
            'recursive' => -1
        ]);
    
        if (empty($table)) {
            return json_encode(['status' => false, 'message' => 'Table not available for quantity update']);
        }
    
        // ✅ Fetch existing order
        $data = $this->Order_orderhistory->find('first', [
            'conditions' => [
                'Order_orderhistory.reference_id' => $reference_id,
                'Order_orderhistory.status !=' => 0,
                'Order_orderhistory.id' => (int)$order_id
            ],
            'recursive' => -1
        ]);
    
        if (empty($data)) {
            return json_encode(['status' => false, 'message' => 'Order not available for quantity update']);
        }
    
        // ✅ Calculate new total
        $price = (float)$data['Order_orderhistory']['price'];
        $total_price = $price * (int)$quantity;
    
        // ✅ Initialize tax accumulator
        $tax = 0;
    
        // ✅ Fetch and update tax records
        $taxdatas = $this->Order_tax->find('all', [
            'conditions' => [
                'Order_tax.reference_id' => $reference_id,
                'Order_tax.orderhistory_id' => (int)$order_id,
                'Order_tax.status !=' => 0
            ],
            'recursive' => -1
        ]);
    
        if (!empty($taxdatas)) {
            foreach ($taxdatas as $taxdata) {
                $tax_percentage = (float)$taxdata['Order_tax']['tax_percentage'];
                $tax_value = ($total_price * $tax_percentage) / 100;
                $tax += $tax_value;
    
                $this->Order_tax->updateAll(
                    [
                        'Order_tax.quantity' => (int)$quantity,
                        'Order_tax.taxable_price' => round($total_price,2),
                        'Order_tax.tax_value' => round($tax_value,2),
                        'Order_tax.sync'            => 0,
                        'Order_tax.local_sync'      => 0
                    ],
                    [
                        'Order_tax.id' => (int)$taxdata['Order_tax']['id']
                    ]
                );
            }
        }
    
        // ✅ Update order history (quantity, total tax, total price)
        $updated = $this->Order_orderhistory->updateAll(
            [
                'Order_orderhistory.quantity'     => (int)$quantity,
                'Order_orderhistory.total_tax'    => round($tax,2),
                'Order_orderhistory.total_price'  => round($total_price,2),
                'Order_orderhistory.sync'         => 0,
                'Order_orderhistory.local_sync'   => 0
            ],
            [
                'Order_orderhistory.reference_id' => $reference_id,
                'Order_orderhistory.id'           => (int)$order_id,
                'Order_orderhistory.status !='    => 0
            ]
        );
    
        if ($updated) {
            // Log user track for quantity update
            $pName = !empty($data['Order_orderhistory']['product_name']) ? $data['Order_orderhistory']['product_name'] : ('Product #' . $data['Order_orderhistory']['product_id']);
            $oldQty = $data['Order_orderhistory']['quantity'] ?? 1;
            $tblNum = $table['Order_table']['number'] ?? 'N/A';
            $locId = $table['Order_table']['location_id'] ?? 0;
            $locName = $table['Order_table']['location_name'] ?? '';

            $this->User_track->create();
            $this->User_track->save([
                'reference_id'  => $reference_id,
                'user_id'       => $cashierid,
                'location_id'   => $locId,
                'location_name' => $locName,
                'type'          => 'quantity_update',
                'remarks'       => "Quantity of '{$pName}' changed from {$oldQty} to {$quantity} on Table {$tblNum}",
                'status'        => 1
            ]);

            $response = ['status' => true, 'message' => 'Quantity and tax updated successfully'];
        } else {
            $response = ['status' => false, 'message' => 'Quantity not updated'];
        }
    
        return json_encode($response);
    }
    
    public function item_move()
    {
        $this->autoRender = false;
    
        $response = ['status' => false, 'message' => 'Failed'];
    
        // ✅ Safely read inputs
        $cashierid    = isset($_REQUEST['id']) ? trim($_REQUEST['id']) : '';
        $order_id     = isset($_REQUEST['order_id']) ? trim($_REQUEST['order_id']) : '';
        $from_reference_id = isset($_REQUEST['from_reference_id']) ? trim($_REQUEST['from_reference_id']) : '';
        $to_reference_id = isset($_REQUEST['to_reference_id']) ? trim($_REQUEST['to_reference_id']) : '';
        
        // ✅ Input validation
        if ($cashierid === '') {
            return json_encode(['status' => false, 'message' => 'Cashier ID is missing']);
        }
        if ($order_id === '') {
            return json_encode(['status' => false, 'message' => 'Order ID is missing']);
        }
        if ($from_reference_id === '') {
            return json_encode(['status' => false, 'message' => 'From Reference ID is missing']);
        }
        if ($to_reference_id === '') {
            return json_encode(['status' => false, 'message' => 'To Reference ID is missing']);
        }
    
        // ✅ Check if user exists
        $user = $this->User->find('first', [
            'conditions' => ['User.id' => $cashierid, 'User.status' => 1],
            'recursive' => -1
        ]);
    
        if (empty($user)) {
            return json_encode(['status' => false, 'message' => 'User not found']);
        }
    
        // ✅ Check if table exists
        $fromtable = $this->Order_table->find('first', [
            'conditions' => [
                'Order_table.reference_id' => $from_reference_id,
                'Order_table.status' => 2
            ],
            'recursive' => -1
        ]);
    
        if (empty($fromtable)) {
            return json_encode(['status' => false, 'message' => 'From Table not available for Item Move']);
        }
        
        
        // Check if destination table is vacant (status=1)
        $toTableVacant = $this->Order_table->find('first', [
            'conditions' => [
                'Order_table.reference_id' => $to_reference_id,
                'Order_table.status'       => 1
            ],
            'recursive' => -1
        ]);

        if (!empty($toTableVacant)) {
            $this->Order_table->updateAll(
                [
                    'Order_table.customer_name'    => "'{$fromtable['Order_table']['customer_name']}'",
                    'Order_table.customer_phone'   => "'{$fromtable['Order_table']['customer_phone']}'",
                    'Order_table.customer_address' => "'{$fromtable['Order_table']['customer_address']}'",
                    'Order_table.customer_pax'     => "'{$fromtable['Order_table']['customer_pax']}'",
                    'Order_table.status'           => 2,
                    'Order_table.modified'         => "'" . date('Y-m-d H:i:s') . "'"
                ],
                [
                    'Order_table.reference_id' => $to_reference_id,
                    'Order_table.status'       => 1
                ]
            );
        }
        
        $totable = $this->Order_table->find('first', [
            'conditions' => [
                'Order_table.reference_id' => $to_reference_id,
                'Order_table.status' => 2
            ],
            'recursive' => -1
        ]);
    
        if (empty($totable)) {
            return json_encode(['status' => false, 'message' => 'To Table not available for Item Receive']);
        }
    
        // ✅ Fetch existing order
        $data = $this->Order_orderhistory->find('first', [
            'conditions' => [
                'Order_orderhistory.reference_id' => $from_reference_id,
                'Order_orderhistory.status !=' => 0,
                'Order_orderhistory.id' => (int)$order_id
            ],
            'recursive' => -1
        ]);
    
        if (empty($data)) {
            return json_encode(['status' => false, 'message' => 'Item Not available for movement']);
        }
        

        $this->Order_tax->updateAll(
            array(
                'Order_tax.reference_id' => "'$to_reference_id'",
                'Order_tax.sync'         => 0,
                'Order_tax.local_sync'   => 0
            ),
            array(
                'Order_tax.orderhistory_id' => (int)$order_id,
                'Order_tax.reference_id'    => $from_reference_id,
                'Order_tax.status !='       => 0
            )
        );
    
        $updated = $this->Order_orderhistory->updateAll(
            array(
                'Order_orderhistory.reference_id' => "'$to_reference_id'",
                'Order_orderhistory.table_number' => "'".$totable['Order_table']['number']."'",
                'Order_orderhistory.sync'         => 0,
                'Order_orderhistory.local_sync'   => 0
            ),
            array(
                'Order_orderhistory.id'            => (int)$order_id,
                'Order_orderhistory.reference_id'  => $from_reference_id,
                'Order_orderhistory.status !='     => 0
            )
        );
    
        if ($updated) {
            
            // Update KDS tracks for the moved item
            $this->Kds_track->updateAll(
                array(
                    'Kds_track.order_reference_id' => "'$to_reference_id'",
                    'Kds_track.table_no' => "'".$totable['Order_table']['number']."'",
                    'Kds_track.sync' => 0,
                    'Kds_track.local_sync' => 0
                ),
                array(
                    'Kds_track.order_history_id' => (int)$order_id,
                    'Kds_track.order_reference_id' => $from_reference_id,
                    'Kds_track.status !=' => 0
                )
            );
            
            // Update modifier reference
            $this->Order_modifier->updateAll(
                array(
                    'Order_modifier.reference_id' => "'$to_reference_id'",
                    'Order_modifier.sync' => 0,
                    'Order_modifier.local_sync' => 0
                ),
                array(
                    'Order_modifier.orderhistory_id' => (int)$order_id,
                    'Order_modifier.reference_id' => $from_reference_id,
                    'Order_modifier.status !=' => 0
                )
            );

            // Log user track for from-table and to-table
            $pName = $data['Order_orderhistory']['product_name'] ?? ('Product #' . $data['Order_orderhistory']['product_id']);
            $pQty = $data['Order_orderhistory']['quantity'] ?? 1;
            $kotNo = $data['Order_orderhistory']['kot_number'] ?? '';
            $fromTblNum = $fromtable['Order_table']['number'] ?? 'N/A';
            $toTblNum = $totable['Order_table']['number'] ?? 'N/A';
            $locId = $totable['Order_table']['location_id'] ?? 0;
            $locName = $totable['Order_table']['location_name'] ?? '';

            $this->User_track->create();
            $this->User_track->save([
                'reference_id'  => $from_reference_id,
                'user_id'       => $cashierid,
                'location_id'   => $locId,
                'location_name' => $locName,
                'type'          => 'item_move',
                'remarks'       => "Item '{$pName}' (Qty: {$pQty}) moved from Table {$fromTblNum} to Table {$toTblNum}" . (!empty($kotNo) ? " (KOT #{$kotNo})" : ""),
                'status'        => 1
            ]);

            $this->User_track->create();
            $this->User_track->save([
                'reference_id'  => $to_reference_id,
                'user_id'       => $cashierid,
                'location_id'   => $locId,
                'location_name' => $locName,
                'type'          => 'item_received',
                'remarks'       => "Item '{$pName}' (Qty: {$pQty}) received from Table {$fromTblNum}" . (!empty($kotNo) ? " (KOT #{$kotNo})" : ""),
                'status'        => 1
            ]);

            $response = ['status' => true, 'message' => 'Item Moved successfully'];
        } else {
            $response = ['status' => false, 'message' => 'Item Not Moved'];
        }
    
        return json_encode($response);
    }
    
    public function kot_move()
    {
        $this->autoRender = false;
    
        $response = ['status' => false, 'message' => 'Failed'];
    
        // ✅ Input parameters
        $cashierid = isset($_REQUEST['id']) ? trim($_REQUEST['id']) : '';
        $group_id = isset($_REQUEST['group_id']) ? trim($_REQUEST['group_id']) : '';
        $from_reference_id = isset($_REQUEST['from_reference_id']) ? trim($_REQUEST['from_reference_id']) : '';
        $to_reference_id = isset($_REQUEST['to_reference_id']) ? trim($_REQUEST['to_reference_id']) : '';
    
        // ✅ Input validation
        if ($cashierid === '') return json_encode(['status' => false, 'message' => 'Cashier ID is missing']);
        if ($group_id === '') return json_encode(['status' => false, 'message' => 'Group ID is missing']);
        if ($from_reference_id === '') return json_encode(['status' => false, 'message' => 'From Reference ID is missing']);
        if ($to_reference_id === '') return json_encode(['status' => false, 'message' => 'To Reference ID is missing']);
    
        // ✅ Validate user
        $user = $this->User->find('first', [
            'conditions' => ['User.id' => $cashierid, 'User.status' => 1],
            'recursive' => -1
        ]);
        if (empty($user)) {
            return json_encode(['status' => false, 'message' => 'User not found']);
        }
    
        // ✅ Validate tables
        $fromtable = $this->Order_table->find('first', [
            'conditions' => [
                'Order_table.reference_id' => $from_reference_id,
                'Order_table.status' => 2
            ],
            'recursive' => -1
        ]);
        if (empty($fromtable)) {
            return json_encode(['status' => false, 'message' => 'From Table not available for Item Move']);
        }
        
        
        // Check if destination table is vacant (status=1)
        $toTableVacant = $this->Order_table->find('first', [
            'conditions' => [
                'Order_table.reference_id' => $to_reference_id,
                'Order_table.status'       => 1
            ],
            'recursive' => -1
        ]);

        if (!empty($toTableVacant)) {
            $this->Order_table->updateAll(
                [
                    'Order_table.customer_name'    => "'{$fromtable['Order_table']['customer_name']}'",
                    'Order_table.customer_phone'   => "'{$fromtable['Order_table']['customer_phone']}'",
                    'Order_table.customer_address' => "'{$fromtable['Order_table']['customer_address']}'",
                    'Order_table.customer_pax'     => "'{$fromtable['Order_table']['customer_pax']}'",
                    'Order_table.status'           => 2,
                    'Order_table.modified'         => "'" . date('Y-m-d H:i:s') . "'"
                ],
                [
                    'Order_table.reference_id' => $to_reference_id,
                    'Order_table.status'       => 1
                ]
            );
        }
    
        $totable = $this->Order_table->find('first', [
            'conditions' => [
                'Order_table.reference_id' => $to_reference_id,
                'Order_table.status' => 2
            ],
            'recursive' => -1
        ]);
        if (empty($totable)) {
            return json_encode(['status' => false, 'message' => 'To Table not available for Item Receive']);
        }
        
        // ✅ Fetch items belonging to that group
        $datas = $this->Order_orderhistory->find('all', [
            'conditions' => [
                'Order_orderhistory.reference_id' => $from_reference_id,
                'Order_orderhistory.status !=' => 0,
                'Order_orderhistory.group_id' => $group_id
            ],
            'recursive' => -1
        ]);
        if (empty($datas)) {
            return json_encode(['status' => false, 'message' => 'No items found for this group']);
        }
    
        $movedCount = 0;
    
        // ✅ Start transaction for consistency
        $dataSource = $this->Order_orderhistory->getDataSource();
        $dataSource->begin();
    
        try {
            foreach ($datas as $data) {
                $order_id = $data['Order_orderhistory']['id'];
    
                // ✅ Move related tax entries
                $this->Order_tax->updateAll(
                    [
                        'Order_tax.reference_id' => "'$to_reference_id'",
                        'Order_tax.sync'         => 0,
                        'Order_tax.local_sync'   => 0
                    ],
                    [
                        'Order_tax.orderhistory_id' => (int)$order_id,
                        'Order_tax.reference_id'    => $from_reference_id,
                        'Order_tax.status !='      => 0
                    ]
                );

    
                // ✅ Move item to new reference
                $success = $this->Order_orderhistory->updateAll(
                    ['Order_orderhistory.reference_id' => "'$to_reference_id'",
                     'Order_orderhistory.table_number' => "'".$totable['Order_table']['number']."'",
                     'Order_orderhistory.sync'         => 0,
                     'Order_orderhistory.local_sync'   => 0
                    ],
                    [
                        'Order_orderhistory.id' => (int)$order_id,
                        'Order_orderhistory.reference_id' => $from_reference_id,
                        'Order_orderhistory.status !=' => 0
                    ]
                );
    
                if ($success) {
                                        
                    // Update KDS tracks for moved KOT item
                    $this->Kds_track->updateAll(
                        array(
                            'Kds_track.order_reference_id' => "'$to_reference_id'",
                            'Kds_track.table_no' => "'".$totable['Order_table']['number']."'",
                            'Kds_track.sync' => 0,
                            'Kds_track.local_sync' => 0
                        ),
                        array(
                            'Kds_track.order_history_id' => (int)$order_id,
                            'Kds_track.order_reference_id' => $from_reference_id
                        )
                    );
                    // Update modifier reference
                    $this->Order_modifier->updateAll(
                        array(
                            'Order_modifier.reference_id' => "'$to_reference_id'",
                            'Order_modifier.sync' => 0,
                            'Order_modifier.local_sync' => 0
                        ),
                        array(
                            'Order_modifier.orderhistory_id' => (int)$order_id,
                            'Order_modifier.reference_id' => $from_reference_id
                        )
                    );

                    // Log user track for moved KOT item
                    $pName = $data['Order_orderhistory']['product_name'] ?? ('Product #' . $data['Order_orderhistory']['product_id']);
                    $pQty = $data['Order_orderhistory']['quantity'] ?? 1;
                    $kotNo = $data['Order_orderhistory']['kot_number'] ?? '';
                    $fromTblNum = $fromtable['Order_table']['number'] ?? 'N/A';
                    $toTblNum = $totable['Order_table']['number'] ?? 'N/A';
                    $locId = $totable['Order_table']['location_id'] ?? 0;
                    $locName = $totable['Order_table']['location_name'] ?? '';

                    $this->User_track->create();
                    $this->User_track->save([
                        'reference_id'  => $from_reference_id,
                        'user_id'       => $cashierid,
                        'location_id'   => $locId,
                        'location_name' => $locName,
                        'type'          => 'item_move',
                        'remarks'       => "Item '{$pName}' (Qty: {$pQty}) moved from Table {$fromTblNum} to Table {$toTblNum}" . (!empty($kotNo) ? " (KOT #{$kotNo})" : ""),
                        'status'        => 1
                    ]);

                    $this->User_track->create();
                    $this->User_track->save([
                        'reference_id'  => $to_reference_id,
                        'user_id'       => $cashierid,
                        'location_id'   => $locId,
                        'location_name' => $locName,
                        'type'          => 'item_received',
                        'remarks'       => "Item '{$pName}' (Qty: {$pQty}) received from Table {$fromTblNum}" . (!empty($kotNo) ? " (KOT #{$kotNo})" : ""),
                        'status'        => 1
                    ]);

                    $movedCount++;
                }
            }
    
            if ($movedCount > 0) {
                $dataSource->commit();
                $response = ['status' => true, 'message' => "$movedCount item(s) moved successfully"];
            } else {
                $dataSource->rollback();
                $response = ['status' => false, 'message' => 'No items were moved'];
            }
    
        } catch (Exception $e) {
            $dataSource->rollback();
            $response = ['status' => false, 'message' => 'Error: ' . $e->getMessage()];
        }
    
        return json_encode($response);
    }

    
    public function dsr_report_print()
    {
        $cashier_id = $_REQUEST['id'];
        $startdate  = $_REQUEST['sdate'];
        $enddate    = $_REQUEST['edate'];
    
        $response = array();
    
        if ($cashier_id == '') {
            $response = array('status' => false, 'message' => "Cashier Id Missing");
            return json_encode($response);
        }
        if ($startdate == '') {
            $response = array('status' => false, 'message' => "Start date Missing");
            return json_encode($response);
        }
        if ($enddate == '') {
            $response = array('status' => false, 'message' => "End date Missing");
            return json_encode($response);
        }
    
        $users = $this->User->find('first', array('conditions' => array('User.id' => $cashier_id, 'User.status' => 1)));
        if (empty($users)) {
            $response = array('status' => false, 'message' => "User not found");
            return json_encode($response);
        }
    
        $cashiernames = $this->User->find('first', array('conditions' => array('User.id' => $cashier_id)));
        $cashiername  = $cashiernames['User']['name'];
        $location_id  = $cashiernames['User']['location_id'];
    
        $shiftRange = $this->getShiftDateRange($startdate, $enddate, $location_id);
        $startDatetime = $shiftRange['startDatetime'];
        $endDatetime   = $shiftRange['endDatetime'];
    
        $cashierFilter  = " AND store_id=$location_id";
        $oohFilter      = " AND ooh.store_id=$location_id";
        $otTaxFilter    = " AND ot_tax.store_id=$location_id";
        $otDFilter      = " AND ot_d.store_id=$location_id";
        $otFilter       = " AND ot.store_id=$location_id";
        $orderTaxFilter = " AND order_tax.store_id=$location_id";
        $opFilter       = " AND op_d.store_id=$location_id";
        $opdwFilter     = " AND op_dw.store_id=$location_id";
        $opn1Filter     = " AND op_n1.store_id=$location_id";
        $opn2Filter     = " AND op_n2.store_id=$location_id";
        $opscFilter     = " AND op_sc.store_id=$location_id";
        $opsc2Filter    = " AND op_sc2.store_id=$location_id";
    
        // ── Payment Data ──────────────────────────────────────────────────────────
        $payments = $this->Order_payment->query("
            SELECT
                SUM(amount) AS total_amount,
                SUM(IF(type=1,  amount, 0)) AS cash,
                SUM(IF(type=10, amount, 0)) AS hold,
                SUM(IF(type=2,  amount, 0)) AS card,
                SUM(IF(type=6,  amount, 0)) AS upi,
                SUM(IF(type=9,  amount, 0)) AS online,
                SUM(IF(type=12,  amount, 0)) AS reelo_wallet,
                SUM(IF(type=7,  amount, 0)) AS no_charge_with_tax,
                SUM(IF(type=7, ROUND(amount - (
                    SELECT SUM(ot_sub.total_tax)
                    FROM order_transactions ot_sub
                    WHERE ot_sub.status != 0
                      AND ot_sub.reference_id = order_payments.reference_id
                      AND ot_sub.store_id = order_payments.store_id
                ), 2), 0)) AS no_charge,
                SUM(IF(type=8, amount, 0)) AS storecard
            FROM order_payments
            WHERE status = 2
              AND created BETWEEN '$startDatetime' AND '$endDatetime'
              $cashierFilter
        ");
    
        $onlinepayments = $this->Order_payment->query("
            SELECT type_value, SUM(amount) AS total_amount
            FROM order_payments
            WHERE type = 11 AND status = 2
              AND created BETWEEN '$startDatetime' AND '$endDatetime'
              $cashierFilter
            GROUP BY type_value
        ");
    
        // Platform tax: 5% GST deposited by Zomato/Swiggy on behalf of restaurant
        $platform_tax_data = $this->Order_payment->query("
            SELECT type_value,
                   ROUND(SUM(amount) * 5/105, 2) AS platform_tax,
                   ROUND(SUM(amount) - SUM(amount)*5/105, 2) AS net_amount
            FROM order_payments
            WHERE type = 11 AND status = 2
              AND created BETWEEN '$startDatetime' AND '$endDatetime'
              $cashierFilter
              AND type_value IN ('swiggy', 'zomato')
            GROUP BY type_value
        ");
        $platform_tax_by_channel = [];
        $platform_tax_total = 0;
        foreach ($platform_tax_data as $p) {
            $tv = $p['order_payments']['type_value'];
            $platform_tax_by_channel[$tv] = (float)$p[0]['platform_tax'];
            $platform_tax_total += (float)$p[0]['platform_tax'];
        }
        $platform_tax_total = round($platform_tax_total, 2);
    
        // ── Transactions ──────────────────────────────────────────────────────────
        $transactions = $this->Order_transaction->query("
            SELECT
                COUNT(order_transactions.id)            AS total_count,
                SUM(order_transactions.pax)             AS pax,
                SUM(order_transactions.total_tax)       AS total_tax,
                SUM(order_transactions.servicecharge)   AS servicecharge,
                SUM(order_transactions.discount)        AS discount,
                SUM(order_transactions.delivery_charge) AS delivery_charge,
                SUM(order_transactions.packing_charge)  AS packing_charge,
                SUM(order_transactions.amount)          AS amount,
                SUM(order_transactions.price)           AS price,
                SUM(order_transactions.round)           AS round,
                SUM(order_transactions.other_taxes)     AS other_taxes
            FROM order_transactions
            WHERE order_transactions.created BETWEEN '$startDatetime' AND '$endDatetime'
              AND order_transactions.status = 2
              $cashierFilter
              AND order_transactions.reference_id NOT IN (
                  SELECT op_nc.reference_id FROM order_payments op_nc
                  WHERE op_nc.type = 7 AND op_nc.status = 2 $cashierFilter
              )
        ");
    
        $transactionsnc = $this->Order_transaction->query("
            SELECT SUM(order_transactions.total_tax) AS total_tax
            FROM order_transactions
            WHERE order_transactions.created BETWEEN '$startDatetime' AND '$endDatetime'
              AND order_transactions.status = 2
              $cashierFilter
              AND order_transactions.reference_id IN (
                  SELECT op_nc2.reference_id FROM order_payments op_nc2
                  WHERE op_nc2.type = 7 AND op_nc2.status = 2 $cashierFilter
              )
        ");
    
        $transactionsubtotal = $this->Order_transaction->query("
            SELECT SUM(order_transactions.price)    AS price,
                   SUM(order_transactions.discount) AS discount
            FROM order_transactions
            WHERE order_transactions.created BETWEEN '$startDatetime' AND '$endDatetime'
              AND order_transactions.status = 2
              $cashierFilter
        ");
    
        // ── Taxes ─────────────────────────────────────────────────────────────────
        $taxes = $this->Order_tax->query("
            SELECT order_tax.tax_id, order_tax.tax_name, order_tax.tax_percentage,
                   SUM(order_tax.tax_value) AS tax_value
            FROM order_tax
            WHERE order_tax.created BETWEEN '$startDatetime' AND '$endDatetime'
              AND order_tax.status = 2
              $cashierFilter
              AND order_tax.reference_id NOT IN (
                  SELECT op_t.reference_id FROM order_payments op_t
                  WHERE op_t.type = 7 AND op_t.status = 2 $cashierFilter
              )
            GROUP BY order_tax.tax_id
        ");
    
        $charges_taxes = $this->Order_payment->query("
            SELECT tax_id, tax_name, tax_percentage, SUM(tax_value) AS tax_value
            FROM tax_charges
            WHERE status = 1
              AND created BETWEEN '$startDatetime' AND '$endDatetime'
              $cashierFilter
            GROUP BY tax_id
        ");
    
        // ── Net Sale ──────────────────────────────────────────────────────────────
        $net_amount_query = $this->Order_transaction->query("
            SELECT ROUND(SUM(ot.price) - IFNULL(SUM(ot.discount), 0), 2) AS net_amount
            FROM order_transactions ot
            WHERE ot.status = 2
              AND ot.created BETWEEN '$startDatetime' AND '$endDatetime'
              $otFilter
              AND ot.reference_id NOT IN (
                  SELECT op_n1.reference_id FROM order_payments op_n1
                  WHERE op_n1.type = 7 AND op_n1.status = 2 $opn1Filter
              )
        ");
    
        // ── NC Net Sale ───────────────────────────────────────────────────────────
        $ncnet_amount_query = $this->Order_transaction->query("
            SELECT ROUND(SUM(ot.price) - IFNULL(SUM(ot.discount), 0), 2) AS net_amount
            FROM order_transactions ot
            WHERE ot.status = 2
              AND ot.created BETWEEN '$startDatetime' AND '$endDatetime'
              $otFilter
              AND ot.reference_id IN (
                  SELECT op_n2.reference_id FROM order_payments op_n2
                  WHERE op_n2.type = 7 AND op_n2.status = 2 $opn2Filter
              )
        ");
    
        // ── Taxable / Non-Taxable ─────────────────────────────────────────────────
        $taxable = $this->Order_orderhistory->query("
            SELECT SUM(total_price) AS total_taxable
            FROM order_orderhistories
            WHERE status = 2
              AND created BETWEEN '$startDatetime' AND '$endDatetime'
              AND total_tax_percentage != 0
              $cashierFilter
              AND reference_id NOT IN (
                  SELECT op_tx1.reference_id FROM order_payments op_tx1
                  WHERE op_tx1.type = 7 AND op_tx1.status = 2 $cashierFilter
              )
        ");
    
        $nontaxable = $this->Order_orderhistory->query("
            SELECT SUM(total_price) AS total_nontaxable
            FROM order_orderhistories
            WHERE status = 2
              AND created BETWEEN '$startDatetime' AND '$endDatetime'
              AND total_tax_percentage = 0
              $cashierFilter
              AND reference_id NOT IN (
                  SELECT op_tx2.reference_id FROM order_payments op_tx2
                  WHERE op_tx2.type = 7 AND op_tx2.status = 2 $cashierFilter
              )
        ");
    
        $nctaxable = $this->Order_orderhistory->query("
            SELECT SUM(total_price) AS total_taxable
            FROM order_orderhistories
            WHERE status = 2
              AND created BETWEEN '$startDatetime' AND '$endDatetime'
              AND total_tax_percentage != 0
              $cashierFilter
              AND reference_id IN (
                  SELECT op_tx3.reference_id FROM order_payments op_tx3
                  WHERE op_tx3.type = 7 AND op_tx3.status = 2 $cashierFilter
              )
        ");
    
        $ncnontaxable = $this->Order_orderhistory->query("
            SELECT SUM(total_price) AS total_nontaxable
            FROM order_orderhistories
            WHERE status = 2
              AND created BETWEEN '$startDatetime' AND '$endDatetime'
              AND total_tax_percentage = 0
              $cashierFilter
              AND reference_id IN (
                  SELECT op_tx4.reference_id FROM order_payments op_tx4
                  WHERE op_tx4.type = 7 AND op_tx4.status = 2 $cashierFilter
              )
        ");
    
        // ── Dish sales ────────────────────────────────────────────────────────
        $dish_sales = $this->Order_orderhistory->query("
            SELECT cp.dish_type,
                SUM(ia.quantity) AS total_qty,
                ROUND(SUM(CASE WHEN bt.bill_item_sum > 0
                            THEN (ia.item_amount / bt.bill_item_sum) * bt.bill_net ELSE 0 END), 2) AS total_amount
            FROM (
                SELECT ooh.id, ooh.local_id, ooh.reference_id, ooh.store_id, ooh.product_id,
                    ooh.quantity, ot_tax.taxable_price AS item_amount
                FROM order_orderhistories ooh
                INNER JOIN (
                    SELECT orderhistory_id, MAX(taxable_price) AS taxable_price, store_id
                    FROM order_tax
                    WHERE order_tax.status != 0 $orderTaxFilter
                    GROUP BY orderhistory_id, store_id
                ) ot_tax ON ot_tax.orderhistory_id = COALESCE(NULLIF(ooh.local_id, ''), ooh.id)
                        AND ot_tax.store_id = ooh.store_id
                WHERE ooh.created BETWEEN '$startDatetime' AND '$endDatetime'
                AND ooh.status = 2
                $oohFilter
                AND ooh.reference_id NOT IN (
                    SELECT op_d.reference_id FROM order_payments op_d
                    WHERE op_d.type = 7 AND op_d.status = 2 $opFilter
                )
            ) ia
            INNER JOIN (
                SELECT ot.reference_id, ot.store_id,
                    (ot.price - ot.discount + ot.servicecharge) AS bill_net,
                    SUM(ia2.item_amount) AS bill_item_sum
                FROM order_transactions ot
                INNER JOIN (
                    SELECT ooh.reference_id, ooh.store_id, ot_tax.taxable_price AS item_amount
                    FROM order_orderhistories ooh
                    INNER JOIN (
                        SELECT orderhistory_id, MAX(taxable_price) AS taxable_price, store_id
                        FROM order_tax
                        WHERE order_tax.status != 0 $orderTaxFilter
                        GROUP BY orderhistory_id, store_id
                    ) ot_tax ON ot_tax.orderhistory_id = COALESCE(NULLIF(ooh.local_id, ''), ooh.id)
                            AND ot_tax.store_id = ooh.store_id
                    WHERE ooh.created BETWEEN '$startDatetime' AND '$endDatetime'
                    AND ooh.status = 2
                    $oohFilter
                    AND ooh.reference_id NOT IN (
                        SELECT op_d.reference_id FROM order_payments op_d
                        WHERE op_d.type = 7 AND op_d.status = 2 $opFilter
                    )
                ) ia2 ON ot.reference_id = ia2.reference_id AND ot.store_id = ia2.store_id
                WHERE ot.status = 2
                AND ot.created BETWEEN '$startDatetime' AND '$endDatetime'
                $otFilter
                AND ot.reference_id NOT IN (
                    SELECT op_d.reference_id FROM order_payments op_d
                    WHERE op_d.type = 7 AND op_d.status = 2 $opFilter
                )
                GROUP BY ot.reference_id, ot.store_id, ot.price, ot.discount, ot.servicecharge
            ) bt ON ia.reference_id = bt.reference_id AND ia.store_id = bt.store_id
            INNER JOIN catalog_product cp ON cp.id = ia.product_id
            GROUP BY cp.dish_type
            ORDER BY cp.dish_type DESC
        ");

                // ── Dish Type Sales Without Service Charge ───────────────────────────
        $dish_saleswithoutservice = $this->Order_orderhistory->query("
            SELECT 
                cp.dish_type AS dish_type,
                SUM(ia.quantity) AS total_qty,
                ROUND(
                    SUM(
                        CASE 
                            WHEN bt.bill_item_sum > 0
                            THEN (ia.item_amount / bt.bill_item_sum) * bt.bill_net
                            ELSE 0
                        END
                    ), 2
                ) AS total_amount
            FROM (
                SELECT 
                    ooh.id,
                    ooh.local_id,
                    ooh.reference_id,
                    ooh.store_id,
                    ooh.product_id,
                    ooh.quantity,
                    (ooh.price * ooh.quantity) * 
                        (1 - IFNULL(ot.discount_percentage, 0) / 100) AS item_amount
                FROM order_orderhistories ooh
                LEFT JOIN (
                    SELECT 
                        orderhistory_id,
                        MAX(discount_percentage) AS discount_percentage,
                        store_id
                    FROM order_tax
                    WHERE order_tax.status != 0
                    $orderTaxFilter
                    GROUP BY orderhistory_id, store_id
                ) ot 
                    ON ot.orderhistory_id = COALESCE(NULLIF(ooh.local_id, ''), ooh.id)
                    AND ot.store_id = ooh.store_id
                WHERE ooh.created BETWEEN '$startDatetime' AND '$endDatetime'
                AND ooh.status = 2
                $oohFilter
                AND ooh.reference_id NOT IN (
                    SELECT op_dw.reference_id
                    FROM order_payments op_dw
                    WHERE op_dw.type = 7
                        AND op_dw.status = 2
                        $opdwFilter
                )
            ) ia

            INNER JOIN (
                SELECT 
                    ot.reference_id,
                    ot.store_id,
                    (ot.price - ot.discount) AS bill_net,
                    SUM(ia2.item_amount) AS bill_item_sum
                FROM order_transactions ot

                INNER JOIN (
                    SELECT 
                        ooh.reference_id,
                        ooh.store_id,
                        (ooh.price * ooh.quantity) * 
                            (1 - IFNULL(ot2.discount_percentage, 0) / 100) AS item_amount
                    FROM order_orderhistories ooh

                    LEFT JOIN (
                        SELECT 
                            orderhistory_id,
                            MAX(discount_percentage) AS discount_percentage,
                            store_id
                        FROM order_tax
                        WHERE order_tax.status != 0
                        $orderTaxFilter
                        GROUP BY orderhistory_id, store_id
                    ) ot2 
                        ON ot2.orderhistory_id = COALESCE(NULLIF(ooh.local_id, ''), ooh.id)
                        AND ot2.store_id = ooh.store_id

                    WHERE ooh.created BETWEEN '$startDatetime' AND '$endDatetime'
                    AND ooh.status = 2
                    $oohFilter
                    AND ooh.reference_id NOT IN (
                        SELECT op_dw.reference_id
                        FROM order_payments op_dw
                        WHERE op_dw.type = 7
                            AND op_dw.status = 2
                            $opdwFilter
                    )
                ) ia2 
                    ON ot.reference_id = ia2.reference_id
                    AND ot.store_id = ia2.store_id

                WHERE ot.status = 2
                AND ot.created BETWEEN '$startDatetime' AND '$endDatetime'
                $otFilter
                AND ot.reference_id NOT IN (
                    SELECT op_dw.reference_id
                    FROM order_payments op_dw
                    WHERE op_dw.type = 7
                        AND op_dw.status = 2
                        $opdwFilter
                )

                GROUP BY 
                    ot.reference_id,
                    ot.store_id,
                    ot.price,
                    ot.discount
            ) bt 
                ON ia.reference_id = bt.reference_id
                AND ia.store_id = bt.store_id

            INNER JOIN catalog_product cp 
                ON cp.id = ia.product_id

            GROUP BY cp.dish_type
            ORDER BY cp.dish_type DESC
        ");

        // ── KDS Sales via shared helper (same as dsr_report) ─────────────────────
        $sales   = $this->_dsrAggregateKdsSales($startdate, $enddate, $cashierFilter, false, $location_id);
        $ncsales = $this->_dsrAggregateKdsSales($startdate, $enddate, $cashierFilter, true, $location_id);
    
        // ── Extract VAT rates dynamically ─────────────────────────────────────────
        $vat_rates = [];
        if (isset($taxes)) {
            foreach ($taxes as $tax) {
                $tax_name = $tax['order_tax']['tax_name'];
                if (stripos($tax_name, 'VAT') !== false) {
                    $vat_rates[] = (float)$tax['order_tax']['tax_percentage'];
                }
            }
        }
        $vat_rates = array_unique($vat_rates);
        sort($vat_rates);
        if (empty($vat_rates)) {
            $vat_rate_str = "18.9";
            $vat_rate_val = 18.9;
        } else {
            $vat_rate_str = implode("/", $vat_rates);
            $vat_rate_val = $vat_rates[0];
        }
    
        // ── Service Charge Breakup ───────────────────────────────────────────
        $sc_data = $this->Order_transaction->query("
            SELECT 
                cp.dish_type,
                ia.tax_percentage,
                ROUND(
                    SUM(
                        CASE 
                            WHEN bt.bill_item_sum > 0
                            THEN (ia.item_amount / bt.bill_item_sum) * bt.servicecharge
                            ELSE 0
                        END
                    ), 2
                ) AS sc_amount
            FROM
            (
                SELECT 
                    ooh.id,
                    ooh.local_id,
                    ooh.reference_id,
                    ooh.store_id,
                    ooh.product_id,
                    ooh.quantity,
                    ot_tax.tax_percentage,
                    ot_tax.taxable_price AS item_amount
                FROM order_transactions ot
                INNER JOIN order_orderhistories ooh
                    ON ooh.reference_id = ot.reference_id
                    AND ooh.store_id = ot.store_id
                INNER JOIN catalog_product cp
                    ON cp.id = ooh.product_id
                INNER JOIN
                (
                    SELECT 
                        orderhistory_id,
                        store_id,
                        MAX(taxable_price) AS taxable_price,
                        MAX(tax_percentage) AS tax_percentage
                    FROM order_tax
                    WHERE status != 0
                    AND store_id = $location_id
                    GROUP BY orderhistory_id, store_id
                ) ot_tax
                    ON ot_tax.orderhistory_id = COALESCE(NULLIF(ooh.local_id, ''), ooh.id)
                    AND ot_tax.store_id = ooh.store_id
                WHERE ot.created BETWEEN '$startDatetime' AND '$endDatetime'
                AND ot.status = 2
                AND ot.store_id = $location_id
                AND ooh.status = 2
                AND ooh.reference_id NOT IN
                (
                    SELECT op_sc2.reference_id
                    FROM order_payments op_sc2
                    WHERE op_sc2.type = 7
                        AND op_sc2.status = 2
                        AND op_sc2.store_id = $location_id
                )
            ) ia
            INNER JOIN
            (
                SELECT 
                    ot.reference_id,
                    ot.store_id,
                    ot.servicecharge,
                    SUM(ia2.item_amount) AS bill_item_sum
                FROM order_transactions ot
                INNER JOIN
                (
                    SELECT 
                        ooh.reference_id,
                        ooh.store_id,
                        ooh.product_id,
                        ot_tax.taxable_price AS item_amount
                    FROM order_orderhistories ooh
                    INNER JOIN
                    (
                        SELECT 
                            orderhistory_id,
                            store_id,
                            MAX(taxable_price) AS taxable_price
                        FROM order_tax
                        WHERE status != 0
                        AND store_id = $location_id
                        GROUP BY orderhistory_id, store_id
                    ) ot_tax
                        ON ot_tax.orderhistory_id =
                        COALESCE(NULLIF(ooh.local_id, ''), ooh.id)
                        AND ot_tax.store_id = ooh.store_id
                    WHERE ooh.status = 2
                    AND ooh.store_id = $location_id
                ) ia2
                    ON ot.reference_id = ia2.reference_id
                    AND ot.store_id = ia2.store_id
                WHERE ot.status = 2
                AND ot.created BETWEEN '$startDatetime' AND '$endDatetime'
                AND ot.store_id = $location_id
                AND ot.reference_id NOT IN
                (
                    SELECT op_sc2.reference_id
                    FROM order_payments op_sc2
                    WHERE op_sc2.type = 7
                        AND op_sc2.status = 2
                        AND op_sc2.store_id = $location_id
                )
                GROUP BY
                    ot.reference_id,
                    ot.store_id,
                    ot.servicecharge
            ) bt
                ON ia.reference_id = bt.reference_id
                AND ia.store_id = bt.store_id
            INNER JOIN catalog_product cp
                ON cp.id = ia.product_id
            GROUP BY
                cp.dish_type,
                ia.tax_percentage
        ");

        $total_sc_from_transactions = isset($transactions[0][0]['servicecharge']) ? (float)$transactions[0][0]['servicecharge'] : 0.0;
        $sc_gst_raw    = 0.0;
        $sc_vat_raw    = 0.0;
        $vat_on_sc_raw = 0.0;
        foreach ($sc_data as $row) {
            $dt  = isset($row['cp']['dish_type']) ? (int)$row['cp']['dish_type'] : (isset($row[0]['dish_type']) ? (int)$row[0]['dish_type'] : 0);
            $amt = isset($row[0]['sc_amount']) ? (float)$row[0]['sc_amount'] : (isset($row['ia']['sc_amount']) ? (float)$row['ia']['sc_amount'] : 0.0);
            $pct = isset($row['ia']['tax_percentage']) ? (float)$row['ia']['tax_percentage'] : (isset($row[0]['tax_percentage']) ? (float)$row[0]['tax_percentage'] : (!empty($vat_rates) ? $vat_rates[0] : 18.9));
            if (abs($pct - 18.9) < 0.01) {
                $sc_vat_raw += $amt;
                $vat_on_sc_raw += $amt * ($pct / 100);
            } else {
                $sc_gst_raw += $amt;
            }
        }
        $diff = $total_sc_from_transactions - ($sc_gst_raw + $sc_vat_raw);
        if (abs($diff) > 0.001) {
            $sc_gst_raw += $diff;
        }
        $sc_gst   = round($sc_gst_raw, 2);
        $sc_vat   = round($sc_vat_raw, 2);
        $sc_total = round($total_sc_from_transactions, 2);
        $vat_on_sc = round($vat_on_sc_raw, 2);
        $sgst_sc  = round($sc_gst * 0.025, 2);
        $cgst_sc  = round($sc_gst * 0.025, 2);
    
        // ── Dish Type Map ─────────────────────────────────────────────────────────
        $dishTypeMap = [0 => 'Food', 1 => 'Beverage', 2 => 'Liquor', 3 => 'Others'];
    
        $newData = [];
    
        // ── Payment Data ──────────────────────────────────────────────────────────
        $newData[] = ['key' => 'Payment Data',        'value' => '------', 'heading' => true];
        $newData[] = ['key' => 'Cashier',              'value' => $cashiername, 'heading' => false];
        $newData[] = ['key' => 'Total Collection',     'value' => (string)round($payments[0][0]['total_amount'] - $payments[0][0]['no_charge_with_tax'] - $platform_tax_total, 2), 'heading' => false];
        $newData[] = ['key' => 'Cash',                 'value' => (string)round($payments[0][0]['cash'], 2),     'heading' => false];
        $newData[] = ['key' => 'Card',                 'value' => (string)round($payments[0][0]['card'], 2),     'heading' => false];
        $newData[] = ['key' => 'UPI',                  'value' => (string)round($payments[0][0]['upi'], 2),      'heading' => false];
        $newData[] = ['key' => 'Online',               'value' => (string)round($payments[0][0]['online'], 2),   'heading' => false];

        foreach ($onlinepayments as $op) {
            $opVal = (float)$op[0]['total_amount'];
            $opKey = $op['order_payments']['type_value'];
            if (isset($platform_tax_by_channel[$opKey])) {
                $opVal -= $platform_tax_by_channel[$opKey];
            }
            $newData[] = ['key' => $opKey, 'value' => (string)round($opVal, 2), 'heading' => false];
        }

        $newData[] = ['key' => 'Storecard',            'value' => (string)round($payments[0][0]['storecard'], 2),         'heading' => false];
        $newData[] = ['key' => 'HoldBill',             'value' => (string)round($payments[0][0]['hold'], 2),              'heading' => false];
        $newData[] = ['key' => 'Reelo Wallet',         'value' => (string)round($payments[0][0]['reelo_wallet'], 2),      'heading' => false];
        $newData[] = ['key' => 'No Charge',            'value' => (string)round($payments[0][0]['no_charge_with_tax'] - $transactionsnc[0][0]['total_tax'], 2), 'heading' => false];
        $newData[] = ['key' => 'No Charge With Tax',   'value' => (string)round($payments[0][0]['no_charge_with_tax'], 2),'heading' => false];

        // ── Taxes ─────────────────────────────────────────────────────────────────
        $newData[] = ['key' => 'Taxes', 'value' => '------', 'heading' => true];
        foreach ($taxes as $tax) {
            $newData[] = [
                'key'     => $tax['order_tax']['tax_name'] . '(' . $tax['order_tax']['tax_percentage'] . '%)',
                'value'   => (string)round($tax[0]['tax_value'], 2),
                'heading' => false,
            ];
        }

        $otherChargesTax = round($transactions[0][0]['other_taxes'], 2);
        if (!empty($otherChargesTax) && $otherChargesTax > 0) {
            $newData[] = ['key' => 'Other Charges Tax(Total)', 'value' => (string)$otherChargesTax, 'heading' => false];
        }

        // ── Other Charges Tax (detailed) ──────────────────────────────────────────
        if (!empty($charges_taxes)) {
            $newData[] = ['key' => 'Other Charges Tax Breakup', 'value' => '------', 'heading' => true];
            foreach ($charges_taxes as $ctax) {
                $ctax_name       = $ctax['tax_charges']['tax_name']       ?? $ctax[0]['tax_name']       ?? '';
                $ctax_percentage = $ctax['tax_charges']['tax_percentage']  ?? $ctax[0]['tax_percentage'] ?? '';
                $ctax_value      = $ctax['tax_charges']['tax_value']       ?? $ctax[0]['tax_value']      ?? 0;
                $newData[] = [
                    'key'     => $ctax_name . ' (' . $ctax_percentage . '%)',
                    'value'   => (string)round($ctax_value, 2),
                    'heading' => false,
                ];
            }
        }

        // ── Sales Aggregation ─────────────────────────────────────────────────────
        $newData[] = ['key' => 'Sales Aggregation', 'value' => '------', 'heading' => true];
        foreach ($sales as $sale) {
            $newData[] = [
                'key'     => $sale['final']['kds_name'] . ' (' . $sale['final']['tax_percentage'] . '%)',
                'value'   => (string)round($sale['final']['value'], 2),
                'heading' => false,
            ];
        }

        // ── NC Sales Aggregation ──────────────────────────────────────────────────
        $newData[] = ['key' => 'NC Sales Aggregation', 'value' => '------', 'heading' => true];
        foreach ($ncsales as $ncsale) {
            $newData[] = [
                'key'     => $ncsale['final']['kds_name'] . ' (' . $ncsale['final']['tax_percentage'] . '%)',
                'value'   => (string)round($ncsale['final']['value'], 2),
                'heading' => false,
            ];
        }

        // ── Dish Type Sales With Service Charge ────────────────────────────────────
        $newData[] = ['key' => 'Dish Type Sales With Service Charge', 'value' => '------', 'heading' => true];
        foreach ($dish_sales as $row) {
            $newData[] = [
                'key'     => $dishTypeMap[(int)$row['cp']['dish_type']] ?? $row['cp']['dish_type'],
                'value'   => (string)round($row[0]['total_amount'] ?? 0, 2),
                'heading' => false,
            ];
        }
        
        // ── Dish Type Sales Without Service Charge ─────────────────────────────────
        $newData[] = ['key' => 'Dish Type Sales Without Service Charge', 'value' => '------', 'heading' => true];
        foreach ($dish_saleswithoutservice as $row) {
