        $newData[] = ['key' => 'Total Service Charge',                     'value' => (string)$sc_total,  'heading' => false];
        $newData[] = ['key' => 'SC on GST Items (5%)',                     'value' => (string)$sc_gst,    'heading' => false];
        $newData[] = ['key' => 'SC on VAT Items (' . $vat_rate_str . '%)', 'value' => (string)$sc_vat,    'heading' => false];
        $newData[] = ['key' => 'SGST on SC (2.5%)',                        'value' => (string)$sgst_sc,   'heading' => false];
        $newData[] = ['key' => 'CGST on SC (2.5%)',                        'value' => (string)$cgst_sc,   'heading' => false];
        $newData[] = ['key' => 'VAT on SC (' . $vat_rate_str . '%)',       'value' => (string)$vat_on_sc, 'heading' => false];

        // ── Total Data ────────────────────────────────────────────────────────────
        $newData[] = ['key' => 'Total Data',              'value' => '------', 'heading' => true];
        $newData[] = ['key' => 'Subtotal',                'value' => (string)round($transactionsubtotal[0][0]['price'], 2),    'heading' => false];
        $newData[] = ['key' => 'Discount',                'value' => (string)round($transactionsubtotal[0][0]['discount'], 2), 'heading' => false];
        $newData[] = ['key' => 'Taxable Amount',          'value' => (string)round($taxable[0][0]['total_taxable'] - $transactionsubtotal[0][0]['discount'], 2), 'heading' => false];
        $newData[] = ['key' => 'Non Taxable Amount',      'value' => (string)round($nontaxable[0][0]['total_nontaxable'], 2),  'heading' => false];
        $newData[] = ['key' => 'NC Taxable Amount',       'value' => (string)round($nctaxable[0][0]['total_taxable'], 2),      'heading' => false];
        $newData[] = ['key' => 'NC Non Taxable Amount',   'value' => (string)round($ncnontaxable[0][0]['total_nontaxable'], 2),'heading' => false];
        $newData[] = ['key' => 'NC Net Sale',             'value' => (string)round($ncnet_amount_query[0][0]['net_amount'], 2),'heading' => false];
        $newData[] = ['key' => 'NC Total Tax',            'value' => (string)round($transactionsnc[0][0]['total_tax'], 2),     'heading' => false];
        $newData[] = ['key' => 'No Charge',               'value' => (string)round($payments[0][0]['no_charge_with_tax'] - $transactionsnc[0][0]['total_tax'], 2), 'heading' => false];
        $newData[] = ['key' => 'No Charge With Tax',      'value' => (string)round($payments[0][0]['no_charge_with_tax'], 2),  'heading' => false];
        $newData[] = ['key' => 'Service Charge',          'value' => (string)round($transactions[0][0]['servicecharge'], 2),   'heading' => false];
        $newData[] = ['key' => 'Delivery Charge',         'value' => (string)round($transactions[0][0]['delivery_charge'], 2), 'heading' => false];
        $newData[] = ['key' => 'Packing Charge',          'value' => (string)round($transactions[0][0]['packing_charge'], 2),  'heading' => false];
        $newData[] = ['key' => 'Net Sale',                'value' => (string)round($net_amount_query[0][0]['net_amount'], 2),  'heading' => false];
        $newData[] = ['key' => 'Total Tax',               'value' => (string)round($transactions[0][0]['total_tax'], 2),       'heading' => false];
        if ($platform_tax_total > 0) {
            $newData[] = ['key' => 'Tax Deposited by Platform (Zomato/Swiggy)', 'value' => (string)-$platform_tax_total, 'heading' => false];
            $newData[] = ['key' => 'Net Tax Liability', 'value' => (string)round($transactions[0][0]['total_tax'] - $platform_tax_total, 2), 'heading' => false];
        }
        $newData[] = ['key' => 'Final Amount',            'value' => (string)round($transactions[0][0]['amount'] - $platform_tax_total, 2), 'heading' => false];
        $newData[] = ['key' => 'Round',                   'value' => (string)round($transactions[0][0]['round'], 2),           'heading' => false];
        $newData[] = ['key' => 'Bill Count',              'value' => (string)round($transactions[0][0]['total_count'], 2),     'heading' => false];
        $newData[] = ['key' => 'Total PAX',               'value' => (string)round($transactions[0][0]['pax'], 2),             'heading' => false];

        $response = array('status' => true, 'message' => "success", 'data' => $newData);
        return json_encode($response, JSON_PRETTY_PRINT);
    }

    private function _dsrSqlStoreFilter($cashierFilter, $alias)
    {
        if ($cashierFilter === '') {
            return '';
        }

        return preg_replace(
            '/\bstore_id\b/',
            $alias . '.store_id',
            $cashierFilter
        );
    }

    private function _dsrKdsSalesSql($dayStart, $dayEnd, $cashierFilter, $nc = false)
    {
        $chargeClause = $nc ? 'IN' : 'NOT IN';

        $otKdsFilter = $this->_dsrSqlStoreFilter($cashierFilter, 'order_tax');
        $oohFilter   = $this->_dsrSqlStoreFilter($cashierFilter, 'ooh');
        $ot2Filter   = $this->_dsrSqlStoreFilter($cashierFilter, 'ot2');
        $opNcFilter  = $this->_dsrSqlStoreFilter($cashierFilter, 'op_nc');
        $opTxFilter  = $this->_dsrSqlStoreFilter($cashierFilter, 'op_tx');

        return "
            SELECT
                final.kds,
                final.kds_name,
                final.tax_percentage,
                final.value

            FROM
            (
                SELECT
                    ia.kds,

                    IFNULL(
                        (
                            SELECT name
                            FROM pos_printers
                            WHERE pos_printers.kds = ia.kds
                            AND pos_printers.store_id = ia.store_id
                            AND pos_printers.status = 1
                            LIMIT 1
                        ),
                        ''
                    ) AS kds_name,

                    ia.tax_percentage,

                    ROUND(
                        SUM(
                            CASE
                                WHEN bt.bill_item_sum > 0
                                THEN
                                    (ia.item_amount / bt.bill_item_sum)
                                    * bt.bill_net
                                ELSE 0
                            END
                        ),
                        2
                    ) AS value

                FROM
                (
                    SELECT
                        ooh.reference_id,
                        ooh.store_id,
                        ooh.quantity,

                        ooh.total_tax_percentage AS tax_percentage,

                        IFNULL(ot_kds.kds, 0) AS kds,

                        (
                            ooh.price * ooh.quantity
                        )
                        *
                        (
                            1 -
                            IFNULL(
                                ot_kds.discount_percentage,
                                0
                            ) / 100
                        ) AS item_amount

                    FROM order_orderhistories ooh

                    INNER JOIN order_transactions ot_b
                        ON ot_b.reference_id = ooh.reference_id
                        AND ot_b.store_id = ooh.store_id
                        AND ot_b.status = 2

                    LEFT JOIN
                    (
                        SELECT
                            orderhistory_id,
                            store_id,

                            MAX(kds) AS kds,

                            MAX(discount_percentage)
                                AS discount_percentage

                        FROM order_tax

                        WHERE status != 0
                        $otKdsFilter

                        GROUP BY
                            orderhistory_id,
                            store_id

                    ) ot_kds

                        ON ot_kds.orderhistory_id =
                        COALESCE(
                            NULLIF(ooh.local_id, ''),
                            ooh.id
                        )

                        AND ot_kds.store_id =
                            ooh.store_id

                    WHERE ot_b.created
                        BETWEEN '$dayStart'
                        AND '$dayEnd'

                    AND ooh.status = 2

                    $oohFilter

                    AND ooh.reference_id $chargeClause
                    (
                        SELECT op_nc.reference_id

                        FROM order_payments op_nc

                        WHERE op_nc.type = 7
                            AND op_nc.status = 2
                            $opNcFilter
                    )

                ) ia

                INNER JOIN
                (
                    SELECT
                        ot2.reference_id,
                        ot2.store_id,

                        (
                            ot2.price -
                            ot2.discount
                        ) AS bill_net,

                        SUM(ia2.item_amount)
                            AS bill_item_sum

                    FROM order_transactions ot2

                    INNER JOIN
                    (
                        SELECT
                            ooh.reference_id,
                            ooh.store_id,

                            (
                                ooh.price * ooh.quantity
                            )
                            *
                            (
                                1 -
                                IFNULL(
                                    ot_kds.discount_percentage,
                                    0
                                ) / 100
                            ) AS item_amount

                        FROM order_orderhistories ooh

                        INNER JOIN order_transactions ot_b

                            ON ot_b.reference_id =
                            ooh.reference_id

                            AND ot_b.store_id =
                                ooh.store_id

                            AND ot_b.status = 2

                        LEFT JOIN
                        (
                            SELECT
                                orderhistory_id,
                                store_id,

                                MAX(discount_percentage)
                                    AS discount_percentage

                            FROM order_tax

                            WHERE status != 0
                            $otKdsFilter

                            GROUP BY
                                orderhistory_id,
                                store_id

                        ) ot_kds

                            ON ot_kds.orderhistory_id =
                            COALESCE(
                                NULLIF(ooh.local_id, ''),
                                ooh.id
                            )

                            AND ot_kds.store_id =
                                ooh.store_id

                        WHERE ot_b.created
                            BETWEEN '$dayStart'
                            AND '$dayEnd'

                        AND ooh.status = 2

                        $oohFilter

                        AND ooh.reference_id $chargeClause
                        (
                            SELECT op_nc.reference_id

                            FROM order_payments op_nc

                            WHERE op_nc.type = 7
                                AND op_nc.status = 2
                                $opNcFilter
                        )

                    ) ia2

                        ON ot2.reference_id =
                        ia2.reference_id

                        AND ot2.store_id =
                            ia2.store_id

                    WHERE ot2.status = 2

                    AND ot2.created
                        BETWEEN '$dayStart'
                        AND '$dayEnd'

                    $ot2Filter

                    AND ot2.reference_id $chargeClause
                    (
                        SELECT op_tx.reference_id

                        FROM order_payments op_tx

                        WHERE op_tx.type = 7
                            AND op_tx.status = 2
                            $opTxFilter
                    )

                    GROUP BY
                        ot2.reference_id,
                        ot2.store_id,
                        ot2.price,
                        ot2.discount

                ) bt

                    ON ia.reference_id =
                    bt.reference_id

                    AND ia.store_id =
                        bt.store_id

                GROUP BY
                    ia.kds,
                    ia.store_id,
                    ia.tax_percentage

            ) final
        ";
    }

    private function _dsrAggregateKdsSales($startdate, $enddate, $cashierFilter, $nc = false, $location_id = null) {
        $salesMap = [];
        $period = new DatePeriod(
            new DateTime($startdate),
            new DateInterval('P1D'),
            (new DateTime($enddate))->modify('+1 day')
        );
        foreach ($period as $dateObj) {
            $day = $dateObj->format('Y-m-d');
            $shiftRange = $this->getShiftDateRange($day, $day, $location_id);
            $dayStart = $shiftRange['startDatetime'];
            $dayEnd   = $shiftRange['endDatetime'];
            $daySales = $this->Order_tax->query(
                $this->_dsrKdsSalesSql($dayStart, $dayEnd, $cashierFilter, $nc)
            );
            foreach ($daySales as $s) {
                $row = isset($s['final']) ? $s['final'] : $s[0];
                $key = ($row['kds_name'] ?? '') . '|' . ($row['tax_percentage'] ?? '');
                if (!isset($salesMap[$key])) {
                    $salesMap[$key] = [
                        'final' => [
                            'kds'            => $row['kds'] ?? null,
                            'kds_name'       => $row['kds_name'] ?? '',
                            'tax_percentage' => $row['tax_percentage'] ?? 0,
                            'value'          => 0,
                        ],
                    ];
                }
                $salesMap[$key]['final']['value'] += (float)($row['value'] ?? 0);
            }
        }
        $sales = array_values($salesMap);
        foreach ($sales as &$saleRow) {
            $saleRow['final']['value'] = round($saleRow['final']['value'], 2);
        }
        unset($saleRow);
        return $sales;
    }

