                'printers'=>$printeritems,
                'brandsale'=>$brandsale,
                'remaining_amount'=>number_format($amount_diff, 2, '.', '')
            );
        return json_encode($response);
    }
    
    public function data_report()
    {
        $cashierid = isset($_REQUEST['id']) ? $_REQUEST['id'] : '';
    
        if ($cashierid == '') {
            return json_encode([
                'status' => false,
                'message' => "Cashier ID Missing",
            ]);
        }
    
        // ✅ Check if cashier exists
        $users = $this->User->find('first', [
            'conditions' => [
                'User.id' => $cashierid,
                'User.status' => 1
            ]
        ]);
    
        if (empty($users)) {
            return json_encode([
                'status' => false,
                'message' => "Cashier not found",
            ]);
        }

        $location_id = !empty($users['User']['location_id']) ? $users['User']['location_id'] : null;
    
        // ✅ Date range: last 7 days
        $todayDate = date("Y-m-d");
        $today = new DateTime();
        $today->modify('-7 days');
        $prevdate = $today->format('Y-m-d');
    
        // ✅ Generate all dates in range
        $dateRange = [];
        $currentDate = new DateTime($prevdate);
        $endDate = new DateTime($todayDate);
        while ($currentDate <= $endDate) {
            $dateRange[] = $currentDate->format('Y-m-d');
            $currentDate->modify('+1 day');
        }
    
        // ✅ Build daily report using dynamic shift time from DB for the cashier's location
        $transactionitems = [];
        foreach ($dateRange as $date) {
            $_dayRange = $this->getShiftDateRange($date, $date, $location_id);
            $dayStart  = $_dayRange['startDatetime'];
            $dayEnd    = $_dayRange['endDatetime'];

            $tQuery = $this->Order_transaction->query("
                SELECT 
                    SUM(amount) AS total_amount,
                    SUM(total_tax) AS total_tax,
                    SUM(servicecharge) AS servicecharge,
                    SUM(discount) AS discount,
                    SUM(delivery_charge) AS delivery_charge,
                    SUM(packing_charge) AS packing_charge,
                    SUM(round) AS round
                FROM order_transactions
                WHERE 
                    created BETWEEN '$dayStart' AND '$dayEnd'
                    AND cashier_id = $cashierid
                    AND status = 2
                    AND reference_id NOT IN (
                        SELECT reference_id 
                        FROM order_payments 
                        WHERE type = 7 AND status = 2 AND cashier_id = $cashierid
                    )
            ");

            $pQuery = $this->Order_payment->query("
                SELECT 
                    SUM(amount) AS total_amount,
                    SUM(IF(type=1, amount, 0)) AS cash,
                    SUM(IF(type=2, amount, 0)) AS card,
                    SUM(IF(type=6, amount, 0)) AS upi,
                    SUM(IF(type=9, amount, 0)) AS online,
                    SUM(IF(type=8, amount, 0)) AS storecard,
                    SUM(IF(type=10, amount, 0)) AS hold,
                    SUM(IF(type=7, amount, 0)) AS no_charge_with_tax,
                    SUM(
                        IF(type=7, 
                            ROUND(amount - (
                                SELECT IFNULL(SUM(total_tax),0)
                                FROM order_transactions 
                                WHERE reference_id = order_payments.reference_id
                            ), 2), 
                        0)
                    ) AS no_charge
                FROM order_payments
                WHERE 
                    created BETWEEN '$dayStart' AND '$dayEnd'
                    AND cashier_id = $cashierid
                    AND status = 2
            ");

            $t = !empty($tQuery[0][0]) ? $tQuery[0][0] : (!empty($tQuery[0]['order_transactions']) ? $tQuery[0]['order_transactions'] : []);
            $p = !empty($pQuery[0][0]) ? $pQuery[0][0] : (!empty($pQuery[0]['order_payments']) ? $pQuery[0]['order_payments'] : []);

            $transactionitems[] = [
                'total_amount'        => number_format($t['total_amount'] ?? 0, 2, '.', ''),
                'total_tax'           => number_format($t['total_tax'] ?? 0, 2, '.', ''),
                'servicecharge'       => number_format($t['servicecharge'] ?? 0, 2, '.', ''),
                'discount'            => number_format($t['discount'] ?? 0, 2, '.', ''),
                'delivery_charge'     => number_format($t['delivery_charge'] ?? 0, 2, '.', ''),
                'packing_charge'      => number_format($t['packing_charge'] ?? 0, 2, '.', ''),
                'round'               => number_format($t['round'] ?? 0, 2, '.', ''),
                'cash'                => number_format($p['cash'] ?? 0, 2, '.', ''),
                'card'                => number_format($p['card'] ?? 0, 2, '.', ''),
                'upi'                 => number_format($p['upi'] ?? 0, 2, '.', ''),
                'online'              => number_format($p['online'] ?? 0, 2, '.', ''),
                'storecard'           => number_format($p['storecard'] ?? 0, 2, '.', ''),
                'hold'                => number_format($p['hold'] ?? 0, 2, '.', ''),
                'no_charge'           => number_format($p['no_charge'] ?? 0, 2, '.', ''),
                'no_charge_with_tax'  => number_format($p['no_charge_with_tax'] ?? 0, 2, '.', ''),
                'transaction_date'    => $date
            ];
        }
    
        return json_encode([
            'status' => true,
            'message' => "success",
            'transactions' => $transactionitems
        ]);
    }
    
    public function data_report_export()
    {
        $cashierid = $_REQUEST['id'] ?? '';
        $sdate = $_REQUEST['sdate'] ?? '';
        $edate = $_REQUEST['edate'] ?? '';
        
        $response = [];
    
        if ($cashierid == '' || $sdate == '' || $edate == '') {
            return json_encode([
                'status' => false,
                'message' => 'Missing required parameters (id, sdate, edate)',
            ]);
        }

        $users = $this->User->find('first', [
            'conditions' => [
                'User.id' => $cashierid,
                'User.status' => 1
            ]
        ]);
        $location_id = !empty($users['User']['location_id']) ? $users['User']['location_id'] : null;

        $shiftRange = $this->getShiftDateRange($sdate, $edate, $location_id);
        $startDatetime = $shiftRange['startDatetime'];
        $endDatetime   = $shiftRange['endDatetime'];

        // ---- PAYMENTS QUERY ----
        $payments = $this->Order_payment->query("
            SELECT 
                SUM(amount) as total_amount,
                SUM(IF(type=1,amount,0)) AS cash,
                SUM(IF(type=10,amount,0)) AS hold,
                SUM(IF(type=6,amount,0)) AS upi,
                SUM(IF(type=2,amount,0)) AS card,
                SUM(IF(type=9,amount,0)) AS online,
                SUM(IF(type=7,amount,0)) AS no_charge_with_tax,
                SUM(
                    IF(type=7, 
                        ROUND(amount - (
                            SELECT SUM(total_tax) 
                            FROM order_transactions 
                            WHERE reference_id = order_payments.reference_id
                        ), 2), 
                    0)
                ) AS no_charge,
                SUM(IF(type=8,amount,0)) AS storecard
            FROM order_payments
            WHERE 
                status = 2 
                AND created BETWEEN '$startDatetime' AND '$endDatetime'
                AND cashier_id = $cashierid
        ");
    
        // ---- TRANSACTIONS QUERY ----
        $transactions = $this->Order_transaction->query("
            SELECT 
                COUNT(id) as total_count,
                SUM(total_tax) AS total_tax,
                SUM(servicecharge) AS servicecharge,
                SUM(discount) AS discount,
                SUM(delivery_charge) AS delivery_charge,
                SUM(packing_charge) AS packing_charge,
                SUM(amount) AS total_amount,
                SUM(price) AS total_price,
                SUM(round) AS round
            FROM order_transactions
            WHERE 
                created BETWEEN '$startDatetime' AND '$endDatetime'
                AND cashier_id = $cashierid
                AND status = 2
                AND reference_id NOT IN (
                    SELECT reference_id 
                    FROM order_payments 
                    WHERE type=7 AND status=2 AND cashier_id = $cashierid
                )
        ");
    
        // ---- FORMAT DATA ----
        $p = $payments[0][0];
        $t = $transactions[0][0];
    
        $data = [
            'total_amount'        => number_format($t['total_amount'] ?? 0, 2, '.', ''),
            'total_price'         => number_format($t['total_price'] ?? 0, 2, '.', ''),
            'total_tax'           => number_format($t['total_tax'] ?? 0, 2, '.', ''),
            'servicecharge'       => number_format($t['servicecharge'] ?? 0, 2, '.', ''),
            'discount'            => number_format($t['discount'] ?? 0, 2, '.', ''),
            'delivery_charge'     => number_format($t['delivery_charge'] ?? 0, 2, '.', ''),
            'packing_charge'      => number_format($t['packing_charge'] ?? 0, 2, '.', ''),
            'round'               => number_format($t['round'] ?? 0, 2, '.', ''),
            'cash'                => number_format($p['cash'] ?? 0, 2, '.', ''),
            'card'                => number_format($p['card'] ?? 0, 2, '.', ''),
            'upi'                 => number_format($p['upi'] ?? 0, 2, '.', ''),
            'online'              => number_format($p['online'] ?? 0, 2, '.', ''),
            'storecard'           => number_format($p['storecard'] ?? 0, 2, '.', ''),
            'hold'                => number_format($p['hold'] ?? 0, 2, '.', ''),
            'no_charge'           => number_format($p['no_charge'] ?? 0, 2, '.', ''),
            'no_charge_with_tax'  => number_format($p['no_charge_with_tax'] ?? 0, 2, '.', ''),
            'transaction_count'   => $t['total_count'] ?? 0,
            'from_date'           => $sdate,
            'to_date'             => $edate,
        ];
    
        // ---- EXPORT CSV ----
        $folderPath = WWW_ROOT . 'uploads/reports/';
        if (!file_exists($folderPath)) {
            mkdir($folderPath, 0777, true);
        }
    
        $filename = 'report_' . $cashierid . '_' . time() . '.csv';
        $filePath = $folderPath . $filename;
        $fileUrl = FULL_BASE_URL . $this->webroot . 'uploads/reports/' . $filename;
    
        $fp = fopen($filePath, 'w');
    
        // Add CSV headers
        fputcsv($fp, array_keys($data));
    
        // Add data row
        fputcsv($fp, array_values($data));
    
        fclose($fp);
    
        // ---- RESPONSE ----
        return json_encode([
            'status' => true,
            'message' => 'success',
            'export' => $fileUrl,
            'data' => $data
        ]);
    }

    public function logout()
    {
        $response['status']= false;
        $response['message']= "fail";
        
        $id = $_REQUEST['id'];
        if($id==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id is Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$id,'User.status'=>1,'User.role'=>'cashier')));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "Cashier not found",
            );
            return json_encode($response);
        }
        
        $tbleschk = $this->Order_table->find('count', [
            'conditions' => [
                'Order_table.status >' => 1
            ],
            'recursive' => -1
        ]);
        
        if ($tbleschk > 0) {
            $response = [
                'status'  => false,
                'message' => "Vacant All Tables first"
            ];
        }

        $datas['User_track']=array(
            'user_id'=>$id,
            'location_id'=>$users['User']['location_id'],
            'location_name'=>$users['User']['location_name'],
            'type'=>'logout',
            'remarks'=>'logout'
        );
        if($this->User_track->saveAll($datas['User_track']))
        {
            $response['status']= true;
            $response['message']= "Logged Out..!";
        }else{
            $response['status']= false;
            $response['message']= "Track not Saved..!";
        }
        return json_encode($response);
    }
    
    public function split_bill_table_package()
    {
        $response['status']= false;
        $response['message']= "fail";
        
        $cashierid = $_REQUEST['id'];
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id is Missing",
            );
            return json_encode($response);
        }
        $table_number = $_REQUEST['table_number'];
        if($table_number==''){
            $response =array(
                'status'=> false,
                'message'=> "Table Number is Missing",
            );
            return json_encode($response);
        }
        $table_referenceid = $_REQUEST['reference_id'];
        if($table_referenceid==''){
            $response =array(
                'status'=> false,
                'message'=> "Table refernce Id is Missing",
            );
            return json_encode($response);
        }
        $device_id='';
        if(isset($_REQUEST['device_id'])){
            $device_id=$_REQUEST['device_id'];
        }
        $name='';
        if(isset($_REQUEST['name'])){
            $name=$_REQUEST['name'];
        }
        $phone='';
        if(isset($_REQUEST['phone'])){
            $phone=$_REQUEST['phone'];
        }
        $address='';
        if(isset($_REQUEST['address'])){
            $address=$_REQUEST['address'];
        }
        $pax=1;
        if(isset($_REQUEST['pax'])){
            $pax=$_REQUEST['pax'];
        }
        
        if (!isset($_REQUEST['data'])) {
            $response = array(
                'status' => false,
                'message' => "data not found",
            );
            return json_encode($response);
        }
        
        $data = json_decode($_REQUEST['data'], true);
        
        // Check if JSON is valid
        if ($data === null) {
            return json_encode([
                'status' => false,
                'message' => 'invalid json'
            ]);
        }
        
        // Validate required structure
        if (
            !isset($data['splits']) ||
            !is_array($data['splits']) ||
            count($data['splits']) == 0
        ) {
            return json_encode([
                'status' => false,
                'message' => 'invalid json structure: splits missing'
            ]);
        }
        
        foreach ($data['splits'] as $split) {
        
            // Check items key
            if (!isset($split['items']) || !is_array($split['items']) || count($split['items']) == 0) {
                return json_encode([
                    'status' => false,
                    'message' => 'invalid json structure: items missing'
                ]);
            }
        
            foreach ($split['items'] as $item) {
        
                if (
                    !isset($item['id']) ||
                    !isset($item['reference_id']) ||
                    !isset($item['quantity'])
                ) {
                    return json_encode([
                        'status' => false,
                        'message' => 'invalid json structure: item keys missing'
                    ]);
                }
            }
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        else{
            $location_id = $users['User']['location_id'];
        }
            
        $tablechk = $this->Order_table->find('first', array('conditions'=>array('Order_table.reference_id'=>$table_referenceid,'Order_table.number'=>$table_number,'Order_table.status'=>2)));
        if(empty($tablechk))
        {
            $response =array(
                'status'=> false,
                'message'=> "Something went wrong for this table kindly check!!!",
            );
            return json_encode($response);
        }
        
        $orderQtyRes = $this->Order_orderhistory->query("
            SELECT id, quantity, product_name, product_id
            FROM order_orderhistories
            WHERE reference_id = '$table_referenceid'
              AND status != 0
        ");
        
        $originalQty  = [];   // order_history_id -> qty
        $originalName = [];   // order_history_id -> product_name

        // Maps for product_id-keyed payloads (POS format)
        $productQty       = [];   // product_id -> total available qty
        $productName      = [];   // product_id -> product_name
        $productHistories = [];   // product_id -> [order_history_ids, ...]

        foreach ($orderQtyRes as $row) {
            
            $hid  = $row['order_orderhistories']['id'];
            $pid  = $row['order_orderhistories']['product_id'];
            $qty  = (int)$row['order_orderhistories']['quantity'];
            $name = $row['order_orderhistories']['product_name'];

            $originalQty[$hid]  = $qty;
            $originalName[$hid] = $name;

            if (!isset($productQty[$pid])) {
                $productQty[$pid]       = 0;
                $productName[$pid]      = $name;
                $productHistories[$pid] = [];
            }
            $productQty[$pid] += $qty;
            $productHistories[$pid][] = $hid;

        }
        
        
        
        
        
        
        
        // Detect whether the payload uses product_id or order_history_id keys.
        // A key is treated as product_id format when it is NOT a known
        // order_history_id but IS a known product_id for this reference.
        $payloadUsesProductId = false;
        foreach ($data['splits'] as $_chkSplit) {
            foreach ($_chkSplit['items'] as $_chkItem) {
                if (!array_key_exists($_chkItem['id'], $originalQty)
                    && array_key_exists($_chkItem['id'], $productQty)) {
                    $payloadUsesProductId = true;
                    break 2;
                }
            }
        }
        
        unset($_chkSplit, $_chkItem);

        if ($payloadUsesProductId) {
            // ── Product_id mode: validate totals then normalize to history ids ──

            $splitProductQty = [];
            foreach ($data['splits'] as $_sp) {
                foreach ($_sp['items'] as $_it) {
                    $splitProductQty[$_it['id']] =
                        ($splitProductQty[$_it['id']] ?? 0) + (int)$_it['quantity'];
                }
            }
            unset($_sp, $_it);

            foreach ($splitProductQty as $_pid => $_reqQty) {
                $_avail = isset($productQty[$_pid]) ? $productQty[$_pid] : 0;
                if ($_reqQty > $_avail) {
                    $_pname = isset($productName[$_pid]) ? $productName[$_pid] : 'Product #'.$_pid;
                    return json_encode([
                        'status'  => false,
                        'message' => "Invalid quantity for $_pname: Available $_avail, Requested $_reqQty"
                    ]);
                }
            }
            unset($_pid, $_reqQty, $_avail, $_pname);

            // Normalize: replace product_id with order_history_id, distributing
            // quantity across history rows in the order they were returned.
            $_histRemaining = [];
            foreach ($orderQtyRes as $_r) {
                $_histRemaining[$_r['order_orderhistories']['id']] =
                    (int)$_r['order_orderhistories']['quantity'];
            }
            unset($_r);

            $normalizedSplits = [];
            foreach ($data['splits'] as $_split) {
                $_newItems = [];
                foreach ($_split['items'] as $_item) {
                    $_pid    = $_item['id'];
                    $_needed = (int)$_item['quantity'];
                    foreach ($productHistories[$_pid] as $_hid) {
                        if ($_needed <= 0) break;
                        $_canUse = min($_needed, $_histRemaining[$_hid]);
                        if ($_canUse <= 0) continue;
                        $_histRemaining[$_hid] -= $_canUse;
                        $_needed -= $_canUse;
                        $_newItems[] = [
                            'id'           => $_hid,
                            'reference_id' => $_item['reference_id'],
                            'quantity'     => $_canUse,
                        ];
                    }
                }
                $normalizedSplits[] = array_merge($_split, ['items' => $_newItems]);
            }
            unset($_split, $_item, $_pid, $_needed, $_hid, $_canUse, $_histRemaining, $_newItems);

            // Apply normalized splits back so downstream code sees history ids
            $data['splits'] = $normalizedSplits;
            unset($normalizedSplits);

        } else {
            // ── Order_history_id mode: original row-exact validation ──

            $splitQty = [];
            foreach ($data['splits'] as $split) {
                foreach ($split['items'] as $item) {
                    $id  = $item['id'];
                    $qty = (int)$item['quantity'];
                    if (!isset($splitQty[$id])) { $splitQty[$id] = 0; }
                    $splitQty[$id] += $qty;
                }
            }

            foreach ($originalQty as $itemId => $qtyFromOrder) {
                $qtyFromSplit = isset($splitQty[$itemId]) ? $splitQty[$itemId] : 0;
                if ($qtyFromSplit != $qtyFromOrder) {
                    $itemName = isset($originalName[$itemId]) ? $originalName[$itemId] : 'Item #'.$itemId;
                    return json_encode([
                        'status'  => false,
                        'message' => "Invalid quantity for $itemName: Ordered $qtyFromOrder, Given $qtyFromSplit"
                    ]);
                }
            }
        }

                    
        
        
        
        $splitBlocks = $data['splits'];

        $waiter_id=$tablechk['Order_table']['waiter_id'];
        $waiter_name = $tablechk['Order_table']['waiter_name'];
        $pax = $tablechk['Order_table']['customer_pax'] ?? 1;
        $name    = trim($tablechk['Order_table']['customer_name']);
        $phone   = trim($tablechk['Order_table']['customer_phone']);
        $address = trim($tablechk['Order_table']['customer_address']);
        $is_takeaway = $tablechk['Order_table']['is_takeaway'];

        $customerchk = $this->Order_customers->find('first', [
            'conditions' => ['Order_customers.phone' => $phone,'Order_customers.status !=' => 0],
            'fields' => ['Order_customers.id'],
            'recursive' => -1
        ]);
    
        if (empty($customerchk)) {
            // Insert new customer
            $data = [
                'Order_customers' => [
                    'phone'   => $phone,
                    'name'    => $name,
                    'address' => $address
                ]
            ];
    
            if ($this->Order_customers->saveAll($data)) {
                
            } else {
                return json_encode([
                    'status' => false,
                    'message' => "Failed to save customer details."
                ]);
            }
        } else {
            // Customer already exists — optional: update their name/address if needed
            $this->Order_customers->id = $customerchk['Order_customers']['id'];
            $this->Order_customers->save([
                'name' => $name,
                'address' => $address
            ]);
    
        }
        
        $this->Order_table->updateAll(
            [
                // 'Order_table.waiter_id' => "'0'",
                // 'Order_table.waiter_name' => "''",
                // 'Order_table.customer_address' => "''",
                // 'Order_table.customer_phone' => "''",
                'Order_table.sync'              => 0,
                'Order_table.local_sync'        => 0
            ],
            ['Order_table.reference_id' => $table_referenceid]
        );
        
        $trxchck = $this->Order_transaction->find('first', array(
            'conditions' => array(
                'Order_transaction.reference_id' => $table_referenceid,
                'NOT' => array('Order_transaction.status' => array(3, 4, 0))
            )
        ));
        if(!empty($trxchck))
        {
            $response =array(
                'status'=> false,
                'message'=> "Reference Id already Exist",
            );
            return json_encode($response);
        }        
        
        $todayDate = date("Y-m-d");
        
        $refid = []; // T9-fix: no merged tables guard

        $mergetablecheck = $this->Order_table_tracking->find('all', [
            'conditions' => [
                'Order_table_tracking.main_table_ref_id' => $table_referenceid,
                'Order_table_tracking.status' => 1,
                "DATE(Order_table_tracking.created) =" => $todayDate
            ]
        ]);
        if (!empty($mergetablecheck)) {
            foreach ($mergetablecheck as $merge) {
                $refid[] = $merge['Order_table_tracking']['merged_table_ref_id']; 
            }
        }
        
        $refid = "'" . implode("','", $refid) . "'";
        
        $this->Order_orderhistory->query("
            UPDATE order_orderhistories o
            SET o.reference_id = '$table_referenceid',o.sync=0,o.local_sync=0
            WHERE o.reference_id IN ($refid)
        ");
        
        $this->Order_tax->query("
            UPDATE order_tax t
            SET t.reference_id = '$table_referenceid',t.sync=0,t.local_sync=0
            WHERE t.reference_id IN ($refid)
        ");
        
        //chk package value in table - item in ordergistory link quanti*package
        // Fetch all product_ids for the given reference_id
        // 1. Set package=1 for packaged items using JOIN (efficient)
        $this->Order_orderhistory->query("
            UPDATE order_orderhistories o
            JOIN catalog_package p ON o.product_id = p.main_product_id AND p.status = 1
            SET o.package = 1,o.sync=0,o.local_sync=0
            WHERE o.reference_id = '$table_referenceid' AND o.status != 0
        ");
        
        $this->Order_tax->query("
            UPDATE order_tax t
            JOIN catalog_package p ON t.product_id = p.main_product_id AND p.status = 1
            SET t.package = 1,t.sync=0,t.local_sync=0
            WHERE t.reference_id = '$table_referenceid' AND t.status = 1
        ");
        // 2. Get total packaged quantity
        $total_package = 0;
        $totalpackagechkorder = $this->Order_orderhistory->query("
            SELECT SUM(package) AS total_package
            FROM order_orderhistories 
            WHERE reference_id = '$table_referenceid' AND status != 0 AND package = 1
        ");
        $packagechngchk=false;
        if (!empty($totalpackagechkorder[0][0]['total_package'])) {
            
            $total_package = isset($totalpackagechkorder[0][0]['total_package']) 
                ? $totalpackagechkorder[0][0]['total_package'] 
                : 0;
                // 3. Non-package items and discount percentage logic
                $discount_percentage = 0;
                $nonpackagechkorder = $this->Order_orderhistory->query("
                    SELECT product_id, SUM(quantity) as order_quantity
                    FROM order_orderhistories 
                    WHERE reference_id = '$table_referenceid' AND status != 0 AND package = 0
                    GROUP BY product_id
                ");
                $discount_pro_array = []; // initialize
                foreach ($nonpackagechkorder as $row) {
                    $orderproduct_id = $row['order_orderhistories']['product_id'];
                    $orderproduct_quantity = $row[0]['order_quantity'];
                    
                    // 4. Find linked package quantity for this non-package item
                    $linkpackagechk = $this->Catalog_package->query("
                        SELECT SUM(link_quantity) AS link_qty,link_product_id
                        FROM catalog_package
                        WHERE link_product_id = '$orderproduct_id' AND status = 1
                        AND main_product_id IN (
                            SELECT product_id 
                            FROM order_orderhistories 
                            WHERE reference_id = '$table_referenceid' AND package = 1 AND status != 0
                        )
                    ");
                    
                    $link_package_item_quantity = 0;
                    if (!empty($linkpackagechk[0][0]['link_qty'])) {
                        $link_package_item_quantity = $linkpackagechk[0][0]['link_qty'];
                    }
                    
                    // 5. Calculate discount
                    if ($orderproduct_quantity <= $link_package_item_quantity) {
                        $discount_percentage = 100;
                    } elseif ($link_package_item_quantity > 0) {
                        $discount_percentage = round(($link_package_item_quantity * 100) / $orderproduct_quantity, 2);
                    } else {
                        $discount_percentage = 0;
                    }
                
                    $orderdata = $this->ordercomputewithpackagediscount($table_referenceid, $cashierid,$orderproduct_id, $discount_percentage);
                    if($orderdata['status'])
                    {
                        $packagechngchk=true;
                    }
                }
            }

            //discount update in ordertax
            $orderss = $this->Order_orderhistory->query("SELECT sum(price) as price,sum(total_tax) as total_tax,sum(total_price) as total_price,sum(discount) as discount FROM `order_orderhistories` WHERE reference_id='$table_referenceid' and status!=0");
            if(!empty($orderss))
            {
                if($orderss[0][0]['total_price']<1){
                    $response =array(
                        'status'=> false,
                        'message'=> "There is no item to bill. Please Check..!",
                    );
                    return json_encode($response);
                }
                
                $todayDate = date("Y-m-d");
                $tdaytrx=$this->Order_transaction->query("SELECT COUNT(id) as tkn FROM `order_transactions` WHERE date(created)='$todayDate' and status=2");
                $token=$tdaytrx['0']['0']['tkn']+1;
                $currenttime=date("H:i:s");
                $updated_discount=0;
                $updated_tax=0;
                $updated_final_amount=0;
                if($packagechngchk){
                    $orderstaxdatas = $this->Order_tax->query("SELECT ot.product_id, SUM((ot.price * ot.quantity) * (ot.discount_percentage / 100)) AS discounted_total, SUM(((ot.price * ot.quantity) * (ot.discount_percentage / 100)) * (IFNULL(ooh.tax_percent, 0) / 100)) AS total_tax, SUM(((ot.price * ot.quantity) * (ot.discount_percentage / 100)) * (1 + (IFNULL(ooh.tax_percent, 0) / 100))) AS final_amount FROM order_tax ot LEFT JOIN ( SELECT product_id, SUM(total_tax_percentage) AS tax_percent FROM order_orderhistories WHERE reference_id = '$table_referenceid' AND status = 1 GROUP BY product_id ) ooh ON ooh.product_id = ot.product_id WHERE ot.reference_id = '$table_referenceid' AND ot.package = 0 AND ot.status = 1");
                    if(!empty($orderstaxdatas))
                    {
                        $updated_discount=$orderstaxdatas[0][0]['discounted_total'];
                        $updated_tax=$orderstaxdatas[0][0]['total_tax'];
                        $updated_final_amount=$orderstaxdatas[0][0]['final_amount'];
                    }
                }
                $grand_total = $orderss[0][0]['total_price'] + $orderss[0][0]['total_tax'];
                $net_total = $grand_total - $orderss[0][0]['discount'] - $updated_final_amount;
                
                $finalamount = round(($orderss[0][0]['total_price']+$orderss[0][0]['total_tax'])-$orderss[0][0]['discount']-$updated_final_amount);        // Rounded to nearest integer
                $roundfinalamount = round(($orderss[0][0]['total_price']+$orderss[0][0]['total_tax'])-$orderss[0][0]['discount']-$updated_final_amount,2); // Rounded to 2 decimal places
                
                $round_amount = $finalamount - $roundfinalamount;
                $split_count = count($splitBlocks);

                $is_split=1;
                if($split_count==1){
                    $split_count=0;
                    $is_split=0;
                }
                
                $this->Order_transaction->begin();
                
                try {
                
                    // =========================================================
                    // 1. SAVE ALL SPLIT DETAILS (orderhistory + tax + split tx)
                    // =========================================================
                    
                    $series_id=sprintf("%02d", $cashierid);
                    $users=$this->User->find('first',array('conditions'=>array('id'=>$cashierid)));
                    $series=strtoupper(substr($users['User']['username'],0,2)); 

                    $ordertrx=$this->Order_transaction->query("SELECT orderno,split_count FROM `order_transactions` order by id desc limit 1");
                    
                    if($ordertrx[0]['order_transactions']['split_count']>1){
                     $last_split_count=$ordertrx[0]['order_transactions']['split_count']-1;
                    }else{
                     $last_split_count=0;
                    }
                     
                    $ordernewstring = substr($ordertrx[0]['order_transactions']['orderno'], -8) + $last_split_count;
                    $ordernonewno=$ordernewstring+1;
                    
                    foreach ($splitBlocks as $block) {

                
                        $refId = null;
                        $blockAmount = 0;   // initialize
                        $blockTax    = 0;   // initialize
                        
                        do {
                            $pin = 'TX' . $cashierid . date('Y') . uniqid();
                        } while ($this->Order_transaction->find('first', array('fields' => 'Order_transaction.id', 'conditions' => array('Order_transaction.reference_id' => $pin))));
                        
                        foreach ($block['items'] as $item) {
                
                            $orderId = $item['id'];
                            $refId   = $item['reference_id'];
                            $qty     = (int)$item['quantity'];
                
                            // ------------------------------------------
                            // FETCH ORIGINAL ORDERHISTORY
                            // ------------------------------------------
                            $original = $this->Order_orderhistory->find('first', [
                                'conditions' => [
                                    'Order_orderhistory.id' => $orderId,
                                    'Order_orderhistory.reference_id' => $refId,
                                    'Order_orderhistory.status !=' => 0
                                ]
                            ]);
                
                            if (empty($original)) {
                                throw new Exception("Original orderhistory not found: ID $orderId");
                            }
                
                            // prepare new row
                            $new = $original['Order_orderhistory'];
                            
                            $new['order_history_id'] = $new['id'];
                            unset($new['id']);
                            
                            $new['quantity'] = $qty;
                
                            // recalc
                            $new['total_tax']   = (($new['price'] * $qty) * $new['total_tax_percentage']) / 100;
                            $new['total_price'] = ($new['price'] * $qty) + $new['total_tax'];
                            
                            $new['split_reference_id'] = $pin;
                        
                            // SAVE split orderhistory
                            $this->Order_split_orderhistory->create();
                            if (!$this->Order_split_orderhistory->save($new)) {
                                throw new Exception("Failed saving Order_split_orderhistory");
                            }
                            
                            // T8-fix: copy modifier rows for this orderhistory item into the split bill.
                            // Modifiers are linked by orderhistory_id+reference_id; we copy them
                            // with the new split_reference_id so the split bill shows correct modifiers.
                            $modifierRows = $this->Order_modifier->find('all', [
                                'conditions' => [
                                    'Order_modifier.orderhistory_id' => $orderId,
                                    'Order_modifier.reference_id'    => $refId,
                                    'Order_modifier.status !='       => 0
                                ]
                            ]);
                            foreach ($modifierRows as $modRow) {
                                $modData = $modRow['Order_modifier'];
                                unset($modData['id'], $modData['created'], $modData['modified']);
                                $modData['reference_id']       = $refId;
                                $modData['split_reference_id'] = $pin;
                                $modData['sync']               = 0;
                                $modData['local_sync']         = 0;
                                $this->Order_modifier->create();
                                if (!$this->Order_modifier->save($modData)) {
                                    throw new Exception("Failed saving split modifier for orderhistory_id=$orderId");
                                }
                            }
                        

                            // accumulate split totals
                            $blockAmount += $new['price'] * $qty;
                            $blockTax    += $new['total_tax'];
                
                            // ------------------------------------------
                            // FETCH RELATED TAX ROWS
                            // ------------------------------------------
                            $taxRows = $this->Order_tax->find('all', [
                                'conditions' => [
                                    'Order_tax.orderhistory_id' => $orderId,
                                    'Order_tax.reference_id'    => $refId,
                                    'Order_tax.status !='       => 0
                                ]
                            ]);
                
                
                
                
                
                
                
                        } // end items loop
                
                        // =========================================================
                        // 2. SAVE SPLIT TRANSACTION FOR THIS BLOCK
                        // =========================================================
                
                        $tx = [];
                        $tx['split_reference_id'] = $pin;
                        
                        $tx['reference_id'] = $refId;
                        $tx['store_id']     = $location_id;
                        $tx['device_id']    = $device_id;
                        $tx['cashier_id']   = $cashierid;
                        $tx['waiter_id']    = $waiter_id;
                        $tx['waiter_name']  = $waiter_name;
                        $tx['name']         = $name;
                        $tx['phone']        = $phone;
                        $tx['address']      = $address;
                
                        $tx['price']        = round($blockAmount, 2);
                        $tx['total_tax']    = round($blockTax, 2);
                        $tx['amount']       = round($blockAmount + $blockTax, 0);
                
                        $tx['is_split']     = 1;
                        $tx['createtime']   = $currenttime;
                        
                        $GOrder = sprintf("%08d", $ordernonewno);
                        $orderNumber = $series_id."".$series.date('Y').$GOrder;     
                        
                        $tx['orderno']   = $orderNumber;
                        
                        $tx['createtime']   = $currenttime;
                        
                        $this->Order_split_transaction->create();
                        if (!$this->Order_split_transaction->save($tx)) {
                            throw new Exception("Failed saving split transaction");
                        }
                    
                        $ordernonewno++;
                    
                    } // end block loop
                
                    // =========================================================
                    // 3. SAVE MAIN / FINAL ORDER_TRANSACTION
                    // =========================================================
                    $datas['Order_transaction']=array(
                        'reference_id'=>$table_referenceid,
                        'device_id'=>$device_id,
                        'cashier_id'=>$cashierid,
                        'store_id'=>$location_id,
                        'price'=>round($orderss[0][0]['total_price']-$updated_discount,2),
                        'total_tax'=>round($orderss[0][0]['total_tax']-$updated_tax,2),
                        'discount'=>round($orderss[0][0]['discount'],2),
                        'amount'=>$finalamount,
                        'round'=>round($round_amount,0),
                        'name'=>$name,
                        'phone'=>$phone,
                        'address'=>$address,
                        'tokenno'=>$token,
                        'table_number'=>$table_number,
                        'pax'=>$pax,
                        'waiter_id'=>$waiter_id,
                        'waiter_name'=>$waiter_name,
                        'is_takeaway' => $is_takeaway,
                        'createtime'=>$currenttime,
                        'is_split' => $is_split,
                        'split_count' => $split_count,
                        'split_type' => 'item'
                    );
                
                    if (!$this->Order_transaction->save($datas['Order_transaction'])) {
                        throw new Exception("Failed to save final Order_transaction");
                    }
                
                    // =========================================================
                    // 4. UPDATE TABLES (ONLY IF EVERYTHING ABOVE SUCCESS)
                    // =========================================================
                
                    $this->Order_table->query("
                        UPDATE order_tables SET status = 3,sync=0,local_sync=0
                        WHERE reference_id = '$table_referenceid' AND status != 0
                    ");
                
                    $this->Order_table->query("
                        UPDATE order_tables SET status = 1,sync=0,local_sync=0
                        WHERE reference_id IN ($refid) AND status != 0
                    ");
                
                    $this->Order_table_tracking->query("
                        UPDATE order_table_tracking SET status = 0,sync=0,local_sync=0
                        WHERE merged_table_ref_id IN ($refid)
                    ");
                
                    // COMMIT ALL
                    $this->Order_transaction->commit();
                
                    return json_encode([
                        'status' => true,
                        'message' => 'Split saved and final transaction saved successfully'
                    ]);
                
                } catch (Exception $e) {
                
                    $this->Order_transaction->rollback();
                
                    return json_encode([
                        'status' => false,
                        'message' => $e->getMessage()
                    ]);
                }
                
            }
        
        return json_encode($response);
    }
    
    public function split_fetch_unsettled_bill()
    {
        $cashierid = $_REQUEST['id'];
        $reference_id = $_REQUEST['reference_id'];
    
        // Validate cashier id
        if ($cashierid == '') {
            return json_encode([
                'status' => false,
                'message' => "Cashier Id Missing"
            ]);
        }
    
        // Validate reference id
        if ($reference_id == '') {
            return json_encode([
                'status' => false,
                'message' => "Reference Id Missing"
            ]);
        }
    
        // Validate user
        $users = $this->User->find('first', [
            'conditions' => ['User.id' => $cashierid, 'User.status' => 1]
        ]);
    
        if (empty($users)) {
            return json_encode([
                'status' => false,
                'message' => "User not found"
            ]);
        }
    
        $transactionitems = [];
        $finalamount = 0;
    
        $transactions = $this->Order_transaction->find('all', [
            'conditions' => ['reference_id' => $reference_id, 'status !=' => 0]
        ]);
        if (empty($transactions)){
            return json_encode([
                'status' => false,
                'message' => "Transaction Not Found"
            ]);
        }
        
        if($transactions[0]['Order_transaction']['is_split']){
            
            
            $splittransactions = $this->Order_split_transaction->find('all', [
                'fields' => [
                    'Order_split_transaction.*',
                    'SUM(Order_split_transaction.amount) AS total_amount'
                ],
                'conditions' => [
                    'Order_split_transaction.reference_id' => $reference_id,
                    'Order_split_transaction.status !=' => 0
                ],
                'group' => ['Order_split_transaction.id']
            ]);
            
            if (!empty($splittransactions)) {
        
                # ============================================================
                # ✅ RETURN ONLY SPLIT BILL DATA
                # ============================================================
                $finalamount=0;
                $finalpayment=0;
                
                foreach ($splittransactions as $split) {
                    $finalamount = $split[0]['total_amount'];
                    $split_id=$split['Order_split_transaction']['id'];
                    
                    $allpayments=$this->Order_split_payment->query("SELECT sum(amount) as pay_amount FROM `order_split_payments` WHERE split_txn_id='$split_id' and reference_id='$reference_id' and status!=0");
                    if($allpayments){
                        $finalpayment=$allpayments[0][0]['pay_amount'];
                    }
                    $amount_diff=round(($finalamount-$finalpayment),2);
                    
                    if($amount_diff>0){
                        if (!$split['Order_split_transaction']['remarks']) {
                            $split['Order_split_transaction']['remarks'] = '';
                        }
            
                        $split_reference = $split['Order_split_transaction']['reference_id'];
            
                        # ------------------------------------------------------------
                        # 🔹 FETCH SPLIT DISCOUNT PERCENTAGE
                        # ------------------------------------------------------------
            
                        $split_discount_percentage = "0";
            
                        $splitdiscper = $this->Order_tax->query("
                            SELECT discount_percentage 
                            FROM order_tax 
                            WHERE reference_id = '$split_reference'
                            AND status != 0 
                            AND discount_percentage != 0 
                            LIMIT 1
                        ");
            
                        if (!empty($splitdiscper)) {
                            $split_discount_percentage = number_format($splitdiscper[0]['order_tax']['discount_percentage'], 2);
                        }
            
                        # ------------------------------------------------------------
                        # 🔹 FETCH SPLIT KOT NUMBERS
                        # ------------------------------------------------------------
            
                        $split_kotQuery = $this->Order_split_orderhistory->query("
                            SELECT GROUP_CONCAT(DISTINCT(kot_number)) AS kot_numbers 
                            FROM order_split_orderhistories 
                            WHERE reference_id = '$split_reference'
                            AND status != 0
                        ");
            
                        $split_kot_numbers = '';
                        if (!empty($split_kotQuery) && isset($split_kotQuery[0][0]['kot_numbers'])) {
                            $split_kot_numbers = $split_kotQuery[0][0]['kot_numbers'];
                        }
            
                        # ------------------------------------------------------------
                        # 🔹 ADD SPLIT TRANSACTION TO ARRAY
                        # ------------------------------------------------------------
            
                        $transactionitems[] = [
                            'id'                   => $split['Order_split_transaction']['id'],
                            'reference_id'         => $split['Order_split_transaction']['reference_id'],
                            'split_reference_id'   => $split['Order_split_transaction']['split_reference_id'] ?? '',
                            'orderno'              => $split['Order_split_transaction']['orderno'],
                            'device_id'            => $split['Order_split_transaction']['device_id'],
                            'cashier_id'           => $split['Order_split_transaction']['cashier_id'],
                            'table_number'         => $split['Order_split_transaction']['table_number'],
                            'price'                => $split['Order_split_transaction']['price'],
                            'total_tax'            => $split['Order_split_transaction']['total_tax'],
                            'servicecharge'        => $split['Order_split_transaction']['servicecharge'],
                            'discount'             => $split['Order_split_transaction']['discount'],
                            'discount_percentage'  => $split_discount_percentage,
                            'delivery_charge'      => $split['Order_split_transaction']['delivery_charge'],
                            'packing_charge'       => $split['Order_split_transaction']['packing_charge'],
                            'amount'               => $split['Order_split_transaction']['amount'],
                            'round'                => $split['Order_split_transaction']['round'],
                            'name'                 => $split['Order_split_transaction']['name'],
                            'phone'                => $split['Order_split_transaction']['phone'],
                            'address'              => $split['Order_split_transaction']['address'],
                            'remarks'              => $split['Order_split_transaction']['remarks'],
                            'status'               => $split['Order_split_transaction']['status'],
                            'tokenno'              => $split['Order_split_transaction']['tokenno'],
                            'createtime'           => $split['Order_split_transaction']['createtime'],
                            'created'              => $split['Order_split_transaction']['created'],
                            'pax'                  => $split['Order_split_transaction']['pax'],
                            'kot_number'           => $split_kot_numbers
                        ];
                    }
                }
            
                # RETURN SPLIT RESPONSE
                return json_encode([
                    'status' => true,
                    'is_split_bill' => true,
                    'data' => $transactionitems
                ]);
            }
        }else{
            # ============================================================
            # 🔍 STEP 1: CHECK IF SPLIT TRANSACTIONS EXIST
            # ============================================================
            
            foreach ($transactions as $orders) {
                $finalamount=$orders['Order_transaction']['amount'];
                
                $finalpayment=0;
                $allpayments=$this->Order_payment->query("SELECT sum(amount) as pay_amount FROM `order_payments` WHERE reference_id='$reference_id' and status!=0");
                if($allpayments){
                    $finalpayment=$allpayments[0][0]['pay_amount'];
                }
                $amount_diff=round(($finalamount-$finalpayment),2);
                
                if($amount_diff>=0){
                    
                    if (!$orders['Order_transaction']['remarks']) {
                        $orders['Order_transaction']['remarks'] = '';
                    }
        
                    $order_ref = $orders['Order_transaction']['reference_id'];
                    
                    # ------------------------------------------------------------
                    # 🔹 DISCOUNT %
                    # ------------------------------------------------------------
        
                    $discount_percentage = "0";
        
                    $discper = $this->Order_tax->query("
                        SELECT discount_percentage 
                        FROM order_tax 
                        WHERE reference_id = '$order_ref'
                        AND status != 0 
                        AND discount_percentage != 0 
                        LIMIT 1
                    ");
        
                    if (!empty($discper)) {
                        $discount_percentage = number_format($discper[0]['order_tax']['discount_percentage'], 2);
                    }
        
                    # ------------------------------------------------------------
                    # 🔹 KOT NUMBERS
                    # ------------------------------------------------------------
        
                    $kotQuery = $this->Order_orderhistory->query("
                        SELECT GROUP_CONCAT(DISTINCT(kot_number)) AS kot_numbers 
                        FROM order_orderhistories 
                        WHERE reference_id = '$order_ref'
                        AND status != 0
                    ");
        
                    $kot_numbers = '';
                    if (!empty($kotQuery) && isset($kotQuery[0][0]['kot_numbers'])) {
                        $kot_numbers = $kotQuery[0][0]['kot_numbers'];
                    }
        
                    # ------------------------------------------------------------
                    # 🔹 ADD NORMAL TRANSACTION
                    # ------------------------------------------------------------
        
                    $transactionitems[] = [
                        'id'                   => $orders['Order_transaction']['id'],
                        'reference_id'         => $orders['Order_transaction']['reference_id'],
                        'split_reference_id'   => '',
                        'orderno'              => $orders['Order_transaction']['orderno'],
                        'device_id'            => $orders['Order_transaction']['device_id'],
                        'cashier_id'           => $orders['Order_transaction']['cashier_id'],
                        'table_number'         => $orders['Order_transaction']['table_number'],
                        'price'                => $orders['Order_transaction']['price'],
                        'total_tax'            => $orders['Order_transaction']['total_tax'],
                        'servicecharge'        => $orders['Order_transaction']['servicecharge'],
                        'discount'             => $orders['Order_transaction']['discount'],
                        'discount_percentage'  => $discount_percentage,
                        'delivery_charge'      => $orders['Order_transaction']['delivery_charge'],
                        'packing_charge'       => $orders['Order_transaction']['packing_charge'],
                        'amount'               => $orders['Order_transaction']['amount'],
                        'round'                => $orders['Order_transaction']['round'],
                        'name'                 => $orders['Order_transaction']['name'],
                        'phone'                => $orders['Order_transaction']['phone'],
                        'address'              => $orders['Order_transaction']['address'],
                        'remarks'              => $orders['Order_transaction']['remarks'],
                        'status'               => $orders['Order_transaction']['status'],
                        'tokenno'              => $orders['Order_transaction']['tokenno'],
                        'createtime'           => $orders['Order_transaction']['createtime'],
                        'created'              => $orders['Order_transaction']['created'],
                        'pax'                  => $orders['Order_transaction']['pax'],
                        'is_split'             => $orders['Order_transaction']['is_split'],
                        'split_count'          => $orders['Order_transaction']['split_count'],
                        'split_type'           => $orders['Order_transaction']['split_type'],
                        'kot_number'           => $kot_numbers
                    ];
                }
            }
            
            return json_encode([
                'status' => true,
                'is_split_bill' => false,
                'data' => $transactionitems
            ]);
        }
    }
    
    public function split_reprint_data()
    {
        $cashierid = $_REQUEST['id'];
        $reference_id = $_REQUEST['reference_id'];
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "User Id Missing",
            );
            return json_encode($response);
        }
        if($reference_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Reference Id Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        $transactions = $this->Order_transaction->find('all', [
            'conditions' => ['reference_id' => $reference_id, 'status !=' => 0]
        ]);
        if (empty($transactions)){
            return json_encode([
                'status' => false,
                'message' => "Transaction Not Found"
            ]);
        }
        $order_punch_by='';
        $reeloDiscountMsg = '';
        
        if($transactions[0]['Order_transaction']['is_split']){
            $split_reference_id = $_REQUEST['split_reference_id'];
            
            $orderitems=[];
            $prodorderhistory_ids=[];
            $orderss = $this->Order_split_orderhistory->query("SELECT *,  ( SELECT name FROM users WHERE id = ( SELECT cashier_id FROM order_split_orderhistories WHERE reference_id = '$reference_id' and split_reference_id='$split_reference_id' AND status != 0 ORDER BY id ASC LIMIT 1 ) LIMIT 1 ) AS first_cashier_name  FROM `order_split_orderhistories` WHERE reference_id='$reference_id' and split_reference_id='$split_reference_id' and status!=0");
            if(!empty($orderss))
            {
                
                foreach($orderss as $orders){
                    $product_id=$orders['order_split_orderhistories']['product_id'];
                    $order_id=$orders['order_split_orderhistories']['order_history_id'];
                    $order_punch_by = $orders[0]['first_cashier_name'];
                
                    $prodorderhistory_ids[]=$orders['order_split_orderhistories']['order_history_id'];
                    $selected_modifiers=[];
                    
