                        'amount' =>  $orders['Order_payment']['amount'],
                        'status' =>  $orders['Order_payment']['status'],
                        'remarks' =>  $orders['Order_payment']['remarks'],
                        'created' =>  $orders['Order_payment']['created']
                    );
                }
            }
            $taxitems=[];
            $taxes = $this->Order_tax->query("SELECT tax_id,tax_name,tax_percentage,sum(tax_value) as tax_value FROM `order_tax` WHERE reference_id='$reference_id' and tax_percentage!=0 and status!=0 GROUP by tax_id");
            if(!empty($taxes))
            {
                foreach($taxes as $tax){
                    $taxitems[]=array(
                        'tax_id' => $tax['order_tax']['tax_id'],
                        'tax_name' =>  $tax['order_tax']['tax_name'],
                        'tax_percentage' =>  $tax['order_tax']['tax_percentage'],
                        'tax_value' =>  "" .round($tax[0]['tax_value'],2)
                    );
                }
            }
            $finalpayment=0;
            $allpayments=$this->Order_payment->query("SELECT sum(amount) as pay_amount FROM `order_payments` WHERE reference_id='$reference_id' and status!=0");
            if($allpayments){
                $finalpayment=$allpayments[0][0]['pay_amount'];
            }
            $amount_diff=round(($finalamount-$finalpayment),2);
            if ($amount_diff < 1 && $amount_diff >= 0) {
                $amount_diff = 0;
            }
        }
        
        $cashier_name='';
        $cashname=$this->User->query("SELECT name FROM `users` WHERE id='$cashierid'");
        if($cashname){
           $cashier_name =$cashname[0]['users']['name'];
        }
        
        $printeritems=[];
        $targetStoreId = !empty($users['User']['location_id']) ? $users['User']['location_id'] : (!empty($transactions[0]['Order_transaction']['store_id']) ? $transactions[0]['Order_transaction']['store_id'] : '');
        $printerCond = !empty($targetStoreId) ? "status=1 AND store_id='$targetStoreId'" : "status=1";
        $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE $printerCond");
        if(empty($printerss) && !empty($targetStoreId)){
            $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE status=1");
        }
        if(!empty($printerss))
        {
            foreach($printerss as $printers){
                $printeritems[]=array(
                    'id' => $printers['pos_printers']['id'],
                    'store_id' =>  $printers['pos_printers']['store_id'],
                    'name' =>  $printers['pos_printers']['name'],
                    'kds' =>  $printers['pos_printers']['kds'],
                    'ip' =>  $printers['pos_printers']['ip'],
                    'status' =>  $printers['pos_printers']['status']
                );
            }
        }

        $brandsale=[];
        $brandsaless = $this->Order_transaction->query("SELECT store_id,(SELECT name from locations WHERE id=order_transactions.store_id) as brandname,(SELECT print_line4 from locations WHERE id=order_transactions.store_id) as brandgst,orderno,(SELECT GROUP_CONCAT(CONCAT(type_value, ' - ', amount)) from order_payments WHERE status=2 and reference_id=order_transactions.reference_id and store_id=order_transactions.store_id) as payment_mode FROM `order_transactions` WHERE reference_id='$reference_id' and status!=0 GROUP by store_id");
        if(!empty($brandsaless))
        {
            foreach($brandsaless as $brandsales){
                
                $brandsale[]=array(
                   'store_id'     => $brandsales['order_transactions']['store_id'] ?? '',
                    'brandname'    => $brandsales[0]['brandname'] ?? '',
                    'brandgst'     => $brandsales[0]['brandgst'] ?? '',
                    'orderno'      => $brandsales['order_transactions']['orderno'] ?? '',
                    'payment_mode' => $brandsales[0]['payment_mode'] ?? ''
                );
            }
        }
        
        $response= array('status'=> true,
                'message'=> "success",
                'cashier_name'=>$cashier_name,
                'order_punch_by'=>$order_punch_by,
                'orders'=>$orderitems,
                'transactions'=>$transactionitems,
                'payments'=>$paymentitems,
                'taxes'=>$taxitems,
                'printers'=>$printeritems,
                'brandsale'=>$brandsale,
                'remaining_amount'=>number_format($amount_diff, 2, '.', ''),
                'reelo_discount_message' => $reeloDiscountMsg
            );
        return json_encode($response);
    }

    
    public function split_orderpaymentsave_table()
    {
        $response['status']= false;
        $response['message']= "fail";
        
        $cashierid = $_REQUEST['id'];
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id is Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
    
        if (isset($_REQUEST['data'])) {
            $data = $_REQUEST['data'];
        } else {
            $response =array(
                'status'=> false,
                'message'=> "data not found",
            );
            return json_encode($response);
        }
        
        $data = json_decode($data, true);
        
        $reference_id=$data['reference_id'];
        $device_id=$data['device_id'];
        
        //payment save
        
        $transactions = $this->Order_transaction->find('first', array('conditions'=>array('Order_transaction.reference_id'=>$reference_id,'Order_transaction.status'=>1)));
        if(empty($transactions))
        {
            $response =array(
                'status'=> false,
                'message'=> "Transaction not found",
            );
            return json_encode($response);
        }
        
        $store_id=$transactions['Order_transaction']['store_id'];
        $is_split=$transactions['Order_transaction']['is_split'];
        
        if($is_split){
            $split_id=$data['id'];
            $split_reference_id=$data['split_reference_id'];
                
            $splittransactions = $this->Order_split_transaction->find('all', [
                'fields' => [
                    'Order_split_transaction.*',
                    'SUM(Order_split_transaction.amount) AS total_amount'
                ],
                'conditions' => [
                    'Order_split_transaction.reference_id' => $reference_id,
                    'Order_split_transaction.split_reference_id' => $split_reference_id,
                    'Order_split_transaction.id' => $split_id,
                    'Order_split_transaction.status' => 1
                ]
            ]);
            
            if (empty($splittransactions[0]['Order_split_transaction']['id'])) {
                $response =array(
                    'status'=> false,
                    'message'=> "No Split Transaction found",
                );
                return json_encode($response);
            }
            
            foreach($data['payment'] as $payment){
                
                if($payment['type']==7){
                    $response['status']= false;
                    $response['message']= "Option not allowed";
                    return json_encode($response);
                }
                
                
                $split_finalamount = $splittransactions[0][0]['total_amount'];
         
                $datas['Order_split_payment']=array(
                    'split_reference_id'=>$split_reference_id,
                    'split_txn_id'=>$split_id,
                    'reference_id'=>$reference_id,
                    'store_id'=>$store_id,
                    'device_id'=>$device_id,
                    'cashier_id'=>$cashierid,
                    'type'=>$payment['type'],
                    'type_value'=>$payment['type_value'],
                    'amount'=>$payment['amount'],
                    'remarks'=>$payment['remarks']
                );
                
                if($this->Order_split_payment->saveAll($datas['Order_split_payment']))
                {
                    $splitPaymentId = $this->Order_split_payment->id;

                    $split_allpayments=$this->Order_split_payment->query("SELECT sum(amount) as pay_amount FROM `order_split_payments` WHERE split_txn_id='$split_id' and split_reference_id='$split_reference_id' and reference_id='$reference_id' and status!=0");
                    if($split_allpayments){
                        $split_finalpayment=$split_allpayments[0][0]['pay_amount'];
                    }
                    $split_amount_diff=round(($split_finalamount-$split_finalpayment),2);
                    
                    if($split_amount_diff<1){
                        $this->Order_split_orderhistory->query("UPDATE order_split_orderhistories SET status = 2,sync=0,local_sync=0 WHERE split_reference_id='$split_reference_id' and reference_id = '$reference_id' and status = 1");
                        $this->Order_split_transaction->query("UPDATE order_split_transactions SET status = 2,payment_mode='$type_value',sync=0,local_sync=0 WHERE id='$split_id' and split_reference_id='$split_reference_id' and reference_id = '$reference_id' and status!=0");
                        $this->Order_split_payment->query("UPDATE order_split_payments SET status = 2,sync=0,local_sync=0 WHERE split_txn_id='$split_id' and split_reference_id='$split_reference_id' and reference_id = '$reference_id' and status!=0");
                    }
                    
                    $datas['Order_payment']=array(
                        'reference_id'=>$reference_id,
                        'store_id'=>$store_id,
                        'device_id'=>$device_id,
                        'cashier_id'=>$cashierid,
                        'type'=>$payment['type'],
                        'type_value'=>$payment['type_value'],
                        'amount'=>$payment['amount'],
                        'remarks'=>$payment['remarks']
                    );
                    if($this->Order_payment->saveAll($datas['Order_payment']))
                    {
                        $mainpayid = $this->Order_payment->id;

                        $this->Order_split_payment->query("UPDATE order_split_payments SET main_payment_id = '$mainpayid',sync=0,local_sync=0 WHERE id='$splitPaymentId' and split_reference_id='$split_reference_id' and reference_id = '$reference_id' and status!=0");
                        
                        $finalpayment=0;
                        $finalamount=0;
                        $allpayments=$this->Order_payment->query("SELECT sum(amount) as pay_amount FROM `order_payments` WHERE reference_id='$reference_id' and status!=0");
                        if($allpayments){
                            $finalpayment=$allpayments[0][0]['pay_amount'];
                        }
                        if($transactions){
                            $finalamount=$transactions['Order_transaction']['amount'];
                        }
                        $amount_diff=$finalamount-$finalpayment;
                        if($amount_diff<=1){
                            
                            $this->Order_orderhistory->query("UPDATE order_orderhistories SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status = 1");
                            $this->Order_transaction->query("UPDATE order_transactions SET status = 2,payment_mode='$type_value',sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status!=0");
                            $this->Order_payment->query("UPDATE order_payments SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status!=0");
                            $this->Order_tax->query("UPDATE order_tax SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status != 0");
                            
                            do {
                                $pin = 'TX' . $cashierid . date('Y') . uniqid();
                            } while ($this->Order_table->find('first', array('fields' => 'Order_table.id', 'conditions' => array('Order_table.reference_id' => $pin))));
                            
                            $tablestatus = $this->Order_table->find('first', array('conditions'=>array('reference_id'=>$reference_id,'is_takeaway'=>1)));
                            if(!empty($tablestatus))
                            {   
                                $this->Order_table->query("UPDATE order_tables SET status=0,sync=0,local_sync=0,modified=NOW()  WHERE reference_id = '$reference_id'");
                            }else{
                                $this->Order_table->query("UPDATE order_tables SET customer_name='',customer_phone='',customer_address='',customer_pax=1,status = 1,reference_id='$pin',is_alert=0,sync=0,local_sync=0,modified=NOW() WHERE reference_id = '$reference_id'");
                            }
        
                            $stockupdate=$this->stock_update($reference_id);
                            if(!$stockupdate){
                                $response['status']= true;
                                $response['message']= "Payment Data Saved Successfully..! But stock not updated";
                                $response['full_payment']= true; 
                            }
                            $response['status']= true;
                            $response['message']= "Payment Data Saved Successfully..!";
                            $response['full_payment']= true;
                        }else{
                            if($split_amount_diff<1){
                                $response['status']= true;
                                $response['message']= "Payment Data Saved Successfully..!";
                                $response['full_payment']= true;
                            }else{
                                $response['status']= true;
                                $response['message']= "Payment Data Saved Successfully..!";
                                $response['full_payment']= false;
                            }
                        }
                    }
                }else{
                    $response['status']= false;
                    $response['message']= "Payment Data not saved Error:102";
                    $response['full_payment']= false;
                }
            }
        }else{
            
            foreach($data['payment'] as $payment){
                $datas['Order_payment']=array(
                    'reference_id'=>$reference_id,
                    'store_id'=>$store_id,
                    'device_id'=>$device_id,
                    'cashier_id'=>$cashierid,
                    'type'=>$payment['type'],
                    'type_value'=>$payment['type_value'],
                    'amount'=>$payment['amount'],
                    'remarks'=>$payment['remarks']
                );
                if($this->Order_payment->saveAll($datas['Order_payment']))
                {
                    $finalpayment=0;
                    $finalamount=0;
                    $allpayments=$this->Order_payment->query("SELECT sum(amount) as pay_amount FROM `order_payments` WHERE reference_id='$reference_id' and status!=0");
                    if($allpayments){
                        $finalpayment=$allpayments[0][0]['pay_amount'];
                    }
                    if($transactions){
                        $finalamount=$transactions['Order_transaction']['amount'];
                    }
                    $amount_diff=$finalamount-$finalpayment;
                    if($amount_diff<1){
                        
                        $this->Order_orderhistory->query("UPDATE order_orderhistories SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status = 1");
                        $this->Order_transaction->query("UPDATE order_transactions SET status = 2,payment_mode='$type_value',sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status!=0");
                        $this->Order_payment->query("UPDATE order_payments SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status!=0");
                        $this->Order_tax->query("UPDATE order_tax SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status != 0");
                        
                        do {
                            $pin = 'TX' . $cashierid . date('Y') . uniqid();
                        } while ($this->Order_table->find('first', array('fields' => 'Order_table.id', 'conditions' => array('Order_table.reference_id' => $pin))));
                        
                        $tablestatus = $this->Order_table->find('first', array('conditions'=>array('reference_id'=>$reference_id,'is_takeaway'=>1)));
                        if(!empty($tablestatus))
                        {   
                            $this->Order_table->query("UPDATE order_tables SET status=0,sync=0,local_sync=0,modified=NOW()  WHERE reference_id = '$reference_id'");
                        }else{
                            $this->Order_table->query("UPDATE order_tables SET customer_name='',customer_phone='',customer_address='',customer_pax=1,status = 1,reference_id='$pin',is_alert=0,sync=0,local_sync=0,modified=NOW() WHERE reference_id = '$reference_id'");
                        }
    
                        $stockupdate=$this->stock_update($reference_id);
                        if(!$stockupdate){
                            $response['status']= true;
                            $response['message']= "Payment Data Saved Successfully..! But stock not updated";
                            $response['full_payment']= true; 
                        }
                        $response['status']= true;
                        $response['message']= "Payment Data Saved Successfully..!";
                        $response['full_payment']= true;
                    }else{
                        $response['status']= true;
                        $response['message']= "Payment Data Saved Successfully..!";
                        $response['full_payment']= false;
                    }
                }else{
                    $response['status']= false;
                    $response['message']= "Payment Data not saved Error:102";
                    $response['full_payment']= false;
                }
            }
        }
        return json_encode($response);
    }
    

    public function item_move_multiple()
    {
        $this->autoRender = false;
    
        // ---------------------------
        // Read Inputs Safely
        // ---------------------------
        $cashierid         = trim($_REQUEST['id'] ?? '');
        $from_reference_id = trim($_REQUEST['from_reference_id'] ?? '');
        $to_reference_id   = trim($_REQUEST['to_reference_id'] ?? '');
    
        // ---------------------------
        // Basic Validation
        // ---------------------------
        if (!$cashierid) {
            return json_encode(['status' => false, 'message' => 'Cashier ID is missing']);
        }
        if (!$from_reference_id) {
            return json_encode(['status' => false, 'message' => 'From Reference ID is missing']);
        }
        if (!$to_reference_id) {
            return json_encode(['status' => false, 'message' => 'To Reference ID is missing']);
        }
    
        // ---------------------------
        // Validate User
        // ---------------------------
        $user = $this->User->find('first', [
            'conditions' => ['User.id' => $cashierid, 'User.status' => 1],
            'recursive'  => -1
        ]);
    
        if (empty($user)) {
            return json_encode(['status' => false, 'message' => 'User not found']);
        }
    
        // ---------------------------
        // Validate Tables
        // ---------------------------
        $fromtable = $this->Order_table->find('first', [
            'conditions' => [
                'Order_table.reference_id' => $from_reference_id,
                'Order_table.status IN'       => [2,4]
            ],
            'recursive' => -1
        ]);
    
        if (empty($fromtable)) {
            return json_encode(['status' => false, 'message' => 'From Table not available for Item Move']);
        }
        
        
        // Check if destination table is vacant (status=1)
        $toTableVacant = $this->Order_table->find('first', [
            'conditions' => [
                'Order_table.reference_id' => $to_reference_id,
                'Order_table.status'       => 1
            ],
            'recursive' => -1
        ]);

        if (!empty($toTableVacant)) {
            $this->Order_table->updateAll(
                [
                    'Order_table.customer_name'    => "'{$fromtable['Order_table']['customer_name']}'",
                    'Order_table.customer_phone'   => "'{$fromtable['Order_table']['customer_phone']}'",
                    'Order_table.customer_address' => "'{$fromtable['Order_table']['customer_address']}'",
                    'Order_table.customer_pax'     => "'{$fromtable['Order_table']['customer_pax']}'",
                    'Order_table.status'           => 2,
                    'Order_table.modified'         => "'" . date('Y-m-d H:i:s') . "'"
                ],
                [
                    'Order_table.reference_id' => $to_reference_id,
                    'Order_table.status'       => 1
                ]
            );
        }
    
        $totable = $this->Order_table->find('first', [
            'conditions' => [
                'Order_table.reference_id' => $to_reference_id,
                'Order_table.status IN'       => [2,4]
            ],
            'recursive' => -1
        ]);
    
        if (empty($totable)) {
            return json_encode(['status' => false, 'message' => 'To Table not available for Item Receive']);
        }
    
        // ---------------------------
        // Decode JSON
        // ---------------------------
        $json = json_decode($_REQUEST['data'] ?? '', true);
    
        if ($json === null) {
            return json_encode(['status' => false, 'message' => 'Invalid JSON']);
        }
    
        if (empty($json['order_ids']) || !is_array($json['order_ids'])) {
            return json_encode(['status' => false, 'message' => 'Invalid JSON structure: order_ids missing']);
        }
    
        // ---------------------------
        // Process Items (STOP on ANY ERROR)
        // ---------------------------
        $updated = false;
        $to_table_number = $totable['Order_table']['number'];
    
        foreach ($json['order_ids'] as $item) {
    
            // ❌ If order_id missing → STOP
            if (empty($item['order_id'])) {
                return json_encode(['status' => false, 'message' => 'Order ID missing in request']);
            }
    
            $order_id = (int)$item['order_id'];
    
            // Fetch order at from table
            $order = $this->Order_orderhistory->find('first', [
                'conditions' => [
                    'Order_orderhistory.id'            => $order_id,
                    'Order_orderhistory.reference_id'  => $from_reference_id,
                    'Order_orderhistory.status !='     => 0
                ],
                'recursive' => -1
            ]);
    
            // ❌ If order not found → STOP
            if (empty($order)) {
                return json_encode(['status' => false, 'message' => 'Item not available for movement']);
            }
    
            // Move TAX records
            $this->Order_tax->updateAll(
                [
                    'Order_tax.reference_id' => "'$to_reference_id'",
                    'Order_tax.sync'            => 0,
                    'Order_tax.local_sync'      => 0
                ],
                [
                    'Order_tax.orderhistory_id' => $order_id,
                    'Order_tax.reference_id'    => $from_reference_id,
                    'Order_tax.status !='      => 0
                ]
            );
            
            $this->Kds_track->updateAll(
                array(
                    'Kds_track.order_reference_id' => "'$to_reference_id'",
                    'Kds_track.table_no' => "'$to_table_number'",
                    'Kds_track.sync' => 0,
                    'Kds_track.local_sync' => 0
                ),
                array(
                    'Kds_track.order_history_id' => (int)$order_id,
                    'Kds_track.order_reference_id' => $from_reference_id,
                    'Kds_track.status !=' => 0
                )
            );
            
            // Update modifier reference
            $this->Order_modifier->updateAll(
                array(
                    'Order_modifier.reference_id' => "'$to_reference_id'",
                    'Order_modifier.sync' => 0,
                    'Order_modifier.local_sync' => 0
                ),
                array(
                    'Order_modifier.orderhistory_id' => (int)$order_id,
                    'Order_modifier.reference_id' => $from_reference_id,
                    'Order_modifier.status !=' => 0
                )
            );
            
            // Move ORDER item
            $res = $this->Order_orderhistory->updateAll(
                [
                    'Order_orderhistory.reference_id' => "'$to_reference_id'",
                    'Order_orderhistory.table_number' => "'$to_table_number'",
                    'Order_orderhistory.sync'         => 0,
                    'Order_orderhistory.local_sync'   => 0
                ],
                [
                    'Order_orderhistory.id'           => $order_id,
                    'Order_orderhistory.reference_id' => $from_reference_id,
                    'Order_orderhistory.status !='   => 0
                ]
            );
    
            if ($res) {
                $updated = true;

                // Log user track for moved item
                $pName = $order['Order_orderhistory']['product_name'] ?? ('Product #' . $order['Order_orderhistory']['product_id']);
                $pQty = $order['Order_orderhistory']['quantity'] ?? 1;
                $kotNo = $order['Order_orderhistory']['kot_number'] ?? '';
                $fromTblNum = $fromtable['Order_table']['number'] ?? 'N/A';
                $locId = $totable['Order_table']['location_id'] ?? 0;
                $locName = $totable['Order_table']['location_name'] ?? '';

                $this->User_track->create();
                $this->User_track->save([
                    'reference_id'  => $from_reference_id,
                    'user_id'       => $cashierid,
                    'location_id'   => $locId,
                    'location_name' => $locName,
                    'type'          => 'item_move',
                    'remarks'       => "Item '{$pName}' (Qty: {$pQty}) moved from Table {$fromTblNum} to Table {$to_table_number}" . (!empty($kotNo) ? " (KOT #{$kotNo})" : ""),
                    'status'        => 1
                ]);

                $this->User_track->create();
                $this->User_track->save([
                    'reference_id'  => $to_reference_id,
                    'user_id'       => $cashierid,
                    'location_id'   => $locId,
                    'location_name' => $locName,
                    'type'          => 'item_received',
                    'remarks'       => "Item '{$pName}' (Qty: {$pQty}) received from Table {$fromTblNum}" . (!empty($kotNo) ? " (KOT #{$kotNo})" : ""),
                    'status'        => 1
                ]);
            }
        }
    
        // ---------------------------
        // Final Response
        // ---------------------------
        if ($updated) {
            return json_encode(['status' => true, 'message' => 'Item(s) moved successfully']);
        }
    
        return json_encode(['status' => false, 'message' => 'No items moved']);
    }
    
    public function bill_table_package_discount()
    {
        $response['status']= false;
        $response['message']= "fail";
        
        $cashierid = $_REQUEST['id'];
        $loyalty_flag = $_REQUEST['loyalty_flag'] ?? 1;
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id is Missing",
            );
            return json_encode($response);
        }
        $table_number = $_REQUEST['table_number'];
        if($table_number==''){
            $response =array(
                'status'=> false,
                'message'=> "Table Number is Missing",
            );
            return json_encode($response);
        }
        $table_referenceid = $_REQUEST['reference_id'];
        if($table_referenceid==''){
            $response =array(
                'status'=> false,
                'message'=> "Table refernce Id is Missing",
            );
            return json_encode($response);
        }
        
        $disc=$_REQUEST['discount'];
        $type = $_REQUEST['type'];
        $dish_type = $_REQUEST['kds'];
        $sc = $_REQUEST['service_charge'] ?? 0;
        
        if($disc==''){
            $response =array(
                'status'=> false,
                'message'=> "Discount Missing",
            );
            return json_encode($response);
        }
        
        if($type==''){
            $response =array(
                'status'=> false,
                'message'=> "Discount Type Missing",
            );
            return json_encode($response);
        }
        
        if($dish_type==''){
            $response =array(
                'status'=> false,
                'message'=> "Dish Type Missing",
            );
            return json_encode($response);
        }
        
        $device_id='';
        if(isset($_REQUEST['device_id'])){
            $device_id=$_REQUEST['device_id'];
        }
        $name='';
        if(isset($_REQUEST['name'])){
            $name=$_REQUEST['name'];
        }
        $phone='';
        if(isset($_REQUEST['phone'])){
            $phone=$_REQUEST['phone'];
        }
        $address='';
        if(isset($_REQUEST['address'])){
            $address=$_REQUEST['address'];
        }
        $pax=1;
        if(isset($_REQUEST['pax'])){
            $pax=$_REQUEST['pax'];
        }
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        else{
            $location_id = $users['User']['location_id'];
        }
            
        $tablechk = $this->Order_table->find('first', array('conditions'=>array('Order_table.reference_id'=>$table_referenceid,'Order_table.number'=>$table_number,'Order_table.status'=>2)));
        if(empty($tablechk))
        {
            $response =array(
                'status'=> false,
                'message'=> "Something went wrong for this table kindly check!!!",
            );
            return json_encode($response);
        }
        $waiter_id=$tablechk['Order_table']['waiter_id'];
        $waiter_name = $tablechk['Order_table']['waiter_name'];
        $pax = $tablechk['Order_table']['customer_pax'] ?? 1;
        $name    = trim($tablechk['Order_table']['customer_name']);
        $phone   = trim($tablechk['Order_table']['customer_phone']);
        $address = trim($tablechk['Order_table']['customer_address']);
        $is_takeaway = $tablechk['Order_table']['is_takeaway'];
        
        $customerchk = $this->Order_customers->find('first', [
            'conditions' => ['Order_customers.phone' => $phone,'Order_customers.status !=' => 0],
            'fields' => ['Order_customers.id'],
            'recursive' => -1
        ]);
    
        if (empty($customerchk)) {
            // Insert new customer
            $data = [
                'Order_customers' => [
                    'phone'   => $phone,
                    'name'    => $name,
                    'address' => $address
                ]
            ];
    
            if ($this->Order_customers->saveAll($data)) {
                
            } else {
                return json_encode([
                    'status' => false,
                    'message' => "Failed to save customer details."
                ]);
            }
        } else {
            // Customer already exists — optional: update their name/address if needed
            $this->Order_customers->id = $customerchk['Order_customers']['id'];
            $this->Order_customers->save([
                'name' => $name,
                'address' => $address
            ]);
    
        }
        
        $this->Order_table->updateAll(
            [
                // 'Order_table.waiter_id' => "'0'",
                // 'Order_table.waiter_name' => "''",
                // 'Order_table.customer_address' => "''",
                // 'Order_table.customer_phone' => "''",
                'Order_table.sync'              => 0,
                'Order_table.local_sync'        => 0
            ],
            ['Order_table.reference_id' => $table_referenceid]
        );
        
        $trxchck = $this->Order_transaction->find('first', array(
            'conditions' => array(
                'Order_transaction.reference_id' => $table_referenceid,
                'NOT' => array('Order_transaction.status' => array(3, 4, 0))
            )
        ));
        if(!empty($trxchck))
        {
            $response =array(
                'status'=> false,
                'message'=> "Reference Id already Exist",
            );
            return json_encode($response);
        }        
        
        $todayDate = date("Y-m-d");
        
        $refid = []; // T9-fix: no merged tables guard

        $mergetablecheck = $this->Order_table_tracking->find('all', [
            'conditions' => [
                'Order_table_tracking.main_table_ref_id' => $table_referenceid,
                'Order_table_tracking.status' => 1,
                "DATE(Order_table_tracking.created) =" => $todayDate
            ]
        ]);
        if (!empty($mergetablecheck)) {
            foreach ($mergetablecheck as $merge) {
                $refid[] = $merge['Order_table_tracking']['merged_table_ref_id']; 
            }
        }
        
        $refid = "'" . implode("','", $refid) . "'";
        
        $this->Order_orderhistory->query("
            UPDATE order_orderhistories o
            SET o.reference_id = '$table_referenceid',o.sync=0,o.local_sync=0
            WHERE o.reference_id IN ($refid)
        ");
        
        $this->Order_tax->query("
            UPDATE order_tax t
            SET t.reference_id = '$table_referenceid',t.sync=0,t.local_sync=0
            WHERE t.reference_id IN ($refid)
        ");
        
        //chk package value in table - item in ordergistory link quanti*package
        // Fetch all product_ids for the given reference_id
        // 1. Set package=1 for packaged items using JOIN (efficient)
        $this->Order_orderhistory->query("
            UPDATE order_orderhistories o
            JOIN catalog_package p ON o.product_id = p.main_product_id AND p.status = 1
            SET o.package = 1,o.sync=0,o.local_sync=0
            WHERE o.reference_id = '$table_referenceid' AND o.status != 0
        ");
        
        $this->Order_tax->query("
            UPDATE order_tax t
            JOIN catalog_package p ON t.product_id = p.main_product_id AND p.status = 1
            SET t.package = 1,t.sync=0,t.local_sync=0
            WHERE t.reference_id = '$table_referenceid' AND t.status = 1
        ");
        // 2. Get total packaged quantity
        $total_package = 0;
        $totalpackagechkorder = $this->Order_orderhistory->query("
            SELECT SUM(package) AS total_package
            FROM order_orderhistories 
            WHERE reference_id = '$table_referenceid' AND status != 0 AND package = 1
        ");
        $packagechngchk=false;
        if (!empty($totalpackagechkorder[0][0]['total_package'])) {
            
            $total_package = isset($totalpackagechkorder[0][0]['total_package']) 
                ? $totalpackagechkorder[0][0]['total_package'] 
                : 0;
                // 3. Non-package items and discount percentage logic
                $discount_percentage = 0;
                $nonpackagechkorder = $this->Order_orderhistory->query("
                    SELECT product_id, SUM(quantity) as order_quantity
                    FROM order_orderhistories 
                    WHERE reference_id = '$table_referenceid' AND status != 0 AND package = 0
                    GROUP BY product_id
                ");
                $discount_pro_array = []; // initialize
                foreach ($nonpackagechkorder as $row) {
                    $orderproduct_id = $row['order_orderhistories']['product_id'];
                    $orderproduct_quantity = $row[0]['order_quantity'];
                    
                    // 4. Find linked package quantity for this non-package item
                    $linkpackagechk = $this->Catalog_package->query("
                        SELECT SUM(link_quantity) AS link_qty,link_product_id
                        FROM catalog_package
                        WHERE link_product_id = '$orderproduct_id' AND status = 1
                        AND main_product_id IN (
                            SELECT product_id 
                            FROM order_orderhistories 
                            WHERE reference_id = '$table_referenceid' AND package = 1 AND status != 0
                        )
                    ");
                    
                    $link_package_item_quantity = 0;
                    if (!empty($linkpackagechk[0][0]['link_qty'])) {
                        $link_package_item_quantity = $linkpackagechk[0][0]['link_qty'];
                    }
                    
                    // 5. Calculate discount
                    if ($orderproduct_quantity <= $link_package_item_quantity) {
                        $discount_percentage = 100;
                    } elseif ($link_package_item_quantity > 0) {
                        $discount_percentage = round(($link_package_item_quantity * 100) / $orderproduct_quantity, 2);
                    } else {
                        $discount_percentage = 0;
                    }
                    
                    $orderdata = $this->ordercomputewithpackagediscount($table_referenceid, $cashierid,$orderproduct_id, $discount_percentage);
                    if($orderdata['status'])
                    {
                        $packagechngchk=true;
                    }
                }
            }

            //discount update in ordertax
            $orderss = $this->Order_orderhistory->query("SELECT sum(price) as price,sum(total_tax) as total_tax,sum(total_price) as total_price,sum(discount) as discount FROM `order_orderhistories` WHERE reference_id='$table_referenceid' and status!=0");
            if(!empty($orderss))
            {
                if($orderss[0][0]['total_price']<1){
                    $response =array(
                        'status'=> false,
                        'message'=> "There is no item to bill. Please Check..!",
                    );
                    return json_encode($response);
                }
                
                $todayDate = date("Y-m-d");
                $tdaytrx=$this->Order_transaction->query("SELECT COUNT(id) as tkn FROM `order_transactions` WHERE date(created)='$todayDate' and status=2");
                $token=$tdaytrx['0']['0']['tkn']+1;
                $currenttime=date("H:i:s");
                $updated_discount=0;
                $updated_tax=0;
                $updated_final_amount=0;
                if($packagechngchk){
                    $orderstaxdatas = $this->Order_tax->query("SELECT ot.product_id, SUM((ot.price * ot.quantity) * (ot.discount_percentage / 100)) AS discounted_total, SUM(((ot.price * ot.quantity) * (ot.discount_percentage / 100)) * (IFNULL(ooh.tax_percent, 0) / 100)) AS total_tax, SUM(((ot.price * ot.quantity) * (ot.discount_percentage / 100)) * (1 + (IFNULL(ooh.tax_percent, 0) / 100))) AS final_amount FROM order_tax ot LEFT JOIN ( SELECT product_id, SUM(total_tax_percentage) AS tax_percent FROM order_orderhistories WHERE reference_id = '$table_referenceid' AND status = 1 GROUP BY product_id ) ooh ON ooh.product_id = ot.product_id WHERE ot.reference_id = '$table_referenceid' AND ot.package = 0 AND ot.status = 1");
                    if(!empty($orderstaxdatas))
                    {
                        $updated_discount=$orderstaxdatas[0][0]['discounted_total'];
                        $updated_tax=$orderstaxdatas[0][0]['total_tax'];
                        $updated_final_amount=$orderstaxdatas[0][0]['final_amount'];
                    }
                }
                $grand_total = $orderss[0][0]['total_price'] + $orderss[0][0]['total_tax'];
                $net_total = $grand_total - $orderss[0][0]['discount'] - $updated_final_amount;
                
                $finalamount = round(($orderss[0][0]['total_price']+$orderss[0][0]['total_tax'])-$orderss[0][0]['discount']-$updated_final_amount);        // Rounded to nearest integer
                $roundfinalamount = round(($orderss[0][0]['total_price']+$orderss[0][0]['total_tax'])-$orderss[0][0]['discount']-$updated_final_amount,2); // Rounded to 2 decimal places
               
                $round_amount = $finalamount - $roundfinalamount;
                
                $datas['Order_transaction']=array(
                    'reference_id'=>$table_referenceid,
                    'device_id'=>$device_id,
                    'cashier_id'=>$cashierid,
                    'store_id'=>$location_id,
                    'price'=>round($orderss[0][0]['total_price']-$updated_discount,2),
                    'total_tax'=>round($orderss[0][0]['total_tax']-$updated_tax,2),
                    'discount'=>round($orderss[0][0]['discount'],2),
                    'discount_items'=>$dish_type,
                    'amount'=>round($finalamount,0),
                    'round'=>round($round_amount,2),
                    'name'=>$name,
                    'phone'=>$phone,
                    'address'=>$address,
                    'tokenno'=>$token,
                    'table_number'=>$table_number,
                    'pax'=>$pax,
                    'waiter_id'=>$waiter_id,
                    'waiter_name'=>$waiter_name,
                    'is_takeaway' => $is_takeaway,
                    'createtime'=>$currenttime,
                    'loyalty_flag'=>$loyalty_flag
                );
                if($this->Order_transaction->saveAll($datas['Order_transaction']))
                {
                    $this->Order_table->query("UPDATE order_tables SET status = 3,sync=0,local_sync=0 WHERE reference_id = '$table_referenceid' and status!=0");
                    $this->Order_table->query("UPDATE order_tables SET status = 1,sync=0,local_sync=0 WHERE reference_id IN ($refid)  and status!=0");
                    $this->Order_table_tracking->query("UPDATE order_table_tracking SET status = 0,sync=0,local_sync=0 WHERE merged_table_ref_id IN ($refid)");

                    if (!$this->bill_table_package_kds_discount($cashierid,$table_referenceid,$disc,$sc,$type,$dish_type)) {
                    
                        return json_encode([
                            'status'  => false,
                            'message' => "Discount not saved",
                        ]);
                    }
                    
                    $response['status']= true;
                    $response['message']= "Bill Generated Successfully..!";
                }else{
                    $response['status']= false;
                    $response['message']= "Transaction Data not saved Error:103";
                }
            }
        
        return json_encode($response);
    }
    
    public function bill_table_package_kds_discount($cashierid,$ref_id,$disc,$sc,$type,$dish_type)
    {
        $todayDate = date("Y-m-d");
        
        $discount_type_value=$disc;
        
        $retry = false;   // 🔒 prevents second retry in same execution

    
    
    
        if($type==0){
            if(!empty($disc)){
                $coup = $this->Coupon->find('first', [
                    'conditions'=>[
                        'Coupon.code'=>$disc,
                        'Coupon.expiry_date >='=>$todayDate,
                        'Coupon.status'=>1
                    ]
                ]);
    
                if(empty($coup)){
                    return json_encode([
                        'status'=> false,
                        'message'=> "Coupon not found Or Coupon Expired",
                    ]);
                }
    
                $disc=$coup['Coupon']['value'];
            }
            else{
                $disc=0;
            }
        }
    
        if($type==1){
            error_log('[DISCOUNT-DEBUG bill_table_package_discount] entering PERCENTAGE branch discount='.$disc);
            $disc=$disc;
        }
    
        if($type==2){
            error_log('[DISCOUNT-DEBUG bill_table_package_discount] entering FLAT branch flat_amount='.$disc);
    
            if($dish_type==='all'){
                $subtotals = $this->Order_orderhistory->query("
                    SELECT SUM(total_price) as subtotal 
                    FROM order_orderhistories 
                    WHERE status!=0 AND reference_id='$ref_id'
                ");
            }
            else{
                $subtotals = $this->Order_orderhistory->query("
                    SELECT SUM(total_price) as subtotal 
                    FROM order_orderhistories 
                    WHERE status!=0 AND reference_id='$ref_id' 
                    AND dish_type=$dish_type
                ");
            }
    
            if($subtotals){
                $subtotal = $subtotals[0][0]['subtotal'];
    
                if($subtotal){
                    $disc = (($disc * 100) / $subtotal);
                    error_log('[DISCOUNT-DEBUG bill_table_package_discount] FLAT->PCT conversion: flat_amount='.$discount_type_value.' subtotal(total_price)='.$subtotal.' converted_pct='.$disc);
                }
                else{
                    return json_encode([
                        'status'=> false,
                        'message'=> "Bill Not Found",
                    ]);
                }
            }
            else{
                return json_encode([
                    'status'=> false,
                    'message'=> "Bill Not Found",
                ]);
            }
        }
    
        if($disc > 99){
            return json_encode([
                'status'=> false,
                'message'=> "Discount is not more than 99%",
            ]);
        }
    
    
    
    
        if($dish_type!='all'){
            $kdschk = $this->Order_orderhistory->find('first', [
                'conditions' => [
                    'Order_orderhistory.reference_id' => $ref_id,
                    'Order_orderhistory.status !=' => 0,
                    'Order_orderhistory.dish_type'=>$dish_type
                ]
            ]);
        }
        else{
            $kdschk = $this->Order_orderhistory->find('first', [
                'conditions'=>[
                    'Order_orderhistory.reference_id'=>$ref_id,
                    'Order_orderhistory.status !='=>0
                ]
            ]);
        }
    
        if(empty($kdschk)){
            return json_encode([
                'status'=> false,
                'message'=> "No Item found for this KDS while applying discount.",
            ]);
        }
        
        $packagechk = $this->Order_orderhistory->find('first', [
            'conditions'=>[
                'Order_orderhistory.reference_id'=>$ref_id,
                'Order_orderhistory.package'=>1,
                'Order_orderhistory.status !='=>0
            ]
        ]);
    
        if(!empty($packagechk)){
            return json_encode([
                'status'=> false,
                'message'=> "You cannot merge Discount with package.",
            ]);
        }
    
        if($disc>=0){
            $checkdiscount=$this->Order_orderhistory->find('first',[
                'conditions'=>[
                    'Order_orderhistory.discount > '=>0,
                    'Order_orderhistory.cashier_id'=>$cashierid,
                    'Order_orderhistory.status'=>2,
                    'Order_orderhistory.reference_id'=>$ref_id
                ]
            ]);
    
            if(!empty($checkdiscount)){
                return json_encode([
                    'status'=> false,
                    'message'=> "Discount cannot merge with item level discount"
                ]);
            }
        }
        else{
            return json_encode([
                'status'=> false,
                'message'=> "Please check discount value"
            ]);
        }
        
        if($dish_type==='all'){
            error_log('[DISCOUNT-DEBUG BEFORE COMPUTE bill_table_package_discount] disc_pct='.$disc.' type='.$type.' sc='.$sc.' dish=all ref='.$ref_id);
            $orderdata=$this->ordercompute($ref_id,$cashierid,$sc,$disc);
        }else{
            $this->Order_tax->query("UPDATE order_tax SET discount_percentage='0',sync=0,local_sync=0 WHERE reference_id = '$ref_id'");
            error_log('[DISCOUNT-DEBUG BEFORE COMPUTE bill_table_package_discount] disc_pct='.$disc.' type='.$type.' sc='.$sc.' dish='.$dish_type.' ref='.$ref_id);
            $orderdata=$this->ordercomputewithkds($ref_id,$cashierid,$sc,$disc,$dish_type);
        }
    
        if($orderdata['status'])
        {
            $totalservicechg=$orderdata['totalservicechg'];
            $totalprice=$orderdata['totalprice'];
            $totaltax=$orderdata['totaltax'];
            $totaldiscount=$orderdata['totaldiscount'];
            $exactTotalAmount=(($totalprice+$totaltax+$totalservicechg)-$totaldiscount); //483
            $round2TotalAmount = round($exactTotalAmount, 2);   // 2 decimal value //
            $finalTotalAmount  = round($exactTotalAmount);      // nearest integer
            $roundOffAmount    = round($finalTotalAmount - $round2TotalAmount, 2);
    
            $createtime = date('H:i:s');
            error_log('[DISCOUNT-DEBUG AFTER COMPUTE bill_table_package_discount] subtotal='.$totalprice.' tax='.$totaltax.' servicecharge='.$totalservicechg.' discount='.$totaldiscount.' discount_type='.$type.' final_amount='.$finalTotalAmount);
            error_log('[DISCOUNT-DEBUG DB WRITE bill_table_package_discount] discount='.$totaldiscount.' discount_type='.$type.' discount_type_value='.$discount_type_value.' amount='.$finalTotalAmount.' price='.$totalprice.' tax='.$totaltax.' servicecharge='.$totalservicechg);
            
            $this->Order_transaction->query("
                UPDATE order_transactions 
                SET 
                    price = '$totalprice',
                    total_tax='$totaltax',
                    servicecharge='$totalservicechg',
                    discount='$totaldiscount',
                    discount_type='$type',
                    discount_type_value='$discount_type_value',
                    amount='$finalTotalAmount',
                    round='$roundOffAmount',
                    createtime='$createtime',sync=0,local_sync=0
                WHERE reference_id = '$ref_id' and status!=0
            ");
            
            if ($disc > 0 && $retry === false) {
                
                // Check if we already attempted safety net for this reference (prevents repeated attempts)
                $transactionCheck = $this->Order_transaction->find('first', array(
                    'conditions' => array(
                        'Order_transaction.reference_id' => $ref_id,
                        'Order_transaction.status' => 1,
                        'Order_transaction.discount >'   => 0
                    ),
                    'fields' => array('id')
                ));
                
                // Only run safety net if transaction has discount but we haven't marked it as processed
                // The transaction discount being set means the main flow completed
                if (!empty($transactionCheck)) {
                    
                    $ordertaxCheck = $this->Order_tax->find('count', array(
                        'conditions' => array(
                            'Order_tax.reference_id' => $ref_id,
                            'Order_tax.discount_percentage >' => 0,
                            'Order_tax.status' => 1
                        ),
                        'fields' => array('id')
                    ));
                    
                    if(!empty($ordertaxCheck==0)){

                        $retry = true;

                        if($dish_type==='all'){
                            $orderdata=$this->ordercompute($ref_id,$cashierid,$sc,$disc);
                        }else{
                            $this->Order_tax->query("UPDATE order_tax SET discount_percentage='0',sync=0,local_sync=0 WHERE reference_id = '$ref_id'");
                            $orderdata=$this->ordercomputewithkds($ref_id,$cashierid,$sc,$disc,$dish_type);
                        }
                    }
                }
            }
            
            return json_encode([
                'status'=> true,
                'message'=> "Saved",
            ]);
        }
        else{
            return json_encode([
                'status'=> false,
                'message'=> "Not Saved",
            ]);
        }
    }
    
    public function split_bill_table_package_discount()
    {
        $response['status']= false;
        $response['message']= "fail";
        
        $cashierid = $_REQUEST['id'];
        $loyalty_flag = $_REQUEST['loyalty_flag'] ?? 1;
        
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id is Missing",
            );
            return json_encode($response);
        }
        $table_number = $_REQUEST['table_number'];
        if($table_number==''){
            $response =array(
                'status'=> false,
                'message'=> "Table Number is Missing",
            );
            return json_encode($response);
        }
        $table_referenceid = $_REQUEST['reference_id'];
        if($table_referenceid==''){
            $response =array(
                'status'=> false,
                'message'=> "Table refernce Id is Missing",
            );
            return json_encode($response);
        }
        
        $disc=$_REQUEST['discount'];
        $type = $_REQUEST['type'];
        $dish_type = $_REQUEST['kds'];
        $sc = $_REQUEST['service_charge'] ?? 0;
        
        if($disc==''){
            return json_encode([
                'status'=> false,
                'message'=> "Discount Missing",
            ]);
        }
        
        if($disc>0){
            return json_encode([
                'status'=> false,
                'message'=> "This feature is not available after applying discount,Remove discount first.",
            ]);
        }
        
        if($type==''){
            return json_encode([
                'status'=> false,
                'message'=> "Discount Type Missing",
            ]);
        }
        
        if($dish_type==''){
            return json_encode([
                'status'=> false,
                'message'=> "Dish Type Missing",
            ]);
        }
        
        $device_id='';
        if(isset($_REQUEST['device_id'])){
            $device_id=$_REQUEST['device_id'];
        }
        $name='';
        if(isset($_REQUEST['name'])){
            $name=$_REQUEST['name'];
        }
        $phone='';
        if(isset($_REQUEST['phone'])){
            $phone=$_REQUEST['phone'];
        }
        $address='';
        if(isset($_REQUEST['address'])){
            $address=$_REQUEST['address'];
        }
        $pax=1;
        if(isset($_REQUEST['pax'])){
            $pax=$_REQUEST['pax'];
        }
        
        if (!isset($_REQUEST['data'])) {
            $response = array(
                'status' => false,
                'message' => "data not found",
            );
            return json_encode($response);
        }
        
        $data = json_decode($_REQUEST['data'], true);
        
        // Check if JSON is valid
        if ($data === null) {
            return json_encode([
                'status' => false,
                'message' => 'invalid json'
            ]);
        }
        
        // Validate required structure
        if (
            !isset($data['splits']) ||
            !is_array($data['splits']) ||
            count($data['splits']) == 0
        ) {
            return json_encode([
                'status' => false,
                'message' => 'invalid json structure: splits missing'
            ]);
        }
        
        foreach ($data['splits'] as $split) {
        
            // Check items key
            if (!isset($split['items']) || !is_array($split['items']) || count($split['items']) == 0) {
                return json_encode([
                    'status' => false,
                    'message' => 'invalid json structure: items missing'
                ]);
            }
        
            foreach ($split['items'] as $item) {
        
                if (
                    !isset($item['id']) ||
                    !isset($item['reference_id']) ||
                    !isset($item['quantity'])
                ) {
                    return json_encode([
                        'status' => false,
                        'message' => 'invalid json structure: item keys missing'
                    ]);
                }
            }
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        else{
            $location_id = $users['User']['location_id'];
        }
            
        $tablechk = $this->Order_table->find('first', array('conditions'=>array('Order_table.reference_id'=>$table_referenceid,'Order_table.number'=>$table_number,'Order_table.status'=>2)));
        if(empty($tablechk))
        {
            $response =array(
                'status'=> false,
                'message'=> "Something went wrong for this table kindly check!!!",
            );
            return json_encode($response);
        }
        
        $orderQtyRes = $this->Order_orderhistory->query("
            SELECT id, quantity, product_name, product_id
            FROM order_orderhistories
            WHERE reference_id = '$table_referenceid'
              AND status != 0
        ");
        $originalQty = [];
        $originalName = [];

        foreach ($orderQtyRes as $row) {
            $itemId = $row['order_orderhistories']['id'];
            $originalQty[$itemId] = (int)$row['order_orderhistories']['quantity'];
            $originalName[$itemId] = $row['order_orderhistories']['product_name'];

        }
        
        $splitQty = [];
        
        foreach ($data['splits'] as $split) {
            foreach ($split['items'] as $item) {
        
                $id = $item['id'];
                $qty = (int)$item['quantity'];
        
                if (!isset($splitQty[$id])) {
                    $splitQty[$id] = 0;
                }
        
                $splitQty[$id] += $qty;
            }
        }
        
        foreach ($originalQty as $itemId => $qtyFromOrder) {
        
            $qtyFromSplit = isset($splitQty[$itemId]) ? $splitQty[$itemId] : 0;
        
            if ($qtyFromSplit != $qtyFromOrder) {
                
                $itemName = isset($originalName[$itemId]) ? $originalName[$itemId] : 'Item #'.$itemId;

                return json_encode([
                    'status' => false,
                    'message' => "Invalid quantity for $itemName: Ordered $qtyFromOrder, Given $qtyFromSplit"
                ]);
            }
        }

        $waiter_id=$tablechk['Order_table']['waiter_id'];
        $waiter_name = $tablechk['Order_table']['waiter_name'];
        $pax = $tablechk['Order_table']['customer_pax'] ?? 1;
        $name    = trim($tablechk['Order_table']['customer_name']);
        $phone   = trim($tablechk['Order_table']['customer_phone']);
        $address = trim($tablechk['Order_table']['customer_address']);
        $is_takeaway = $tablechk['Order_table']['is_takeaway'];

        $customerchk = $this->Order_customers->find('first', [
            'conditions' => ['Order_customers.phone' => $phone,'Order_customers.status !=' => 0],
            'fields' => ['Order_customers.id'],
            'recursive' => -1
        ]);
    
        if (empty($customerchk)) {
            // Insert new customer
            $data = [
                'Order_customers' => [
                    'phone'   => $phone,
                    'name'    => $name,
                    'address' => $address
                ]
            ];
    
            if ($this->Order_customers->saveAll($data)) {
                
            } else {
                return json_encode([
                    'status' => false,
                    'message' => "Failed to save customer details."
                ]);
            }
        } else {
            // Customer already exists — optional: update their name/address if needed
            $this->Order_customers->id = $customerchk['Order_customers']['id'];
            $this->Order_customers->save([
                'name' => $name,
                'address' => $address
            ]);
    
        }
        
        $this->Order_table->updateAll(
            [
                // 'Order_table.waiter_id' => "'0'",
                // 'Order_table.waiter_name' => "''",
                // 'Order_table.customer_address' => "''",
                // 'Order_table.customer_phone' => "''",
                'Order_table.sync'              => 0,
                'Order_table.local_sync'        => 0
            ],
            ['Order_table.reference_id' => $table_referenceid]
        );
        
        $trxchck = $this->Order_transaction->find('first', array(
            'conditions' => array(
                'Order_transaction.reference_id' => $table_referenceid,
                'NOT' => array('Order_transaction.status' => array(3, 4, 0))
            )
        ));
        if(!empty($trxchck))
        {
            $response =array(
                'status'=> false,
                'message'=> "Reference Id already Exist",
            );
            return json_encode($response);
        }        
        
        $todayDate = date("Y-m-d");
        
        $refid = []; // T9-fix: no merged tables guard

        $mergetablecheck = $this->Order_table_tracking->find('all', [
            'conditions' => [
                'Order_table_tracking.main_table_ref_id' => $table_referenceid,
                'Order_table_tracking.status' => 1,
                "DATE(Order_table_tracking.created) =" => $todayDate
            ]
        ]);
        if (!empty($mergetablecheck)) {
            foreach ($mergetablecheck as $merge) {
                $refid[] = $merge['Order_table_tracking']['merged_table_ref_id']; 
            }
        }
        
        $refid = "'" . implode("','", $refid) . "'";
        
        $this->Order_orderhistory->query("
            UPDATE order_orderhistories o
            SET o.reference_id = '$table_referenceid',o.sync=0,o.local_sync=0
            WHERE o.reference_id IN ($refid)
        ");
        
        $this->Order_tax->query("
            UPDATE order_tax t
            SET t.reference_id = '$table_referenceid',t.sync=0,t.local_sync=0
            WHERE t.reference_id IN ($refid)
        ");
        
        //chk package value in table - item in ordergistory link quanti*package
        // Fetch all product_ids for the given reference_id
        // 1. Set package=1 for packaged items using JOIN (efficient)
        $this->Order_orderhistory->query("
            UPDATE order_orderhistories o
            JOIN catalog_package p ON o.product_id = p.main_product_id AND p.status = 1
            SET o.package = 1,o.sync=0,o.local_sync=0
            WHERE o.reference_id = '$table_referenceid' AND o.status != 0
        ");
        
        $this->Order_tax->query("
            UPDATE order_tax t
            JOIN catalog_package p ON t.product_id = p.main_product_id AND p.status = 1
            SET t.package = 1,t.sync=0,t.local_sync=0
            WHERE t.reference_id = '$table_referenceid' AND t.status = 1
        ");
        // 2. Get total packaged quantity
        $total_package = 0;
        $totalpackagechkorder = $this->Order_orderhistory->query("
            SELECT SUM(package) AS total_package
            FROM order_orderhistories 
            WHERE reference_id = '$table_referenceid' AND status != 0 AND package = 1
        ");
        $packagechngchk=false;
        if (!empty($totalpackagechkorder[0][0]['total_package'])) {
            
            $total_package = isset($totalpackagechkorder[0][0]['total_package']) 
                ? $totalpackagechkorder[0][0]['total_package'] 
                : 0;
                // 3. Non-package items and discount percentage logic
                $discount_percentage = 0;
                $nonpackagechkorder = $this->Order_orderhistory->query("
                    SELECT product_id, SUM(quantity) as order_quantity
                    FROM order_orderhistories 
                    WHERE reference_id = '$table_referenceid' AND status != 0 AND package = 0
                    GROUP BY product_id
                ");
                $discount_pro_array = []; // initialize
                foreach ($nonpackagechkorder as $row) {
                    $orderproduct_id = $row['order_orderhistories']['product_id'];
                    $orderproduct_quantity = $row[0]['order_quantity'];
                    
                    // 4. Find linked package quantity for this non-package item
                    $linkpackagechk = $this->Catalog_package->query("
                        SELECT SUM(link_quantity) AS link_qty,link_product_id
                        FROM catalog_package
                        WHERE link_product_id = '$orderproduct_id' AND status = 1
                        AND main_product_id IN (
                            SELECT product_id 
                            FROM order_orderhistories 
                            WHERE reference_id = '$table_referenceid' AND package = 1 AND status != 0
                        )
                    ");
                    
                    $link_package_item_quantity = 0;
                    if (!empty($linkpackagechk[0][0]['link_qty'])) {
                        $link_package_item_quantity = $linkpackagechk[0][0]['link_qty'];
                    }
                    
                    // 5. Calculate discount
                    if ($orderproduct_quantity <= $link_package_item_quantity) {
                        $discount_percentage = 100;
                    } elseif ($link_package_item_quantity > 0) {
                        $discount_percentage = round(($link_package_item_quantity * 100) / $orderproduct_quantity, 2);
                    } else {
                        $discount_percentage = 0;
                    }
                
                    $orderdata = $this->ordercomputewithpackagediscount($table_referenceid, $cashierid,$orderproduct_id, $discount_percentage);
                    if($orderdata['status'])
                    {
                        $packagechngchk=true;
                    }
                }
            }

            //discount update in ordertax
            $orderss = $this->Order_orderhistory->query("SELECT sum(price) as price,sum(total_tax) as total_tax,sum(total_price) as total_price,sum(discount) as discount FROM `order_orderhistories` WHERE reference_id='$table_referenceid' and status!=0");
            if(!empty($orderss))
            {
                if($orderss[0][0]['total_price']<1){
                    $response =array(
                        'status'=> false,
                        'message'=> "There is no item to bill. Please Check..!",
                    );
                    return json_encode($response);
                }
                
                $todayDate = date("Y-m-d");
                $tdaytrx=$this->Order_transaction->query("SELECT COUNT(id) as tkn FROM `order_transactions` WHERE date(created)='$todayDate' and status=2");
                $token=$tdaytrx['0']['0']['tkn']+1;
                $currenttime=date("H:i:s");
                $updated_discount=0;
                $updated_tax=0;
                $updated_final_amount=0;
                if($packagechngchk){
                    $orderstaxdatas = $this->Order_tax->query("SELECT ot.product_id, SUM((ot.price * ot.quantity) * (ot.discount_percentage / 100)) AS discounted_total, SUM(((ot.price * ot.quantity) * (ot.discount_percentage / 100)) * (IFNULL(ooh.tax_percent, 0) / 100)) AS total_tax, SUM(((ot.price * ot.quantity) * (ot.discount_percentage / 100)) * (1 + (IFNULL(ooh.tax_percent, 0) / 100))) AS final_amount FROM order_tax ot LEFT JOIN ( SELECT product_id, SUM(total_tax_percentage) AS tax_percent FROM order_orderhistories WHERE reference_id = '$table_referenceid' AND status = 1 GROUP BY product_id ) ooh ON ooh.product_id = ot.product_id WHERE ot.reference_id = '$table_referenceid' AND ot.package = 0 AND ot.status = 1");
                    if(!empty($orderstaxdatas))
                    {
                        $updated_discount=$orderstaxdatas[0][0]['discounted_total'];
                        $updated_tax=$orderstaxdatas[0][0]['total_tax'];
                        $updated_final_amount=$orderstaxdatas[0][0]['final_amount'];
                    }
                }
                $grand_total = $orderss[0][0]['total_price'] + $orderss[0][0]['total_tax'];
                $net_total = $grand_total - $orderss[0][0]['discount'] - $updated_final_amount;
                
                $finalamount = round(($orderss[0][0]['total_price']+$orderss[0][0]['total_tax'])-$orderss[0][0]['discount']-$updated_final_amount);        // Rounded to nearest integer
                $roundfinalamount = round(($orderss[0][0]['total_price']+$orderss[0][0]['total_tax'])-$orderss[0][0]['discount']-$updated_final_amount,2); // Rounded to 2 decimal places
                
                $round_amount = $finalamount - $roundfinalamount;
                $split_count = count($data['splits']);
                
                $is_split=1;
                if($split_count==1){
                    $split_count=0;
                    $is_split=0;
                }
                
                $this->Order_transaction->begin();
                
                try {
                
                    // =========================================================
                    // 1. SAVE ALL SPLIT DETAILS (orderhistory + tax + split tx)
                    // =========================================================
                    
                    $series_id=sprintf("%02d", $cashierid);
                    $users=$this->User->find('first',array('conditions'=>array('id'=>$cashierid)));
                    $series=strtoupper(substr($users['User']['username'],0,2)); 

                    $ordertrx=$this->Order_transaction->query("SELECT orderno,split_count FROM `order_transactions` order by id desc limit 1");
                    
                    if($ordertrx[0]['order_transactions']['split_count']>1){
                     $last_split_count=$ordertrx[0]['order_transactions']['split_count']-1;
                    }else{
                     $last_split_count=0;
                    }
                     
                    $ordernewstring = substr($ordertrx[0]['order_transactions']['orderno'], -8) + $last_split_count;
                    $ordernonewno=$ordernewstring+1;
                    
                    foreach ($data['splits'] as $block) {
                
                        $refId = null;
                        $blockAmount = 0;   // initialize
                        $blockTax    = 0;   // initialize
                        $blockprice  = 0;
                        
                        do {
                            $pin = 'TX' . $cashierid . date('Y') . uniqid();
                        } while ($this->Order_transaction->find('first', array('fields' => 'Order_transaction.id', 'conditions' => array('Order_transaction.reference_id' => $pin))));
                        
                        foreach ($block['items'] as $item) {
                
                            $orderId = $item['id'];
                            $refId   = $item['reference_id'];
                            $qty     = (int)$item['quantity'];
                
                            // ------------------------------------------
                            // FETCH ORIGINAL ORDERHISTORY
                            // ------------------------------------------
                            $original = $this->Order_orderhistory->find('first', [
                                'conditions' => [
                                    'Order_orderhistory.id' => $orderId,
                                    'Order_orderhistory.reference_id' => $refId,
                                    'Order_orderhistory.status !=' => 0
                                ]
                            ]);
                
                            if (empty($original)) {
                                throw new Exception("Original orderhistory not found: ID $orderId");
                            }
                
                            // prepare new row
                            $new = $original['Order_orderhistory'];
                            
                            $new['order_history_id'] = $new['id'];
                            unset($new['id']);
                            
                            $new['quantity'] = $qty;
                
                            // recalc
                            $new['total_tax']   = (($new['price'] * $qty) * $new['total_tax_percentage']) / 100;
                            $new['total_price'] = ($new['price'] * $qty);
                            
                            $new['split_reference_id'] = $pin;
                        
                            // SAVE split orderhistory
                            $this->Order_split_orderhistory->create();
                            if (!$this->Order_split_orderhistory->save($new)) {
                                throw new Exception("Failed saving Order_split_orderhistory");
                            }
                
                            // accumulate split totals
                            $blockprice += $new['price'];
                            $blockAmount += $new['price'] * $qty;
                            $blockTax    += $new['total_tax'];
                
                        } // end items loop
                
                        // =========================================================
                        // 2. SAVE SPLIT TRANSACTION FOR THIS BLOCK
                        // =========================================================
                
                        $tx = [];
                        $tx['split_reference_id'] = $pin;
                        
                        $tx['reference_id'] = $refId;
                        $tx['store_id']     = $location_id;
                        $tx['device_id']    = $device_id;
                        $tx['cashier_id']   = $cashierid;
                        $tx['waiter_id']    = $waiter_id;
                        $tx['waiter_name']  = $waiter_name;
                        $tx['name']         = $name;
                        $tx['phone']        = $phone;
                        $tx['address']      = $address;
                
                        $tx['table_number'] = $table_number;
                        
                        
                        $tx['price']        = round($blockAmount, 2);
                        $tx['total_tax']    = round($blockTax, 2);
                
                        $splitExactAmount = ($blockAmount + $blockTax);          // exact value
                        $splitRound2      = round($splitExactAmount, 2);         // 2 decimals
                        $splitFinalAmount = round($splitExactAmount);            // nearest integer
                        $splitRoundOff    = round($splitFinalAmount - $splitRound2, 2); // round diff
                        
                        $tx['amount']    = round($splitFinalAmount,0);   // integer payable
                        $tx['round']     = $splitRoundOff;       // round-off value

                        $tx['is_split']     = 1;
                        $tx['createtime']   = $currenttime;
                        
                        $GOrder = sprintf("%08d", $ordernonewno);
                        $orderNumber = $series_id."".$series.date('Y').$GOrder;     

                        $tx['orderno']   = $orderNumber;
                        
                        $tx['createtime']   = $currenttime;
                        $tx['loyalty_flag']   = $loyalty_flag;
                        
                        $this->Order_split_transaction->create();
                        if (!$this->Order_split_transaction->save($tx)) {
                            throw new Exception("Failed saving split transaction");
                        }
                    
                        $ordernonewno++;
                    
                    } // end block loop
                
                    // =========================================================
                    // 3. SAVE MAIN / FINAL ORDER_TRANSACTION
                    // =========================================================
                    $datas['Order_transaction']=array(
                        'reference_id'=>$table_referenceid,
                        'device_id'=>$device_id,
                        'cashier_id'=>$cashierid,
                        'store_id'=>$location_id,
                        'price'=>round($orderss[0][0]['total_price']-$updated_discount,2),
                        'total_tax'=>round($orderss[0][0]['total_tax']-$updated_tax,2),
                        'discount'=>round($orderss[0][0]['discount'],2),
                        'discount_items'=>$dish_type,
                        'amount'=>round($finalamount,0),
                        'round'=>round($round_amount,2),
                        'name'=>$name,
                        'phone'=>$phone,
                        'address'=>$address,
                        'tokenno'=>$token,
                        'table_number'=>$table_number,
                        'pax'=>$pax,
                        'waiter_id'=>$waiter_id,
                        'waiter_name'=>$waiter_name,
                        'is_takeaway' => $is_takeaway,
                        'createtime'=>$currenttime,
                        'is_split' => $is_split,
                        'split_count' => $split_count,
                        'split_type' => 'item',
                        'loyalty_flag' => $loyalty_flag
                    );
                
                    if (!$this->Order_transaction->save($datas['Order_transaction'])) {
                        throw new Exception("Failed to save final Order_transaction");
                    }
                
                    // =========================================================
                    // 4. UPDATE TABLES (ONLY IF EVERYTHING ABOVE SUCCESS)
                    // =========================================================
                
                    $this->Order_table->query("
                        UPDATE order_tables SET status = 3 ,sync=0,local_sync=0
                        WHERE reference_id = '$table_referenceid' AND status != 0
                    ");
                
                    $this->Order_table->query("
                        UPDATE order_tables SET status = 1,sync=0,local_sync=0 
                        WHERE reference_id IN ($refid) AND status != 0
                    ");
                
                    $this->Order_table_tracking->query("
                        UPDATE order_table_tracking SET status = 0,sync=0,local_sync=0
                        WHERE merged_table_ref_id IN ($refid)
                    ");
                
                    // COMMIT ALL
                    $this->Order_transaction->commit();
                    
                    if($disc>=0){
                        if (!$this->bill_table_package_kds_discount($cashierid,$table_referenceid,$disc,$sc,$type,$dish_type)) {
                        
                            return json_encode([
                                'status'  => false,
                                'message' => "Main Discount not saved",
                            ]);
                        }
                        
                        //Split
                        $splittransactions = $this->Order_split_transaction->find('all', [
                            'fields' => [
                                'Order_split_transaction.*'
                            ],
                            'conditions' => [
                                'Order_split_transaction.reference_id' => $table_referenceid,
                                'Order_split_transaction.status !=' => 0
                            ]
                        ]);
                    
                        if (!empty($splittransactions)) {
                    
                            foreach ($splittransactions as $split) {
                                
                                $split_reference_id=$split['Order_split_transaction']['split_reference_id'];
                            
                                $this->split_bill_table_package_kds_discount($cashierid,$table_referenceid,$split_reference_id,$disc,$sc,$type,$dish_type);
                                
                            }
                        }
                    }
                    
                    return json_encode([
                        'status' => true,
                        'message' => 'Split saved and final transaction saved successfully'
                    ]);
                
                } catch (Exception $e) {
                
                    $this->Order_transaction->rollback();
                
                    return json_encode([
                        'status' => false,
                        'message' => $e->getMessage()
                    ]);
                }
            }
        
        return json_encode($response);
    }
    
    public function split_bill_table_package_kds_discount($cashierid,$ref_id,$split_reference_id,$disc,$sc,$type,$dish_type)
    {
        $todayDate = date("Y-m-d");
    
    
    
        $disc_original_active = $disc; // capture before any type conversion
        
        if($type==0){
            if(!empty($disc)){
                $coup = $this->Coupon->find('first', [
                    'conditions'=>[
                        'Coupon.code'=>$disc,
                        'Coupon.expiry_date >='=>$todayDate,
                        'Coupon.status'=>1
                    ]
                ]);
    
                if(empty($coup)){
                }
    
                $disc=$coup['Coupon']['value'];
            }
            else{
                $disc=0;
            }
        }
    
        if($type==1){
            $disc=$disc;
        }
        
        
        if($type==2){

            // Use this split's own subtotal so the full flat amount is applied
            $splitsubtotals = $this->Order_split_orderhistory->query("
                SELECT SUM(total_price) as subtotal
                FROM order_split_orderhistories
                WHERE status!=0
                  AND reference_id='$ref_id'
                  AND split_reference_id='$split_reference_id'
            ");

            if(!empty($splitsubtotals[0][0]['subtotal'])){

                $splitSubtotal = $splitsubtotals[0][0]['subtotal'];

                if($splitSubtotal > 0){
                    if($disc >= $splitSubtotal){
                        return json_encode([
                            'status'  => false,
                            'message' => "Flat discount cannot exceed or equal the split bill total",
                        ]);
                    }
                    // convert flat amount to percentage against this split only
                    $disc = ($disc * 100) / $splitSubtotal;
                }else{
                    return json_encode([
                        'status'=> false,
                        'message'=> "Bill Not Found",
                    ]);
                }

            }else{
                return json_encode([
                    'status'=> false,
                    'message'=> "Bill Not Found",
                ]);
            }
        }

        if($disc > 99){
        }
    
        if($dish_type!='all'){
            $kdsStoreId = '';
            if (!empty($cashierid)) {
                $cashierUser = $this->User->find('first', [
                    'conditions' => ['User.id' => $cashierid, 'User.status' => 1],
                    'fields' => ['location_id'],
                    'recursive' => -1
                ]);
                $kdsStoreId = !empty($cashierUser['User']['location_id']) ? $cashierUser['User']['location_id'] : '';
            }
            $kdsarray = explode(",", $dish_type);
            $kdsConditions = ['Pos_printer.kds' => $kdsarray, 'Pos_printer.status' => 1];
            if (!empty($kdsStoreId)) {
                $kdsConditions['Pos_printer.store_id'] = $kdsStoreId;
            }
            $kdschk = $this->Pos_printer->find('first', [
                'conditions' => $kdsConditions
            ]);
            if (empty($kdschk) && !empty($kdsStoreId)) {
                $kdschk = $this->Pos_printer->find('first', [
                    'conditions' => ['Pos_printer.kds' => $kdsarray, 'Pos_printer.status' => 1]
                ]);
            }
            if (empty($kdschk)) {
                return json_encode([
                    'status' => false,
                    'message' => "KDS not found",
                ]);
            }
        }
       
        if($dish_type!='all'){
            $kdschk = $this->Order_split_orderhistory->find('first', [
                'conditions'=>[
                    'Order_split_orderhistory.reference_id'=>$ref_id,
                    'Order_split_orderhistory.split_reference_id'=>$split_reference_id,
                    'Order_split_orderhistory.dish_type'=>$dish_type,
                    'Order_split_orderhistory.status !='=>0
                ],
                'recursive' => -1
            ]);
        }
        else{
            $kdschk = $this->Order_split_orderhistory->find('first', [
                'conditions'=>[
                    'Order_split_orderhistory.reference_id'=>$ref_id,
                    'Order_split_orderhistory.split_reference_id'=>$split_reference_id,
                    'Order_split_orderhistory.status !='=>0
                ],
                'recursive' => -1
            ]);
        }
    
        if(empty($kdschk)){
            // return json_encode([
            //     'status'=> false,
            //     'message'=> "No Item found for this KDS while applying discount.",
            // ]);
        }
    
    
        $packagechk = $this->Order_split_orderhistory->find('first', [
            'conditions' => [
                'Order_split_orderhistory.reference_id'       => $ref_id,
                'Order_split_orderhistory.split_reference_id' => $split_reference_id,
                'Order_split_orderhistory.package'            => 1,
                'Order_split_orderhistory.status >'           => 0
            ],
            'recursive' => -1
        ]);

        if(!empty($packagechk)){
        }
     
        if($disc>=0){
            $checkdiscount=$this->Order_split_orderhistory->find('first',[
                'conditions'=>[
                    'Order_split_orderhistory.discount > '=>0,
                    'Order_split_orderhistory.cashier_id'=>$cashierid,
                    'Order_split_orderhistory.status'=>2,
                    'Order_split_orderhistory.reference_id'=>$ref_id,
                    'Order_split_orderhistory.split_reference_id'=>$split_reference_id
                ],
                'recursive' => -1
            ]);
    
            if(!empty($checkdiscount)){
            }
        }
        else{
        }
        
        if($dish_type=='all'){
            $orderdata=$this->split_ordercompute($ref_id,$split_reference_id,$cashierid,$sc,$disc);
        }else{
            $orderdata=$this->split_ordercomputewithkds($ref_id,$split_reference_id,$cashierid,$sc,$disc,$dish_type);
        }
        
        if($orderdata['status'])
        {
            $totalservicechg=$orderdata['totalservicechg'];
            $totalprice=$orderdata['totalprice'];
            $totaltax=$orderdata['totaltax'];
            $totaldiscount=$orderdata['totaldiscount'];
            $exactTotalAmount = (($totalprice + $totaltax + $totalservicechg) - $totaldiscount);

            $round2TotalAmount = round($exactTotalAmount, 2);   // 2 decimal value
            $finalTotalAmount  = round($exactTotalAmount);      // nearest integer
            $roundOffAmount    = round($finalTotalAmount - $round2TotalAmount, 2);
            
            $createtime = date('H:i:s');
    
            $this->Order_split_transaction->query("
                UPDATE order_split_transactions 
                SET 
                    price = '$totalprice',
                    total_tax='$totaltax',
                    servicecharge='$totalservicechg',
                    discount='$totaldiscount',
                    discount_type='$type',
                    discount_type_value='$disc_original_active',
                    discount_items='$dish_type',
                    amount='$finalTotalAmount',
                    round='$roundOffAmount',
                    createtime='$createtime',sync=0,local_sync=0
                WHERE reference_id = '$ref_id' and split_reference_id='$split_reference_id' and status!=0
            ");
            
            // return json_encode([
            //     'status'=> true,
            //     'message'=> "Saved",
            // ]);
        }
        else{
            // return json_encode([
            //     'status'=> false,
            //     'message'=> "Not Saved",
            // ]);
        }
    }
    
    public function split_ordercompute($txnid=null,$split_reference_id=null,$user_id=null,$is_sc=1,$discount=0)
    {
        $response['status']=false;
        $totalservicechg=0;
        $totalprice=0;
        $totaltax1=0;
        $totaltax2=0;
        $totaldiscount=0;
        $sc=0;
        if($is_sc==1){
            $locIdForSc = $this->resolveLocationIdForTxn($txnid, $user_id);
            $sc = $this->getLocationServiceChargeRate($locIdForSc);
        }
        $this->Order_split_orderhistory->virtualFields = [];

        $discq="(((Order_split_orderhistory.total_price)-(Order_split_orderhistory.discount))*$discount/100)";
        $priceq="((Order_split_orderhistory.total_price)-(Order_split_orderhistory.discount))";
    
        $this->Order_split_orderhistory->virtualFields = array('tdisc'=>"SUM($discq)",'tservicechg'=>"SUM(($priceq-$discq)*($sc/100))",'tprice'=>"SUM($priceq)",'total_tax'=>"SUM(($priceq+(($priceq-$discq)*($sc/100))-$discq)*((Order_split_orderhistory.total_tax_percentage)/100))");  
        
        $orderhistories = $this->Order_split_orderhistory->find('first', [
            'conditions' => [
                'Order_split_orderhistory.reference_id'       => $txnid,
                'Order_split_orderhistory.split_reference_id' => $split_reference_id,
                'Order_split_orderhistory.status !='          => 0
            ],
            'fields' => [
                'tdisc',
                'Order_split_orderhistory.reference_id',
                'tprice',
                'total_tax',
                'tservicechg'
            ],
            'recursive' => -1
        ]);

        if(!empty($orderhistories['Order_split_orderhistory']['reference_id'])){
            $response['status']=true;
            $totalservicechg=round($orderhistories['Order_split_orderhistory']['tservicechg'],2);
            $totalprice=round($orderhistories['Order_split_orderhistory']['tprice'],2);
            $totaltax=round($orderhistories['Order_split_orderhistory']['total_tax'],2);
            $totaldiscount=round($orderhistories['Order_split_orderhistory']['tdisc'],2);
            
            $response['totalservicechg']=$totalservicechg;
            $response['totalprice']=$totalprice;
            $response['totaltax']=$totaltax;
            $response['totaldiscount']=$totaldiscount;
            
            
            // Now update order_tax for each item, just like ordercompute() does
            $itemDiscq = "((Order_split_orderhistory.price - Order_split_orderhistory.discount) * $discount / 100)";
            $itemPriceq = "(Order_split_orderhistory.price - Order_split_orderhistory.discount)";
            $itemScq = "(($itemPriceq - $itemDiscq) * $sc / 100)";
            $itemTamountq = "($itemPriceq - $itemDiscq + $itemScq)";
            
            $this->Order_split_orderhistory->virtualFields = [
                'tamount' => $itemTamountq
            ];
            
            $items = $this->Order_split_orderhistory->find('all', [
                'conditions' => [
                    'Order_split_orderhistory.reference_id'       => $txnid,
                    'Order_split_orderhistory.split_reference_id' => $split_reference_id,
                    'Order_split_orderhistory.status !='          => 0
                ],
                'fields' => ['id', 'order_history_id', 'product_id', 'quantity', 'price', 'tamount'],
                'recursive' => -1
            ]);
            
            foreach ($items as $row) {
                $orderhistory_id = $row['Order_split_orderhistory']['order_history_id'];
                $product_id = $row['Order_split_orderhistory']['product_id'];
                $tamount = round($row['Order_split_orderhistory']['tamount'], 2);
                
                $taxItems = $this->Order_tax->find('all', [
                    'conditions' => [
                        'Order_tax.reference_id'     => $txnid,
                        'Order_tax.orderhistory_id' => $orderhistory_id,
                        'Order_tax.product_id'      => $product_id,
                        'Order_tax.status !='       => 0
                    ],
                    'recursive' => -1
                ]);
                
                foreach ($taxItems as $taxRow) {
                    $tax = $taxRow['Order_tax'];
                    $taxable_price = round($tamount * $tax['quantity'], 2);
                    $tax_value = round(($taxable_price * $tax['tax_percentage']) / 100, 2);
                    
                    try {
                        $this->Order_tax->updateAll(
                            [
                                'Order_tax.taxable_price'       => $taxable_price,
                                'Order_tax.tax_value'           => $tax_value,
                                'Order_tax.discount_percentage' => $discount,
                                'Order_tax.sync'                => 0,
                                'Order_tax.local_sync'          => 0
                            ],
                            [
                                'Order_tax.id' => $tax['id']
                            ]
                        );
                        
                        $db = $this->Order_tax->getDataSource();
                        if ($db->lastError()) {
                            $this->trackUser($txnid, $user_id, 'order_tax_update_sql_error', [
                                'tax_id' => $tax['id'],
                                'error'  => $db->lastError()
                            ]);
                        }
                    } catch (Exception $e) {
                        $this->trackUser($txnid, $user_id, 'order_tax_update_exception', [
                            'tax_id' => $tax['id'],
                            'error'  => $e->getMessage()
                        ]);
                    }
                }
            }

        }
        return $response;
    }
    
    public function split_ordercomputewithkds(
        $txnid = null,
        $split_reference_id = null,
        $user_id = null,
        $is_sc = 1,
        $discount = 0,
        $dish_type = 0
    ){
        $response = ['status' => false];
    
        if (empty($txnid) || empty($split_reference_id)) {
            return $response;
        }
    
        $sc = 0;
        if ($is_sc == 1) {
            $locIdForSc = $this->resolveLocationIdForTxn($txnid, $user_id);
            $sc = $this->getLocationServiceChargeRate($locIdForSc);
        }
        $kds = (int)$dish_type;
    
        // --------------------------------------------------
        // STEP 1 : FETCH ALL SPLIT ITEMS
        // --------------------------------------------------
        $items = $this->Order_split_orderhistory->find('all', [
            'conditions' => [
                'Order_split_orderhistory.reference_id'       => $txnid,
                'Order_split_orderhistory.split_reference_id' => $split_reference_id,
                'Order_split_orderhistory.status !='          => 0
            ],
            'fields' => [
                'id',
                'order_history_id',
                'product_id',
                'dish_type',
                'price',
                'quantity',
                'discount',
                'total_tax_percentage'
            ],
            'recursive' => -1
        ]);
    
        if (empty($items)) {
            return $response;
        }
    
        // --------------------------------------------------
        // STEP 2 : CALCULATE TOTALS (same as main function)
        // --------------------------------------------------
        $totalprice = 0;
        $totaldiscount = 0;
        $totalservicechg = 0;
        $totaltax = 0;
    
        foreach ($items as $row) {
    
            $item = $row['Order_split_orderhistory'];
    
            $basePrice = ($item['price'] * $item['quantity']) - $item['discount'];
    
            // discount only for matching dish_type
            $applyDiscount = ($item['dish_type'] == $kds);
    
            $itemDiscount = $applyDiscount
                ? ($basePrice * $discount) / 100
                : 0;
    
            $priceAfterDiscount = $basePrice - $itemDiscount;
    
            $serviceCharge = ($priceAfterDiscount * $sc) / 100;
    
            $taxableAmount = $priceAfterDiscount + $serviceCharge;
    
            $taxValue = ($taxableAmount * $item['total_tax_percentage']) / 100;
    
            $totalprice      += $basePrice;
            $totaldiscount   += $itemDiscount;
            $totalservicechg += $serviceCharge;
            $totaltax        += $taxValue;
            
                        
            // Now update order_tax for this item, just like ordercompute() does
            $orderhistory_id = $item['order_history_id'];
            $product_id = $item['product_id'];
            $perItemPrice = $item['price'] - $item['discount'];
            $perItemDiscount = $applyDiscount ? ($perItemPrice * $discount / 100) : 0;
            $perItemAfterDiscount = $perItemPrice - $perItemDiscount;
            $perItemServiceCharge = ($perItemAfterDiscount * $sc) / 100;
            $perItemTamount = $perItemAfterDiscount + $perItemServiceCharge;
            $tamount = round($perItemTamount, 2);
            
            $taxItems = $this->Order_tax->find('all', [
                'conditions' => [
                    'Order_tax.reference_id'     => $txnid,
                    'Order_tax.orderhistory_id' => $orderhistory_id,
                    'Order_tax.product_id'      => $product_id,
                    'Order_tax.status !='       => 0
                ],
                'recursive' => -1
            ]);
            
            foreach ($taxItems as $taxRow) {
                $tax = $taxRow['Order_tax'];
                $taxable_price = round($tamount * $tax['quantity'], 2);
                $new_tax_value = round(($taxable_price * $tax['tax_percentage']) / 100, 2);
                
                try {
                    $this->Order_tax->updateAll(
                        [
                            'Order_tax.taxable_price'       => $taxable_price,
                            'Order_tax.tax_value'           => $new_tax_value,
                            'Order_tax.discount_percentage' => $applyDiscount ? $discount : 0,
                            'Order_tax.sync'                => 0,
                            'Order_tax.local_sync'          => 0
                        ],
                        [
                            'Order_tax.id' => $tax['id']
                        ]
                    );
                    
                    $db = $this->Order_tax->getDataSource();
                    if ($db->lastError()) {
                        $this->trackUser($txnid, $user_id, 'order_tax_update_sql_error', [
                            'tax_id' => $tax['id'],
                            'error'  => $db->lastError()
                        ]);
                    }
                } catch (Exception $e) {
                    $this->trackUser($txnid, $user_id, 'order_tax_update_exception', [
                        'tax_id' => $tax['id'],
                        'error'  => $e->getMessage()
                    ]);
                }
            }

        }
    
        // --------------------------------------------------
        // STEP 3 : RETURN TOTALS
        // --------------------------------------------------
        return [
            'status'          => true,
            'totalprice'      => round($totalprice, 2),
            'totaldiscount'   => round($totaldiscount, 2),
            'totalservicechg' => round($totalservicechg, 2),
            'totaltax'        => round($totaltax, 2)
        ];
    }

    
    public function bill_preview_with_discount()
    {
        $cashierid = $_REQUEST['id'];
        $ref_id=$_REQUEST['reference_id'];
        $sc = $_REQUEST['service_charge'];
        $disc=$_REQUEST['discount'];
        $type = $_REQUEST['type'];
        $dish_type = $_REQUEST['kds'];
        $discount_type_value=$disc;
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "User Id Missing",
            );
            return json_encode($response);
        }
        
        if($disc==''){
            $response =array(
                'status'=> false,
                'message'=> "Discount Missing",
            );
            return json_encode($response);
        }
        
        if($type==''){
            $response =array(
                'status'=> false,
                'message'=> "Discount Type Missing",
            );
            return json_encode($response);
        }
        
        if($dish_type==''){
            $response =array(
                'status'=> false,
                'message'=> "Dish Type Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        $todayDate = date("Y-m-d");
        
        $ref_id = [$ref_id]; // convert initial ref id to array
        
        $refid = []; // T9-fix: no merged tables guard

        $mergetablecheck = $this->Order_table_tracking->find('all', [
            'conditions' => [
                'Order_table_tracking.main_table_ref_id' => $ref_id[0],
                'Order_table_tracking.status' => 1,
                "DATE(Order_table_tracking.created) =" => $todayDate
            ]
        ]);
        if (!empty($mergetablecheck)) {
            foreach ($mergetablecheck as $merge) {
                $ref_id[] = $merge['Order_table_tracking']['merged_table_ref_id']; 
            }
        }
        $ref_in = "'" . implode("','", $ref_id) . "'";
        
        
        if($type==0){
            if(!empty($disc)){
                $coup = $this->Coupon->find('first', array('conditions'=>array('Coupon.code'=>$disc,'Coupon.expiry_date >='=>$todayDate,'Coupon.status'=>1)));
                if(empty($coup))
                {
                    $response =array(
                        'status'=> false,
                        'message'=> "Coupon not found Or Coupon Expired",
                    );
                    return json_encode($response);
                }
                $disc=$coup['Coupon']['value'];
            }else{
                $disc=0;
            }
        }
        
        if($type==1){
            $disc=$disc;
        }
        
        if($type==2){
            if($dish_type=='all'){
                $subtotals = $this->Order_orderhistory->query("SELECT SUM(total_price) as subtotal FROM `order_orderhistories` WHERE status!=0 and reference_id IN ($ref_in)");
            }else{
                $subtotals = $this->Order_orderhistory->query("SELECT SUM(total_price) as subtotal FROM `order_orderhistories` WHERE status!=0 and reference_id IN ($ref_in) and dish_type=$dish_type");
            }
            
            if($subtotals){
                $subtotal=$subtotals[0][0]['subtotal'];
                if($subtotal){
                    $disc=(($disc*100)/$subtotal);
                }else{
                    $response =array(
                        'status'=> false,
