    public function ordercomputewithkdstemp($txnid = null, $user_id = null, $is_sc = 1, $discount = 0, $dish = 0)
    {
        $response = ['status' => false];
    
        if (empty($txnid)) {
            return $response;
        }
    
        $sc = 0;
        if ($is_sc == 1) {
            $locIdForSc = $this->resolveLocationIdForTxn($txnid, $user_id);
            $sc = $this->getLocationServiceChargeRate($locIdForSc);
        }
        $kds = (int)$dish; // dish type to filter discount
    
        // STEP 1: FETCH ALL ORDER ITEMS
        $items = $this->Order_orderhistory->find('all', [
            'conditions' => [
                'Order_orderhistory.reference_id' => $txnid,
                'Order_orderhistory.status !=' => 0
            ],
            'fields' => [
                'Order_orderhistory.id',
                'Order_orderhistory.product_id',
                'Order_orderhistory.dish_type',
                'Order_orderhistory.price',
                'Order_orderhistory.quantity',
                'Order_orderhistory.discount',
                'Order_orderhistory.total_tax_percentage'
            ],
            'recursive' => -1
        ]);
    
        if (empty($items)) return $response;
    
        // STEP 2: CALCULATE TOTALS
        $totalprice = $totaldiscount = $totalservicechg = $totaltax = 0;
    
        foreach ($items as $row) {
            $item = $row['Order_orderhistory'];
    
            $basePrice = ($item['price'] * $item['quantity']) - $item['discount'];
            $applyDiscount = ($item['dish_type'] == $kds);
            $itemDiscount = $applyDiscount ? ($basePrice * $discount) / 100 : 0;
    
            $priceAfterDiscount = $basePrice - $itemDiscount;
            $serviceCharge = ($priceAfterDiscount * $sc) / 100;
            $taxableAmount = $priceAfterDiscount + $serviceCharge;
            $taxValue = ($taxableAmount * $item['total_tax_percentage']) / 100;
    
            $totalprice += $basePrice;
            $totaldiscount += $itemDiscount;
            $totalservicechg += $serviceCharge;
            $totaltax += $taxValue;
        }
    
        // STEP 3: UPDATE ORDER TAX (RESET + APPLY)
        $taxRows = $this->Order_tax->find('all', [
            'conditions' => [
                'Order_tax.reference_id' => $txnid,
                'Order_tax.status !=' => 0
            ],
            'fields' => [
                'Order_tax.id',
                'Order_tax.orderhistory_id',
                'Order_tax.tax_percentage',
                'Order_tax.quantity'
            ],
            'recursive' => -1
        ]);
    
        // Build a lookup map
        $itemMap = [];
        foreach ($items as $itemRow) {
            $itemMap[$itemRow['Order_orderhistory']['id']] = $itemRow['Order_orderhistory'];
        }
    
        foreach ($taxRows as $row) {
            $tax = $row['Order_tax'];
    
            if (!isset($itemMap[$tax['orderhistory_id']])) continue;
    
            $item = $itemMap[$tax['orderhistory_id']];
    
            $basePrice = ($item['price'] * $tax['quantity']) - $item['discount'];
    
            // Use the item’s dish_type to determine discount
            $applyDiscount = ($item['dish_type'] == $kds);
            $itemDiscount = $applyDiscount ? ($basePrice * $discount) / 100 : 0;
    
            $priceAfterDiscount = $basePrice - $itemDiscount;
            $serviceCharge = ($priceAfterDiscount * $sc) / 100;
            $taxablePrice = round($priceAfterDiscount + $serviceCharge, 2);
            $taxValue = round(($taxablePrice * $tax['tax_percentage']) / 100, 2);
            $discountPercent = $applyDiscount ? (float)$discount : 0.0;
    
        }
    
        // STEP 4: RETURN TOTALS
        return [
            'status' => true,
            'totalprice' => round($totalprice, 2),
            'totaldiscount' => round($totaldiscount, 2),
            'totalservicechg' => round($totalservicechg, 2),
            'totaltax' => round($totaltax, 2)
        ];
    }
    

    public function split_table_unbill()
    {
        $this->autoRender = false;
    
        $cashierid = $_REQUEST['id'];
        $ref_id = $_REQUEST['reference_id'];
        
        if (empty($cashierid)) {
            return json_encode([
                'status' => false,
                'message' => 'User Id Missing'
            ]);
        }
    
        if (empty($ref_id)) {
            return json_encode([
                'status' => false,
                'message' => 'Reference id Missing'
            ]);
        }
    
        $user = $this->User->find('first', [
            'conditions' => [
                'User.id' => $cashierid,
                'User.status' => 1
            ]
        ]);
    
        if (empty($user)) {
            return json_encode([
                'status' => false,
                'message' => 'User not found'
            ]);
        }
    
        $txn = $this->Order_transaction->find('first', [
            'conditions' => ['Order_transaction.reference_id' => $ref_id,'Order_transaction.status !=' => 0]
        ]);
    
        if (empty($txn)) {
            return json_encode([
                'status' => false,
                'message' => 'No Transaction found'
            ]);
        }
    
        $tableid = $txn['Order_transaction']['table_number'];
    
        $table = $this->Order_table->find('first', [
            'conditions' => [
                'Order_table.number' => $tableid,
                'Order_table.reference_id' => $ref_id,
                'Order_table.status !=' => 0
            ]
        ]);
    
        $this->ordercompute($ref_id, $cashierid, 0, 0);
    
        $ds = $this->Order_transaction->getDataSource();
        $ds->begin();
    
        try {
    
            $this->Order_transaction->updateAll(
                [
                    'Order_transaction.status' => 0,
                    'Order_transaction.sync' => 0,
                    'Order_transaction.local_sync' => 0
                ],
                ['Order_transaction.reference_id' => $ref_id]
            );
    
            $this->Order_split_transaction->updateAll(
                [
                    'Order_split_transaction.status' => 0,
                    'Order_split_transaction.sync' => 0,
                    'Order_split_transaction.local_sync' => 0
                ],
                ['Order_split_transaction.reference_id' => $ref_id]
            );
    
            $this->Order_split_orderhistory->updateAll(
                [
                    'Order_split_orderhistory.status' => 0,
                    'Order_split_orderhistory.sync' => 0,
                    'Order_split_orderhistory.local_sync' => 0
                ],
                ['Order_split_orderhistory.reference_id' => $ref_id]
            );
    
            $this->Order_split_payment->updateAll(
                [
                    'Order_split_payment.status' => 0,
                    'Order_split_payment.sync' => 0,
                    'Order_split_payment.local_sync' => 0
                ],
                ['Order_split_payment.reference_id' => $ref_id]
            );
            
            $this->Order_orderhistory->updateAll(
                [
                    'Order_orderhistory.discount' => 0,
                    'Order_orderhistory.sync' => 0,
                    'Order_orderhistory.local_sync' => 0
                ],
                ['Order_orderhistory.reference_id' => $ref_id]
            );
            
            $this->Order_payment->updateAll(
                array(
                    'Order_payment.status' => 0,
                    'Order_payment.sync' => 0,
                    'Order_payment.local_sync' => 0
                ),
                array(
                    'Order_payment.reference_id' => $ref_id
                )
            );
    
            if (!empty($table['Order_table']['id'])) {
                $this->Order_table->updateAll(
                    [
                        'Order_table.status' => 2,
                        'Order_table.sync' => 0,
                        'Order_table.local_sync' => 0
                    ],
                    ['Order_table.id' => $table['Order_table']['id']]
                );
            }

            $this->loadModel('ReeloDiscount');
            $reeloDiscountExist = $this->ReeloDiscount->find('first', array(
                'conditions' => array(
                    'ReeloDiscount.reference_id' => $ref_id
                )
            ));
            if (!empty($reeloDiscountExist)) {
                $this->ReeloDiscount->updateAll(
                    array(
                        'ReeloDiscount.status' => 0,
                        'ReeloDiscount.sync' => 0,
                        'ReeloDiscount.local_sync' => 0
                    ),
                    array(
                        'ReeloDiscount.reference_id' => $ref_id
                    )
                );
            }
    
            $ds->commit();
    
            return json_encode([
                'status' => true,
                'message' => 'Bill updated'
            ]);
    
        } catch (Exception $e) {
    
            $ds->rollback();
    
            return json_encode([
                'status' => false,
                'message' => 'Failed to update bill'
            ]);
        }
    }

    
    public function split_transaction_history()
    {
        $this->autoRender = false;
    
        $cashierid = $_REQUEST['id'] ?? '';
        $startdate = $_REQUEST['from'] ?? date("Y-m-d");
        $enddate   = $_REQUEST['to'] ?? date("Y-m-d");

        if ($cashierid == '') {
            return json_encode([
                'status'  => false,
                'message' => 'User Id Missing'
            ]);
        }
    
        $users = $this->User->find('first', [
            'conditions' => [
                'User.id'     => $cashierid,
                'User.status' => 1
            ]
        ]);
    
        if (empty($users)) {
            return json_encode([
                'status'  => false,
                'message' => 'Cashier not found'
            ]);
        }
    
        $location_id = !empty($users['User']['location_id']) ? $users['User']['location_id'] : null;

        // build shift-based datetime
        $_shiftRange = $this->getShiftDateRange($startdate, $enddate, $location_id);
        $startDatetime = $_shiftRange['startDatetime'];
        $endDatetime   = $_shiftRange['endDatetime'];

        $transactionitems = [];
    
        $splittransactions = $this->Order_split_transaction->find('all', [
            'conditions' => [
                'status'     => 2,
                'cashier_id' => $cashierid,
                'created BETWEEN ? AND ?' => [
                    $startDatetime,
                    $endDatetime
                ]
            ],
            'order' => ['Order_split_transaction.id' => 'DESC']
        ]);
    
        foreach ($splittransactions as $orders) {
    
            $ost = $orders['Order_split_transaction'];
    
            $reference_id       = $ost['reference_id'];
            $split_reference_id = $ost['split_reference_id'];
            $store_id           = $ost['store_id'];
    
            $discount_percentage = "0";
            $discper = $this->Order_tax->query("
                SELECT discount_percentage 
                FROM order_tax 
                WHERE reference_id = '$reference_id'
                  AND status != 0 
                  AND discount_percentage != 0
                LIMIT 1
            ");
    
            if (!empty($discper)) {
                $discount_percentage = number_format(
                    $discper[0]['order_tax']['discount_percentage'], 2
                );
            }
    
            $payment_mode = '';
            $pay_mode = $this->Order_split_payment->query("
                SELECT GROUP_CONCAT(type_value) AS payment
                FROM order_split_payments
                WHERE reference_id = '$reference_id'
                  AND split_reference_id = '$split_reference_id'
                  AND store_id = '$store_id'
                  AND status = 2
            ");
            if (!empty($pay_mode)) {
                $payment_mode = $pay_mode[0][0]['payment'];
            }
    
            $orderitems = [];
            $orderss = $this->Order_split_orderhistory->query("
                SELECT *,
                       SUM(quantity) AS quantity,
                       SUM(total_tax) AS total_tax,
                       SUM(total_price) AS total_price,
                       SUM(discount) AS discount
                FROM order_split_orderhistories
                WHERE reference_id = '$reference_id'
                  AND split_reference_id = '$split_reference_id'
                  AND store_id = '$store_id'
                  AND status != 0
                GROUP BY product_id
            ");
    
            foreach ($orderss as $items) {
    
                if (!isset($items['order_split_orderhistories']['remarks'])) {
                    $items['order_split_orderhistories']['remarks'] = '';
                }
    
                $oi = $items['order_split_orderhistories'];
    
                $orderitems[] = [
                    'id'            => $oi['id'],
                    'reference_id'  => $oi['reference_id'],
                    'cashier_id'    => $oi['cashier_id'],
                    'group_id'      => $oi['group_id'],
                    'category'      => $oi['category'],
                    'category_name' => $oi['category_name'],
                    'kds'           => $oi['kds'],
                    'product_id'    => $oi['product_id'],
                    'product_name'  => $oi['product_name'],
                    'quantity'      => $items[0]['quantity'],
                    'price'         => $oi['price'],
                    'total_tax'     => $items[0]['total_tax'],
                    'total_price'   => $items[0]['total_price'],
                    'discount'      => $items[0]['discount'],
                    'table_number'  => $oi['table_number'],
                    'remarks'       => $oi['remarks'] ?? '',
                    'status'        => $oi['status'],
                    'created'       => $oi['created']
                ];
            }
    
            $transactionitems[] = [
                'id'                    => $ost['id'],
                'reference_id'          => $reference_id,
                'split_reference_id'    => $split_reference_id,
                'orderno'               => $ost['orderno'],
                'device_id'             => $ost['device_id'],
                'cashier_id'            => $ost['cashier_id'],
                'table_number'          => $ost['table_number'],
                'price'                 => $ost['price'],
                'total_tax'             => $ost['total_tax'],
                'servicecharge'         => $ost['servicecharge'],
                'discount'              => $ost['discount'],
                'discount_percentage'   => $discount_percentage,
                'discount_type'         => $ost['discount_type'],
                'discount_type_value'   => $ost['discount_type_value'],
                'delivery_charge'       => $ost['delivery_charge'],
                'packing_charge'        => $ost['packing_charge'],
                'amount'                => $ost['amount'],
                'round'                 => $ost['round'],
                'name'                  => $ost['name'],
                'phone'                 => $ost['phone'],
                'address'               => $ost['address'],
                'remarks'               => $ost['remarks'] ?? '',
                'status'                => $ost['status'],
                'tokenno'               => $ost['tokenno'],
                'createtime'            => $ost['createtime'],
                'created'               => $ost['created'],
                'payment_mode'          => $payment_mode,
                'items'                 => $orderitems
            ];
        }
    
        $transactions = $this->Order_transaction->find('all', [
            'conditions' => [
                'status'     => 2,
                'is_split'     => 0,
                'cashier_id' => $cashierid,
                'created BETWEEN ? AND ?' => [
                    $startDatetime,
                    $endDatetime
                ]
            ],
            'order' => ['Order_transaction.id' => 'DESC']
        ]);
    
        foreach ($transactions as $orders) {
    
            $ot = $orders['Order_transaction'];
            $reference_id = $ot['reference_id'];
            $store_id     = $ot['store_id'];
    
            $discount_percentage = "0";
            $discper = $this->Order_tax->query("
                SELECT discount_percentage 
                FROM order_tax 
                WHERE reference_id = '$reference_id'
                  AND status != 0
                  AND discount_percentage != 0
                LIMIT 1
            ");
            if (!empty($discper)) {
                $discount_percentage = number_format(
                    $discper[0]['order_tax']['discount_percentage'], 2
                );
            }
    
            $payment_mode = '';
            $pay_mode = $this->Order_payment->query("
                SELECT GROUP_CONCAT(type_value) AS payment
                FROM order_payments
                WHERE reference_id = '$reference_id'
                  AND store_id = '$store_id'
                  AND status = 2
            ");
            if (!empty($pay_mode)) {
                $payment_mode = $pay_mode[0][0]['payment'];
            }
    
            $orderitems = [];
            $orderss = $this->Order_orderhistory->query("
                SELECT *,
                       SUM(quantity) AS quantity,
                       SUM(total_tax) AS total_tax,
                       SUM(total_price) AS total_price,
                       SUM(discount) AS discount
                FROM order_orderhistories
                WHERE reference_id = '$reference_id'
                  AND store_id = '$store_id'
                  AND status != 0
                GROUP BY product_id
            ");
    
            foreach ($orderss as $items) {
    
                if (!isset($items['order_orderhistories']['remarks'])) {
                    $items['order_orderhistories']['remarks'] = '';
                }
    
                $oi = $items['order_orderhistories'];
    
                $orderitems[] = [
                    'id'            => $oi['id'],
                    'reference_id'  => $oi['reference_id'],
                    'cashier_id'    => $oi['cashier_id'],
                    'group_id'      => $oi['group_id'],
                    'category'      => $oi['category'],
                    'category_name' => $oi['category_name'],
                    'kds'           => $oi['kds'],
                    'product_id'    => $oi['product_id'],
                    'product_name'  => $oi['product_name'],
                    'quantity'      => $items[0]['quantity'],
                    'price'         => $oi['price'],
                    'total_tax'     => $items[0]['total_tax'],
                    'total_price'   => $items[0]['total_price'],
                    'discount'      => $items[0]['discount'],
                    'table_number'  => $oi['table_number'],
                    'remarks'       => $oi['remarks'] ?? '',
                    'status'        => $oi['status'],
                    'created'       => $oi['created']
                ];
            }
    
            $transactionitems[] = [
                'id'                    => $ot['id'],
                'reference_id'          => $reference_id,
                'split_reference_id'    => 0,
                'orderno'               => $ot['orderno'],
                'device_id'             => $ot['device_id'],
                'cashier_id'            => $ot['cashier_id'],
                'table_number'          => $ot['table_number'],
                'price'                 => $ot['price'],
                'total_tax'             => $ot['total_tax'],
                'servicecharge'         => $ot['servicecharge'],
                'discount'              => $ot['discount'],
                'discount_percentage'   => $discount_percentage,
                'discount_type'         => $ot['discount_type'],
                'discount_type_value'   => $ot['discount_type_value'],
                'delivery_charge'       => $ot['delivery_charge'],
                'packing_charge'        => $ot['packing_charge'],
                'amount'                => $ot['amount'],
                'round'                 => $ot['round'],
                'name'                  => $ot['name'],
                'phone'                 => $ot['phone'],
                'address'               => $ot['address'],
                'remarks'               => $ot['remarks'] ?? '',
                'status'                => $ot['status'],
                'tokenno'               => $ot['tokenno'],
                'createtime'            => $ot['createtime'],
                'created'               => $ot['created'],
                'payment_mode'          => $payment_mode ?? '',
                'items'                 => $orderitems
            ];
        }
    
        usort($transactionitems, function ($a, $b) {
        
            preg_match('/(\d+)$/', $a['orderno'], $ma);
            preg_match('/(\d+)$/', $b['orderno'], $mb);
        
            $numA = isset($ma[1]) ? (int)$ma[1] : 0;
            $numB = isset($mb[1]) ? (int)$mb[1] : 0;
        
            return $numB <=> $numA; // DESC
        });

        $cashier_name = '';
        $cashname = $this->User->query("SELECT name FROM users WHERE id = '$cashierid'");
        if (!empty($cashname)) {
            $cashier_name = $cashname[0]['users']['name'];
        }
    
        return json_encode([
            'status'       => true,
            'message'      => 'success',
            'cashier_name' => $cashier_name,
            'transactions' => $transactionitems
        ]);
    }
    
