        }
        
        $cashier_name='';
        $cashname=$this->User->query("SELECT name FROM `users` WHERE id='$cashierid'");
        if($cashname){
           $cashier_name =$cashname[0]['users']['name'];
        }
        
        $response= array('status'=> true,
                'message'=> "success",
                'cashier_name'=>$cashier_name,
                'transactions'=>$transactionitems
            );
        return json_encode($response);
    }
    
    
    public function split_payment_status_update()
    {
        $this->autoRender = false;
    
        $cashierid    = ($_REQUEST['id'] ?? 0);
        $main_pay_id  = ($_REQUEST['main_pay_id'] ?? 0);
        $split_pay_id = ($_REQUEST['split_pay_id'] ?? 0);
    
        if (!$cashierid) {
            return json_encode(['status' => false, 'message' => 'Cashier ID is missing']);
        }
    
        if (!$main_pay_id) {
            return json_encode(['status' => false, 'message' => 'Main Payment ID is missing']);
        }
        
        // ---------------------------
        // Validate User
        // ---------------------------
        $user = $this->User->find('first', [
            'conditions' => ['User.id' => $cashierid, 'User.status' => 1],
            'recursive' => -1
        ]);
    
        if (empty($user)) {
            return json_encode(['status' => false, 'message' => 'User not found']);
        }
        
        // ---------------------------
        // Validate Main Payment
        // ---------------------------
        $mainPay = $this->Order_payment->find('first', [
            'conditions' => [
                'Order_payment.id' => $main_pay_id,
                'Order_payment.status !=' => 0
            ],
            'recursive' => -1
        ]);
    
        if (empty($mainPay)) {
            return json_encode(['status' => false, 'message' => 'Main payment not found']);
        }
        
        $type=$mainPay['Order_payment']['type'];
        $type_value=$mainPay['Order_payment']['type_value'];
        
        if ($split_pay_id > 0) {
    
            $split_update = $this->Order_split_payment->updateAll(
                [
                    'Order_split_payment.status'     => 0,
                    'Order_split_payment.sync'       => 0,
                    'Order_split_payment.local_sync' => 0
                ],
                [
                    'Order_split_payment.id' => $split_pay_id,
                    'Order_split_payment.status !=' => 0
                ]
            );
    
            if (!$split_update || $this->Order_split_payment->getAffectedRows() == 0) {
                return json_encode([
                    'status' => false,
                    'message' => 'Split payment update failed or already updated'
                ]);
            }
        }
    
        $main_update = $this->Order_payment->updateAll(
            [
                'Order_payment.status'     => 0,
                'Order_payment.sync'       => 0,
                'Order_payment.local_sync' => 0
            ],
            [
                'Order_payment.id' => $main_pay_id,
                'Order_payment.status !=' => 0
            ]
        );
    
        if (!$main_update || $this->Order_payment->getAffectedRows() == 0) {
            return json_encode([
                'status' => false,
                'message' => 'Main payment update failed or already updated'
            ]);
        }
    
        return json_encode([
            'status' => true,
            'message' => 'Payment status updated successfully'
        ]);
    }

    public function update_split_adjustments()
    {
        $this->autoRender = false;

        $cashierid  = trim($_REQUEST['id']                  ?? '');
        $ref_id     = trim($_REQUEST['reference_id']        ?? '');
        $split_ref  = trim($_REQUEST['split_reference_id']  ?? '');
        $disc       = trim($_REQUEST['discount']            ?? '0');
        $type       = (int)($_REQUEST['type']               ?? 1);
        $sc         = (int)($_REQUEST['service_charge']     ?? 1);
        $dish_type  = trim($_REQUEST['kds']                 ?? 'all');
        

        if(!empty($split_ref) && $split_ref != ''){
        
            if($type==0){
                if(!empty($disc)){
                    $coup = $this->Coupon->find('first', [
                        'conditions'=>[
                            'Coupon.code'=>$disc,
                            'Coupon.expiry_date >='=>$todayDate,
                            'Coupon.status'=>1
                        ]
                    ]);
                    $discper=$coup['Coupon']['value'] ?? 0;
                }
                else{
                    $discper=0;
                }
            }
        
            if($type==1){
                $discper=$disc;
            }
            
            if($type==2){

                $splitsubtotals = $this->Order_split_orderhistory->query("
                    SELECT SUM(total_price) as subtotal
                    FROM order_split_orderhistories
                    WHERE status!=0
                    AND reference_id='$ref_id'
                    AND split_reference_id='$split_ref'
                ");

                if(!empty($splitsubtotals[0][0]['subtotal'])){

                    $splitSubtotal = $splitsubtotals[0][0]['subtotal'];

                    if($splitSubtotal > 0){
                        if($disc >= $splitSubtotal){
                            return json_encode([
                                'status'  => false,
                                'message' => "Flat discount cannot exceed or equal the split bill total",
                            ]);
                        }
                        $discper = ($disc * 100) / $splitSubtotal;
                    }else{
                        return json_encode([
                            'status'=> false,
                            'message'=> "Bill Not Found",
                        ]);
                    }

                }else{
                    return json_encode([
                        'status'=> false,
                        'message'=> "Bill Not Found",
                    ]);
                }
            }
            
            if($discper>99){
                $response =array(
                    'status'=> false,
                    'message'=> "Discount is not more than 99%",
                );
                return json_encode($response);
            }
            
            if (empty($cashierid)) {
                return json_encode(['status' => false, 'message' => 'User ID missing']);
            }
            if (empty($ref_id)) {
                return json_encode(['status' => false, 'message' => 'reference_id missing']);
            }
            if (empty($split_ref)) {
                return json_encode(['status' => false, 'message' => 'split_reference_id missing']);
            }

            $user = $this->User->find('first', [
                'conditions' => ['User.id' => $cashierid, 'User.status' => 1],
                'recursive'  => -1
            ]);
            if (empty($user)) {
                return json_encode(['status' => false, 'message' => 'User not found']);
            }

            $parentTxn = $this->Order_transaction->find('first', [
                'conditions' => [
                    'Order_transaction.reference_id' => $ref_id,
                    'Order_transaction.status !='    => 0
                ],
                'recursive' => -1
            ]);
            if (empty($parentTxn)) {
                return json_encode(['status' => false, 'message' => 'Transaction not found']);
            }
            if (empty($parentTxn['Order_transaction']['is_split'])) {
                return json_encode(['status' => false, 'message' => 'This is not a split bill']);
            }

            $splitTxn = $this->Order_split_transaction->find('first', [
                'conditions' => [
                    'Order_split_transaction.reference_id'       => $ref_id,
                    'Order_split_transaction.split_reference_id' => $split_ref,
                    'Order_split_transaction.status !='          => 0
                ],
                'recursive' => -1
            ]);
            if (empty($splitTxn)) {
                return json_encode(['status' => false, 'message' => 'Split transaction not found']);
            }

            if ((int)$splitTxn['Order_split_transaction']['status'] === 2) {
                return json_encode([
                    'status'     => false,
                    'error_code' => 'SPLIT_ALREADY_SETTLED',
                    'message'    => 'This split has already been settled and cannot be modified'
                ]);
            }

            $paidRows = $this->Order_split_payment->query("
                SELECT COALESCE(SUM(amount), 0) AS paid
                FROM order_split_payments
                WHERE reference_id      = '$ref_id'
                AND split_reference_id = '$split_ref'
                AND status            != 0
            ");
            $alreadyPaid = isset($paidRows[0][0]['paid']) ? (float)$paidRows[0][0]['paid'] : 0.0;

            $ds = $this->Order_split_transaction->getDataSource();
            $ds->begin();

            try {

                $helperResult = $this->split_bill_table_package_kds_discount(
                    $cashierid,
                    $ref_id,
                    $split_ref,
                    $disc,
                    $sc,
                    $type,
                    $dish_type
                );

                if ($helperResult !== null) {
                    $ds->rollback();
                    return $helperResult;
                }

                $updated = $this->Order_split_transaction->find('first', [
                    'conditions' => [
                        'Order_split_transaction.reference_id'       => $ref_id,
                        'Order_split_transaction.split_reference_id' => $split_ref,
                        'Order_split_transaction.status !='          => 0
                    ],
                    'recursive' => -1
                ]);
                if (empty($updated)) {
                    $ds->rollback();
                    return json_encode([
                        'status'     => false,
                        'error_code' => 'COMPUTE_FAILED',
                        'message'    => 'Adjustment could not be applied. Please try again.'
                    ]);
                }

                $newAmount = (float)$updated['Order_split_transaction']['amount'];

                if ($alreadyPaid > 0 && $newAmount < $alreadyPaid) {
                    $ds->rollback();
                    return json_encode([
                        'status'     => false,
                        'error_code' => 'AMOUNT_BELOW_PAID',
                        'message'    => 'New total (' . number_format($newAmount, 2) . ') cannot be less than amount already paid (' . number_format($alreadyPaid, 2) . ')'
                    ]);
                }

                $this->Order_transaction->query("
                    UPDATE order_transactions
                    SET
                        price         = (SELECT COALESCE(SUM(price), 0)
                                        FROM order_split_transactions
                                        WHERE reference_id = '$ref_id' AND status != 0),
                        total_tax     = (SELECT COALESCE(SUM(total_tax), 0)
                                        FROM order_split_transactions
                                        WHERE reference_id = '$ref_id' AND status != 0),
                        servicecharge = (SELECT COALESCE(SUM(servicecharge), 0)
                                        FROM order_split_transactions
                                        WHERE reference_id = '$ref_id' AND status != 0),
                        discount      = (SELECT COALESCE(SUM(discount), 0)
                                        FROM order_split_transactions
                                        WHERE reference_id = '$ref_id' AND status != 0),
                        amount        = round((SELECT COALESCE(SUM(amount), 0)
                                        FROM order_split_transactions
                                        WHERE reference_id = '$ref_id' AND status != 0),0),
                        sync          = 0,
                        local_sync    = 0
                    WHERE reference_id = '$ref_id'
                    AND status != 0
                ");

                // Log User Track for Bill Modification
                $modDetails = [];
                if (!empty($disc) && (float)$disc > 0) {
                    if ($type == 2) {
                        $discTypeText = "as flat ₹" . round((float)$disc, 2);
                    } elseif ($type == 1) {
                        $discTypeText = "as {$disc}%";
                    } elseif ($type == 0) {
                        $discTypeText = "via Coupon {$disc}";
                    } else {
                        $discTypeText = "(₹{$disc})";
                    }
                    $dishTypeText = ($dish_type === 'all') ? 'All Items' : ucfirst($dish_type);
                    $modDetails[] = "discount applied {$discTypeText} on {$dishTypeText}";
                }
                if ($sc == 0) {
                    $modDetails[] = "service charge removed";
                } elseif ($sc == 1) {
                    $modDetails[] = "service charge applied";
                }

                $splitOrderNo = $splitTxn['Order_split_transaction']['orderno'] ?? '';
                $billNoText = !empty($splitOrderNo) ? " on bill no #{$splitOrderNo}" : "";
                $userFullName = !empty($user['User']['name']) ? $user['User']['name'] : ($user['User']['username'] ?? 'Manager');

                $trackRemarks = "Bill modified - " . (!empty($modDetails) ? implode(', ', $modDetails) : "Adjustments applied") . " by {$userFullName}{$billNoText}.";

                $this->User_track->create();
                $this->User_track->save([
                    'user_id'       => $cashierid,
                    'reference_id'  => $ref_id,
                    'location_id'   => $user['User']['location_id'] ?? ($splitTxn['Order_split_transaction']['store_id'] ?? 0),
                    'location_name' => '',
                    'type'          => 'bill_modified',
                    'status'        => 1,
                    'remarks'       => $trackRemarks,
                    'created'       => date('Y-m-d H:i:s'),
                    'modified'      => date('Y-m-d H:i:s')
                ]);

                $ds->commit();

            } catch (Exception $e) {

                $ds->rollback();
                return json_encode([
                    'status'     => false,
                    'error_code' => 'SPLIT_LOCKED',
                    'message'    => 'Update conflict detected. Please try again.'
                ]);
            }

            $freshTxn = $this->Order_split_transaction->query("
                SELECT ost.*, SUM(ost.amount) AS total_amount
                FROM order_split_transactions ost
                WHERE ost.reference_id       = '$ref_id'
                AND ost.split_reference_id = '$split_ref'
                AND ost.status            != 0
            ");

            $transactionitems = [];

            if (!empty($freshTxn)) {
                foreach ($freshTxn as $row) {
                    $sqlData   = $row[0];
                    $transData = $row['ost'];

                    $discperRows = $this->Order_tax->query("
                        SELECT discount_percentage
                        FROM order_tax
                        WHERE reference_id       = '$ref_id'
                        AND status            != 0
                        AND discount_percentage != 0
                        LIMIT 1
                    ");
                    $discount_percentage = (!empty($discperRows))
                        ? number_format($discperRows[0]['order_tax']['discount_percentage'], 2)
                        : '0';

                    $transactionitems[] = [
                        'id'                  => $transData['id'],
                        'reference_id'        => $transData['reference_id'],
                        'split_reference_id'  => $transData['split_reference_id'],
                        'orderno'             => $transData['orderno'],
                        'device_id'           => $transData['device_id'],
                        'cashier_id'          => $transData['cashier_id'],
                        'table_number'        => $transData['table_number'],
                        'price'               => $transData['price'],
                        'total_tax'           => $transData['total_tax'],
                        'servicecharge'       => $transData['servicecharge'],
                        'discount'            => $transData['discount'],
                        'discount_percentage' => $discount_percentage,
                        'discount_type'       => $transData['discount_type'],
                        'discount_type_value' => $transData['discount_type_value'],
                        'taxable_amount'      => number_format(
                            ($transData['price'] + $transData['servicecharge']) - $transData['discount'],
                            2
                        ),
                        'delivery_charge'     => $transData['delivery_charge'],
                        'packing_charge'      => $transData['packing_charge'],
                        'amount'              => $sqlData['total_amount'],
                        'round'               => $transData['round'],
                        'name'                => $transData['name'],
                        'phone'               => $transData['phone'],
                        'address'             => $transData['address'],
                        'tokenno'             => $transData['tokenno'],
                        'createtime'          => $transData['createtime'],
                        'created'             => $transData['created'],
                        'pax'                 => $transData['pax'],
                        'status'              => $transData['status'],
                        'waiter_id'           => $transData['waiter_id'],
                        'waiter_name'         => $transData['waiter_name'],
                        'is_takeaway'         => $transData['is_takeaway'],
                        'remarks'             => $transData['remarks'] ?? '',
                    ];
                }
            }

            $paidAfter = $this->Order_split_payment->query("
                SELECT COALESCE(SUM(amount), 0) AS paid
                FROM order_split_payments
                WHERE reference_id       = '$ref_id'
                AND split_reference_id = '$split_ref'
                AND status            != 0
            ");
            $paidAmount  = isset($paidAfter[0][0]['paid']) ? (float)$paidAfter[0][0]['paid'] : 0.0;
            $freshAmount = !empty($transactionitems) ? (float)$transactionitems[0]['amount'] : 0.0;
            $remaining   = max(0, $freshAmount - $paidAmount);

            return json_encode([
                'status'           => true,
                'message'          => 'Split adjustments saved successfully',
                'transactions'     => $transactionitems,
                'remaining_amount' => number_format($remaining, 2, '.', '')
            ]);

        }
        else{
            $todayDate = date("Y-m-d");

            if ($type == 0) {
                if (!empty($disc)) {
                    $coup = $this->Coupon->find('first', [
                        'conditions' => [
                            'Coupon.code'        => $disc,
                            'Coupon.expiry_date >=' => $todayDate,
                            'Coupon.status'      => 1
                        ]
                    ]);
                    $discper = $coup['Coupon']['value'] ?? 0;
                } else {
                    $discper = 0;
                }
            }

            if ($type == 1) {
                $discper = $disc;
            }

            if ($type == 2) {
                $totalsubtotals = $this->Order_orderhistory->query("
                    SELECT SUM(total_price) as subtotal
                    FROM order_orderhistories
                    WHERE status != 0
                    AND reference_id = '$ref_id'
                ");

                if (!empty($totalsubtotals[0][0]['subtotal'])) {
                    $billSubtotal = $totalsubtotals[0][0]['subtotal'];
                    if ($billSubtotal > 0) {
                        if ($disc >= $billSubtotal) {
                            return json_encode([
                                'status'  => false,
                                'message' => "Flat discount cannot exceed or equal the bill total",
                            ]);
                        }
                        $discper = ($disc * 100) / $billSubtotal;
                    } else {
                        return json_encode([
                            'status'  => false,
                            'message' => "Bill Not Found",
                        ]);
                    }
                } else {
                    return json_encode([
                        'status'  => false,
                        'message' => "Bill Not Found",
                    ]);
                }
            }

            if ($discper > 99) {
                return json_encode([
                    'status'  => false,
                    'message' => "Discount is not more than 99%",
                ]);
            }

            if (empty($cashierid)) {
                return json_encode(['status' => false, 'message' => 'User ID missing']);
            }
            if (empty($ref_id)) {
                return json_encode(['status' => false, 'message' => 'reference_id missing']);
            }

            $user = $this->User->find('first', [
                'conditions' => ['User.id' => $cashierid, 'User.status' => 1],
                'recursive'  => -1
            ]);
            if (empty($user)) {
                return json_encode(['status' => false, 'message' => 'User not found']);
            }

            $parentTxn = $this->Order_transaction->find('first', [
                'conditions' => [
                    'Order_transaction.reference_id' => $ref_id,
                    'Order_transaction.status !='    => 0
                ],
                'recursive' => -1
            ]);
            if (empty($parentTxn)) {
                return json_encode(['status' => false, 'message' => 'Transaction not found']);
            }

            if ((int)$parentTxn['Order_transaction']['status'] === 2) {
                return json_encode([
                    'status'     => false,
                    'error_code' => 'BILL_ALREADY_SETTLED',
                    'message'    => 'This bill has already been settled and cannot be modified'
                ]);
            }

            $paidRows = $this->Order_payment->query("
                SELECT COALESCE(SUM(amount), 0) AS paid
                FROM order_payments
                WHERE reference_id = '$ref_id'
                AND status != 0
            ");
            $alreadyPaid = isset($paidRows[0][0]['paid']) ? (float)$paidRows[0][0]['paid'] : 0.0;

            $ds = $this->Order_transaction->getDataSource();
            $ds->begin();

            try {
                if ($dish_type == 'all') {
                    $orderdata = $this->ordercompute($ref_id, $cashierid, $sc, $discper);
                } else {
                    $orderdata = $this->ordercomputewithkds($ref_id, $cashierid, $sc, $discper, $dish_type);
                }

                if (empty($orderdata) || empty($orderdata['status'])) {
                    $ds->rollback();
                    return json_encode([
                        'status'     => false,
                        'error_code' => 'COMPUTE_FAILED',
                        'message'    => 'Adjustment could not be applied. Please try again.'
                    ]);
                }

                $totalservicechg = $orderdata['totalservicechg'];
                $totalprice      = $orderdata['totalprice'];
                $totaltax        = $orderdata['totaltax'];
                $totaldiscount   = $orderdata['totaldiscount'];
                $totalamount     = round((($totalprice + $totaltax + $totalservicechg) - $totaldiscount), 0);

                if ($alreadyPaid > 0 && $totalamount < $alreadyPaid) {
                    $ds->rollback();
                    return json_encode([
                        'status'     => false,
                        'error_code' => 'AMOUNT_BELOW_PAID',
                        'message'    => 'New total (' . number_format($totalamount, 2) . ') cannot be less than amount already paid (' . number_format($alreadyPaid, 2) . ')'
                    ]);
                }

                $this->Order_transaction->query("
                    UPDATE order_transactions
                    SET
                        price               = '$totalprice',
                        total_tax           = '$totaltax',
                        servicecharge       = '$totalservicechg',
                        discount            = '$totaldiscount',
                        discount_type       = '$type',
                        discount_type_value = '$disc',
                        amount              = '$totalamount',
                        sync                = 0,
                        local_sync          = 0
                    WHERE reference_id = '$ref_id'
                    AND status != 0
                ");

                $ds->commit();

            } catch (Exception $e) {
                $ds->rollback();
                return json_encode([
                    'status'     => false,
                    'error_code' => 'BILL_LOCKED',
                    'message'    => 'Update conflict detected. Please try again.'
                ]);
            }

            $freshTxn = $this->Order_transaction->find('first', [
                'conditions' => [
                    'Order_transaction.reference_id' => $ref_id,
                    'Order_transaction.status !='    => 0
                ],
                'recursive' => -1
            ]);

            $transactionitems = [];

            if (!empty($freshTxn)) {
                $transData = $freshTxn['Order_transaction'];

                $discperRows = $this->Order_tax->query("
                    SELECT discount_percentage
                    FROM order_tax
                    WHERE reference_id = '$ref_id'
                    AND status != 0
                    AND discount_percentage != 0
                    LIMIT 1
                ");
                $discount_percentage = (!empty($discperRows))
                    ? number_format($discperRows[0]['order_tax']['discount_percentage'], 2)
                    : '0';

                $transactionitems[] = [
                    'id'                  => $transData['id'],
                    'reference_id'        => $transData['reference_id'],
                    'split_reference_id'  => 0,
                    'orderno'             => $transData['orderno'],
                    'device_id'           => $transData['device_id'],
                    'cashier_id'          => $transData['cashier_id'],
                    'table_number'        => $transData['table_number'],
                    'price'               => $transData['price'],
                    'total_tax'           => $transData['total_tax'],
                    'servicecharge'       => $transData['servicecharge'],
                    'discount'            => $transData['discount'],
                    'discount_percentage' => $discount_percentage,
                    'discount_type'       => $transData['discount_type'],
                    'discount_type_value' => $transData['discount_type_value'],
                    'taxable_amount'      => number_format(
                        ($transData['price'] + $transData['servicecharge']) - $transData['discount'],
                        2
                    ),
                    'delivery_charge'     => $transData['delivery_charge'] ?? 0,
                    'packing_charge'      => $transData['packing_charge'] ?? 0,
                    'amount'              => $transData['amount'],
                    'round'               => $transData['round'],
                    'name'                => $transData['name'] ?? '',
                    'phone'               => $transData['phone'] ?? '',
                    'address'             => $transData['address'] ?? '',
                    'tokenno'             => $transData['tokenno'] ?? '',
                    'createtime'          => $transData['createtime'] ?? '',
                    'created'             => $transData['created'] ?? '',
                    'pax'                 => $transData['pax'] ?? '',
                    'status'              => $transData['status'],
                    'waiter_id'           => $transData['waiter_id'] ?? '',
                    'waiter_name'         => $transData['waiter_name'] ?? '',
                    'is_takeaway'         => $transData['is_takeaway'] ?? 0,
                    'remarks'             => $transData['remarks'] ?? '',
                ];
            }

            $paidAfter = $this->Order_payment->query("
                SELECT COALESCE(SUM(amount), 0) AS paid
                FROM order_payments
                WHERE reference_id = '$ref_id'
                AND status != 0
            ");
            $paidAmount  = isset($paidAfter[0][0]['paid']) ? (float)$paidAfter[0][0]['paid'] : 0.0;
            $freshAmount = !empty($transactionitems) ? (float)$transactionitems[0]['amount'] : 0.0;
            $remaining   = max(0, $freshAmount - $paidAmount);

            return json_encode([
                'status'           => true,
                'message'          => 'Bill adjustments saved successfully',
                'transactions'     => $transactionitems,
                'remaining_amount' => number_format($remaining, 2, '.', '')
            ]);
        }
    }

    public function void_reprint_data()
    {
        $cashierid = $_REQUEST['id'];
        $reference_id = $_REQUEST['reference_id'];
        $group_id = $_REQUEST['order_id'];
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "User Id Missing",
            );
            return json_encode($response);
        }
        if($reference_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Reference Id Missing",
            );
            return json_encode($response);
        }
        if($group_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Group Id Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        $orderitems=[];
        
        $orderss = $this->Order_orderhistory->query("SELECT * FROM `order_orderhistories` WHERE reference_id='$reference_id' and id='$group_id' and status=0 ");
        if(!empty($orderss))
        {
            foreach($orderss as $orders){
                $product_id=$orders['order_orderhistories']['product_id'];
                $order_id=$orders['order_orderhistories']['id'];
                $selected_modifiers=[];
                $orders_modifiers = $this->Order_modifier->query("SELECT * FROM `order_modifier` WHERE reference_id='$reference_id' and product_id='$product_id' and orderhistory_id='$order_id' and status=0");
                foreach($orders_modifiers as $orders_modifier){
                    $modifiers=$orders_modifier['order_modifier'];
                    $modifier_group_id=$modifiers['modifier_group_id'];
                    $modifier_group_name=$modifiers['modifier_group_name'];
                    $modifier_id=$modifiers['modifier_id'];
                    $modifier_name=$modifiers['modifier_name'];
                    $modifier_price=$modifiers['modifier_price'];
                    
                    $selected_modifiers[]=array(
                        'modifier_group_id' => $modifier_group_id,
                        'modifier_group_name' => $modifier_group_name,
                        'modifier_id' => $modifier_id,
                        'modifier_name' => $modifier_name,
                        'modifier_price' => $modifier_price,
                    );
                }
                
                if(!isset($orders['order_orderhistories']['remarks'])){
                    $orders['order_orderhistories']['remarks']='';
                }
                $orderitems[]=array(
                    'id' => $orders['order_orderhistories']['id'],
                    'reference_id' =>  $orders['order_orderhistories']['reference_id'],
                    'cashier_id' =>  $orders['order_orderhistories']['cashier_id'],
                    'group_id' =>  $orders['order_orderhistories']['group_id'],
                    'category' =>  $orders['order_orderhistories']['category'],
                    'category_name' =>  $orders['order_orderhistories']['category_name'],
                    'kds' =>  $orders['order_orderhistories']['kds'],
                    'product_id' =>  $orders['order_orderhistories']['product_id'],
                    'product_name' =>  $orders['order_orderhistories']['product_name'],
                    'quantity' =>  $orders['order_orderhistories']['quantity'],
                    'price' =>  $orders['order_orderhistories']['price'],
                    'total_tax' =>  $orders['order_orderhistories']['total_tax'],
                    'total_price' =>  $orders['order_orderhistories']['total_price'],
                    'discount' =>  $orders['order_orderhistories']['discount'],
                    'table_number' =>  $orders['order_orderhistories']['table_number'],
                    'kot_number' =>  $orders['order_orderhistories']['kot_number'],
                    'remarks' =>  $orders['order_orderhistories']['remarks'],
                    'selected_modifiers' => $selected_modifiers,
                    'status' =>  $orders['order_orderhistories']['status'],
                    'created' =>  $orders['order_orderhistories']['created']
                );
            }
        }
        $finalamount=0;
        $transactionitems=[];
        $transactions = $this->Order_transaction->find('all', array('conditions'=>array('reference_id'=>$reference_id,'status'=>0)));
        if(!empty($transactions))
        {
            foreach($transactions as $orders){
                if(!$orders['Order_transaction']['remarks']){
                    $orders['Order_transaction']['remarks']='';
                }
                $finalamount=$orders['Order_transaction']['amount'];
                $cashierid=$orders['Order_transaction']['cashier_id'];
                $reference_id=$orders['Order_transaction']['reference_id'];
                
                $discper = $this->Order_tax->query("SELECT discount_percentage FROM `order_tax` WHERE reference_id='$reference_id' and status=0 and discount_percentage!=0 limit 1");
                if(!empty($discper))
                {
                    $discount_percentage=$discper[0]['order_tax']['discount_percentage'];
                }
                if(!isset($discount_percentage)){
                    $discount_percentage="0";
                }
                
                $transactionitems[]=array(
                    'id' => $orders['Order_transaction']['id'],
                    'reference_id' =>  $orders['Order_transaction']['reference_id'],
                    'orderno' =>  $orders['Order_transaction']['orderno'],
                    'device_id' =>  $orders['Order_transaction']['device_id'],
                    'cashier_id' =>  $orders['Order_transaction']['cashier_id'],
                    'table_number' =>  $orders['Order_transaction']['table_number'],
                    'price' =>  $orders['Order_transaction']['price'],
                    'total_tax' =>  $orders['Order_transaction']['total_tax'],
                    'servicecharge' =>  $orders['Order_transaction']['servicecharge'],
                    'discount' =>  $orders['Order_transaction']['discount'],
                    'discount_percentage' =>  $discount_percentage,
                    'discount_type' =>  $orders['Order_transaction']['discount_type'],
                    'discount_type_value' =>  $orders['Order_transaction']['discount_type_value'],
                    'delivery_charge' =>  $orders['Order_transaction']['delivery_charge'],
                    'packing_charge' =>  $orders['Order_transaction']['packing_charge'],
                    'amount' =>  $orders['Order_transaction']['amount'],
                    'round' =>  $orders['Order_transaction']['round'],
                    'name' =>  $orders['Order_transaction']['name'],
                    'phone' =>  $orders['Order_transaction']['phone'],
                    'address' =>  $orders['Order_transaction']['address'],
                    'remarks' =>  $orders['Order_transaction']['remarks'],
                    'status' =>  $orders['Order_transaction']['status'],
                    'tokenno' =>  $orders['Order_transaction']['tokenno'],
                    'createtime' =>  $orders['Order_transaction']['createtime'],
                    'pax' =>  $orders['Order_transaction']['pax'],
                    'created' =>  $orders['Order_transaction']['created']
                );
            }
        }
        
        $paymentitems=[];
        $payments = $this->Order_payment->find('all', array('conditions'=>array('reference_id'=>$reference_id,'status'=>0)));
        if(!empty($payments))
        {
            foreach($payments as $orders){
                if(!isset($orders['Order_payment']['remarks'])){
                    $orders['Order_payment']['remarks']='';
                }
                $paymentitems[]=array(
                    'id' => $orders['Order_payment']['id'],
                    'reference_id' =>  $orders['Order_payment']['reference_id'],
                    'cashier_id' =>  $orders['Order_payment']['cashier_id'],
                    'type' =>  $orders['Order_payment']['type'],
                    'type_value' =>  $orders['Order_payment']['type_value'],
                    'amount' =>  $orders['Order_payment']['amount'],
                    'status' =>  $orders['Order_payment']['status'],
                    'remarks' =>  $orders['Order_payment']['remarks'],
                    'created' =>  $orders['Order_payment']['created']
                );
            }
        }
        $taxitems=[];
        $taxes = $this->Order_tax->query("SELECT tax_id,tax_name,tax_percentage,sum(tax_value) as tax_value FROM `order_tax` WHERE reference_id='$reference_id' and tax_percentage!=0 and status=0 GROUP by tax_id");
        if(!empty($taxes))
        {
            foreach($taxes as $tax){
                
                $taxitems[]=array(
                    'tax_id' => $tax['order_tax']['tax_id'],
                    'tax_name' =>  $tax['order_tax']['tax_name'],
                    'tax_percentage' =>  $tax['order_tax']['tax_percentage'],
                    'tax_value' =>  "" .round($tax[0]['tax_value'],2)
                );
            }
        }
        $finalpayment=0;
        $allpayments=$this->Order_payment->query("SELECT sum(amount) as pay_amount FROM `order_payments` WHERE reference_id='$reference_id' and status=0");
        if($allpayments){
            $finalpayment=$allpayments[0][0]['pay_amount'];
        }
        $amount_diff=round(($finalamount-$finalpayment),2);
        if ($amount_diff < 1 && $amount_diff >= 0) {
            $amount_diff = 0;
        }
        
        $cashier_name='';
        $cashname=$this->User->query("SELECT name FROM `users` WHERE id='$cashierid'");
        if($cashname){
           $cashier_name =$cashname[0]['users']['name'];
        }
        
        $printeritems=[];
        $targetStoreId = !empty($users['User']['location_id']) ? $users['User']['location_id'] : (!empty($orderss[0]['order_orderhistories']['store_id']) ? $orderss[0]['order_orderhistories']['store_id'] : '');
        $printerCond = !empty($targetStoreId) ? "status=1 AND store_id='$targetStoreId'" : "status=1";
        $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE $printerCond");
        if(empty($printerss) && !empty($targetStoreId)){
            $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE status=1");
        }
        if(!empty($printerss))
        {
            foreach($printerss as $printers){
                if($printers['pos_printers']['name']=='Bar'){
                    $name = $printers['pos_printers']['name'];
                    $ip = $printers['pos_printers']['ip'];
                }else{
                    $name = 'expo';
                    $ip='192.168.1.240';
                }
                $printeritems[]=array(
                    'id' => $printers['pos_printers']['id'],
                    'store_id' =>  $printers['pos_printers']['store_id'],
                    'name' =>  $name,
                    'kds' =>  $printers['pos_printers']['kds'],
                    'ip' =>  $ip,
                    'status' =>  $printers['pos_printers']['status']
                );
            }
        }
        
        $response= array('status'=> true,
                'message'=> "success",
                'cashier_name'=>$cashier_name,
                'orders'=>$orderitems,
                'transactions'=>$transactionitems,
                'payments'=>$paymentitems,
                'taxes'=>$taxitems,
                'printers'=>$printeritems,
                'remaining_amount'=>number_format($amount_diff, 2, '.', '')
            );
        return json_encode($response);
    }
    
