                $printeritems[]=array(
                    'id' => $printers['pos_printers']['id'],
                    'store_id' =>  $printers['pos_printers']['store_id'],
                    'name' =>  $name,
                    'kds' =>  $printers['pos_printers']['kds'],
                    'ip' =>  $ip,
                    'status' =>  $printers['pos_printers']['status']
                );
            }
        }
        
        $response= array('status'=> true,
                'message'=> "success",  
                'cashier_name'=>$cashier_name,
                'orders'=>$orderitems,
                'transactions'=>$transactionitems,
                'payments'=>$paymentitems,
                'taxes'=>$taxitems,
                'printers'=>$printeritems,
                'remaining_amount'=>number_format($amount_diff, 2, '.', '')
            );
        return json_encode($response);
    }
    
    private function _getOutletTaxes($productId, $outletId = null)
    { 
        // Ensure model is loaded (DI-free dynamic load)
        if (!isset($this->Catalog_product_tax_outlet)) {
            $this->loadModel('Catalog_product_tax_outlet');
        }
        if ($outletId) {
            $today = date('Y-m-d');
            $outletTaxes = $this->Catalog_product_tax_outlet->find('all', array(
                'conditions' => array(
                    'Catalog_product_tax_outlet.product_id' => $productId,
                    'Catalog_product_tax_outlet.outlet_id'  => $outletId,
                    'Catalog_product_tax_outlet.status'     => 1,
                    'OR' => array(
                        'Catalog_product_tax_outlet.effective_from IS NULL',
                        'Catalog_product_tax_outlet.effective_from <=' => $today
                    )
                ),
                'recursive' => -1
            ));
            if (!empty($outletTaxes)) {
                $result = array();
                foreach ($outletTaxes as $t) {
                    $result[] = array(
                        'tax_id'         => $t['Catalog_product_tax_outlet']['tax_id'],
                        'tax_name'       => $t['Catalog_product_tax_outlet']['tax_name'],
                        'tax_percentage' => $t['Catalog_product_tax_outlet']['tax_percentage']
                    );
                }
                return $result;
            }
        }
        // Fall back to global taxes
        $global = $this->Catalog_product_tax->find('all', array(
            'conditions' => array(
                'Catalog_product_tax.product_id' => $productId,
                'Catalog_product_tax.status'     => 1
            ),
            'recursive' => -1
        ));
        $result = array();
        foreach ($global as $t) {
            $result[] = array(
                'tax_id'         => $t['Catalog_product_tax']['tax_id'],
                'tax_name'       => $t['Catalog_product_tax']['tax_name'],
                'tax_percentage' => $t['Catalog_product_tax']['tax_percentage']
            );
        }
        return $result;
    }
    
    public function save_editing_request()
    {
        $response = array('status' => false, 'message' => 'Failed');

        $reference_id = isset($_REQUEST['reference_id']) ? trim($_REQUEST['reference_id']) : '';
        $cashier_id = isset($_REQUEST['cashier_id']) ? trim($_REQUEST['cashier_id']) : (isset($_REQUEST['id']) ? trim($_REQUEST['id']) : '');
        $remarks = isset($_REQUEST['remarks']) ? trim($_REQUEST['remarks']) : '';
        $type = isset($_REQUEST['type']) ? trim($_REQUEST['type']) : '';

        if ($reference_id == '') {
            $response['status'] = false;
            $response['message'] = "Reference Id is Missing";
            return json_encode($response);
        }

        if ($cashier_id == '') {
            $response['status'] = false;
            $response['message'] = "Cashier Id is Missing";
            return json_encode($response);
        }

        if ($type == '') {
            $response['status'] = false;
            $response['message'] = "Type Missing";
            return json_encode($response);
        }

        // Validate Cashier / User
        $user = $this->User->find('first', array(
            'conditions' => array('User.id' => $cashier_id, 'User.status' => 1)
        ));
        if (empty($user)) {
            $response['status'] = false;
            $response['message'] = "Cashier not found";
            return json_encode($response);
        }

        $cashier_name = $user['User']['name'] ?? $user['User']['username'] ?? '';
        $store_id = $user['User']['location_id'] ?? 0;
        $store_name = $user['User']['location_name'] ?? '';

        if (!empty($store_id)) {
            $loc = $this->Location->find('first', array(
                'conditions' => array('Location.id' => $store_id)
            ));
            if (!empty($loc)) {
                $store_name = $loc['Location']['name'];
            }
        }

        $this->loadModel('Editing_management');

        $this->Editing_management->create();
        $data = array(
            'reference_id' => $reference_id,
            'cashier_id'   => $cashier_id,
            'cashier_name' => $cashier_name,
            'store_id'     => $store_id,
            'store_name'   => $store_name,
            'remarks'      => $remarks,
            'type'         => $type,
            'status'       => 1, // 1 = Pending
            'sync'         => 0,
            'local_sync'   => 0,
            'created'      => date('Y-m-d H:i:s'),
            'modified'     => date('Y-m-d H:i:s')
        );
        $this->Editing_management->save($data);
        $id = $this->Editing_management->id;
        
        $response = array(
            'status'         => true,
            'message'        => "Editing request saved successfully",
            'id'             => $id,
            'reference_id'   => $reference_id,
            'cashier_id'     => (int)$cashier_id,
            'cashier_name'   => $cashier_name,
            'store_id'       => (int)$store_id,
            'store_name'     => $store_name,
            'type'           => $type,
            'remarks'        => $remarks,
            'request_status' => 1,
            'status_name'    => 'pending',
            'status_text'    => 'Pending'
        );

        return json_encode($response);
    }

    public function get_editing_status()
    {
        $response = array('status' => false, 'message' => 'Failed');

        $reference_id = isset($_REQUEST['reference_id']) ? trim($_REQUEST['reference_id']) : '';
        $cashier_id = isset($_REQUEST['cashier_id']) ? trim($_REQUEST['cashier_id']) : '';
        $id = isset($_REQUEST['id']) ? trim($_REQUEST['id']) : '';

        if ($reference_id == '') {
            $response['status'] = false;
            $response['message'] = "Reference Id is Missing";
            return json_encode($response);
        }
        
        if ($cashier_id == '') {
            $response['status'] = false;
            $response['message'] = "Cashier Id is Missing";
            return json_encode($response);
        }
        
        if ($id == '') {
            $response['status'] = false;
            $response['message'] = "Id is Missing";
            return json_encode($response);
        }

        $this->loadModel('Editing_management');

        $conditions = array('Editing_management.reference_id' => $reference_id);
        $conditions['Editing_management.cashier_id'] = $cashier_id;
        $conditions['Editing_management.id'] = $id;
    
        $record = $this->Editing_management->find('first', array(
            'conditions' => $conditions,
            'order' => array('Editing_management.id DESC')
        ));

        if (empty($record)) {
            $response['status'] = false;
            $response['message'] = "Editing request record not found";
            return json_encode($response);
        }

        $statusVal = (int)$record['Editing_management']['status'];
        $statusText = 'Pending';
        $statusName = 'pending';
        $action = 'pending';

        if ($statusVal === 2) {
            $statusText = 'Approved';
            $statusName = 'approved';
            $action = 'approve';
        } elseif ($statusVal === 3) {
            $statusText = 'Rejected';
            $statusName = 'rejected';
            $action = 'reject';
        }

        $response = array(
            'status'         => true,
            'message'        => 'success',
            'id'             => $record['Editing_management']['id'],
            'reference_id'   => $record['Editing_management']['reference_id'],
            'cashier_id'     => (int)$record['Editing_management']['cashier_id'],
            'cashier_name'   => $record['Editing_management']['cashier_name'],
            'store_id'       => (int)$record['Editing_management']['store_id'],
            'store_name'     => $record['Editing_management']['store_name'],
            'type'           => $record['Editing_management']['type'],
            'remarks'        => $record['Editing_management']['remarks'],
            'request_status' => $statusVal,
            'status_name'    => $statusName,
            'status_text'    => $statusText,
            'action'         => $action,
            'action_by'      => $record['Editing_management']['action_by'],
            'action_by_name' => $record['Editing_management']['action_by_name'],
            'action_date'    => $record['Editing_management']['action_date'],
            'created'        => $record['Editing_management']['created'],
            'modified'       => $record['Editing_management']['modified']
        );

        return json_encode($response);
    }
    
    public function update_split_orderpaymentsave_table()
    {
        $response['status']= false;
        $response['message']= "fail";
        
        $cashierid = $_REQUEST['id'];
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "Cashier Id is Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
    
        if (isset($_REQUEST['data'])) {
            $data = $_REQUEST['data'];
        } else {
            $response =array(
                'status'=> false,
                'message'=> "data not found",
            );
            return json_encode($response);
        }
        
        $data = json_decode($data, true);
        
        $reference_id=$data['reference_id'];
        $device_id=$data['device_id'];
        
        //payment save
        
        $transactions = $this->Order_transaction->find('first', array('conditions'=>array('Order_transaction.reference_id'=>$reference_id,'Order_transaction.status'=>2)));
        if(empty($transactions))
        {
            $response =array(
                'status'=> false,
                'message'=> "Transaction not found",
            );
            return json_encode($response);
        }
        
        $store_id=$transactions['Order_transaction']['store_id'];
        $is_split=$transactions['Order_transaction']['is_split'];
        
        if($is_split){
            $split_id=$data['id'];
            $split_reference_id=$data['split_reference_id'];
                
            $splittransactions = $this->Order_split_transaction->find('all', [
                'fields' => [
                    'Order_split_transaction.*',
                    'SUM(Order_split_transaction.amount) AS total_amount'
                ],
                'conditions' => [
                    'Order_split_transaction.reference_id' => $reference_id,
                    'Order_split_transaction.split_reference_id' => $split_reference_id,
                    'Order_split_transaction.id' => $split_id,
                    'Order_split_transaction.status' => 2
                ]
            ]);
            
            if (empty($splittransactions[0]['Order_split_transaction']['id'])) {
                $response =array(
                    'status'=> false,
                    'message'=> "No Split Transaction found",
                );
                return json_encode($response);
            }
            
            foreach($data['payment'] as $payment){
                
                if($payment['type']==7){
                    $response['status']= false;
                    $response['message']= "Option not allowed";
                    return json_encode($response);
                }
                
                if($payment['amount']<1){
                    $response['status']= false;
                    $response['message']= "Amount is not valid..!";
                    return json_encode($response);
                }
                
                
                $split_finalamount = $splittransactions[0][0]['total_amount'];
         
                $datas['Order_split_payment']=array(
                    'split_reference_id'=>$split_reference_id,
                    'split_txn_id'=>$split_id,
                    'reference_id'=>$reference_id,
                    'store_id'=>$store_id,
                    'device_id'=>$device_id,
                    'cashier_id'=>$cashierid,
                    'type'=>$payment['type'],
                    'type_value'=>$payment['type_value'],
                    'amount'=>$payment['amount'],
                    'remarks'=>$payment['remarks']
                );
                
                if($this->Order_split_payment->saveAll($datas['Order_split_payment']))
                {
                    $splitPaymentId = $this->Order_split_payment->id;

                    $split_allpayments=$this->Order_split_payment->query("SELECT sum(amount) as pay_amount FROM `order_split_payments` WHERE split_txn_id='$split_id' and split_reference_id='$split_reference_id' and reference_id='$reference_id' and status!=0");
                    if($split_allpayments){
                        $split_finalpayment=$split_allpayments[0][0]['pay_amount'];
                    }
                    $split_amount_diff=round(($split_finalamount-$split_finalpayment),2);
                    
                    if($split_amount_diff<1){
                        $this->Order_split_orderhistory->query("UPDATE order_split_orderhistories SET status = 2,sync=0,local_sync=0 WHERE split_reference_id='$split_reference_id' and reference_id = '$reference_id' and status = 1");
                        $this->Order_split_transaction->query("UPDATE order_split_transactions SET status = 2,payment_mode='$type_value',sync=0,local_sync=0 WHERE id='$split_id' and split_reference_id='$split_reference_id' and reference_id = '$reference_id' and status!=0");
                        $this->Order_split_payment->query("UPDATE order_split_payments SET status = 2,sync=0,local_sync=0 WHERE split_txn_id='$split_id' and split_reference_id='$split_reference_id' and reference_id = '$reference_id' and status!=0");
                    }
                    
                    $datas['Order_payment']=array(
                        'reference_id'=>$reference_id,
                        'store_id'=>$store_id,
                        'device_id'=>$device_id,
                        'cashier_id'=>$cashierid,
                        'type'=>$payment['type'],
                        'type_value'=>$payment['type_value'],
                        'amount'=>$payment['amount'],
                        'remarks'=>$payment['remarks']
                    );
                    if($this->Order_payment->saveAll($datas['Order_payment']))
                    {
                        $mainpayid = $this->Order_payment->id;

                        $this->Order_split_payment->query("UPDATE order_split_payments SET main_payment_id = '$mainpayid',sync=0,local_sync=0 WHERE id='$splitPaymentId' and split_reference_id='$split_reference_id' and reference_id = '$reference_id' and status!=0");
                        
                        $finalpayment=0;
                        $finalamount=0;
                        $allpayments=$this->Order_payment->query("SELECT sum(amount) as pay_amount FROM `order_payments` WHERE reference_id='$reference_id' and status!=0");
                        if($allpayments){
                            $finalpayment=$allpayments[0][0]['pay_amount'];
                        }
                        if($transactions){
                            $finalamount=$transactions['Order_transaction']['amount'];
                        }
                        $amount_diff=$finalamount-$finalpayment;
                        if($amount_diff<=1){
                            
                            $this->Order_orderhistory->query("UPDATE order_orderhistories SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status = 1");
                            $this->Order_transaction->query("UPDATE order_transactions SET status = 2,payment_mode='$type_value',sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status!=0");
                            $this->Order_payment->query("UPDATE order_payments SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status!=0");
                            $this->Order_tax->query("UPDATE order_tax SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status != 0");
                            
                            do {
                                $pin = 'TX' . $cashierid . date('Y') . uniqid();
                            } while ($this->Order_table->find('first', array('fields' => 'Order_table.id', 'conditions' => array('Order_table.reference_id' => $pin))));
                            
                            $tablestatus = $this->Order_table->find('first', array('conditions'=>array('reference_id'=>$reference_id,'is_takeaway'=>1)));
                            if(!empty($tablestatus))
                            {   
                                $this->Order_table->query("UPDATE order_tables SET status=0,sync=0,local_sync=0,modified=NOW()  WHERE reference_id = '$reference_id'");
                            }else{
                                $this->Order_table->query("UPDATE order_tables SET customer_name='',customer_phone='',customer_address='',customer_pax=1,status = 1,reference_id='$pin',is_alert=0,sync=0,local_sync=0,modified=NOW() WHERE reference_id = '$reference_id'");
                            }
        
                            $stockupdate=$this->stock_update($reference_id);
                            if(!$stockupdate){
                                $response['status']= true;
                                $response['message']= "Payment Data Saved Successfully..! But stock not updated";
                                $response['full_payment']= true; 
                            }
                            $response['status']= true;
                            $response['message']= "Payment Data Saved Successfully..!";
                            $response['full_payment']= true;
                        }else{
                            if($split_amount_diff<1){
                                $response['status']= true;
                                $response['message']= "Payment Data Saved Successfully..!";
                                $response['full_payment']= true;
                            }else{
                                $response['status']= true;
                                $response['message']= "Payment Data Saved Successfully..!";
                                $response['full_payment']= false;
                            }
                        }
                    }
                }else{
                    $response['status']= false;
                    $response['message']= "Payment Data not saved Error:102";
                    $response['full_payment']= false;
                }
            }
        }else{
            
            foreach($data['payment'] as $payment){
                
                if($payment['amount']<1){
                    $response['status']= false;
                    $response['message']= "Amount is not valid..!";
                    return json_encode($response);
                }
                
                $datas['Order_payment']=array(
                    'reference_id'=>$reference_id,
                    'store_id'=>$store_id,
                    'device_id'=>$device_id,
                    'cashier_id'=>$cashierid,
                    'type'=>$payment['type'],
                    'type_value'=>$payment['type_value'],
                    'amount'=>$payment['amount'],
                    'remarks'=>$payment['remarks']
                );
                if($this->Order_payment->saveAll($datas['Order_payment']))
                {
                    $finalpayment=0;
                    $finalamount=0;
                    $allpayments=$this->Order_payment->query("SELECT sum(amount) as pay_amount FROM `order_payments` WHERE reference_id='$reference_id' and status!=0");
                    if($allpayments){
                        $finalpayment=$allpayments[0][0]['pay_amount'];
                    }
                    if($transactions){
                        $finalamount=$transactions['Order_transaction']['amount'];
                    }
                    $amount_diff=$finalamount-$finalpayment;
                    if($amount_diff<1){
                        
                        $this->Order_orderhistory->query("UPDATE order_orderhistories SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status = 1");
                        $this->Order_transaction->query("UPDATE order_transactions SET status = 2,payment_mode='$type_value',sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status!=0");
                        $this->Order_payment->query("UPDATE order_payments SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status!=0");
                        $this->Order_tax->query("UPDATE order_tax SET status = 2,sync=0,local_sync=0 WHERE reference_id = '$reference_id' and status != 0");
                        
                        do {
                            $pin = 'TX' . $cashierid . date('Y') . uniqid();
                        } while ($this->Order_table->find('first', array('fields' => 'Order_table.id', 'conditions' => array('Order_table.reference_id' => $pin))));
                        
                        $tablestatus = $this->Order_table->find('first', array('conditions'=>array('reference_id'=>$reference_id,'is_takeaway'=>1)));
                        if(!empty($tablestatus))
                        {   
                            $this->Order_table->query("UPDATE order_tables SET status=0,sync=0,local_sync=0,modified=NOW()  WHERE reference_id = '$reference_id'");
                        }else{
                            $this->Order_table->query("UPDATE order_tables SET customer_name='',customer_phone='',customer_address='',customer_pax=1,status = 1,reference_id='$pin',is_alert=0,sync=0,local_sync=0,modified=NOW() WHERE reference_id = '$reference_id'");
                        }
    
                        $stockupdate=$this->stock_update($reference_id);
                        if(!$stockupdate){
                            $response['status']= true;
                            $response['message']= "Payment Data Saved Successfully..! But stock not updated";
                            $response['full_payment']= true; 
                        }
                        $response['status']= true;
                        $response['message']= "Payment Data Saved Successfully..!";
                        $response['full_payment']= true;
                    }else{
                        $response['status']= true;
                        $response['message']= "Payment Data Saved Successfully..!";
                        $response['full_payment']= false;
                    }
                }else{
                    $response['status']= false;
                    $response['message']= "Payment Data not saved Error:102";
                    $response['full_payment']= false;
                }
            }
        }
        return json_encode($response);
    }
    
    public function update_split_fetch_unsettled_bill()
    {
        $cashierid = $_REQUEST['id'];
        $reference_id = $_REQUEST['reference_id'];
    
        // Validate cashier id
        if ($cashierid == '') {
            return json_encode([
                'status' => false,
                'message' => "Cashier Id Missing"
            ]);
        }
    
        // Validate reference id
        if ($reference_id == '') {
            return json_encode([
                'status' => false,
                'message' => "Reference Id Missing"
            ]);
        }
    
        // Validate user
        $users = $this->User->find('first', [
            'conditions' => ['User.id' => $cashierid, 'User.status' => 1]
        ]);
    
        if (empty($users)) {
            return json_encode([
                'status' => false,
                'message' => "User not found"
            ]);
        }
    
        $transactionitems = [];
        $finalamount = 0;
    
        $transactions = $this->Order_transaction->find('all', [
            'conditions' => ['reference_id' => $reference_id, 'status' => 2]
        ]);
        if (empty($transactions)){
            return json_encode([
                'status' => false,
                'message' => "Transaction Not Found"
            ]);
        }
        
        if($transactions[0]['Order_transaction']['is_split']){
            
            
            $splittransactions = $this->Order_split_transaction->find('all', [
                'fields' => [
                    'Order_split_transaction.*',
                    'SUM(Order_split_transaction.amount) AS total_amount'
                ],
                'conditions' => [
                    'Order_split_transaction.reference_id' => $reference_id,
                    'Order_split_transaction.status' => 2
                ],
                'group' => ['Order_split_transaction.id']
            ]);
            if (!empty($splittransactions)) {
        
                # ============================================================
                # ✅ RETURN ONLY SPLIT BILL DATA
                # ============================================================
                $finalamount=0;
                $finalpayment=0;
                
                foreach ($splittransactions as $split) {
                    $finalamount = $split[0]['total_amount'];
                    $split_id=$split['Order_split_transaction']['id'];
                    
                    $allpayments=$this->Order_split_payment->query("SELECT sum(amount) as pay_amount FROM `order_split_payments` WHERE split_txn_id='$split_id' and reference_id='$reference_id' and status=2");
                    if($allpayments){
                        $finalpayment=$allpayments[0][0]['pay_amount'];
                    }
                    $amount_diff=round(($finalamount-$finalpayment),2);
                    
                    if (!$split['Order_split_transaction']['remarks']) {
                        $split['Order_split_transaction']['remarks'] = '';
                    }
        
                    $split_reference = $split['Order_split_transaction']['reference_id'];
        
                    # ------------------------------------------------------------
                    # 🔹 FETCH SPLIT DISCOUNT PERCENTAGE
                    # ------------------------------------------------------------
        
                    $split_discount_percentage = "0";
        
                    $splitdiscper = $this->Order_tax->query("
                        SELECT discount_percentage 
                        FROM order_tax 
                        WHERE reference_id = '$split_reference'
                        AND status = 2 
                        AND discount_percentage != 0 
                        LIMIT 1
                    ");
        
                    if (!empty($splitdiscper)) {
                        $split_discount_percentage = number_format($splitdiscper[0]['order_tax']['discount_percentage'], 2);
                    }
        
                    # ------------------------------------------------------------
                    # 🔹 FETCH SPLIT KOT NUMBERS
                    # ------------------------------------------------------------
        
                    $split_kotQuery = $this->Order_split_orderhistory->query("
                        SELECT GROUP_CONCAT(DISTINCT(kot_number)) AS kot_numbers 
                        FROM order_split_orderhistories 
                        WHERE reference_id = '$split_reference'
                        AND status =2
                    ");
        
                    $split_kot_numbers = '';
                    if (!empty($split_kotQuery) && isset($split_kotQuery[0][0]['kot_numbers'])) {
                        $split_kot_numbers = $split_kotQuery[0][0]['kot_numbers'];
                    }
        
                    # ------------------------------------------------------------
                    # 🔹 ADD SPLIT TRANSACTION TO ARRAY
                    # ------------------------------------------------------------
        
                    $transactionitems[] = [
                        'id'                   => $split['Order_split_transaction']['id'],
                        'reference_id'         => $split['Order_split_transaction']['reference_id'],
                        'split_reference_id'   => $split['Order_split_transaction']['split_reference_id'] ?? '',
                        'orderno'              => $split['Order_split_transaction']['orderno'],
                        'device_id'            => $split['Order_split_transaction']['device_id'],
                        'cashier_id'           => $split['Order_split_transaction']['cashier_id'],
                        'table_number'         => $split['Order_split_transaction']['table_number'],
                        'price'                => $split['Order_split_transaction']['price'],
                        'total_tax'            => $split['Order_split_transaction']['total_tax'],
                        'servicecharge'        => $split['Order_split_transaction']['servicecharge'],
                        'discount'             => $split['Order_split_transaction']['discount'],
                        'discount_percentage'  => $split_discount_percentage,
                        'delivery_charge'      => $split['Order_split_transaction']['delivery_charge'],
                        'packing_charge'       => $split['Order_split_transaction']['packing_charge'],
                        'amount'               => $split['Order_split_transaction']['amount'],
                        'round'                => $split['Order_split_transaction']['round'],
                        'name'                 => $split['Order_split_transaction']['name'],
                        'phone'                => $split['Order_split_transaction']['phone'],
                        'address'              => $split['Order_split_transaction']['address'],
                        'remarks'              => $split['Order_split_transaction']['remarks'],
                        'status'               => $split['Order_split_transaction']['status'],
                        'tokenno'              => $split['Order_split_transaction']['tokenno'],
                        'createtime'           => $split['Order_split_transaction']['createtime'],
                        'created'              => $split['Order_split_transaction']['created'],
                        'pax'                  => $split['Order_split_transaction']['pax'],
                        'kot_number'           => $split_kot_numbers
                    ];
                }
            
                # RETURN SPLIT RESPONSE
                return json_encode([
                    'status' => true,
                    'is_split_bill' => true,
                    'data' => $transactionitems
                ]);
            }
        }else{
            # ============================================================
            # 🔍 STEP 1: CHECK IF SPLIT TRANSACTIONS EXIST
            # ============================================================
            
            foreach ($transactions as $orders) {
                $finalamount=$orders['Order_transaction']['amount'];
                
                $finalpayment=0;
                $allpayments=$this->Order_payment->query("SELECT sum(amount) as pay_amount FROM `order_payments` WHERE reference_id='$reference_id' and status!=0");
                if($allpayments){
                    $finalpayment=$allpayments[0][0]['pay_amount'];
                }
                $amount_diff=round(($finalamount-$finalpayment),2);
                
                if (!$orders['Order_transaction']['remarks']) {
                    $orders['Order_transaction']['remarks'] = '';
                }
    
                $order_ref = $orders['Order_transaction']['reference_id'];
                
                # ------------------------------------------------------------
                # 🔹 DISCOUNT %
                # ------------------------------------------------------------
    
                $discount_percentage = "0";
    
                $discper = $this->Order_tax->query("
                    SELECT discount_percentage 
                    FROM order_tax 
                    WHERE reference_id = '$order_ref'
                    AND status != 0 
                    AND discount_percentage != 0 
                    LIMIT 1
                ");
    
                if (!empty($discper)) {
                    $discount_percentage = number_format($discper[0]['order_tax']['discount_percentage'], 2);
                }
    
                # ------------------------------------------------------------
                # 🔹 KOT NUMBERS
                # ------------------------------------------------------------
    
                $kotQuery = $this->Order_orderhistory->query("
                    SELECT GROUP_CONCAT(DISTINCT(kot_number)) AS kot_numbers 
                    FROM order_orderhistories 
                    WHERE reference_id = '$order_ref'
                    AND status != 0
                ");
    
                $kot_numbers = '';
                if (!empty($kotQuery) && isset($kotQuery[0][0]['kot_numbers'])) {
                    $kot_numbers = $kotQuery[0][0]['kot_numbers'];
                }
    
                # ------------------------------------------------------------
                # 🔹 ADD NORMAL TRANSACTION
                # ------------------------------------------------------------
    
                $transactionitems[] = [
                    'id'                   => $orders['Order_transaction']['id'],
                    'reference_id'         => $orders['Order_transaction']['reference_id'],
                    'split_reference_id'   => '',
                    'orderno'              => $orders['Order_transaction']['orderno'],
                    'device_id'            => $orders['Order_transaction']['device_id'],
                    'cashier_id'           => $orders['Order_transaction']['cashier_id'],
                    'table_number'         => $orders['Order_transaction']['table_number'],
                    'price'                => $orders['Order_transaction']['price'],
                    'total_tax'            => $orders['Order_transaction']['total_tax'],
                    'servicecharge'        => $orders['Order_transaction']['servicecharge'],
                    'discount'             => $orders['Order_transaction']['discount'],
                    'discount_percentage'  => $discount_percentage,
                    'delivery_charge'      => $orders['Order_transaction']['delivery_charge'],
                    'packing_charge'       => $orders['Order_transaction']['packing_charge'],
                    'amount'               => $orders['Order_transaction']['amount'],
                    'round'                => $orders['Order_transaction']['round'],
                    'name'                 => $orders['Order_transaction']['name'],
                    'phone'                => $orders['Order_transaction']['phone'],
                    'address'              => $orders['Order_transaction']['address'],
                    'remarks'              => $orders['Order_transaction']['remarks'],
                    'status'               => $orders['Order_transaction']['status'],
                    'tokenno'              => $orders['Order_transaction']['tokenno'],
                    'createtime'           => $orders['Order_transaction']['createtime'],
                    'created'              => $orders['Order_transaction']['created'],
                    'pax'                  => $orders['Order_transaction']['pax'],
                    'is_split'             => $orders['Order_transaction']['is_split'],
                    'split_count'          => $orders['Order_transaction']['split_count'],
                    'split_type'           => $orders['Order_transaction']['split_type'],
                    'kot_number'           => $kot_numbers
                ];
            }
            
            return json_encode([
                'status' => true,
                'is_split_bill' => false,
                'data' => $transactionitems
            ]);
        }
    }
    
    public function fetch_printdata_gstwise_itemwise()
    {
        $cashierid = $_REQUEST['id'];
        $reference_id = $_REQUEST['reference_id'];
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "User Id Missing",
            );
            return json_encode($response);
        }
        if($reference_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Reference Id Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        $orderitems=[];
        $order_punch_by='';
        
        $orderss = $this->Order_orderhistory->query("SELECT *,  ( SELECT name FROM users WHERE id = ( SELECT cashier_id FROM order_orderhistories WHERE reference_id = '$reference_id'  AND status != 0 ORDER BY id ASC LIMIT 1 ) LIMIT 1 ) AS first_cashier_name FROM `order_orderhistories` WHERE reference_id='$reference_id' and status!=0");
        if(!empty($orderss))
        {
            $grouped_orders = array();
            foreach($orderss as $orders){
                $product_id=$orders['order_orderhistories']['product_id'];
                $order_id=$orders['order_orderhistories']['id'];
                $order_punch_by = $orders[0]['first_cashier_name'];

                $selected_modifiers=[];
                $orders_modifiers = $this->Order_modifier->query("SELECT * FROM `order_modifier` WHERE reference_id='$reference_id' and product_id='$product_id' and orderhistory_id='$order_id' and status!=0");
                foreach($orders_modifiers as $orders_modifier){
                    $modifiers=$orders_modifier['order_modifier'];
                    $selected_modifiers[]=array(
                        'modifier_group_id' => $modifiers['modifier_group_id'],
                        'modifier_group_name' => $modifiers['modifier_group_name'],
                        'modifier_id' => $modifiers['modifier_id'],
                        'modifier_name' => $modifiers['modifier_name'],
                        'modifier_price' => $modifiers['modifier_price'],
                    );
                }
                
                $remarks = isset($orders['order_orderhistories']['remarks']) ? trim($orders['order_orderhistories']['remarks']) : '';
                $kot_num = isset($orders['order_orderhistories']['kot_number']) ? trim($orders['order_orderhistories']['kot_number']) : '';
                $qty = (float)$orders['order_orderhistories']['quantity'];
                $total_tax = (float)$orders['order_orderhistories']['total_tax'];
                $total_price = (float)$orders['order_orderhistories']['total_price'];
                $discount = (float)($orders['order_orderhistories']['discount'] ?? 0);
                $price = isset($orders['order_orderhistories']['price']) ? (float)$orders['order_orderhistories']['price'] : 0;
                $group_key = $product_id . '_' . $price;

                if (!isset($grouped_orders[$group_key])) {
                    $grouped_orders[$group_key] = array(
                        'id' => $orders['order_orderhistories']['id'],
                        'reference_id' =>  $orders['order_orderhistories']['reference_id'],
                        'cashier_id' =>  $orders['order_orderhistories']['cashier_id'],
                        'group_id' =>  $orders['order_orderhistories']['group_id'],
                        'category' =>  $orders['order_orderhistories']['category'],
                        'category_name' =>  $orders['order_orderhistories']['category_name'],
                        'kds' =>  $orders['order_orderhistories']['kds'],
                        'kot_number' =>  $kot_num,
                        'product_id' =>  $orders['order_orderhistories']['product_id'],
                        'product_name' =>  $orders['order_orderhistories']['product_name'],
                        'quantity' =>  $qty,
                        'price' =>  $orders['order_orderhistories']['price'],
                        'total_tax' =>  $total_tax,
                        'total_price' =>  $total_price,
                        'discount' =>  $discount,
                        'table_number' =>  $orders['order_orderhistories']['table_number'],
                        'remarks' =>  $remarks,
                        'selected_modifiers' => $selected_modifiers,
                        'status' =>  $orders['order_orderhistories']['status'],
                        'created' =>  $orders['order_orderhistories']['created'],
                        '_kots' => !empty($kot_num) ? array($kot_num) : array(),
                        '_remarks' => !empty($remarks) ? array($remarks) : array()
                    );
                } else {
                    $grouped_orders[$group_key]['quantity'] += $qty;
                    $grouped_orders[$group_key]['total_tax'] = round($grouped_orders[$group_key]['total_tax'] + $total_tax, 2);
                    $grouped_orders[$group_key]['total_price'] = round($grouped_orders[$group_key]['total_price'] + $total_price, 2);
                    $grouped_orders[$group_key]['discount'] = round($grouped_orders[$group_key]['discount'] + $discount, 2);

                    if (!empty($kot_num) && !in_array($kot_num, $grouped_orders[$group_key]['_kots'])) {
                        $grouped_orders[$group_key]['_kots'][] = $kot_num;
                        $grouped_orders[$group_key]['kot_number'] = implode(', ', $grouped_orders[$group_key]['_kots']);
                    }
                    if (!empty($remarks) && !in_array($remarks, $grouped_orders[$group_key]['_remarks'])) {
                        $grouped_orders[$group_key]['_remarks'][] = $remarks;
                        $grouped_orders[$group_key]['remarks'] = implode(', ', $grouped_orders[$group_key]['_remarks']);
                    }
                    if (!empty($selected_modifiers)) {
                        foreach ($selected_modifiers as $mod) {
                            $modExists = false;
                            foreach ($grouped_orders[$group_key]['selected_modifiers'] as $existingMod) {
                                if ($existingMod['modifier_id'] == $mod['modifier_id']) {
                                    $modExists = true;
                                    break;
                                }
                            }
                            if (!$modExists) {
                                $grouped_orders[$group_key]['selected_modifiers'][] = $mod;
                            }
                        }
                    }
                }
            }

            foreach ($grouped_orders as $gItem) {
                unset($gItem['_kots']);
                unset($gItem['_remarks']);
                $gItem['quantity'] = (string)$gItem['quantity'];
                $gItem['total_tax'] = (string)$gItem['total_tax'];
                $gItem['total_price'] = (string)$gItem['total_price'];
                $gItem['discount'] = (string)$gItem['discount'];
                $orderitems[] = $gItem;
            }
        }

        $reeloDiscountMsg = '';
        $this->loadModel('ReeloDiscount');
        $reeloDiscsForMsg = $this->ReeloDiscount->find('all', array(
            'conditions' => array(
                'ReeloDiscount.reference_id' => $reference_id,
                'ReeloDiscount.status' => 1,
                'ReeloDiscount.discount_on' => 'item'
            ),
            'recursive' => -1
        ));

        if (!empty($reeloDiscsForMsg)) {
            $this->loadModel('Order_orderhistory');
            $activeOhItems = $this->Order_orderhistory->find('all', array(
                'conditions' => array(
                    'Order_orderhistory.reference_id' => $reference_id,
                    'Order_orderhistory.status !=' => 0
                ),
                'fields' => array('Order_orderhistory.product_id', 'Order_orderhistory.id'),
                'recursive' => -1
            ));
            $activeItemIds = array();
            foreach ($activeOhItems as $aoh) {
                if (isset($aoh['Order_orderhistory']['product_id'])) {
                    $activeItemIds[] = (string)$aoh['Order_orderhistory']['product_id'];
                }
                if (isset($aoh['Order_orderhistory']['id'])) {
                    $activeItemIds[] = (string)$aoh['Order_orderhistory']['id'];
                }
            }

            $prodMap = array();
            foreach ($orderitems as $oitem) {
                if (isset($oitem['product_id'])) {
                    $prodMap[(string)$oitem['product_id']] = $oitem['product_name'] ?? '';
                }
                if (isset($oitem['id'])) {
                    $prodMap[(string)$oitem['id']] = $oitem['product_name'] ?? '';
                }
            }

            $msgParts = array();
            foreach ($reeloDiscsForMsg as $rdisc) {
                $itemJsonStr = $rdisc['ReeloDiscount']['item_json'] ?? '';
                $discType = $rdisc['ReeloDiscount']['discount_type'] ?? '';
                $discVal = $rdisc['ReeloDiscount']['discount_value'] ?? $rdisc['ReeloDiscount']['discount_type_value'] ?? '';

                $formattedDisc = '';
                if (strcasecmp($discType, 'percentage') === 0) {
                    $formattedDisc = floatval($discVal) . '%';
                } else {
                    $formattedDisc = 'Rs.' . floatval($discVal);
                }

                $itemsArr = json_decode($itemJsonStr, true);
                if (is_array($itemsArr) && !empty($itemsArr)) {
                    $itemNames = array();
                    foreach ($itemsArr as $iObj) {
                        if (is_array($iObj)) {
                            $pId = $iObj['product_id'] ?? $iObj['_id'] ?? $iObj['id'] ?? null;
                            $q = $iObj['quantity'] ?? null;
                        } else if (is_scalar($iObj)) {
                            $pId = (string)$iObj;
                            $q = null;
                        } else {
                            $pId = null;
                            $q = null;
                        }

                        if ($pId !== null && in_array((string)$pId, $activeItemIds, true)) {
                            $pName = $prodMap[(string)$pId] ?? '';
                            if (empty($pName)) {
                                $pName = 'Item ' . $pId;
                            }
                            if ($q !== null && intval($q) > 0) {
                                $itemNames[] = intval($q) . 'x ' . $pName;
                            } else {
                                $itemNames[] = $pName;
                            }
                        }
                    }
                    if (!empty($itemNames)) {
                        $msgParts[] = $formattedDisc . ' Off on ' . implode(', ', $itemNames);
                    } else {
                        $msgParts[] = $formattedDisc . ' Off on selected items';
                    }
                } else {
                    $msgParts[] = $formattedDisc . ' Off on item level';
                }
            }
            if (!empty($msgParts)) {
                $reeloDiscountMsg = implode('; ', $msgParts);
            }
        }

        $finalamount=0;
        $transactionitems=[];
        $transactions = $this->Order_transaction->query(
            "SELECT GROUP_CONCAT(id) as id,reference_id,GROUP_CONCAT(orderno) as orderno,device_id,cashier_id,table_number,
            SUM(price) as price,SUM(total_tax) as total_tax,SUM(servicecharge) as servicecharge,SUM(discount) as discount,
            SUM(discount_type_value) as discount_type_value,SUM(delivery_charge) as delivery_charge,SUM(packing_charge) as packing_charge,
            SUM(amount) as amount,SUM(round) as round,discount_type ,name,phone,address,GROUP_CONCAT(remarks) as remarks,status,GROUP_CONCAT(tokenno) as tokenno,
            createtime,created,pax,(select name from users where id=order_transactions.cashier_id) as cash_name FROM `order_transactions` WHERE reference_id='$reference_id' and status!=0");
        
        if(!empty($transactions))
        {
            foreach($transactions as $orders){
                if(!$orders[0]['remarks']){
                    $orders[0]['remarks']='';
                }
                $finalamount=$orders[0]['amount'];
                $cashierid=$orders[0]['cashier_id'];
                $reference_id=$orders['order_transactions']['reference_id'];
                
                $discper = $this->Order_tax->query("SELECT discount_percentage FROM `order_tax` WHERE reference_id='$reference_id' and status!=0 and discount_percentage!=0 limit 1");
                if(!empty($discper))
                {
                    $discount_percentage=number_format($discper[0]['order_tax']['discount_percentage'],2);
                }
                if(!isset($discount_percentage)){
                    $discount_percentage="0";
                }
                
                $kotQuery = $this->Order_orderhistory->query("
                    SELECT GROUP_CONCAT(DISTINCT(kot_number)) AS kot_numbers 
                    FROM order_orderhistories 
                    WHERE reference_id = '$reference_id' and status!=0
                ");
        
                $kot_numbers = '';
                if (!empty($kotQuery) && isset($kotQuery[0][0]['kot_numbers'])) {
                    $kot_numbers = $kotQuery[0][0]['kot_numbers'];
                }
                
                $transactionitems[]=array(
                    'id' => $orders[0]['id'],
                    'reference_id' =>  $orders['order_transactions']['reference_id'],
                    'orderno' =>  $orders[0]['orderno'],
                    'device_id' =>  $orders['order_transactions']['device_id'],
                    'cashier_id' =>  $orders['order_transactions']['cashier_id'],
                    'cashier_name' => isset($orders[0]['cash_name']) ? $orders[0]['cash_name'] : '',
                    'table_number' =>  $orders['order_transactions']['table_number'],
                    'price' =>  number_format($orders[0]['price'],2),
                    'total_tax' =>  number_format($orders[0]['total_tax'],2),
                    'servicecharge' =>  $orders[0]['servicecharge'],
                    'discount' =>  $orders[0]['discount'],
                    'discount_percentage' =>  $discount_percentage,
                    'discount_type' =>  $orders['order_transactions']['discount_type'],
                    'discount_type_value' =>  $orders[0]['discount_type_value'],
                    'taxable_amount' => number_format(($orders[0]['price'] + $orders[0]['servicecharge']) - $orders[0]['discount'], 2),
                    'delivery_charge' =>  $orders[0]['delivery_charge'],
                    'packing_charge' =>  $orders[0]['packing_charge'],
                    'amount' =>  $orders[0]['amount'],
                    'round' =>  $orders[0]['round'],
                    'name' =>  $orders['order_transactions']['name'],
                    'phone' =>  $orders['order_transactions']['phone'],
                    'address' =>  $orders['order_transactions']['address'],
                    'remarks' =>  $orders['order_transactions']['remarks'],
                    'status' =>  $orders['order_transactions']['status'],
                    'tokenno' =>  $orders[0]['tokenno'],
                    'createtime' =>  $orders['order_transactions']['createtime'],
                    'pax' =>  $orders['order_transactions']['pax'],
                    'created' =>  $orders['order_transactions']['created'],
                    'kot_number' => $kot_numbers
                );
            }
        }
        $paymentitems=[];
        $payments = $this->Order_payment->find('all', array('conditions'=>array('reference_id'=>$reference_id,'status !='=>0)));
        if(!empty($payments))
        {
            foreach($payments as $orders){
                if(!isset($orders['Order_payment']['remarks'])){
                    $orders['Order_payment']['remarks']='';
                }
                $paymentitems[]=array(
                    'id' => $orders['Order_payment']['id'],
                    'reference_id' =>  $orders['Order_payment']['reference_id'],
                    'cashier_id' =>  $orders['Order_payment']['cashier_id'],
                    'type' =>  $orders['Order_payment']['type'],
                    'type_value' =>  $orders['Order_payment']['type_value'],
                    'amount' =>  $orders['Order_payment']['amount'],
                    'status' =>  $orders['Order_payment']['status'],
                    'remarks' =>  $orders['Order_payment']['remarks'],
                    'created' =>  $orders['Order_payment']['created']
                );
            }
        }
        $taxitems=[];
        $taxes = $this->Order_tax->query("SELECT tax_id,tax_name,tax_percentage,sum(tax_value) as tax_value FROM `order_tax` WHERE reference_id='$reference_id' and tax_percentage!=0 and status!=0 GROUP by tax_id");
        if(!empty($taxes))
        {
            foreach($taxes as $tax){
                $taxitems[]=array(
                    'tax_id' => $tax['order_tax']['tax_id'],
                    'tax_name' =>  $tax['order_tax']['tax_name'],
                    'tax_percentage' =>  $tax['order_tax']['tax_percentage'],
                    'tax_value' =>  "" .round($tax[0]['tax_value'],2)
                );
            }
        }
        
        $finalpayment=0;
        $allpayments=$this->Order_payment->query("SELECT sum(amount) as pay_amount FROM `order_payments` WHERE reference_id='$reference_id' and status=2");
        if($allpayments){
            $finalpayment=$allpayments[0][0]['pay_amount'];
        }
        
        $amount_diff=round(($finalamount-$finalpayment),2);
        if ($amount_diff < 1 && $amount_diff >= 0) {
            $amount_diff = 0;
        }
        
        $cashier_name='';
        $cashname=$this->User->query("SELECT name FROM `users` WHERE id='$cashierid'");
        if($cashname){
           $cashier_name =$cashname[0]['users']['name'];
        }
        
        $printeritems=[];
        $targetStoreId = !empty($users['User']['location_id']) ? $users['User']['location_id'] : (!empty($transactions[0]['Order_transaction']['store_id']) ? $transactions[0]['Order_transaction']['store_id'] : '');
        $printerCond = !empty($targetStoreId) ? "status=1 AND store_id='$targetStoreId'" : "status=1";
        $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE $printerCond");
        if(empty($printerss) && !empty($targetStoreId)){
            $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE status=1");
        }
        if(!empty($printerss))
        {
            foreach($printerss as $printers){
                $printeritems[]=array(
                    'id' => $printers['pos_printers']['id'],
                    'store_id' =>  $printers['pos_printers']['store_id'],
                    'name' =>  $printers['pos_printers']['name'],
                    'kds' =>  $printers['pos_printers']['kds'],
                    'ip' =>  $printers['pos_printers']['ip'],
                    'status' =>  $printers['pos_printers']['status']
                );
            }
        }
        
        $brandsale=[];
        $brandsaless = $this->Order_transaction->query("SELECT store_id,(SELECT name from locations WHERE id=order_transactions.store_id) as brandname,(SELECT print_line4 from locations WHERE id=order_transactions.store_id) as brandgst,orderno,(SELECT GROUP_CONCAT(CONCAT(type_value, ' - ', amount)) from order_payments WHERE status=2 and reference_id=order_transactions.reference_id and store_id=order_transactions.store_id) as payment_mode FROM `order_transactions` WHERE reference_id='$reference_id' and status!=0 GROUP by store_id");
        if(!empty($brandsaless))
        {
            foreach($brandsaless as $brandsales){
                $brandsale[]=array(
                   'store_id'     => $brandsales['order_transactions']['store_id'] ?? '',
                'brandname'    => $brandsales[0]['brandname'] ?? '',
                'brandgst'     => $brandsales[0]['brandgst'] ?? '',
                'orderno'      => $brandsales['order_transactions']['orderno'] ?? '',
                'payment_mode' => $brandsales[0]['payment_mode'] ?? ''
                );
            }
        }
        
        $response= array('status'=> true,
                'message'=> "success",
                'cashier_name'=>$cashier_name,
                'order_punch_by'=>$order_punch_by,
                'orders'=>$orderitems,
                'transactions'=>$transactionitems,
                'payments'=>$paymentitems,
                'taxes'=>$taxitems,
                'printers'=>$printeritems,
                'brandsale'=>$brandsale,
                'remaining_amount'=>number_format($amount_diff, 2, '.', ''),
                'reelo_discount_message' => $reeloDiscountMsg
            );
            
        return json_encode($response);
    }
    
    public function split_reprint_data_itemwise()
    {
        $cashierid = $_REQUEST['id'];
        $reference_id = $_REQUEST['reference_id'];
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "User Id Missing",
            );
            return json_encode($response);
        }
        if($reference_id==''){
            $response =array(
                'status'=> false,
                'message'=> "Reference Id Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        $transactions = $this->Order_transaction->find('all', [
            'conditions' => ['reference_id' => $reference_id, 'status !=' => 0]
        ]);
        if (empty($transactions)){
            return json_encode([
                'status' => false,
                'message' => "Transaction Not Found"
            ]);
        }
        $order_punch_by='';
        $reeloDiscountMsg = '';
        
