                        'name' =>  $orders['Order_transaction']['name'],
                        'phone' =>  $orders['Order_transaction']['phone'],
                        'address' =>  $orders['Order_transaction']['address'],
                        'remarks' =>  $orders['Order_transaction']['remarks'],
                        'status' =>  $orders['Order_transaction']['status'],
                        'tokenno' =>  $orders['Order_transaction']['tokenno'],
                        'createtime' =>  $orders['Order_transaction']['createtime'],
                        'created' =>  $orders['Order_transaction']['created'],
                        'pax' =>  $orders['Order_transaction']['pax'],
                        'is_split'             => $orders['Order_transaction']['is_split'],
                        'split_count'          => $orders['Order_transaction']['split_count'],
                        'split_type'           => $orders['Order_transaction']['split_type'],
                        'kot_number' => $kot_numbers
                    );
                }
            }
            $paymentitems=[];
            $payments = $this->Order_payment->find('all', array('conditions'=>array('reference_id'=>$reference_id,'status !='=>0)));
            if(!empty($payments))
            {
                foreach($payments as $orders){
                    if(!isset($orders['Order_payment']['remarks'])){
                        $orders['Order_payment']['remarks']='';
                    }
                    $paymentitems[]=array(
                        'id' => $orders['Order_payment']['id'],
                        'split_pay_id' => '0',
                        'split_reference_id' => '0',
                        'reference_id' =>  $orders['Order_payment']['reference_id'],
                        'cashier_id' =>  $orders['Order_payment']['cashier_id'],
                        'type' =>  $orders['Order_payment']['type'],
                        'type_value' =>  $orders['Order_payment']['type_value'],
                        'amount' =>  $orders['Order_payment']['amount'],
                        'status' =>  $orders['Order_payment']['status'],
                        'remarks' =>  $orders['Order_payment']['remarks'],
                        'created' =>  $orders['Order_payment']['created']
                    );
                }
            }
            $taxitems=[];
            $taxes = $this->Order_tax->query("SELECT tax_id,tax_name,tax_percentage,sum(tax_value) as tax_value FROM `order_tax` WHERE reference_id='$reference_id' and tax_percentage!=0 and status!=0 GROUP by tax_id");
            if(!empty($taxes))
            {
                foreach($taxes as $tax){
                    $taxitems[]=array(
                        'tax_id' => $tax['order_tax']['tax_id'],
                        'tax_name' =>  $tax['order_tax']['tax_name'],
                        'tax_percentage' =>  $tax['order_tax']['tax_percentage'],
                        'tax_value' =>  "" .round($tax[0]['tax_value'],2)
                    );
                }
            }
            $finalpayment=0;
            $allpayments=$this->Order_payment->query("SELECT sum(amount) as pay_amount FROM `order_payments` WHERE reference_id='$reference_id' and status!=0");
            if($allpayments){
                $finalpayment=$allpayments[0][0]['pay_amount'];
            }
            $amount_diff=round(($finalamount-$finalpayment),2);
            if ($amount_diff < 1 && $amount_diff >= 0) {
                $amount_diff = 0;
            }
        }
        
        $cashier_name='';
        $cashname=$this->User->query("SELECT name FROM `users` WHERE id='$cashierid'");
        if($cashname){
           $cashier_name =$cashname[0]['users']['name'];
        }
        
        $printeritems=[];
        $targetStoreId = !empty($users['User']['location_id']) ? $users['User']['location_id'] : (!empty($transactions[0]['Order_transaction']['store_id']) ? $transactions[0]['Order_transaction']['store_id'] : '');
        $printerCond = !empty($targetStoreId) ? "status=1 AND store_id='$targetStoreId'" : "status=1";
        $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE $printerCond");
        if(empty($printerss) && !empty($targetStoreId)){
            $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE status=1");
        }
        if(!empty($printerss))
        {
            foreach($printerss as $printers){
                $printeritems[]=array(
                    'id' => $printers['pos_printers']['id'],
                    'store_id' =>  $printers['pos_printers']['store_id'],
                    'name' =>  $printers['pos_printers']['name'],
                    'kds' =>  $printers['pos_printers']['kds'],
                    'ip' =>  $printers['pos_printers']['ip'],
                    'status' =>  $printers['pos_printers']['status']
                );
            }
        }

        $brandsale=[];
        $brandsaless = $this->Order_transaction->query("SELECT store_id,(SELECT name from locations WHERE id=order_transactions.store_id) as brandname,(SELECT print_line4 from locations WHERE id=order_transactions.store_id) as brandgst,orderno,(SELECT GROUP_CONCAT(CONCAT(type_value, ' - ', amount)) from order_payments WHERE status=2 and reference_id=order_transactions.reference_id and store_id=order_transactions.store_id) as payment_mode FROM `order_transactions` WHERE reference_id='$reference_id' and status!=0 GROUP by store_id");
        if(!empty($brandsaless))
        {
            foreach($brandsaless as $brandsales){
                $brandsale[]=array(
                   'store_id'     => $brandsales['order_transactions']['store_id'] ?? '',
                    'brandname'    => $brandsales[0]['brandname'] ?? '',
                    'brandgst'     => $brandsales[0]['brandgst'] ?? '',
                    'orderno'      => $brandsales['order_transactions']['orderno'] ?? '',
                    'payment_mode' => $brandsales[0]['payment_mode'] ?? ''
                );
            }
        }
        
        $response= array('status'=> true,
                'message'=> "success",
                'cashier_name'=>$cashier_name,
                'order_punch_by'=>$order_punch_by,
                'orders'=>$orderitems,
                'transactions'=>$transactionitems,
                'payments'=>$paymentitems,
                'taxes'=>$taxitems,
                'printers'=>$printeritems,
                'brandsale'=>$brandsale,
                'remaining_amount'=>number_format($amount_diff, 2, '.', ''),
                'reelo_discount_message' => $reeloDiscountMsg
            );
        return json_encode($response);
    }

    public function bill_preview_with_discount_itemwise()
    {
        $cashierid = $_REQUEST['id'];
        $ref_id=$_REQUEST['reference_id'];
        $sc = $_REQUEST['service_charge'];
        $disc=$_REQUEST['discount'];
        $type = $_REQUEST['type'];
        $dish_type = $_REQUEST['kds'];
        $discount_type_value=$disc;
        
        $response = array();
        if($cashierid==''){
            $response =array(
                'status'=> false,
                'message'=> "User Id Missing",
            );
            return json_encode($response);
        }
        
        if($disc==''){
            $response =array(
                'status'=> false,
                'message'=> "Discount Missing",
            );
            return json_encode($response);
        }
        
        if($type==''){
            $response =array(
                'status'=> false,
                'message'=> "Discount Type Missing",
            );
            return json_encode($response);
        }
        
        if($dish_type==''){
            $response =array(
                'status'=> false,
                'message'=> "Dish Type Missing",
            );
            return json_encode($response);
        }
        
        $users = $this->User->find('first', array('conditions'=>array('User.id'=>$cashierid,'User.status'=>1)));
        if(empty($users))
        {
            $response =array(
                'status'=> false,
                'message'=> "User not found",
            );
            return json_encode($response);
        }
        
        $todayDate = date("Y-m-d");
        
        $ref_id = [$ref_id]; // convert initial ref id to array
        
        $refid = []; // T9-fix: no merged tables guard

        $mergetablecheck = $this->Order_table_tracking->find('all', [
            'conditions' => [
                'Order_table_tracking.main_table_ref_id' => $ref_id[0],
                'Order_table_tracking.status' => 1,
                "DATE(Order_table_tracking.created) =" => $todayDate
            ]
        ]);
        if (!empty($mergetablecheck)) {
            foreach ($mergetablecheck as $merge) {
                $ref_id[] = $merge['Order_table_tracking']['merged_table_ref_id']; 
            }
        }
        $ref_in = "'" . implode("','", $ref_id) . "'";
        
        
        if($type==0){
            if(!empty($disc)){
                $coup = $this->Coupon->find('first', array('conditions'=>array('Coupon.code'=>$disc,'Coupon.expiry_date >='=>$todayDate,'Coupon.status'=>1)));
                if(empty($coup))
                {
                    $response =array(
                        'status'=> false,
                        'message'=> "Coupon not found Or Coupon Expired",
                    );
                    return json_encode($response);
                }
                $disc=$coup['Coupon']['value'];
            }else{
                $disc=0;
            }
        }
        
        if($type==1){
            $disc=$disc;
        }
        
        if($type==2){
            if($dish_type=='all'){
                $subtotals = $this->Order_orderhistory->query("SELECT SUM(total_price) as subtotal FROM `order_orderhistories` WHERE status!=0 and reference_id IN ($ref_in)");
            }else{
                $subtotals = $this->Order_orderhistory->query("SELECT SUM(total_price) as subtotal FROM `order_orderhistories` WHERE status!=0 and reference_id IN ($ref_in) and dish_type=$dish_type");
            }
            
            if($subtotals){
                $subtotal=$subtotals[0][0]['subtotal'];
                if($subtotal){
                    $disc=(($disc*100)/$subtotal);
                }else{
                    $response =array(
                        'status'=> false,
                        'message'=> "Bill Not Found",
                    );
                    return json_encode($response);
                }
            }else{
                $response =array(
                    'status'=> false,
                    'message'=> "Bill Not Found",
                );
                return json_encode($response);
            }
        }
        
        if($disc>99){
            $response =array(
                'status'=> false,
                'message'=> "Discount is not more than 99%",
            );
            return json_encode($response);
        }
        
        $kdsarray = explode(",", $kds);
        
        
        if($dish_type!='all'){
            $kdschk = $this->Order_orderhistory->find('first', array('conditions'=>array('Order_orderhistory.reference_id'=>$ref_id,'Order_orderhistory.dish_type'=>$dish_type,'Order_orderhistory.status !='=>0)));
        }else{
            $kdschk = $this->Order_orderhistory->find('first', array('conditions'=>array('Order_orderhistory.reference_id'=>$ref_id,'Order_orderhistory.status !='=>0)));
        }
        if(empty($kdschk))
        {
            $response =array(
                'status'=> false,
                'message'=> "No Item found for this KDS.",
            );
            return json_encode($response);
        }
        
        $packagechk = $this->Order_orderhistory->find('first', array('conditions'=>array('Order_orderhistory.reference_id'=>$ref_id,'Order_orderhistory.package'=>1,'Order_orderhistory.status !='=>0)));
        if(!empty($packagechk))
        {
            $response =array(
                'status'=> false,
                'message'=> "You can not Merge Discount with package.",
            );
            return json_encode($response);
        }
        
        if($disc>=0){
            $checkdiscount=$this->Order_orderhistory->find('first',array('conditions'=>array('Order_orderhistory.discount > '=>0,'Order_orderhistory.cashier_id'=>$cashierid,'Order_orderhistory.status'=>2,'Order_orderhistory.reference_id'=>$ref_id)));
            if(!empty($checkdiscount)){
                $response['status']= false;
                $response['message']= "Discount can not merge with item level discount";
                return json_encode($response);     
            }
        }else{
            $response['status']= false;
            $response['message']= "please check discount value";
            return json_encode($response);  
        }
        
        if($dish_type=='all'){
            $orderdata=$this->ordercomputewithdiscounttemp($ref_id,$cashierid,$sc,$disc);
        }else{
            $orderdata=$this->ordercomputewithkdstemp($ref_id,$cashierid,$sc,$disc,$dish_type);
        }
        
        if($orderdata['status'])
        {
            $totalservicechg=$orderdata['totalservicechg'];
            $totalprice=$orderdata['totalprice'];
            $totaltax=$orderdata['totaltax'];
            $totaldiscount=$orderdata['totaldiscount'];
            $totalamount=round((($totalprice+$totaltax+$totalservicechg)-$totaldiscount),2);
            
            
            $orderitems=[];
            $orderss = $this->Order_orderhistory->query("SELECT id,reference_id,group_id,cashier_id,category,category_name,kds,product_id,product_name,SUM(quantity) as quantity,price,sum(total_tax) as total_tax,sum(total_tax_percentage) as total_tax_percentage,sum(total_price) as total_price,SUM(discount) as discount,table_number,remarks,device_id,status,created FROM `order_orderhistories` WHERE reference_id IN ($ref_in) and status!=0 group BY product_id, price");
            
            if(!empty($orderss))
            {
                foreach($orderss as $orders){
                    if(!isset($orders['order_orderhistories']['remarks'])){
                        $orders['order_orderhistories']['remarks']='';
                    }
                    
                    $taxesitems=[];
                    $taxess = $this->Catalog_product_tax->find('all', array('conditions'=>array('Catalog_product_tax.product_id'=>$orders['order_orderhistories']['product_id'],'Catalog_product_tax.status'=>1)));
                    foreach($taxess as $tax){
                        $taxesitems[]=array(
                            'tax_id' => $tax['Catalog_product_tax']['tax_id'],
                            'tax_name' =>  $tax['Catalog_product_tax']['tax_name'],
                            'tax_percentage' =>  $tax['Catalog_product_tax']['tax_percentage']
                        );
                    }
                    
                    $orderitems[]=array(
                        'id' => $orders['order_orderhistories']['id'],
                        'reference_id' =>  $orders['order_orderhistories']['reference_id'],
                        'cashier_id' =>  $orders['order_orderhistories']['cashier_id'],
                        'group_id' =>  $orders['order_orderhistories']['group_id'],
                        'category' =>  $orders['order_orderhistories']['category'],
                        'category_name' =>  $orders['order_orderhistories']['category_name'],
                        'kds' =>  $orders['order_orderhistories']['kds'],
                        'product_id' =>  $orders['order_orderhistories']['product_id'],
                        'product_name' =>  $orders['order_orderhistories']['product_name'],
                        'quantity' =>  $orders[0]['quantity'],
                        'price' =>  $orders['order_orderhistories']['price'],
                        'total_tax' =>  $orders[0]['total_tax'],
                        'total_price' =>  $orders[0]['total_price'],
                        'discount' =>  $orders[0]['discount'],
                        'table_number' =>  $orders['order_orderhistories']['table_number'],
                        'remarks' =>  $orders['order_orderhistories']['remarks'],
                        'status' =>  $orders['order_orderhistories']['status'],
                        'created' =>  $orders['order_orderhistories']['created'],
                        'taxes'=>$taxesitems
                    );
                }
            }
            $tablenomb=0;
            $tableno=$this->Order_table->query("SELECT GROUP_CONCAT(number) as tbale FROM `order_tables` WHERE status!=0 and reference_id IN ($ref_in)");
            if($tableno){
               $tablenomb =$tableno[0][0]['tbale'];
            }
            
            $finalamount=0;
            $transactionitems=[];
            $createtime = date('H:i:s');
            $transactionitems[]=array(
                'id' => '',
                'reference_id' =>  $ref_in,
                'orderno' =>  '',
                'device_id' =>  '',
                'cashier_id' =>  $cashierid,
                'table_number'        => (string) $tablenomb,
                'price'               => (string) number_format($totalprice, 2), // optional 2 decimals
                'total_tax'           => (string) round($totaltax, 2),
                'servicecharge'       => (string) $totalservicechg,
                'discount'            => (string) $totaldiscount,
                'discount_percentage' => (string) $disc,
                'delivery_charge'     => '0',
                'packing_charge'      => '0',
                'amount'              => (string) round($totalamount, 0),
                'round'               => '0',
                'name' =>  '',
                'phone' =>  '',
                'address' => '',
                'remarks' =>  '',
                'status' =>  '',
                'tokenno' =>  '',
                'createtime' =>  $createtime,
                'created' =>  ''
            );
            
            $paymentitems=[];
            
            $taxitems=[];
            $taxess=$orderdata['taxes'];
            foreach($taxess as $tax){
                $taxitems[]=array(
                    'tax_id' => $tax['tax_id'],
                    'tax_name' =>  $tax['tax_name'],
                    'tax_percentage' =>  $tax['tax_percentage'],
                    'tax_value' =>  number_format($tax['tax_value'],1)
                );
            }
                
            $amount_diff=0;
            
            $cashier_name='';
            $cashname=$this->User->query("SELECT name FROM `users` WHERE id='$cashierid'");
            if($cashname){
               $cashier_name =$cashname[0]['users']['name'];
            }
            
            $printeritems=[];
            $targetStoreId = !empty($users['User']['location_id']) ? $users['User']['location_id'] : (!empty($kdschk['Order_orderhistory']['store_id']) ? $kdschk['Order_orderhistory']['store_id'] : '');
            $printerCond = !empty($targetStoreId) ? "status=1 AND store_id='$targetStoreId'" : "status=1";
            $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE $printerCond");
            if(empty($printerss) && !empty($targetStoreId)){
                $printerss = $this->Pos_printer->query("SELECT * FROM `pos_printers` WHERE status=1");
            }
            if(!empty($printerss))
            {
                foreach($printerss as $printers){
                    
                    $printeritems[]=array(
                        'id' => $printers['pos_printers']['id'],
                        'store_id' =>  $printers['pos_printers']['store_id'],
                        'name' =>  $printers['pos_printers']['name'],
                        'kds' =>  $printers['pos_printers']['kds'],
                        'ip' =>  $printers['pos_printers']['ip'],
                        'status' =>  $printers['pos_printers']['status']
                    );
                }
            }
            
            
            $response= array('status'=> true,
                'message'=> "success",
                'cashier_name'=>$cashier_name,
                'orders'=>$orderitems,
                'transactions'=>$transactionitems,
                'payments'=>$paymentitems,
                'taxes'=>$taxitems,
                'printers'=>$printeritems,
                'remaining_amount'=>(string) round($totalamount, 2)
            );
            
            return json_encode($response);
        }else{
            $response =array(
                'status'=> false,
                'message'=> "No data found",
            );
            return json_encode($response);
        }
    }
}